stm32_mdma_probe: 解析设备树资源并完成 STM32 MDMA 控制器的设备级初始化此函数是STM32 MDMA 驱动真正的设备级初始化入口。它由 platform 总线在设备树匹配成功后调用，用于把一个具体的 MDMA 控制器实例（寄存器、中断、时钟、复位等资源）初始化为 Linux DMAengine 可用的 DMA 控制器。
其核心原理是：把设备树描述的硬件资源转换为内核中可管理的对象，并把该控制器注册到 DMAengine 与 OF-DMA 框架。整个过程包含四类关键动作：

设备树参数读取与约束建立：读取 dma-channels、dma-requests、st,ahb-addr-masks 等属性，构成后续合法性边界与资源规模。
资源获取与使能：映射寄存器资源、获取并使能时钟、执行可选复位序列，确保 MDMA 处于可访问且可控状态。
DMAengine 设备建模：设置 dma_device 的能力掩码与回调函数集合，并初始化每个通道的 virt_dma_chan。
注册与对外发布：申请中断、注册到 DMAengine 核心、注册 OF-DMA 翻译器，使设备树客户端能通过 phandle 申请 MDMA 通道。

在 STM32H750（单核、无 MMU）视角下，需要强调的点是：

单核不会改变该函数的语义；该函数本身是典型“启动阶段一次性初始化”。
无 MMU 对此类驱动模型代码没有直接影响（这里的 __iomem、devm_* 等属于内核抽象层）。
真正与“传输正确性&#x2F;性能”相关的部分主要来自：能力声明、回调绑定、通道初始化方式，以及后续具体 prep&#x2F;issue 路径。

/* * stm32_mdma_probe: 初始化一个 STM32 MDMA 控制器实例并注册到 DMAengine * @pdev: platform 设备实例，承载设备树节点与资源 * * 该函数完成： * - 读取设备树属性（通道数、请求线数、地址掩码等） * - 映射寄存器资源 * - 获取并使能时钟、执行可选复位 * - 初始化 dma_device 能力与回调 * - 初始化每个虚拟通道 vchan * - 申请 IRQ * - 注册 DMAengine 与 OF-DMA 控制器 */static int stm32_mdma_probe(struct platform_device *pdev)&#123;	struct stm32_mdma_chan *chan;	struct stm32_mdma_device *dmadev;	struct dma_device *dd;	struct device_node *of_node;	struct reset_control *rst;	u32 nr_channels, nr_requests;	int i, count, ret;	/* 获取设备树节点；若无设备树描述，则不支持该设备实例 */	of_node = pdev-&gt;dev.of_node;	if (!of_node)		return -ENODEV;	/*	 * 读取 MDMA 通道数量。	 * 若未提供该属性，则退回到驱动支持的最大通道数，并给出告警。	 * 该值用于确定后续通道初始化循环次数与资源规模。	 */	ret = device_property_read_u32(&amp;pdev-&gt;dev, &quot;dma-channels&quot;, &amp;nr_channels);	if (ret) &#123;		nr_channels = STM32_MDMA_MAX_CHANNELS;		dev_warn(&amp;pdev-&gt;dev, &quot;MDMA defaulting on %i channels\n&quot;, nr_channels);	&#125;	/*	 * 读取 MDMA 请求线数量。	 * 请求线用于配置触发源选择与合法性校验；缺省时退回到最大值。	 */	ret = device_property_read_u32(&amp;pdev-&gt;dev, &quot;dma-requests&quot;, &amp;nr_requests);	if (ret) &#123;		nr_requests = STM32_MDMA_MAX_REQUESTS;		dev_warn(&amp;pdev-&gt;dev, &quot;MDMA defaulting on %i request lines\n&quot;, nr_requests);	&#125;	/*	 * 读取 st,ahb-addr-masks 的元素个数。	 * 该属性用于对某些地址域施加掩码约束（与具体 SoC AHB 地址映射相关）。	 * 若不存在该属性，count 视为 0。	 */	count = device_property_count_u32(&amp;pdev-&gt;dev, &quot;st,ahb-addr-masks&quot;);	if (count &lt; 0)		count = 0;	/*	 * 分配 dmadev，并同时为可变长度数组 ahb_addr_masks[] 预留空间。	 * 采用 devm_ 管理，确保探测失败或卸载时自动释放。	 */	dmadev = devm_kzalloc(&amp;pdev-&gt;dev,			      struct_size(dmadev, ahb_addr_masks, count),			      GFP_KERNEL);	if (!dmadev)		return -ENOMEM;	/* 保存可变数组长度与设备能力参数 */	dmadev-&gt;nr_ahb_addr_masks = count;	dmadev-&gt;nr_channels = nr_channels;	dmadev-&gt;nr_requests = nr_requests;	/* 读取地址掩码数组本体（若 count 为 0，该调用等价于无操作） */	device_property_read_u32_array(&amp;pdev-&gt;dev, &quot;st,ahb-addr-masks&quot;,				       dmadev-&gt;ahb_addr_masks, count);	/*	 * 映射寄存器资源（resource index 0）。	 * 返回值为 __iomem 指针，用于后续寄存器读写封装函数访问。	 */	dmadev-&gt;base = devm_platform_ioremap_resource(pdev, 0);	if (IS_ERR(dmadev-&gt;base))		return PTR_ERR(dmadev-&gt;base);	/*	 * 获取时钟并使能。	 * MDMA 寄存器访问与内部状态机运行依赖时钟；未使能时钟会导致访问异常或硬件不响应。	 */	dmadev-&gt;clk = devm_clk_get(&amp;pdev-&gt;dev, NULL);	if (IS_ERR(dmadev-&gt;clk))		return dev_err_probe(&amp;pdev-&gt;dev, PTR_ERR(dmadev-&gt;clk),				     &quot;Missing clock controller\n&quot;);	ret = clk_prepare_enable(dmadev-&gt;clk);	if (ret &lt; 0) &#123;		dev_err(&amp;pdev-&gt;dev, &quot;clk_prep_enable error: %d\n&quot;, ret);		return ret;	&#125;	/*	 * 可选复位：若存在 reset controller，则执行一次 assert-&gt;短延时-&gt;deassert。	 * 目的：把 MDMA 控制器恢复到确定的硬件初始状态，避免早期阶段残留配置影响驱动假设。	 */	rst = devm_reset_control_get(&amp;pdev-&gt;dev, NULL);	if (IS_ERR(rst)) &#123;		ret = PTR_ERR(rst);		if (ret == -EPROBE_DEFER)			goto err_clk;	&#125; else &#123;		reset_control_assert(rst);		udelay(2);		reset_control_deassert(rst);	&#125;	/*	 * 初始化 DMAengine 设备对象 dd（dmadev-&gt;ddev）。	 * 该对象向 DMAengine core 描述“这个控制器支持什么、如何操作它”。	 */	dd = &amp;dmadev-&gt;ddev;	/* 声明能力：支持 SLAVE / PRIVATE / CYCLIC / MEMCPY */	dma_cap_set(DMA_SLAVE, dd-&gt;cap_mask);	dma_cap_set(DMA_PRIVATE, dd-&gt;cap_mask);	dma_cap_set(DMA_CYCLIC, dd-&gt;cap_mask);	dma_cap_set(DMA_MEMCPY, dd-&gt;cap_mask);	/*	 * 绑定 DMAengine 设备级回调。	 * 这些回调定义资源管理、描述符准备、状态查询、启动/暂停/恢复/终止等行为。	 */	dd-&gt;device_alloc_chan_resources = stm32_mdma_alloc_chan_resources;	dd-&gt;device_free_chan_resources  = stm32_mdma_free_chan_resources;	dd-&gt;device_tx_status            = stm32_mdma_tx_status;	dd-&gt;device_issue_pending        = stm32_mdma_issue_pending;	dd-&gt;device_prep_slave_sg        = stm32_mdma_prep_slave_sg;	dd-&gt;device_prep_dma_cyclic      = stm32_mdma_prep_dma_cyclic;	dd-&gt;device_prep_dma_memcpy      = stm32_mdma_prep_dma_memcpy;	dd-&gt;device_config               = stm32_mdma_slave_config;	dd-&gt;device_pause                = stm32_mdma_pause;	dd-&gt;device_resume               = stm32_mdma_resume;	dd-&gt;device_terminate_all        = stm32_mdma_terminate_all;	dd-&gt;device_synchronize          = stm32_mdma_synchronize;	/*	 * descriptor_reuse 为 true 表示描述符可复用，这影响 DMAengine 对描述符生命周期的管理策略。	 * 其正确性依赖驱动对描述符释放/重用路径的严格实现。	 */	dd-&gt;descriptor_reuse = true;	/*	 * 声明支持的总线宽度（源/目的）以及方向集合。	 * 这些字段用于在 DMAengine 层面进行能力匹配与参数合法性约束。	 */	dd-&gt;src_addr_widths = BIT(DMA_SLAVE_BUSWIDTH_1_BYTE) |			      BIT(DMA_SLAVE_BUSWIDTH_2_BYTES) |			      BIT(DMA_SLAVE_BUSWIDTH_4_BYTES) |			      BIT(DMA_SLAVE_BUSWIDTH_8_BYTES);	dd-&gt;dst_addr_widths = BIT(DMA_SLAVE_BUSWIDTH_1_BYTE) |			      BIT(DMA_SLAVE_BUSWIDTH_2_BYTES) |			      BIT(DMA_SLAVE_BUSWIDTH_4_BYTES) |			      BIT(DMA_SLAVE_BUSWIDTH_8_BYTES);	dd-&gt;directions = BIT(DMA_DEV_TO_MEM) | BIT(DMA_MEM_TO_DEV) | BIT(DMA_MEM_TO_MEM);	/* residue 粒度与最大 burst 约束，影响剩余量统计语义与上层期望 */	dd-&gt;residue_granularity = DMA_RESIDUE_GRANULARITY_BURST;	dd-&gt;max_burst = STM32_MDMA_MAX_BURST;	/* 建立 dma_device 与 struct device 的绑定，并初始化通道链表头 */	dd-&gt;dev = &amp;pdev-&gt;dev;	INIT_LIST_HEAD(&amp;dd-&gt;channels);	/*	 * 初始化每个通道对象：	 * - 设置通道 id	 * - 读取 CCR 的 Secure 标记并记录为 reserved（用于后续过滤与分配约束）	 * - 初始化 virt-dma 通道，并设置描述符释放回调	 */	for (i = 0; i &lt; dmadev-&gt;nr_channels; i++) &#123;		chan = &amp;dmadev-&gt;chan[i];		chan-&gt;id = i;		/* 若硬件将该通道标记为 Secure，则记录为 reserved，避免非安全域使用 */		if (stm32_mdma_read(dmadev, STM32_MDMA_CCR(i)) &amp; STM32_MDMA_CCR_SM)			dmadev-&gt;chan_reserved |= BIT(i);		chan-&gt;vchan.desc_free = stm32_mdma_desc_free;		vchan_init(&amp;chan-&gt;vchan, dd);	&#125;	/*	 * 获取 IRQ 并申请中断处理函数。	 * 中断用于处理传输完成、块完成、错误等事件，是驱动正确性的核心路径之一。	 */	dmadev-&gt;irq = platform_get_irq(pdev, 0);	if (dmadev-&gt;irq &lt; 0) &#123;		ret = dmadev-&gt;irq;		goto err_clk;	&#125;	ret = devm_request_irq(&amp;pdev-&gt;dev, dmadev-&gt;irq, stm32_mdma_irq_handler,			       0, dev_name(&amp;pdev-&gt;dev), dmadev);	if (ret) &#123;		dev_err(&amp;pdev-&gt;dev, &quot;failed to request IRQ\n&quot;);		goto err_clk;	&#125;	/*	 * 注册 DMAengine 设备。	 * 注册成功后，DMAengine core 才会将该控制器对外可见，并允许客户端申请通道。	 */	ret = dmaenginem_async_device_register(dd);	if (ret)		goto err_clk;	/*	 * 注册 OF-DMA 控制器，使设备树中的 DMA phandle 能通过 xlate 函数映射为 dma_chan。	 * 这是设备树客户端获取 MDMA 通道的关键路径。	 */	ret = of_dma_controller_register(of_node, stm32_mdma_of_xlate, dmadev);	if (ret &lt; 0) &#123;		dev_err(&amp;pdev-&gt;dev, &quot;STM32 MDMA DMA OF registration failed %d\n&quot;, ret);		goto err_clk;	&#125;	/*	 * 保存驱动私有数据，并启用 runtime PM。	 * runtime PM 是否实际生效由系统策略决定，但驱动需提供可用的 enable/disable 入口。	 */	platform_set_drvdata(pdev, dmadev);	pm_runtime_set_active(&amp;pdev-&gt;dev);	pm_runtime_enable(&amp;pdev-&gt;dev);	pm_runtime_get_noresume(&amp;pdev-&gt;dev);	pm_runtime_put(&amp;pdev-&gt;dev);	dev_info(&amp;pdev-&gt;dev, &quot;STM32 MDMA driver registered\n&quot;);	return 0;err_clk:	/* 失败路径：撤销时钟使能，保证资源状态可预测 */	clk_disable_unprepare(dmadev-&gt;clk);	return ret;&#125;

stm32_mdma_of_xlate: 将设备树 DMA phandle 参数翻译为可用的 MDMA 通道并固化通道配置stm32_mdma_of_xlate 是 STM32 MDMA 控制器驱动注册到 OF-DMA 框架的 xlate 回调：当设备树里的某个 DMA 客户端通过 phandle 引用该 MDMA 控制器时，OF-DMA 会把 phandle 参数打包成 struct of_phandle_args，并调用本函数完成两件事：

做参数合法性约束（参数个数、request line 范围、优先级范围）。
向 DMAengine 申请一个符合条件的通道，并把设备树参数固化到 chan-&gt;chan_config，作为后续“准备描述符&#x2F;配置寄存器”的静态约束输入。 ([codebrowser.dev][1])

在 STM32H750（单核、无 MMU）场景下，本函数的关键意义不在于硬件差异，而在于：它把“设备树静态约束”转换为“DMAengine 通道对象 + 驱动私有配置”，从而让上层驱动后续调用 DMAengine API 时不需要重复携带设备树参数；并且通道分配仍必须通过 DMAengine 的全局机制完成（即使单核也可能在不同上下文交错访问全局通道表，因此不能省略锁语义）。
static bool stm32_mdma_filter_fn(struct dma_chan *c, void *fn_param)&#123;	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/* Check if chan is marked Secure */	if (dmadev-&gt;chan_reserved &amp; BIT(chan-&gt;id))		return false;	return true;&#125;/** * @brief 将设备树中的 MDMA phandle 参数翻译为一个可用的 DMAengine 通道，并固化通道配置 * * 本函数是 OF-DMA 的 xlate 回调入口：负责解析 dma_spec 参数，申请通道，并把解析结果保存到 * 驱动私有通道结构体中，供后续 prepare/issue 等路径使用。 * * @param dma_spec 设备树 phandle 参数集合，args[0..4] 的语义由本驱动定义 * @param ofdma OF-DMA 框架对象，携带控制器实例指针与设备树节点等上下文 * @return 成功时返回可用的 struct dma_chan*；失败时返回 NULL */static struct dma_chan *stm32_mdma_of_xlate(struct of_phandle_args *dma_spec,					    struct of_dma *ofdma)&#123;	/* 通过 OF-DMA 上下文取回本控制器实例（probe 注册 of_dma_controller_register 时写入） */	struct stm32_mdma_device *dmadev = ofdma-&gt;of_dma_data;	/* 复制控制器对外声明的能力掩码，用于通道申请时的 capability 过滤 */	dma_cap_mask_t mask = dmadev-&gt;ddev.cap_mask;	/* 驱动私有通道指针：用于把解析出的配置固化到 chan-&gt;chan_config */	struct stm32_mdma_chan *chan;	/* DMAengine 通道抽象：作为返回值与后续 DMAengine API 的输入 */	struct dma_chan *c;	/* 通道配置快照：由设备树参数构造，既用于过滤器选择通道，也用于最终固化 */	struct stm32_mdma_chan_config config;	/* 设备树参数个数检查：本驱动要求至少 5 个参数（request/priority/transfer/mask_addr/mask_data） */	if (dma_spec-&gt;args_count &lt; 5) &#123;		/* 记录错误：这里使用控制器设备对象打印，便于定位是哪一个 MDMA 控制器实例 */		dev_err(mdma2dev(dmadev), &quot;Bad number of args\n&quot;);		return NULL; /* 以 NULL 表示 xlate 失败，OF-DMA 将认为无法得到通道 */	&#125;	/* 将 config 清零，确保未显式设置的字段保持确定性（避免栈垃圾影响过滤或后续路径） */	memset(&amp;config, 0, sizeof(config));	/* 解析设备树参数：request line（触发源/请求线编号） */	config.request = dma_spec-&gt;args[0];	/* 解析设备树参数：优先级（驱动用该值约束 CCR/优先级相关寄存器的编程） */	config.priority_level = dma_spec-&gt;args[1];	/* 解析设备树参数：传输配置（用于后续 CTCR 等寄存器组合，xlate 阶段只固化不解码） */	config.transfer_config = dma_spec-&gt;args[2];	/* 解析设备树参数：地址掩码（与硬件 mask address 寄存器语义对应，作为后续编程输入） */	config.mask_addr = dma_spec-&gt;args[3];	/* 解析设备树参数：数据掩码（与硬件 mask data 寄存器语义对应，作为后续编程输入） */	config.mask_data = dma_spec-&gt;args[4];	/* request line 合法性检查：避免客户端引用不存在的请求线 */	if (config.request &gt;= dmadev-&gt;nr_requests) &#123;		dev_err(mdma2dev(dmadev), &quot;Bad request line\n&quot;);		return NULL;	&#125;	/* 优先级合法性检查：驱动只支持到 VERY_HIGH_PRIORITY（通常对应硬件允许的最大编码） */	if (config.priority_level &gt; STM32_MDMA_VERY_HIGH_PRIORITY) &#123;		dev_err(mdma2dev(dmadev), &quot;Priority level not supported\n&quot;);		return NULL;	&#125;	/*	 * 申请一个 DMAengine 通道：	 * - mask：能力筛选条件	 * - stm32_mdma_filter_fn：驱动过滤器（会基于 config 与通道保留位等约束筛选通道）	 * - &amp;config：过滤器参数（把设备树约束参与到通道选择中）	 * - ofdma-&gt;of_node：限制匹配到当前控制器实例的通道集合	 */	c = __dma_request_channel(&amp;mask, stm32_mdma_filter_fn, &amp;config, ofdma-&gt;of_node);	if (!c) &#123;		/* 没有可用通道：可能是通道耗尽，也可能是过滤条件导致无匹配 */		dev_err(mdma2dev(dmadev), &quot;No more channels available\n&quot;);		return NULL;	&#125;	/* 将通用 dma_chan 转换为驱动私有 stm32_mdma_chan，以便写入私有配置字段 */	chan = to_stm32_mdma_chan(c);	/* 固化通道配置：后续数据路径无需再从设备树解析，直接使用 chan-&gt;chan_config */	chan-&gt;chan_config = config;	/* 返回通道给 OF-DMA/DMAengine 客户端使用 */	return c;&#125;



m2m_hw 是什么m2m_hw 在这份驱动里的含义是：“内存到内存（M2M）的硬件触发模式”，更具体一点是你代码里那句注释所说的场景：由 STM32 的另一个 DMA（常见是 DMA&#x2F;BDMA）产生硬件触发节拍，来驱动 MDMA 按 SG 段逐段执行。
它不是“普通的 memcpy”（纯软件发起、MDMA 自己跑完），而是强调：

触发源不是 CPU，而是“另一个 DMA&#x2F;外设事件”
MDMA 的每个 SG 节点可能需要配合“上游 DMA 的重装填&#x2F;再使能”
所以驱动在 prep_slave_sg() 里对 DMA_MEM_TO_DEV 的 m2m_hw 情况，把每个硬件描述符的 cmar/cmdr 清零，目的是改变完成标志&#x2F;节拍相关的行为，让 CPU 能在合适时机“重装填上游 STM32 DMA，并更新 dmaengine 框架状态”（你贴的英文注释就是这个意思）

你可以把它理解为：MDMA 在这里扮演“被节拍驱动的搬运器”，节拍来自另一个 DMA。

“外设从模式 SG 传输” 是什么“外设从模式（slave）”在 DMAengine 里指：DMA 的一端是外设寄存器地址（固定或按规则变化），另一端是内存，常见方向：

DMA_DEV_TO_MEM：外设 -&gt; 内存（接收）
DMA_MEM_TO_DEV：内存 -&gt; 外设（发送）

“SG（scatter-gather）传输”指：一次传输不是一段连续缓冲区，而是一组分散的内存片段（struct scatterlist 数组）。驱动需要把这些片段转换成硬件能执行的“多段&#x2F;链式”传输。
所以“外设从模式 SG 传输”合起来就是：

外设 &lt;-&gt; 内存 的 DMA 传输，内存侧由多个 scatterlist 段组成；驱动负责把这些段编成硬件描述符链，并交给 DMA 引擎执行。

你贴的 stm32_mdma_prep_slave_sg() 就是做这件事：分配 desc（含多个 node），再 setup_xfer() 把 SG 段转成硬件描述符，最后 vchan_tx_prep() 把它挂入 virt-dma 队列。
stm32_mdma_slave_config &#x2F; stm32_mdma_prep_slave_sg: 固化外设侧配置并将 SG 请求转换为可提交的 MDMA 描述符这两个函数是外设流主线的前两步，关系非常紧密：

stm32_mdma_slave_config：把上层（外设驱动）传入的 dma_slave_config 固化到通道私有状态（chan-&gt;dma_config），并在“STM32 DMA 触发 MDMA（m2m_hw）”这种特殊模式下，从 peripheral_config 里提取 MDMA 需要的 request/cmar/cmdr，写入 chan-&gt;chan_config，形成后续构建硬件描述符的静态输入。
stm32_mdma_prep_slave_sg：基于 chan-&gt;chan_config + chan-&gt;dma_config 以及本次 sgl/sg_len/direction，分配 desc，并调用 stm32_mdma_setup_xfer() 把 SG 转换成一组可执行的硬件描述符节点；在 m2m_hw &amp;&amp; DMA_MEM_TO_DEV 特例下，按驱动策略把每个节点的 cmar/cmdr 清零，以改变“硬件完成标志的清理方式&#x2F;节拍”，满足“CPU 重新装填 STM32 DMA 并同步框架状态”的需求。


/** * @brief 配置 MDMA 从模式通道：固化 dma_slave_config，并处理“STM32 DMA 触发 MDMA”的扩展参数 * @param[in] c      DMAengine 抽象通道指针 * @param[in] config 上层外设驱动提供的从模式配置（方向、地址、宽度、burst 等） * @return 成功返回 0；失败返回负错误码（本实现始终返回 0） */static int stm32_mdma_slave_config(struct dma_chan *c,				   struct dma_slave_config *config)&#123;	/** 将通用 dma_chan 转为驱动私有 stm32_mdma_chan */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/**	 * 固化外设侧配置：	 * 这里直接按结构体大小拷贝，意味着后续数据路径不再依赖调用者保留 config 生命周期。	 */	memcpy(&amp;chan-&gt;dma_config, config, sizeof(*config));	/**	 * 判断是否启用“STM32 DMA 触发 MDMA”的扩展模式：	 * 该驱动以 peripheral_size 作为是否存在扩展配置的判据。	 *	 * 注意：这属于驱动约定语义，而非 dma_slave_config 字段在通用框架中的唯一用法。	 */	if (config-&gt;peripheral_size) &#123;		/** 扩展配置的解释类型：由调用者在 peripheral_config 中传入并由本驱动按约定解析 */		struct stm32_mdma_dma_config *mdma_config;		/**		 * 将通用的 peripheral_config 指针解释为 stm32_mdma_dma_config：		 * 该指针的类型与内容完全由“调用者与本驱动的约定”决定，		 * 框架不做类型检查，因此这里的解释必须依赖调用者正确传入。		 */		mdma_config = (struct stm32_mdma_dma_config *)chan-&gt;dma_config.peripheral_config;		/** 固化 request line：用于后续选择/配置 MDMA 的触发请求线 */		chan-&gt;chan_config.request = mdma_config-&gt;request;		/** 固化地址掩码输入：后续会写入硬件描述符的 CMAR 字段或相关寄存器语义 */		chan-&gt;chan_config.mask_addr = mdma_config-&gt;cmar;		/** 固化数据掩码输入：后续会写入硬件描述符的 CMDR 字段或相关寄存器语义 */		chan-&gt;chan_config.mask_data = mdma_config-&gt;cmdr;		/**		 * 标记该通道进入 m2m_hw 模式：		 * 用于在 prep/irq 等路径中启用特殊处理（例如对完成标志清理/节拍的策略差异）。		 */		chan-&gt;chan_config.m2m_hw = true;	&#125;	/** 本实现不做参数合法性拒绝，直接返回成功 */	return 0;&#125;/** * @brief 准备外设从模式 SG 传输：构建 MDMA 描述符并返回可提交的异步事务描述符 * @param[in] c          DMAengine 抽象通道指针 * @param[in] sgl        scatterlist 首元素指针 * @param[in] sg_len     scatterlist 元素数量 * @param[in] direction  传输方向（DEV_TO_MEM / MEM_TO_DEV 等） * @param[in] flags      dmaengine flags（如 DMA_PREP_INTERRUPT 等） * @param[in] context    上层透传上下文指针（此处未使用） * @return 成功返回 dma_async_tx_descriptor 指针；失败返回 NULL */static struct dma_async_tx_descriptor *stm32_mdma_prep_slave_sg(struct dma_chan *c, struct scatterlist *sgl,			 u32 sg_len, enum dma_transfer_direction direction,			 unsigned long flags, void *context)&#123;	/** 将通用 dma_chan 转为驱动私有通道 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/** 取出通道级静态配置引用（由 of_xlate 或 slave_config 等路径写入） */	struct stm32_mdma_chan_config *chan_config = &amp;chan-&gt;chan_config;	/** desc：本次要构建的 MDMA 描述符（包含多个 node，每个 node 对应一个 SG 元素或分段） */	struct stm32_mdma_desc *desc;	/** i：循环索引；ret：错误码 */	int i, ret;	/**	 * 循环模式互斥约束：	 * 一旦该通道已进入 cyclic 模式并持有 cyclic 描述符，则不允许再提交新的非 cyclic 请求。	 *	 * 该限制的实质是：cyclic 运行时通道的状态机与队列语义不同，	 * 若允许混入普通 SG，会破坏“循环推进/回调节拍”的不变式。	 */	if (chan-&gt;desc &amp;&amp; chan-&gt;desc-&gt;cyclic) &#123;		/** 报错并拒绝请求 */		dev_err(chan2dev(chan),			&quot;Request not allowed when dma in cyclic mode\n&quot;);		return NULL;	&#125;	/**	 * 分配描述符对象：	 * - sg_len 决定 node 数量上界（典型实现为每个 SG 元素一个 node）	 * - desc 内部通常还会关联硬件描述符（从 dma_pool 分配）与物理地址	 */	desc = stm32_mdma_alloc_desc(chan, sg_len);	if (!desc)		return NULL;	/**	 * 建立本次传输的硬件执行形态：	 * 将 (sgl, sg_len, direction) 转换为一组硬件描述符节点的配置，	 * 并把必要的寄存器字段/LLI 链关系写入 desc-&gt;node[i].hwdesc 等结构。	 */	ret = stm32_mdma_setup_xfer(chan, desc, sgl, sg_len, direction);	if (ret &lt; 0)		goto xfer_setup_err;	/**	 * m2m_hw 特例处理（由 stm32_mdma_slave_config 写入 chan_config-&gt;m2m_hw）：	 * 当 MDMA 是由 STM32 DMA 触发、且方向为 MEM_TO_DEV 时，驱动选择把每个节点的 cmar/cmdr 清零。	 *	 * 该处理的核心目的是改变“传输完成标志相关的清理/再装填节拍”，	 * 使 CPU 能够在合适的时机重新装填 STM32 DMA 的下一段 SG，并同步 dmaengine 框架的部分状态。	 *	 * 注意：这是驱动对特定硬件协同模式的策略实现，不是通用 SG 传输的必需步骤。	 */	if (chan_config-&gt;m2m_hw &amp;&amp; direction == DMA_MEM_TO_DEV) &#123;		/** hwdesc：硬件描述符指针；每个 node 一份 */		struct stm32_mdma_hwdesc *hwdesc;		/** 遍历所有 SG 节点并清零对应硬件描述符的 cmar/cmdr 字段 */		for (i = 0; i &lt; sg_len; i++) &#123;			hwdesc = desc-&gt;node[i].hwdesc;			hwdesc-&gt;cmar = 0;			hwdesc-&gt;cmdr = 0;		&#125;	&#125;	/** 明确标记该描述符不是 cyclic 描述符 */	desc-&gt;cyclic = false;	/**	 * 交给 virt-dma 框架生成通用的 tx_descriptor：	 * - vchan_tx_prep 会把 vdesc 挂入 vchan 队列管理体系	 * - flags 决定是否需要中断回调、是否允许重复提交等语义	 */	return vchan_tx_prep(&amp;chan-&gt;vchan, &amp;desc-&gt;vdesc, flags);xfer_setup_err:	/**	 * 失败回收路径：	 * - 回收每个 node 分配的硬件描述符（dma_pool_free）	 * - 释放 desc 本体（kfree）	 *	 * 关键点：这里依赖 desc-&gt;count 来确定已成功分配/初始化的节点数量，	 * 避免对未初始化指针做 free。	 */	for (i = 0; i &lt; desc-&gt;count; i++)		dma_pool_free(chan-&gt;desc_pool, desc-&gt;node[i].hwdesc,			      desc-&gt;node[i].hwdesc_phys);	kfree(desc);	return NULL;&#125;

stm32_mdma_alloc_chan_resources &#x2F; stm32_mdma_free_chan_resources &#x2F; stm32_mdma_alloc_desc &#x2F; stm32_mdma_desc_free: 建立通道资源与描述符生命周期闭环这四段代码构成了 STM32 MDMA 驱动里“资源与对象生命周期”的最小闭环：

stm32_mdma_alloc_chan_resources：为一个通道建立硬件描述符内存池（desc_pool），并通过 runtime PM 确保控制器处于可访问状态，然后把硬件通道拉回“禁用&#x2F;干净”的基线状态（stm32_mdma_disable_chan）。
stm32_mdma_free_chan_resources：在释放通道资源前，如果通道仍处于 busy，先在 vchan 锁保护下停止硬件并清理当前描述符指针；随后 pm_runtime_put 释放 PM 引用，释放 vchan 资源，销毁描述符池。
stm32_mdma_alloc_desc：按 count 分配一个可变长 desc，并为每个 node 从 desc_pool 分配一块 stm32_mdma_hwdesc，形成“软件描述符 + 硬件描述符数组”的组合对象。
stm32_mdma_desc_free：virt-dma 统一的释放钩子，只做两件事：逐 node 归还 hwdesc 到 pool，再 kfree(desc) 释放软件描述符本体。


/** * @brief 为一个 MDMA 通道分配运行态资源：创建硬件描述符 pool，并把硬件通道置于可用基线状态 * @param[in] c DMAengine 抽象通道指针 * @return 成功返回 0；失败返回负错误码 */static int stm32_mdma_alloc_chan_resources(struct dma_chan *c)&#123;	/** 将通用 dma_chan 转换为驱动私有通道对象 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/** 获取该通道所属的控制器对象，用于 runtime PM 与硬件控制 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/** 通用错误码返回值 */	int ret;	/**	 * 创建通道级硬件描述符内存池：	 * - 每个元素大小为 struct stm32_mdma_hwdesc	 * - 对齐要求使用 __alignof__(struct stm32_mdma_hwdesc)	 * - dmam_ 前缀表示该 pool 的生命周期被 device-managed 机制跟踪	 *	 * 第一个参数使用通道的 device 名称作为 pool 名字，主要用于调试可见性。	 */	chan-&gt;desc_pool = dmam_pool_create(dev_name(&amp;c-&gt;dev-&gt;device),					   c-&gt;device-&gt;dev,					   sizeof(struct stm32_mdma_hwdesc),					   __alignof__(struct stm32_mdma_hwdesc),					   0);	/**	 * pool 创建失败：属于硬失败，后续无法构建任何 hwdesc 节点	 */	if (!chan-&gt;desc_pool) &#123;		dev_err(chan2dev(chan), &quot;failed to allocate descriptor pool\n&quot;);		return -ENOMEM;	&#125;	/**	 * 获取 runtime PM 引用并确保设备处于 active：	 * - 成功后，寄存器访问与后续 disable/stop 等硬件操作才具有确定语义	 * - ret &lt; 0 表示设备未就绪或依赖未满足	 */	ret = pm_runtime_resume_and_get(dmadev-&gt;ddev.dev);	if (ret &lt; 0)		return ret;	/**	 * 将硬件通道置为禁用/干净状态：	 * 该步骤的工程意义是消除“上一次使用残留状态”对新提交事务的影响。	 */	ret = stm32_mdma_disable_chan(chan);	if (ret &lt; 0)		/** 失败则释放 runtime PM 引用，避免引用泄漏导致设备无法进入低功耗 */		pm_runtime_put(dmadev-&gt;ddev.dev);	/** 返回 disable 结果（0 表示成功，负值表示失败） */	return ret;&#125;/** * @brief 释放一个 MDMA 通道的运行态资源：停止通道、释放 vchan 资源并销毁描述符 pool * @param[in] c DMAengine 抽象通道指针 */static void stm32_mdma_free_chan_resources(struct dma_chan *c)&#123;	/** 通用 dma_chan -&gt; 私有通道 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/** 私有通道 -&gt; 控制器，用于 runtime PM put */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/** 保存并恢复 IRQ 状态的自旋锁标志 */	unsigned long flags;	/** 调试输出：释放哪个通道 */	dev_dbg(chan2dev(chan), &quot;Freeing channel %d\n&quot;, chan-&gt;id);	/**	 * 若通道仍在运行（busy），必须先停止硬件：	 * 使用 vchan.lock + irqsave 的原因是避免与中断处理/回调推进路径并发交错，	 * 保证 stop 与 chan-&gt;desc 置空的原子性。	 */	if (chan-&gt;busy) &#123;		spin_lock_irqsave(&amp;chan-&gt;vchan.lock, flags);		stm32_mdma_stop(chan);		chan-&gt;desc = NULL;		spin_unlock_irqrestore(&amp;chan-&gt;vchan.lock, flags);	&#125;	/**	 * 释放 runtime PM 引用：	 * 与 alloc_chan_resources 中的 pm_runtime_resume_and_get 成对出现。	 */	pm_runtime_put(dmadev-&gt;ddev.dev);	/**	 * 释放 virt-dma 通道资源：	 * 该调用会清理 vchan 队列、cookie 状态等框架对象。	 */	vchan_free_chan_resources(to_virt_chan(c));	/**	 * 销毁通道级描述符 pool，并把指针清空：	 * 这里使用 dmam_pool_destroy 显式销毁，避免后续错误路径误用该 pool。	 */	dmam_pool_destroy(chan-&gt;desc_pool);	chan-&gt;desc_pool = NULL;&#125;/** * @brief 分配一个软件描述符对象，并为每个 node 分配一块硬件描述符（来自通道 pool） * @param[in] chan  私有通道对象 * @param[in] count node 数量（通常等于 sg_len 或其分解后的段数） * @return 成功返回 desc；失败返回 NULL */static struct stm32_mdma_desc *stm32_mdma_alloc_desc(		struct stm32_mdma_chan *chan, u32 count)&#123;	/** 可变长描述符对象指针 */	struct stm32_mdma_desc *desc;	/** 循环索引 */	int i;	/**	 * 分配可变长 desc：	 * struct_size(desc, node, count) 计算包含 count 个 node 的总字节数。	 * GFP_NOWAIT 表示不允许睡眠等待；在内存紧张时更容易失败，因此必须严格回滚。	 */	desc = kzalloc(struct_size(desc, node, count), GFP_NOWAIT);	if (!desc)		return NULL;	/** 固化 node 数量，用于后续释放与错误回滚的边界 */	desc-&gt;count = count;	/**	 * 为每个 node 分配硬件描述符：	 * - 从 chan-&gt;desc_pool 取出一块 struct stm32_mdma_hwdesc	 * - 同时得到该块的物理地址 hwdesc_phys（供硬件链表/寄存器指向使用）	 */	for (i = 0; i &lt; count; i++) &#123;		desc-&gt;node[i].hwdesc =			dma_pool_alloc(chan-&gt;desc_pool, GFP_NOWAIT,				       &amp;desc-&gt;node[i].hwdesc_phys);		if (!desc-&gt;node[i].hwdesc)			goto err;	&#125;	/** 所有 node 分配成功：返回 desc */	return desc;err:	/**	 * 错误回滚：	 * - i 目前指向失败的索引位置	 * - 需要释放之前已成功分配的 [0, i) 区间	 */	dev_err(chan2dev(chan), &quot;Failed to allocate descriptor\n&quot;);	while (--i &gt;= 0)		dma_pool_free(chan-&gt;desc_pool, desc-&gt;node[i].hwdesc,			      desc-&gt;node[i].hwdesc_phys);	/** 释放 desc 本体 */	kfree(desc);	return NULL;&#125;/** * @brief virt-dma 描述符释放回调：归还硬件描述符并释放软件描述符本体 * @param[in] vdesc virt-dma 的通用描述符基类指针 */static void stm32_mdma_desc_free(struct virt_dma_desc *vdesc)&#123;	/** vdesc -&gt; 私有 desc */	struct stm32_mdma_desc *desc = to_stm32_mdma_desc(vdesc);	/** 通过 vdesc-&gt;tx.chan 找到所属通道，从而拿到 desc_pool */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(vdesc-&gt;tx.chan);	/** 循环索引 */	int i;	/** 逐 node 归还硬件描述符到 pool */	for (i = 0; i &lt; desc-&gt;count; i++)		dma_pool_free(chan-&gt;desc_pool, desc-&gt;node[i].hwdesc,			      desc-&gt;node[i].hwdesc_phys);	/** 释放软件描述符对象 */	kfree(desc);&#125;

stm32_mdma_disable_chan &#x2F; stm32_mdma_stop: 关闭 MDMA 通道并以轮询确认传输已完成，随后清中断并复位软件忙状态这两段代码对应你前面看到的资源释放路径里的关键动作：在释放 vchan&#x2F;desc&#x2F;pool 之前，驱动必须把硬件通道拉回“确定停止”的状态，并清理残留中断状态，避免后续复用同一通道时出现错误触发或状态机错乱。

stm32_mdma_disable_chan：做“硬件层面的停机”，并用 原子轮询确认硬件侧认为“当前传输已完成（CTCIF 置位）”。
stm32_mdma_stop：在成功 disable 后，清掉通道的中断状态寄存器（若有残留），最后把 chan-&gt;busy 置为 false，完成“软件状态机复位”。

/** * @brief 关闭一个 MDMA 通道：先屏蔽中断，再清 EN，并以原子轮询确认硬件传输完成 * @param[in] chan 目标 MDMA 通道 * @return 成功返回 0；超时返回 -EBUSY */static int stm32_mdma_disable_chan(struct stm32_mdma_chan *chan)&#123;	/** 控制器对象，用于寄存器访问 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/** ccr：通道控制寄存器当前值；cisr：通道中断状态寄存器读取值；id：通道号；reg：CCR 寄存器地址偏移 */	u32 ccr, cisr, id, reg;	/** ret：轮询超时返回码 */	int ret;	/** 取通道号并计算该通道 CCR 寄存器偏移 */	id = chan-&gt;id;	reg = STM32_MDMA_CCR(id);	/**	 * 先屏蔽该通道所有中断：	 * 目的：停机过程中避免新的 IRQ 进入，从而扰乱“停机-确认-清状态”的序列。	 */	stm32_mdma_clr_bits(dmadev, reg, STM32_MDMA_CCR_IRQ_MASK);	/** 读取当前 CCR，判断通道是否处于使能状态 */	ccr = stm32_mdma_read(dmadev, reg);	if (ccr &amp; STM32_MDMA_CCR_EN) &#123;		/**		 * 清 EN 关闭通道：		 * 这一步是“请求停止”，但硬件可能仍在完成最后一次总线事务。		 */		stm32_mdma_clr_bits(dmadev, reg, STM32_MDMA_CCR_EN);		/**		 * 原子轮询等待传输完成标志 CTCIF：		 * - 使用 *_atomic 版本，保证在不可睡眠上下文也能调用		 * - 条件为 (cisr &amp; CTCIF) 为真		 * - 轮询间隔 10us，总超时 1000us		 *		 * 该同步点的驱动假设是：只有当硬件报告“传输完成”后，		 * 才能安全进入后续的资源释放/状态复位，避免硬件仍访问描述符或数据缓冲。		 */		ret = readl_relaxed_poll_timeout_atomic(				dmadev-&gt;base + STM32_MDMA_CISR(id), cisr,				(cisr &amp; STM32_MDMA_CISR_CTCIF), 10, 1000);		if (ret) &#123;			/** 超时：说明硬件未在期望窗口内完成，返回忙错误 */			dev_err(chan2dev(chan), &quot;%s: timeout!\n&quot;, __func__);			return -EBUSY;		&#125;	&#125;	/** 通道本就未使能或已确认完成：返回成功 */	return 0;&#125;/** * @brief 停止 MDMA 通道：关闭通道、清残留中断状态，并复位软件 busy 状态 * @param[in] chan 目标 MDMA 通道 */static void stm32_mdma_stop(struct stm32_mdma_chan *chan)&#123;	/** 控制器对象 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/** status：通道中断状态寄存器快照 */	u32 status;	/** ret：disable 返回码 */	int ret;	/** 关闭 DMA 通道（含轮询确认完成） */	ret = stm32_mdma_disable_chan(chan);	if (ret &lt; 0)		return;	/**	 * 若存在残留中断状态，则清除：	 * - 先读 CISR 得到当前挂起状态	 * - 再向 CIFCR 写入同样的位值进行清除（写 1 清除的典型风格）	 */	status = stm32_mdma_read(dmadev, STM32_MDMA_CISR(chan-&gt;id));	if (status) &#123;		dev_dbg(chan2dev(chan), &quot;%s(): clearing interrupt: 0x%08x\n&quot;,			__func__, status);		stm32_mdma_set_bits(dmadev, STM32_MDMA_CIFCR(chan-&gt;id), status);	&#125;	/** 复位软件忙状态：表示该通道已不再执行任何传输 */	chan-&gt;busy = false;&#125;

stm32_mdma_prep_dma_cyclic: 构建循环（cyclic）传输的硬件描述符链并返回可提交事务该函数把一段连续环形缓冲区（buf_addr/buf_len）按 period_len 切分为 count 个周期段，并为每个周期段生成一个硬件描述符节点（hwdesc）。最后一个节点会被配置为“循环回到起点”的语义（通过传给 stm32_mdma_setup_hwdesc() 的标志位组合实现），从而形成硬件级循环传输。vchan_tx_prep() 负责把私有 desc 挂入 virt-dma 队列体系，真正启动要等 device_issue_pending 路径。
/** * @brief 准备 cyclic 传输：把环形缓冲区按 period 切段并生成循环硬件描述符链 * @param[in] c           DMAengine 抽象通道 * @param[in] buf_addr    环形缓冲区 DMA 地址（连续区域） * @param[in] buf_len     缓冲区总长度（必须是 period_len 的整数倍） * @param[in] period_len  单个周期段长度（必须 &lt;= 硬件最大块长） * @param[in] direction   传输方向（DMA_MEM_TO_DEV / DMA_DEV_TO_MEM） * @param[in] flags       DMAengine prep flags * @return 成功返回可提交的 dma_async_tx_descriptor；失败返回 NULL */static struct dma_async_tx_descriptor *stm32_mdma_prep_dma_cyclic(struct dma_chan *c, dma_addr_t buf_addr,			   size_t buf_len, size_t period_len,			   enum dma_transfer_direction direction,			   unsigned long flags)&#123;	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);                 /**&lt; 通用通道转私有通道 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);          /**&lt; 反查控制器对象，用于寄存器/总线选择等 */	struct dma_slave_config *dma_config = &amp;chan-&gt;dma_config;             /**&lt; 外设侧配置（src_addr/dst_addr 等） */	struct stm32_mdma_chan_config *chan_config = &amp;chan-&gt;chan_config;     /**&lt; 通道级静态配置（含 m2m_hw 等） */	struct stm32_mdma_desc *desc;                                        /**&lt; 本次 cyclic 描述符（含 count 个 node） */	dma_addr_t src_addr, dst_addr;                                       /**&lt; 每段的源/目的 DMA 地址 */	u32 ccr, ctcr, ctbr, count;                                          /**&lt; CCR/CTCR/CTBR 组合字段与周期段计数 */	int i, ret;                                                          /**&lt; i：段索引；ret：错误码 */	/**	 * 若该通道已处于 cyclic 状态，则拒绝再次建立 cyclic：	 * 该约束避免“一个通道同时存在多个循环语义的描述符链”，否则状态机无法定义。	 */	if (chan-&gt;desc &amp;&amp; chan-&gt;desc-&gt;cyclic) &#123;		dev_err(chan2dev(chan),			&quot;Request not allowed when dma in cyclic mode\n&quot;);		return NULL;	&#125;	/**	 * 参数合法性：	 * - buf_len/period_len 必须非 0	 * - 单段长度不能超过硬件最大块长	 */	if (!buf_len || !period_len || period_len &gt; STM32_MDMA_MAX_BLOCK_LEN) &#123;		dev_err(chan2dev(chan), &quot;Invalid buffer/period len\n&quot;);		return NULL;	&#125;	/** 必须整除：保证能形成整数个周期段，否则循环边界无法对齐 */	if (buf_len % period_len) &#123;		dev_err(chan2dev(chan), &quot;buf_len not multiple of period_len\n&quot;);		return NULL;	&#125;	/** 周期段数量：每个周期段对应一个硬件描述符节点 */	count = buf_len / period_len;	/** 分配描述符与 count 个硬件描述符节点 */	desc = stm32_mdma_alloc_desc(chan, count);	if (!desc)		return NULL;	/**	 * 生成一次循环传输的“共用”寄存器域，并选择总线：	 * - 对 MEM_TO_DEV：源来自 buf_addr，目的通常来自 dma_config-&gt;dst_addr（外设侧）	 * - 对 DEV_TO_MEM：源通常来自 dma_config-&gt;src_addr（外设侧），目的为 buf_addr	 *	 * 此处把地址传给 set_xfer_param 的目的，是让其依据地址属性决定宽度/对齐/总线等策略。	 */	if (direction == DMA_MEM_TO_DEV) &#123;		src_addr = buf_addr;                                            /* 源为环形缓冲区起始地址 */		ret = stm32_mdma_set_xfer_param(chan, direction, &amp;ccr, &amp;ctcr,						&amp;ctbr, src_addr, period_len);		stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_SBUS,				   src_addr);	&#125; else &#123;		dst_addr = buf_addr;                                            /* 目的为环形缓冲区起始地址 */		ret = stm32_mdma_set_xfer_param(chan, direction, &amp;ccr, &amp;ctcr,						&amp;ctbr, dst_addr, period_len);		stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_DBUS,				   dst_addr);	&#125;	/** 参数推导失败则回收 desc/hwdesc */	if (ret &lt; 0)		goto xfer_setup_err;	/**	 * 配置中断使能（写入 desc-&gt;ccr，供后续启动时下发到硬件）：	 * - 先清 IRQ mask（允许中断）	 * - 再显式打开：传输错误（TE）、传输完成（CTC）、块完成（BT）中断	 *	 * cyclic 需要“周期节拍”，块完成中断通常用于 period 回调节奏。	 */	ccr &amp;= ~STM32_MDMA_CCR_IRQ_MASK;	ccr |= STM32_MDMA_CCR_TEIE | STM32_MDMA_CCR_CTCIE | STM32_MDMA_CCR_BTIE;	desc-&gt;ccr = ccr;	/**	 * 逐周期段构建硬件描述符链：	 * 每一段的 buf_addr 都按 i * period_len 递增。	 *	 * m2m_hw 特例：	 * - 使用 (i &amp; 1) 在奇偶段之间对“外设侧地址”做 period_len 偏移	 * - 其效果等价于在两个地址之间做 ping-pong（双缓冲/双地址节拍）	 * - 该偏移的意义取决于“上游触发源（STM32 DMA）如何装填/切换地址”的协同约定	 */	for (i = 0; i &lt; count; i++) &#123;		if (direction == DMA_MEM_TO_DEV) &#123;			src_addr = buf_addr + i * period_len;                        /* 源：环形缓冲区第 i 段 */			dst_addr = dma_config-&gt;dst_addr;                             /* 目的：外设侧地址（默认固定） */			if (chan_config-&gt;m2m_hw &amp;&amp; (i &amp; 1))				dst_addr += period_len;                                   /* m2m_hw：奇数段偏移，形成双地址节拍 */		&#125; else &#123;			src_addr = dma_config-&gt;src_addr;                             /* 源：外设侧地址（默认固定） */			if (chan_config-&gt;m2m_hw &amp;&amp; (i &amp; 1))				src_addr += period_len;                                   /* m2m_hw：奇数段偏移，形成双地址节拍 */			dst_addr = buf_addr + i * period_len;                        /* 目的：环形缓冲区第 i 段 */		&#125;		/**		 * 写入第 i 个硬件描述符：		 * - src/dst/len：该段的搬运参数		 * - ctcr/ctbr：共用配置域		 * - i == count - 1：标记最后一段（用于建立“回环到首段”或设置末段标志）		 * - i == 0：标记首段（用于首段初始化差异）		 * - true：表示这是 cyclic 链（由下层据此写入循环相关控制位/next 指针策略）		 */		stm32_mdma_setup_hwdesc(chan, desc, direction, i, src_addr,					dst_addr, period_len, ctcr, ctbr,					i == count - 1, i == 0, true);	&#125;	/** 标记该描述符为 cyclic 描述符，后续提交/终止路径将按 cyclic 语义处理 */	desc-&gt;cyclic = true;	/** 交给 virt-dma：生成通用 tx 描述符并入队，等待 issue_pending 启动 */	return vchan_tx_prep(&amp;chan-&gt;vchan, &amp;desc-&gt;vdesc, flags);xfer_setup_err:	/**	 * 失败回收：	 * - 逐段归还 hwdesc 到 pool	 * - 释放 desc 本体	 */	for (i = 0; i &lt; desc-&gt;count; i++)		dma_pool_free(chan-&gt;desc_pool, desc-&gt;node[i].hwdesc,			      desc-&gt;node[i].hwdesc_phys);	kfree(desc);	return NULL;&#125;


1) 为什么 if (chan_config-&gt;m2m_hw &amp;&amp; (i &amp; 1)) src_addr +&#x3D; period_len; 要这么做？在 m2m_hw 模式下，这里的 (i &amp; 1)（奇偶段）+ +&#x3D; period_len 本质是在做乒乓（ping-pong）双地址：
偶数段 i&#x3D;0,2,4…：用基地址 src_addr &#x3D; base
奇数段 i&#x3D;1,3,5…：用第二个地址 src_addr &#x3D; base + period_len
目的不是“让地址更连续”这么简单，而是让循环的每个 period 在两个地址之间交替，从而匹配一种常见协同模式：上游触发源（例如另一个 DMA&#x2F;硬件节拍）往往以“半周期&#x2F;周期”为节奏在两块缓冲区之间切换。MDMA 的 cyclic 描述符链也必须跟着交替，否则你会出现：
每个 period 都搬同一块源&#x2F;目的地址，导致另一块缓冲区永远不被消费&#x2F;填充；
或者上游以双缓冲产出数据，而下游 MDMA 只读其中一块，形成节拍错位。
所以这行代码表达的是：m2m_hw 时，把“外设侧（在框架里叫 dev 侧）”当成两个交替地址使用，用 period_len 作为两块区域的固定偏移量。
你这个质疑点非常关键：不是所有 DMA 都只会“按连续地址搬运”。STM32H7 的 MDMA 明确支持一种硬件级“linked-list mode（链表&#x2F;列表模式）”，它让硬件在完成一个块（block）后，自己去内存里读取下一组“通道寄存器配置”，从而继续搬运下一段（下一段可以是完全不同的源&#x2F;目的地址与长度）。
硬件为什么会“按链表推进”？要把两类“地址”分清楚：

数据搬运地址（SAR&#x2F;DAR）这是你说的“DMA 按连续地址搬运”的那部分：在单个块内，MDMA 根据 SAR（源地址）&#x2F;DAR（目的地址）以及增量模式，把数据搬完这一段。

描述符&#x2F;配置地址（CxLAR 指向的内存结构）在 MDMA linked-list mode 下，硬件在块传输结束时会触发一个机制：

读取 MDMA_CxLAR（Channel x Link Address Register）里给出的地址；
把该地址指向的一段内存当作“一个 node（节点）”，从里面重新装载一组 MDMA 通道配置寄存器值（包括 CxTCR, CxBNDTR, CxSAR, CxDAR, ... , CxLAR, ... 等）；
其中 CxLAR 自身也会被重载：如果新装载的 CxLAR != 0，硬件就认为“还有下一个节点”，继续在下一个块结束时再装载；如果为 0 就停止；如果两个节点互相指向，就形成硬件环形循环。 ([STMicroelectronics][1])



所以：硬件并不是“看不懂链表”。它是通过专门的寄存器 CxLAR把“下一次要装载的配置结构”挂到一个内存地址上；然后硬件作为总线 master 去读这段内存，更新自身寄存器，再按新的 SAR/DAR/BNDTR/... 继续搬下一段。 ([STMicroelectronics][1])

你说的“DMA 只能连续地址”是最基础 DMA的能力；MDMA 这种更复杂的控制器支持“搬运数据的同时，还能从内存装载下一段配置”，因此可以实现非连续段的自动推进。

stm32_mdma_set_bus: 根据地址高位选择 SBUS&#x2F;DBUS 所在总线这个函数只做一件事：根据“地址的高 4bit（0xF0000000 掩码）”判断该地址属于哪类内存窗口，然后把 CTBR 里由 ctbr_mask 指定的那个位域置位或清零，从而选择 MDMA 的源&#x2F;目的总线（SBUS&#x2F;DBUS）是走 AHB 还是 AXI。其判断依据来自 dmadev-&gt;ahb_addr_masks[]（probe 阶段从设备树属性填充）。
/** * @brief 根据地址窗口配置 CTBR 中的 SBUS/DBUS 总线选择位 * @param[in]  dmadev     MDMA 控制器实例，提供 AHB 地址窗口掩码表 * @param[in,out] ctbr    指向将被修改的 CTBR 值（软件构造的寄存器镜像） * @param[in]  ctbr_mask  需要配置的位域掩码（例如 STM32_MDMA_CTBR_SBUS/DBUS） * @param[in]  src_addr   用于判断地址窗口的 32bit 地址（这里按 0xF0000000 做分类） */static void stm32_mdma_set_bus(struct stm32_mdma_device *dmadev, u32 *ctbr,			       u32 ctbr_mask, u32 src_addr)&#123;	u32 mask;                                             /**&lt; 地址窗口掩码后的高位结果 */	int i;                                                /**&lt; 遍历 ahb_addr_masks[] 的索引 */	*ctbr &amp;= ~ctbr_mask;                                   /* 清掉目标位域：默认选择 AXI 或默认态 */	mask = src_addr &amp; 0xF0000000;                          /* 取地址高 4bit：用作“窗口分类键” */	for (i = 0; i &lt; dmadev-&gt;nr_ahb_addr_masks; i++) &#123;       /* 遍历设备树提供的 AHB 窗口集合 */		if (mask == dmadev-&gt;ahb_addr_masks[i]) &#123;            /* 命中：该窗口属于 AHB */			*ctbr |= ctbr_mask;                             /* 置位：选择 AHB（由硬件位语义决定） */			break;                                          /* 首次命中即可退出 */		&#125;	&#125;&#125;


stm32_mdma_set_xfer_param: 计算并回填一次传输所需的 CCR&#x2F;CTCR&#x2F;CTBR，并预置 CSAR&#x2F;CDAR这个函数的价值在于它做了**“把上层抽象参数（width&#x2F;burst&#x2F;request&#x2F;transfer_config&#x2F;buf_len）收敛成 MDMA 寄存器字段”**的工作，核心点有三类：

TLEN 的“写入值&#x3D;字节数-1”：从 CTCR 里取出 LEN2，再写回 TLEN(tlen-1)，这是硬件编码规则，不是软件习惯。
burst 与 width 的组合约束：强制 maxburst * buswidth &lt;= STM32_MDMA_MAX_BURST，并且 maxburst 必须是 2 的幂；否则直接拒绝。
当源&#x2F;目的数据宽度不一致时启用 PKE（pack）：避免宽度不一致导致的硬件对齐&#x2F;吞吐问题，由硬件 pack 逻辑完成数据重排。

它还会根据方向（DMA_MEM_TO_DEV &#x2F; DMA_DEV_TO_MEM）：

计算 设备侧与内存侧各自的 SIZE/INCOS/BURST；
配置 CTBR.TSEL（请求线）；
调 stm32_mdma_set_bus() 选择 SBUS&#x2F;DBUS；
直接写入本通道 CSAR 或 CDAR，把源&#x2F;目的地址预置到通道寄存器中。

/** * @brief 依据方向与配置计算 MDMA 的 CCR/CTCR/CTBR，并配置通道地址寄存器 * @param[in]  chan       MDMA 通道私有对象 * @param[in]  direction  DMA 传输方向（仅支持 MEM_TO_DEV / DEV_TO_MEM） * @param[out] mdma_ccr   回填的 CCR 软件镜像 * @param[out] mdma_ctcr  回填的 CTCR 软件镜像 * @param[out] mdma_ctbr  回填的 CTBR 软件镜像 * @param[in]  addr       “内存侧”起始地址（dma_addr_t） * @param[in]  buf_len    本次传输总长度（字节） * @return 0 表示成功；负值表示参数不合法或宽度计算失败 */static int stm32_mdma_set_xfer_param(struct stm32_mdma_chan *chan,				     enum dma_transfer_direction direction,				     u32 *mdma_ccr, u32 *mdma_ctcr,				     u32 *mdma_ctbr, dma_addr_t addr,				     u32 buf_len)&#123;	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);          /**&lt; 控制器实例：寄存器访问与全局能力 */	struct stm32_mdma_chan_config *chan_config = &amp;chan-&gt;chan_config;     /**&lt; 通道静态配置：request/priority/transfer_config/m2m_hw */	enum dma_slave_buswidth src_addr_width, dst_addr_width;             /**&lt; 源/目的地址对应的总线宽度枚举 */	phys_addr_t src_addr, dst_addr;                                      /**&lt; 设备侧地址（这里用 phys_addr_t 承载） */	int src_bus_width, dst_bus_width;                                    /**&lt; 转成 MDMA 寄存器编码后的 width 值（非字节数） */	u32 src_maxburst, dst_maxburst, src_best_burst, dst_best_burst;      /**&lt; burst 上限与“最佳 burst”选择结果 */	u32 ccr, ctcr, ctbr, tlen;                                           /**&lt; 寄存器镜像与 TLEN 中间变量 */	src_addr_width = chan-&gt;dma_config.src_addr_width;                    /* 读取上层配置：源宽度 */	dst_addr_width = chan-&gt;dma_config.dst_addr_width;                    /* 读取上层配置：目的宽度 */	src_maxburst = chan-&gt;dma_config.src_maxburst;                        /* 读取上层配置：源 burst */	dst_maxburst = chan-&gt;dma_config.dst_maxburst;                        /* 读取上层配置：目的 burst */	ccr = stm32_mdma_read(dmadev, STM32_MDMA_CCR(chan-&gt;id)) &amp; ~STM32_MDMA_CCR_EN; /* 取当前 CCR，并确保软件镜像里 EN 清零 */	ctcr = stm32_mdma_read(dmadev, STM32_MDMA_CTCR(chan-&gt;id));            /* 取当前 CTCR 作为基线 */	ctbr = stm32_mdma_read(dmadev, STM32_MDMA_CTBR(chan-&gt;id));            /* 取当前 CTBR 作为基线 */	ctcr &amp;= ~STM32_MDMA_CTCR_SWRM;                                        /* 选择硬件请求模式：清 SWRM */	ctcr &amp;= ~STM32_MDMA_CTCR_CFG_MASK;                                    /* 清掉可配置字段位域 */	ctcr |= chan_config-&gt;transfer_config &amp; STM32_MDMA_CTCR_CFG_MASK;      /* 应用设备树/通道配置给出的 DINC/SINC/INCOS/TRGM/TLEN 等 */	tlen = STM32_MDMA_CTCR_LEN2_GET(ctcr);                                /* 取 LEN2（“每个 buffer chunk 的长度”语义） */	ctcr &amp;= ~STM32_MDMA_CTCR_LEN2_MSK;                                    /* 清 LEN2 位域 */	ctcr |= STM32_MDMA_CTCR_TLEN((tlen - 1));                             /* 写 TLEN：硬件编码要求写 (字节数 - 1) */	ctcr &amp;= ~STM32_MDMA_CTCR_PKE;                                         /* 默认禁用 pack：只有宽度不一致时才启用 */	if (src_maxburst * src_addr_width &gt; STM32_MDMA_MAX_BURST ||           /* 约束：burst*width 不得超过硬件上限 */	    dst_maxburst * dst_addr_width &gt; STM32_MDMA_MAX_BURST) &#123;		dev_err(chan2dev(chan),			&quot;burst size * bus width higher than %d bytes\n&quot;,			STM32_MDMA_MAX_BURST);		return -EINVAL;                                                  /* 参数不合法：拒绝配置 */	&#125;	if ((!is_power_of_2(src_maxburst) &amp;&amp; src_maxburst &gt; 0) ||             /* 约束：burst 必须是 2 的幂（或为 0 表示未指定） */	    (!is_power_of_2(dst_maxburst) &amp;&amp; dst_maxburst &gt; 0)) &#123;		dev_err(chan2dev(chan), &quot;burst size must be a power of 2\n&quot;);		return -EINVAL;                                                  /* 参数不合法：拒绝配置 */	&#125;	ccr &amp;= ~(STM32_MDMA_CCR_SWRQ | STM32_MDMA_CCR_WEX | STM32_MDMA_CCR_HEX | /* 硬件请求：清 SWRQ；并清异常注入相关位 */		 STM32_MDMA_CCR_BEX | STM32_MDMA_CCR_PL_MASK);                   /* 清优先级位域：准备重写 */	ccr |= STM32_MDMA_CCR_PL(chan_config-&gt;priority_level);               /* 写入通道优先级 */	ctbr &amp;= ~STM32_MDMA_CTBR_TSEL_MASK;                                   /* 清触发选择 */	ctbr |= STM32_MDMA_CTBR_TSEL(chan_config-&gt;request);                  /* 写入 request line：决定由哪个硬件请求触发 */	switch (direction) &#123;	case DMA_MEM_TO_DEV:		dst_addr = chan-&gt;dma_config.dst_addr;                             /* 设备侧目的地址：来自 slave_config */		if (chan_config-&gt;m2m_hw)                                          /* 特殊：STM32 DMA 触发 MDMA 的“硬件 M2M”模式 */			dst_addr_width = stm32_mdma_get_max_width(dst_addr, buf_len,								  STM32_MDMA_MAX_BUF_LEN); /* 设备侧宽度按地址/长度推导 */		dst_bus_width = stm32_mdma_get_width(chan, dst_addr_width);        /* 把 buswidth 枚举转成寄存器编码 */		if (dst_bus_width &lt; 0)			return dst_bus_width;                                          /* 宽度不支持：直接失败 */		ctcr &amp;= ~STM32_MDMA_CTCR_DSIZE_MASK;                               /* 清目的数据宽度位域 */		ctcr |= STM32_MDMA_CTCR_DSIZE(dst_bus_width);                      /* 写目的数据宽度 */		if (chan_config-&gt;m2m_hw) &#123;                                         /* 硬件 M2M：目的地址也需要 INCOS */			ctcr &amp;= ~STM32_MDMA_CTCR_DINCOS_MASK;                           /* 清目的 INCOS */			ctcr |= STM32_MDMA_CTCR_DINCOS(dst_bus_width);                  /* 目的 INCOS 与数据宽度一致 */		&#125;		if (chan_config-&gt;m2m_hw)                                           /* 硬件 M2M：目的侧 burst 取最大可用 */			dst_maxburst = STM32_MDMA_MAX_BUF_LEN / dst_addr_width;		dst_best_burst = stm32_mdma_get_best_burst(buf_len, tlen,           /* 根据 buf_len 与 tlen 选最合适的 burst */							  dst_maxburst,							  dst_addr_width);		chan-&gt;mem_burst = dst_best_burst;                                  /* 记录：后续可能用于调试/路径判断 */		ctcr &amp;= ~STM32_MDMA_CTCR_DBURST_MASK;                               /* 清目的 burst 位域 */		ctcr |= STM32_MDMA_CTCR_DBURST((ilog2(dst_best_burst)));            /* 写目的 burst：用 log2 编码 */		src_addr_width = stm32_mdma_get_max_width(addr, buf_len, tlen);     /* 内存侧宽度推导：尽量使用更宽以提升吞吐 */		chan-&gt;mem_width = src_addr_width;                                  /* 记录：内存侧 width */		src_bus_width = stm32_mdma_get_width(chan, src_addr_width);        /* width 枚举 -&gt; 寄存器编码 */		if (src_bus_width &lt; 0)			return src_bus_width;		ctcr &amp;= ~STM32_MDMA_CTCR_SSIZE_MASK |			STM32_MDMA_CTCR_SINCOS_MASK;                                    /* 清源侧数据宽度与 INCOS */		ctcr |= STM32_MDMA_CTCR_SSIZE(src_bus_width) |			STM32_MDMA_CTCR_SINCOS(src_bus_width);                          /* 源侧：宽度 + 递增步长（INCOS） */		src_maxburst = STM32_MDMA_MAX_BUF_LEN / src_addr_width;            /* 内存侧最大 burst：由硬件上限/宽度决定 */		src_best_burst = stm32_mdma_get_best_burst(buf_len, tlen,							  src_maxburst,							  src_addr_width);		chan-&gt;mem_burst = src_best_burst;                                  /* 记录：内存侧 burst */		ctcr &amp;= ~STM32_MDMA_CTCR_SBURST_MASK;                               /* 清源 burst */		ctcr |= STM32_MDMA_CTCR_SBURST((ilog2(src_best_burst)));            /* 写源 burst */		stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_DBUS, dst_addr);  /* 目的侧（设备侧）挂在 DBUS：按地址窗口选 AHB/AXI */		if (dst_bus_width != src_bus_width)                                /* 宽度不一致：打开 pack 由硬件完成重排 */			ctcr |= STM32_MDMA_CTCR_PKE;		stm32_mdma_write(dmadev, STM32_MDMA_CDAR(chan-&gt;id), dst_addr);      /* 预置目的地址寄存器：设备侧地址 */		break;	case DMA_DEV_TO_MEM:		src_addr = chan-&gt;dma_config.src_addr;                              /* 设备侧源地址：来自 slave_config */		if (chan_config-&gt;m2m_hw)                                          /* 硬件 M2M：源侧宽度按地址/长度推导 */			src_addr_width = stm32_mdma_get_max_width(src_addr, buf_len,								  STM32_MDMA_MAX_BUF_LEN);		src_bus_width = stm32_mdma_get_width(chan, src_addr_width);        /* width 枚举 -&gt; 寄存器编码 */		if (src_bus_width &lt; 0)			return src_bus_width;		ctcr &amp;= ~STM32_MDMA_CTCR_SSIZE_MASK;                               /* 清源数据宽度 */		ctcr |= STM32_MDMA_CTCR_SSIZE(src_bus_width);                      /* 写源数据宽度 */		if (chan_config-&gt;m2m_hw) &#123;                                         /* 硬件 M2M：源侧也需要 INCOS */			ctcr &amp;= ~STM32_MDMA_CTCR_SINCOS_MASK;			ctcr |= STM32_MDMA_CTCR_SINCOS(src_bus_width);		&#125;		if (chan_config-&gt;m2m_hw)                                           /* 硬件 M2M：源侧 burst 取最大可用 */			src_maxburst = STM32_MDMA_MAX_BUF_LEN / src_addr_width;		src_best_burst = stm32_mdma_get_best_burst(buf_len, tlen,							  src_maxburst,							  src_addr_width);		ctcr &amp;= ~STM32_MDMA_CTCR_SBURST_MASK;                               /* 清源 burst */		ctcr |= STM32_MDMA_CTCR_SBURST((ilog2(src_best_burst)));            /* 写源 burst */		dst_addr_width = stm32_mdma_get_max_width(addr, buf_len, tlen);     /* 内存侧目的宽度推导 */		chan-&gt;mem_width = dst_addr_width;                                  /* 记录：内存侧 width */		dst_bus_width = stm32_mdma_get_width(chan, dst_addr_width);        /* width 枚举 -&gt; 寄存器编码 */		if (dst_bus_width &lt; 0)			return dst_bus_width;		ctcr &amp;= ~(STM32_MDMA_CTCR_DSIZE_MASK |			  STM32_MDMA_CTCR_DINCOS_MASK);                                /* 清目的宽度与 INCOS */		ctcr |= STM32_MDMA_CTCR_DSIZE(dst_bus_width) |			STM32_MDMA_CTCR_DINCOS(dst_bus_width);                          /* 目的侧：宽度 + 递增步长 */		dst_maxburst = STM32_MDMA_MAX_BUF_LEN / dst_addr_width;            /* 内存侧最大 burst */		dst_best_burst = stm32_mdma_get_best_burst(buf_len, tlen,							  dst_maxburst,							  dst_addr_width);		ctcr &amp;= ~STM32_MDMA_CTCR_DBURST_MASK;                               /* 清目的 burst */		ctcr |= STM32_MDMA_CTCR_DBURST((ilog2(dst_best_burst)));            /* 写目的 burst */		stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_SBUS, src_addr);  /* 源侧（设备侧）挂在 SBUS：按地址窗口选 AHB/AXI */		if (dst_bus_width != src_bus_width)                                /* 宽度不一致：打开 pack */			ctcr |= STM32_MDMA_CTCR_PKE;		stm32_mdma_write(dmadev, STM32_MDMA_CSAR(chan-&gt;id), src_addr);      /* 预置源地址寄存器：设备侧地址 */		break;	default:		dev_err(chan2dev(chan), &quot;Dma direction is not supported\n&quot;);       /* 该 helper 明确不处理其它方向 */		return -EINVAL;	&#125;	*mdma_ccr = ccr;                                                       /* 回填 CCR 镜像：供上层写硬件或写描述符 */	*mdma_ctcr = ctcr;                                                     /* 回填 CTCR 镜像 */	*mdma_ctbr = ctbr;                                                     /* 回填 CTBR 镜像 */	return 0;                                                               /* 成功 */&#125;


stm32_mdma_setup_hwdesc: 填充一个硬件描述符并串接到下一节点（或回环）这里的“链表”不是 CPU 的 struct list_head，而是硬件描述符链：每个 struct stm32_mdma_hwdesc 在内存里有一个字段 clar，驱动把“下一个描述符的物理地址”写进 clar：

非最后节点：clar = desc-&gt;node[next].hwdesc_phys

最后节点：

循环：clar = desc-&gt;node[0].hwdesc_phys（回到头结点形成环）
非循环：clar = 0（链结束）



硬件在完成当前节点后，会通过总线主接口去读取 clar 指向的下一描述符内容，从而实现“自动推进”。因此：

stm32_mdma_setup_hwdesc() 确实能配置多个；上限不在“函数”，而在于：

你一次性为 desc-&gt;node[] 分配了多少个 hwdesc（内存资源上限）；
每个节点的 BNDT&#x2F;块长度受硬件字段宽度和驱动约束限制（例如 STM32_MDMA_MAX_BLOCK_LEN 之类的上游检查）。


这些节点保存在 desc-&gt;node[i].hwdesc 指向的 DMA coherent 内存块里（由 dma_pool_alloc 分配），并且每个节点都对应一个总线可见的 hwdesc_phys。


/** * @brief 构造一个 MDMA 硬件描述符节点，并设置 CLAR 指向下一节点/回环/结束 * @param[in] chan       MDMA 通道 * @param[in] desc       软件描述符（包含 node[]，每个 node 持有一个 hwdesc 与其物理地址） * @param[in] dir        方向（此处主要用于调用方语义，当前函数不分支处理） * @param[in] count      当前节点索引 * @param[in] src_addr   本节点源地址（写入 CSAR） * @param[in] dst_addr   本节点目的地址（写入 CDAR） * @param[in] len        本节点传输长度（写入 BNDT） * @param[in] ctcr       本节点 CTCR 预配置值 * @param[in] ctbr       本节点 CTBR 预配置值 * @param[in] is_last    是否为最后一个节点 * @param[in] is_first   是否为第一个节点（当前实现未使用，但保留参数用于调用方一致性） * @param[in] is_cyclic  是否构造成循环链表（最后节点回指到 0 号节点） */static void stm32_mdma_setup_hwdesc(struct stm32_mdma_chan *chan,				   struct stm32_mdma_desc *desc,				   enum dma_transfer_direction dir, u32 count,				   dma_addr_t src_addr, dma_addr_t dst_addr,				   u32 len, u32 ctcr, u32 ctbr, bool is_last,				   bool is_first, bool is_cyclic)&#123;	struct stm32_mdma_chan_config *config = &amp;chan-&gt;chan_config;          /**&lt; 通道静态配置：mask_addr/mask_data 等 */	struct stm32_mdma_hwdesc *hwdesc;                                     /**&lt; 当前要填的硬件描述符指针 */	u32 next = count + 1;                                                 /**&lt; 计算下一个节点索引 */	hwdesc = desc-&gt;node[count].hwdesc;                                    /* 取出当前节点的 hwdesc（coherent 内存） */	hwdesc-&gt;ctcr = ctcr;                                                  /* 写 CTCR：本节点传输控制参数 */	hwdesc-&gt;cbndtr &amp;= ~(STM32_MDMA_CBNDTR_BRC_MK |                         /* 清除 BNDT/重复/累加相关位域：重新写本节点长度 */			    STM32_MDMA_CBNDTR_BRDUM |			    STM32_MDMA_CBNDTR_BRSUM |			    STM32_MDMA_CBNDTR_BNDT_MASK);	hwdesc-&gt;cbndtr |= STM32_MDMA_CBNDTR_BNDT(len);                         /* 写 BNDT：本节点块长度 */	hwdesc-&gt;csar = src_addr;                                              /* 写源地址 */	hwdesc-&gt;cdar = dst_addr;                                              /* 写目的地址 */	hwdesc-&gt;cbrur = 0;                                                    /* 复位重复相关寄存器字段（本驱动该路径固定为 0） */	hwdesc-&gt;ctbr = ctbr;                                                  /* 写 CTBR：触发选择与总线选择等 */	hwdesc-&gt;cmar = config-&gt;mask_addr;                                     /* 写地址掩码（用于特定硬件触发/屏蔽语义） */	hwdesc-&gt;cmdr = config-&gt;mask_data;                                     /* 写数据掩码 */	if (is_last) &#123;                                                        /* 最后一个节点：决定“回环/结束” */		if (is_cyclic)			hwdesc-&gt;clar = desc-&gt;node[0].hwdesc_phys;                      /* 循环：CLAR 指向首节点物理地址，形成硬件环 */		else			hwdesc-&gt;clar = 0;                                              /* 非循环：CLAR=0 表示链结束 */	&#125; else &#123;		hwdesc-&gt;clar = desc-&gt;node[next].hwdesc_phys;                       /* 非最后：CLAR 指向下一个节点物理地址 */	&#125;	stm32_mdma_dump_hwdesc(chan, &amp;desc-&gt;node[count]);                      /* 调试输出：打印该节点的关键字段 */&#125;

stm32_mdma_prep_dma_memcpy: 为 DMAengine 的 memcpy 请求构建 STM32 MDMA 硬件描述符并返回可提交的事务描述符这个函数实现 dma_device.device_prep_dma_memcpy 回调：把一次“内存到内存”的复制请求（src→dest，长度 len）转换为 STM32 MDMA 可执行的硬件描述符（单段或链表），并封装为 virt-dma 的 dma_async_tx_descriptor 返回给上层，供后续 issue_pending 真正启动。([codebrowser.dev][1])
核心实现原理
两级分解策略（决定触发模式 TRGM）

len &lt;= STM32_MDMA_MAX_BLOCK_LEN：使用“单描述符”路径；再根据 len &lt;= STM32_MDMA_MAX_BUF_LEN 选择 BUFFER 或 BLOCK 触发模式。([codebrowser.dev][1])
len &gt; STM32_MDMA_MAX_BLOCK_LEN：使用 LINKED_LIST（链表）模式，把传输拆成 count = DIV_ROUND_UP(len, MAX_BLOCK_LEN) 个节点，每节点最多 MAX_BLOCK_LEN。([codebrowser.dev][1])


带宽&#x2F;对齐驱动的参数选择（宽度与突发）通过 stm32_mdma_get_max_width() 与 stm32_mdma_get_best_burst() 在 tlen 约束下计算“可行最大宽度”和“最优 burst”，再用 ilog2(best_burst) 写入 CTCR 的 SBURST/DBURST 字段；同时把 SSIZE/DSIZE 与 SINCOS/DINCOS 配套设置。([codebrowser.dev][1])当源&#x2F;目的总线宽度不同，置位 PKE（pack&#x2F;unpack），由硬件在搬运过程中做字节打包&#x2F;解包。([codebrowser.dev][1])

寄存器“清理 + 重建”式编程读取当前通道寄存器镜像（CCR&#x2F;CTCR&#x2F;CTBR&#x2F;CBNDTR），显式清除与 memcpy 无关或可能污染的位域（例如硬件触发选择、优先级、地址掩码&#x2F;写回等），再只保留 memcpy 路径必需的配置：软件请求模式、地址自增、异常&#x2F;完成中断选择、总线选择等。([codebrowser.dev][1])


/** * stm32_mdma_prep_dma_memcpy - 为 DMAengine memcpy 请求准备 STM32 MDMA 事务描述符 * @c:       DMAengine 抽象通道指针（驱动会转换为 stm32_mdma_chan） * @dest:    目的 DMA 总线地址（dma_addr_t） * @src:     源 DMA 总线地址（dma_addr_t） * @len:     需要复制的字节数 * @flags:   DMAengine 事务标志（例如 DMA_PREP_INTERRUPT 等） * * 返回值： * 成功：返回可提交的 dma_async_tx_descriptor 指针（virt-dma 封装） * 失败：返回 NULL */static struct dma_async_tx_descriptor *stm32_mdma_prep_dma_memcpy(struct dma_chan *c, dma_addr_t dest, dma_addr_t src,			   size_t len, unsigned long flags)&#123;	/* 将通用 dma_chan 转为驱动私有通道对象，后续需要访问 id/vchan/desc 等字段 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/* 从通道反推出控制器实例（寄存器基址、能力、资源等都归属该实例） */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/* 记录“当前可用的最大总线宽度”，用于后续选择 SSIZE/DSIZE */	enum dma_slave_buswidth max_width;	/* 本次事务的驱动私有描述符对象（包含 vdesc + node[] 硬件描述符） */	struct stm32_mdma_desc *desc;	/* 直接指向第一个硬件描述符（单段路径会直接写 node[0]） */	struct stm32_mdma_hwdesc *hwdesc;	/* CCR/CTCR/CTBR/CBNDTR 为通道关键寄存器组合；count 为链表节点数 */	u32 ccr, ctcr, ctbr, cbndtr, count, max_burst, mdma_burst;	/* best_burst 为“最优突发长度（以 beat 计）”，tlen 为缓冲传输长度参数 */	u32 best_burst, tlen;	/* xfer_count 为每个节点的实际搬运长度；offset 为节点内偏移 */	size_t xfer_count, offset;	/* 源/目的侧的“硬件编码后的宽度枚举值”（写入 CTCR 的 SSIZE/DSIZE） */	int src_bus_width, dst_bus_width;	/* 通用循环变量 */	int i;	/* 若通道当前被配置为 cyclic，则该驱动禁止再用此通道承载新的 memcpy 请求 */	if (chan-&gt;desc &amp;&amp; chan-&gt;desc-&gt;cyclic) &#123;		dev_err(chan2dev(chan),			&quot;Request not allowed when dma in cyclic mode\n&quot;);		return NULL;	&#125;	/* 链表节点数：每个节点最大承载 STM32_MDMA_MAX_BLOCK_LEN 字节 */	count = DIV_ROUND_UP(len, STM32_MDMA_MAX_BLOCK_LEN);	/* 分配驱动描述符，并为每个节点从 DMA pool 申请硬件描述符缓冲 */	desc = stm32_mdma_alloc_desc(chan, count);	if (!desc)		return NULL;	/* 读取当前硬件寄存器值并基于其“清理/重建”；CCR 需要确保 EN=0（未使能） */	ccr = stm32_mdma_read(dmadev, STM32_MDMA_CCR(chan-&gt;id)) &amp; ~STM32_MDMA_CCR_EN;	ctcr = stm32_mdma_read(dmadev, STM32_MDMA_CTCR(chan-&gt;id));	ctbr = stm32_mdma_read(dmadev, STM32_MDMA_CTBR(chan-&gt;id));	cbndtr = stm32_mdma_read(dmadev, STM32_MDMA_CBNDTR(chan-&gt;id));	/* 使能必要的异常中断并清除与 memcpy 无关的位域（优先级/异常屏蔽/IRQ 选择等） */	ccr &amp;= ~(STM32_MDMA_CCR_WEX | STM32_MDMA_CCR_HEX |		 STM32_MDMA_CCR_BEX | STM32_MDMA_CCR_PL_MASK |		 STM32_MDMA_CCR_IRQ_MASK);	ccr |= STM32_MDMA_CCR_TEIE;	/* 设置软件请求模式 + 源/目的地址自增；同时清理触发模式、宽度、突发、偏移等位域 */	ctcr &amp;= ~(STM32_MDMA_CTCR_BWM | STM32_MDMA_CTCR_TRGM_MSK |		  STM32_MDMA_CTCR_PAM_MASK | STM32_MDMA_CTCR_PKE |		  STM32_MDMA_CTCR_TLEN_MSK | STM32_MDMA_CTCR_DBURST_MASK |		  STM32_MDMA_CTCR_SBURST_MASK | STM32_MDMA_CTCR_DINCOS_MASK |		  STM32_MDMA_CTCR_SINCOS_MASK | STM32_MDMA_CTCR_DSIZE_MASK |		  STM32_MDMA_CTCR_SSIZE_MASK | STM32_MDMA_CTCR_DINC_MASK |		  STM32_MDMA_CTCR_SINC_MASK);	ctcr |= STM32_MDMA_CTCR_SWRM |		STM32_MDMA_CTCR_SINC(STM32_MDMA_INC) |		STM32_MDMA_CTCR_DINC(STM32_MDMA_INC);	/* 清空硬件触发选择（TSEL），确保走软件请求/链表触发语义 */	ctbr &amp;= ~STM32_MDMA_CTBR_TSEL_MASK;	/* 选择源/目的侧总线类型（依据地址范围：AHB/AXI/TCM 等，由 set_bus 内部判定/编码） */	stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_SBUS, src);	stm32_mdma_set_bus(dmadev, &amp;ctbr, STM32_MDMA_CTBR_DBUS, dest);	/* 清理 CBNDTR 中与块/缓冲/重复相关的字段，准备重新写 BNDT/BRC 等 */	cbndtr &amp;= ~(STM32_MDMA_CBNDTR_BRC_MK | STM32_MDMA_CBNDTR_BRDUM |		    STM32_MDMA_CBNDTR_BRSUM | STM32_MDMA_CBNDTR_BNDT_MASK);	/* -------- 路径 1：len 不超过单个“块”的最大长度，可用单硬件描述符完成 -------- */	if (len &lt;= STM32_MDMA_MAX_BLOCK_LEN) &#123;		/* BNDT：本次块内需要搬运的字节数 */		cbndtr |= STM32_MDMA_CBNDTR_BNDT(len);		/* 根据 len 是否超过“缓冲最大长度”选择 BUFFER 或 BLOCK 触发模式 */		if (len &lt;= STM32_MDMA_MAX_BUF_LEN) &#123;			/* 缓冲传输：通常以“传输完成”中断作为主要完成通知 */			ccr |= STM32_MDMA_CCR_TCIE | STM32_MDMA_CCR_CTCIE;			ctcr |= STM32_MDMA_CTCR_TRGM(STM32_MDMA_BUFFER);		&#125; else &#123;			/* 块传输：以“块完成”中断推进（配合 CTCIE 用于链表/上下文完成语义） */			ccr |= STM32_MDMA_CCR_BTIE | STM32_MDMA_CCR_CTCIE;			ctcr |= STM32_MDMA_CTCR_TRGM(STM32_MDMA_BLOCK);		&#125;		/* TLEN：配置缓冲长度参数；此处固定取 MAX_BUF_LEN 并按硬件定义写 (tlen-1) */		tlen = STM32_MDMA_MAX_BUF_LEN;		ctcr |= STM32_MDMA_CTCR_TLEN((tlen - 1));		/* -------- 计算并配置源侧最优宽度与突发 -------- */		max_width = stm32_mdma_get_max_width(src, len, tlen);     /* 可行最大宽度（考虑对齐与长度） */		src_bus_width = stm32_mdma_get_width(chan, max_width);   /* 宽度枚举 -&gt; 硬件编码 */		max_burst = tlen / max_width;                            /* 在 tlen 约束下的最大 burst beat 数 */		best_burst = stm32_mdma_get_best_burst(len, tlen, max_burst, max_width);		mdma_burst = ilog2(best_burst);                          /* 硬件 burst 字段用 log2 编码 */		ctcr |= STM32_MDMA_CTCR_SBURST(mdma_burst) |			STM32_MDMA_CTCR_SSIZE(src_bus_width) |			STM32_MDMA_CTCR_SINCOS(src_bus_width);		/* -------- 计算并配置目的侧最优宽度与突发 -------- */		max_width = stm32_mdma_get_max_width(dest, len, tlen);		dst_bus_width = stm32_mdma_get_width(chan, max_width);		max_burst = tlen / max_width;		best_burst = stm32_mdma_get_best_burst(len, tlen, max_burst, max_width);		mdma_burst = ilog2(best_burst);		ctcr |= STM32_MDMA_CTCR_DBURST(mdma_burst) |			STM32_MDMA_CTCR_DSIZE(dst_bus_width) |			STM32_MDMA_CTCR_DINCOS(dst_bus_width);		/* 若源/目的宽度不同，启用打包/解包，使硬件完成宽度转换 */		if (dst_bus_width != src_bus_width)			ctcr |= STM32_MDMA_CTCR_PKE;		/* -------- 填充 node[0] 的硬件描述符（单段直接写字段） -------- */		hwdesc = desc-&gt;node[0].hwdesc;		hwdesc-&gt;ctcr = ctcr;         /* CTCR：触发/宽度/突发/增量/打包等综合配置 */		hwdesc-&gt;cbndtr = cbndtr;     /* CBNDTR：块长度等 */		hwdesc-&gt;csar = src;          /* 源地址 */		hwdesc-&gt;cdar = dest;         /* 目的地址 */		hwdesc-&gt;cbrur = 0;           /* 块重复相关寄存器：memcpy 路径不使用 */		hwdesc-&gt;clar = 0;            /* 链表地址寄存器：单段路径不使用 */		hwdesc-&gt;ctbr = ctbr;         /* 总线/触发选择等 */		hwdesc-&gt;cmar = 0;            /* 掩码地址：memcpy 路径不使用 */		hwdesc-&gt;cmdr = 0;            /* 掩码数据：memcpy 路径不使用 */		/* 调试：打印硬件描述符内容（不影响功能） */		stm32_mdma_dump_hwdesc(chan, &amp;desc-&gt;node[0]);	&#125; else &#123;		/* -------- 路径 2：len 超过单块上限，改用链表（LINKED_LIST）模式 -------- */		/* 配置链表触发模式，并把 TLEN 固定为 MAX_BUF_LEN（写入 tlen-1） */		ctcr |= STM32_MDMA_CTCR_TRGM(STM32_MDMA_LINKED_LIST) |			STM32_MDMA_CTCR_TLEN((STM32_MDMA_MAX_BUF_LEN - 1));		/* 链表模式一般用“块完成”中断推进节点，同时保留 CTCIE 作为上下文完成通知 */		ccr |= STM32_MDMA_CCR_BTIE | STM32_MDMA_CCR_CTCIE;		tlen = STM32_MDMA_MAX_BUF_LEN;		/* 对每个节点计算 xfer_count（&lt;= MAX_BLOCK_LEN），并调用 setup_hwdesc 生成对应 hwdesc */		for (i = 0, offset = 0; offset &lt; len; i++, offset += xfer_count) &#123;			/* 本节点搬运的字节数：最后一个节点可能不足 MAX_BLOCK_LEN */			xfer_count = min_t(size_t, len - offset, STM32_MDMA_MAX_BLOCK_LEN);			/* 注意：这里复用同一套“宽度/突发”选择逻辑，为链表节点配置 CTCR */			max_width = stm32_mdma_get_max_width(src, len, tlen);			src_bus_width = stm32_mdma_get_width(chan, max_width);			max_burst = tlen / max_width;			best_burst = stm32_mdma_get_best_burst(len, tlen, max_burst, max_width);			mdma_burst = ilog2(best_burst);			ctcr |= STM32_MDMA_CTCR_SBURST(mdma_burst) |				STM32_MDMA_CTCR_SSIZE(src_bus_width) |				STM32_MDMA_CTCR_SINCOS(src_bus_width);			max_width = stm32_mdma_get_max_width(dest, len, tlen);			dst_bus_width = stm32_mdma_get_width(chan, max_width);			max_burst = tlen / max_width;			best_burst = stm32_mdma_get_best_burst(len, tlen, max_burst, max_width);			mdma_burst = ilog2(best_burst);			ctcr |= STM32_MDMA_CTCR_DBURST(mdma_burst) |				STM32_MDMA_CTCR_DSIZE(dst_bus_width) |				STM32_MDMA_CTCR_DINCOS(dst_bus_width);			if (dst_bus_width != src_bus_width)				ctcr |= STM32_MDMA_CTCR_PKE;			/* 生成第 i 个节点硬件描述符，并设置是否为首/末节点（末节点决定链表终止语义） */			stm32_mdma_setup_hwdesc(chan, desc, DMA_MEM_TO_MEM, i,						src + offset, dest + offset,						xfer_count, ctcr, ctbr,						i == count - 1, i == 0, false);		&#125;	&#125;	/* 把计算后的 CCR 写入描述符，后续 start_transfer 会把它写回硬件寄存器 */	desc-&gt;ccr = ccr;	/* 明确标记为非 cyclic（memcpy 事务语义是一次性） */	desc-&gt;cyclic = false;	/* 交给 virt-dma：建立 cookie、挂入待执行队列，并返回通用 tx 描述符给上层 */	return vchan_tx_prep(&amp;chan-&gt;vchan, &amp;desc-&gt;vdesc, flags);&#125;

stm32_mdma_start_transfer &#x2F; stm32_mdma_issue_pending: 从 virt-dma 队列取出描述符并编程寄存器启动 MDMA 传输stm32_mdma_issue_pending() 是 DMAengine 的“提交触发点”：它在持有 chan-&gt;vchan.lock（并关闭本地中断）的条件下，判断 virt-dma 队列里是否存在可发起的事务；若当前通道既没有正在执行的 chan-&gt;desc 且 chan-&gt;busy == false，则调用 stm32_mdma_start_transfer() 将队列头部描述符取出并启动硬件。
stm32_mdma_start_transfer() 则完成“从软件队列到硬件寄存器”的关键转换：

从 virt_dma_chan 的待执行队列取出下一个 virt_dma_desc
转换为驱动私有的 stm32_mdma_desc，取首个硬件描述符 node[0].hwdesc
将描述符中的寄存器快照写入 MDMA 通道寄存器（CCR&#x2F;CTCR&#x2F;CBNDTR&#x2F;CSAR&#x2F;CDAR&#x2F;…）
清理残留中断状态后使能通道（EN），若是 MEM2MEM 软件请求模式则额外置位 SWRQ
置 chan-&gt;busy = true，表示硬件侧已开始执行

/** * @brief 从 virt-dma 队列取出下一个描述符，编程 MDMA 通道寄存器并启动传输 * @param[in,out] chan STM32 MDMA 驱动私有通道对象 * * 设计要点： * 1) 该函数假设调用方已经在合适的锁保护下（通常是持有 chan-&gt;vchan.lock）。 * 2) 只使用 desc-&gt;node[0] 的硬件描述符作为“首段寄存器装载模板”。 * 3) 对于 MEM2MEM + SWRM（软件请求模式），在 EN 后额外触发一次 SWRQ。 */static void stm32_mdma_start_transfer(struct stm32_mdma_chan *chan)&#123;	/* 通过通道对象反查控制器实例，用于寄存器读写封装 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/* virt-dma 的通用描述符基类指针，用于从 vchan 队列取出事务 */	struct virt_dma_desc *vdesc;	/* 指向首个硬件描述符（node[0]），其字段对应通道寄存器装载值 */	struct stm32_mdma_hwdesc *hwdesc;	/* 通道硬件编号，用于计算各寄存器偏移 */	u32 id = chan-&gt;id;	/* status：用于读取/清理通道中断状态；reg：临时寄存器地址 */	u32 status, reg;	/* 获取 vchan 队列中的下一个待执行描述符（不为空才可启动） */	vdesc = vchan_next_desc(&amp;chan-&gt;vchan);	if (!vdesc) &#123;		/* 队列为空：明确表示当前无正在执行的描述符 */		chan-&gt;desc = NULL;		return;	&#125;	/* 从 vchan 队列摘除该描述符节点，避免被重复启动 */	list_del(&amp;vdesc-&gt;node);	/* 将 virt-dma 描述符转换为驱动私有描述符，获得硬件描述符数组 */	chan-&gt;desc = to_stm32_mdma_desc(vdesc);	/* 取本次事务的首段硬件描述符，作为寄存器初始化模板 */	hwdesc = chan-&gt;desc-&gt;node[0].hwdesc;	/* 当前正在执行的硬件描述符索引初始化为 0（首段） */	chan-&gt;curr_hwdesc = 0;	/* 依次写入通道控制寄存器快照：这些值由 prep 阶段构造并固化在描述符中 */	stm32_mdma_write(dmadev, STM32_MDMA_CCR(id), chan-&gt;desc-&gt;ccr);      /* CCR：中断/优先级/使能等 */	stm32_mdma_write(dmadev, STM32_MDMA_CTCR(id), hwdesc-&gt;ctcr);        /* CTCR：触发模式/宽度/burst/增量等 */	stm32_mdma_write(dmadev, STM32_MDMA_CBNDTR(id), hwdesc-&gt;cbndtr);    /* CBNDTR：块长度/重复等 */	stm32_mdma_write(dmadev, STM32_MDMA_CSAR(id), hwdesc-&gt;csar);        /* CSAR：源地址 */	stm32_mdma_write(dmadev, STM32_MDMA_CDAR(id), hwdesc-&gt;cdar);        /* CDAR：目的地址 */	stm32_mdma_write(dmadev, STM32_MDMA_CBRUR(id), hwdesc-&gt;cbrur);      /* CBRUR：块重复/更新寄存器 */	stm32_mdma_write(dmadev, STM32_MDMA_CLAR(id), hwdesc-&gt;clar);        /* CLAR：链表地址/链表控制相关 */	stm32_mdma_write(dmadev, STM32_MDMA_CTBR(id), hwdesc-&gt;ctbr);        /* CTBR：触发选择/总线选择等 */	stm32_mdma_write(dmadev, STM32_MDMA_CMAR(id), hwdesc-&gt;cmar);        /* CMAR：掩码地址（如启用掩码功能） */	stm32_mdma_write(dmadev, STM32_MDMA_CMDR(id), hwdesc-&gt;cmdr);        /* CMDR：掩码数据（如启用掩码功能） */	/* 读取通道中断状态寄存器，若存在残留状态则写入 IFCR 清除，避免“上次遗留中断”污染本次传输 */	status = stm32_mdma_read(dmadev, STM32_MDMA_CISR(id));	if (status)		stm32_mdma_set_bits(dmadev, STM32_MDMA_CIFCR(id), status);	/* 调试：打印寄存器快照，辅助定位启动前寄存器装载是否正确 */	stm32_mdma_dump_reg(chan);	/* 置位 EN 启动 DMA 通道：此时硬件开始按已装载寄存器运行 */	stm32_mdma_set_bits(dmadev, STM32_MDMA_CCR(id), STM32_MDMA_CCR_EN);	/* 若配置为软件请求模式（SWRM），则在启动后额外触发一次 SWRQ，典型用于 MEM2MEM 启动触发 */	if (hwdesc-&gt;ctcr &amp; STM32_MDMA_CTCR_SWRM) &#123;		reg = STM32_MDMA_CCR(id);		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CCR_SWRQ);	&#125;	/* 标记通道忙：用于避免 issue_pending 重入时重复启动 */	chan-&gt;busy = true;	/* 调试：记录该虚拟通道已启动 */	dev_dbg(chan2dev(chan), &quot;vchan %p: started\n&quot;, &amp;chan-&gt;vchan);&#125;/** * @brief DMAengine 回调：提交 pending 描述符，必要时启动硬件 * @param[in] c DMAengine 抽象通道指针 * * 并发语义： * - 使用 spin_lock_irqsave 保护 vchan 队列与 chan-&gt;desc/busy 状态，避免与同核 IRQ/下半部并发。 * - vchan_issue_pending() 用于推进 virt-dma 的“pending -&gt; issued”内部状态。 */static void stm32_mdma_issue_pending(struct dma_chan *c)&#123;	/* 转换为驱动私有通道对象 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/* 保存并恢复中断标志，用于在锁持有期间屏蔽本地中断 */	unsigned long flags;	/* 进入临界区：保护 vchan 队列与启动状态，同时关本地中断避免与 IRQ 处理路径竞态 */	spin_lock_irqsave(&amp;chan-&gt;vchan.lock, flags);	/* 若没有可推进的 pending 事务，则无需进一步动作 */	if (!vchan_issue_pending(&amp;chan-&gt;vchan))		goto end;	/* 调试：记录已经“提交/发起” */	dev_dbg(chan2dev(chan), &quot;vchan %p: issued\n&quot;, &amp;chan-&gt;vchan);	/* 仅当当前没有正在执行的描述符且硬件不忙时，才从队列取出一个描述符并启动 */	if (!chan-&gt;desc &amp;&amp; !chan-&gt;busy)		stm32_mdma_start_transfer(chan);end:	/* 退出临界区：恢复中断并释放自旋锁 */	spin_unlock_irqrestore(&amp;chan-&gt;vchan.lock, flags);&#125;

stm32_mdma_irq_handler: 处理 STM32 MDMA 通道中断并驱动事务推进与错误清理这个中断处理函数完成三类工作：

定位触发中断的通道：读取全局中断状态 GISR0，用 __ffs(status) 找到最低位的置位通道号 id，并据此取得 dmadev-&gt;chan[id]。这里隐含一个重要约束：一次只处理一个通道（最低位优先），其余通道若也置位，会留到后续中断再次处理。

按“实际使能的中断源”过滤伪中断：读取通道中断状态 CISR，并把 CRQA 位屏蔽掉（MEM2MEM 场景可能置位但不代表需要处理）；再从 CCR 中提取本通道的“中断使能集合” ien，用 if (!(status &amp; ien)) 判定是否为伪中断并快速退出。这一步避免了因为状态位残留或硬件噪声导致的无意义处理。

逐位清中断并推进状态机：对 TEIF&#x2F;CTCIF&#x2F;BRTIF&#x2F;BTIF&#x2F;TCIF 等位分别写 CIFCR 清除；其中 CTCIF 会调用 stm32_mdma_xfer_end(chan) 推进一次传输结束路径，而 BTIF 在 cyclic 场景会推进 curr_hwdesc 并触发 vchan_cyclic_callback()。最后如果仍有未知&#x2F;未处理状态位残留，则统一清除并打印错误，且在 CCR.EN 已被硬件清掉时额外报告“通道被硬件关闭”。


/** * @brief STM32 MDMA 全局中断入口：识别通道、清除中断源、推进传输完成/循环回调并处理错误 * @param[in] irq  中断号（未直接使用，保留以符合 irq_handler 原型） * @param[in] devid  注册中断时传入的私有指针，这里约定为 struct stm32_mdma_device * * @return IRQ_HANDLED 表示已处理；IRQ_NONE 表示伪中断/无状态 */static irqreturn_t stm32_mdma_irq_handler(int irq, void *devid)&#123;	/* 取回控制器实例指针：包含寄存器基址与所有通道对象数组 */	struct stm32_mdma_device *dmadev = devid;	/* 当前触发中断的通道指针 */	struct stm32_mdma_chan *chan;	/* reg：通道中断清除寄存器地址；id：通道号；ccr：通道控制寄存器快照；ien：有效中断使能位集合；status：状态位 */	u32 reg, id, ccr, ien, status;	/* 读取全局中断状态：用于判断哪个通道产生中断（这里使用 GISR0 对应一组通道位图） */	status = readl_relaxed(dmadev-&gt;base + STM32_MDMA_GISR0);	if (!status) &#123;		/* 全局状态为 0：说明没有任何通道报告中断，按伪中断处理 */		dev_dbg(mdma2dev(dmadev), &quot;spurious it\n&quot;);		return IRQ_NONE;	&#125;	/* 选取最低位的置位 bit 作为通道号：一次只处理一个通道（最低位优先） */	id = __ffs(status);	/* 由通道号定位到驱动私有通道对象 */	chan = &amp;dmadev-&gt;chan[id];	/* 进入临界区：保护 vchan 队列与通道状态字段，避免与提交/启动路径并发破坏状态 */	spin_lock(&amp;chan-&gt;vchan.lock);	/* 读取该通道的中断状态寄存器 */	status = stm32_mdma_read(dmadev, STM32_MDMA_CISR(id));	/* 屏蔽 CRQA：该位在 MEM2MEM 场景可能置位，但不作为需要处理的“事件源” */	status &amp;= ~STM32_MDMA_CISR_CRQA;	/* 读取通道控制寄存器，用于提取中断使能集合（只处理已使能的事件） */	ccr = stm32_mdma_read(dmadev, STM32_MDMA_CCR(id));	/* 从 CCR 的 IRQ_MASK 字段提取“使能的中断位集合”，并做位对齐（与 CISR 位语义匹配） */	ien = (ccr &amp; STM32_MDMA_CCR_IRQ_MASK) &gt;&gt; 1;	/* 若当前状态位与使能位没有交集：认为是伪中断，退出 */	if (!(status &amp; ien)) &#123;		spin_unlock(&amp;chan-&gt;vchan.lock);		/* busy 时仍出现伪中断更值得关注，因此用 warn；否则仅 debug */		if (chan-&gt;busy)			dev_warn(chan2dev(chan),				 &quot;spurious it (status=0x%04x, ien=0x%04x)\n&quot;, status, ien);		else			dev_dbg(chan2dev(chan),				&quot;spurious it (status=0x%04x, ien=0x%04x)\n&quot;, status, ien);		return IRQ_NONE;	&#125;	/* 计算该通道的中断清除寄存器地址：后续通过写 CIFCR 清除对应事件位 */	reg = STM32_MDMA_CIFCR(id);	/* 处理传输错误中断：读取错误状态寄存器 CESR，清除 TEIF，并从待处理状态中消去该位 */	if (status &amp; STM32_MDMA_CISR_TEIF) &#123;		dev_err(chan2dev(chan), &quot;Transfer Err: stat=0x%08x\n&quot;,			readl_relaxed(dmadev-&gt;base + STM32_MDMA_CESR(id)));		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CIFCR_CTEIF);		status &amp;= ~STM32_MDMA_CISR_TEIF;	&#125;	/* 处理“上下文传输完成”事件：清除 CTCIF，并进入传输结束路径（更新队列/启动下一次等由 xfer_end 决定） */	if (status &amp; STM32_MDMA_CISR_CTCIF) &#123;		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CIFCR_CCTCIF);		status &amp;= ~STM32_MDMA_CISR_CTCIF;		stm32_mdma_xfer_end(chan);	&#125;	/* 处理“块重复传输”事件：清除 BRTIF；该事件不推进 curr_hwdesc，仅清除并消去状态位 */	if (status &amp; STM32_MDMA_CISR_BRTIF) &#123;		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CIFCR_CBRTIF);		status &amp;= ~STM32_MDMA_CISR_BRTIF;	&#125;	/* 处理“块传输完成”事件：清除 BTIF，并推进当前硬件描述符索引；cyclic 时触发周期回调 */	if (status &amp; STM32_MDMA_CISR_BTIF) &#123;		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CIFCR_CBTIF);		status &amp;= ~STM32_MDMA_CISR_BTIF;		/* 进入下一段硬件描述符：链表/多段传输时用于定位当前执行段 */		chan-&gt;curr_hwdesc++;		/* cyclic 语义：达到末尾则回绕，并触发一次 cyclic 回调 */		if (chan-&gt;desc &amp;&amp; chan-&gt;desc-&gt;cyclic) &#123;			if (chan-&gt;curr_hwdesc == chan-&gt;desc-&gt;count)				chan-&gt;curr_hwdesc = 0;			vchan_cyclic_callback(&amp;chan-&gt;desc-&gt;vdesc);		&#125;	&#125;	/* 处理“末级传输完成”事件：清除 TCIF，并消去状态位（具体完成语义由驱动组合中断方式决定） */	if (status &amp; STM32_MDMA_CISR_TCIF) &#123;		stm32_mdma_set_bits(dmadev, reg, STM32_MDMA_CIFCR_CLTCIF);		status &amp;= ~STM32_MDMA_CISR_TCIF;	&#125;	/* 若仍存在未覆盖的状态位：统一清除并报告为错误，同时检查是否被硬件关闭 EN */	if (status) &#123;		stm32_mdma_set_bits(dmadev, reg, status);		dev_err(chan2dev(chan), &quot;DMA error: status=0x%08x\n&quot;, status);		if (!(ccr &amp; STM32_MDMA_CCR_EN))			dev_err(chan2dev(chan), &quot;chan disabled by HW\n&quot;);	&#125;	/* 退出临界区：允许提交/启动路径继续推进 */	spin_unlock(&amp;chan-&gt;vchan.lock);	/* 返回已处理：本函数已对通道状态与中断位做了明确处理 */	return IRQ_HANDLED;&#125;

stm32_mdma_tx_status: 查询指定 cookie 的事务状态并计算剩余字节数（residue）这个函数实现 dma_device.device_tx_status 回调：它先用 DMAengine 通用的 dma_cookie_status() 得到 cookie 对应事务的宏观状态（例如 DMA_COMPLETE&#x2F;DMA_IN_PROGRESS&#x2F;DMA_ERROR 等），若事务未完成且调用者提供了 state，则在持有 chan-&gt;vchan.lock 的临界区内定位对应描述符，并调用 stm32_mdma_desc_residue() 计算剩余量，再通过 dma_set_residue() 写回到 state。
/** * @brief 查询指定 cookie 的 DMA 事务状态，并在需要时计算并返回剩余传输量 residue * @param[in]  c       DMAengine 抽象通道指针 * @param[in]  cookie  需要查询的事务 cookie * @param[out] state   可选输出：用于返回 residue 等扩展状态；为 NULL 时仅返回 status * @return DMAengine 定义的事务状态枚举值 */static enum dma_status stm32_mdma_tx_status(struct dma_chan *c,					    dma_cookie_t cookie,					    struct dma_tx_state *state)&#123;	/* 转换为驱动私有通道对象，用于访问 vchan/desc/curr_hwdesc 等状态 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/* vdesc：用于在 virt-dma 队列中定位“尚未执行/已排队”的描述符 */	struct virt_dma_desc *vdesc;	/* status：DMAengine 通用 cookie 状态 */	enum dma_status status;	/* flags：保存并恢复中断标志，保证临界区内不被同核中断打断 */	unsigned long flags;	/* residue：剩余未搬运字节数，默认 0 */	u32 residue = 0;	/* 先走 DMAengine 通用状态查询：它会根据 cookie 与通道的 completed cookie 等信息得出宏观状态 */	status = dma_cookie_status(c, cookie, state);	/* 若已完成，或调用者不关心扩展信息（state==NULL），直接返回宏观状态 */	if ((status == DMA_COMPLETE) || (!state))		return status;	/* 进入临界区：防止与 IRQ/提交路径并发修改 chan-&gt;desc/curr_hwdesc 或 vchan 队列 */	spin_lock_irqsave(&amp;chan-&gt;vchan.lock, flags);	/* 在 virt-dma 维护的队列结构中查找该 cookie 对应的描述符（通常对应“尚未开始或尚未完成”的事务） */	vdesc = vchan_find_desc(&amp;chan-&gt;vchan, cookie);	/*	 * 情况 1：cookie 正好是当前正在执行的 desc（chan-&gt;desc）的 cookie	 * 此时 residue 需要结合当前执行到第几个硬件描述符（curr_hwdesc）以及硬件寄存器状态来计算	 */	if (chan-&gt;desc &amp;&amp; cookie == chan-&gt;desc-&gt;vdesc.tx.cookie)		residue = stm32_mdma_desc_residue(chan, chan-&gt;desc,						 chan-&gt;curr_hwdesc, state);	/*	 * 情况 2：cookie 对应的是队列中的某个 vdesc（可能尚未启动，或处于排队等待）	 * 对于未启动的描述符，通常从第 0 个硬件描述符开始计算剩余量	 */	else if (vdesc)		residue = stm32_mdma_desc_residue(chan, to_stm32_mdma_desc(vdesc),						 0, state);	/* 将计算得到的剩余量写回到 dma_tx_state，供上层查询进度 */	dma_set_residue(state, residue);	/* 退出临界区：恢复中断并释放锁 */	spin_unlock_irqrestore(&amp;chan-&gt;vchan.lock, flags);	/* 返回宏观状态（residue 作为附加信息已写入 state） */	return status;&#125;

stm32_mdma_desc_residue &#x2F; dma_set_residue: 基于“当前硬件节点 + 当前块剩余”估算事务剩余字节数，并写回到 tx_statestm32_mdma_desc_residue() 的目标是给 tx_status() 提供 residue（剩余未搬运字节数）。它的实现思路是“上界估计”：

用硬件寄存器 CLAR 找到当前硬件正在处理的链表节点（或下一节点指针语义，取决于硬件定义），
把“当前节点之后尚未处理的所有 hwdesc 的 BNDT”累加起来，
再加上当前硬件寄存器 CBNDTR.BNDT 表示的“当前块剩余”，
如果启用了 mem_burst，则把 residue 向上取整到 burst_size 的整数倍，避免上层看到“非突发对齐”的剩余量（该值更符合硬件实际可能的总线提交粒度）。

dma_set_residue() 只是把计算结果写入 state-&gt;residue，不参与计算。
/** * @brief 计算某个 STM32 MDMA 描述符的剩余传输字节数 residue（用于 tx_status） * @param[in]  chan        私有通道对象 * @param[in]  desc        私有描述符对象（包含 count 个 hwdesc 节点） * @param[in]  curr_hwdesc 当前硬件描述符索引（本实现未使用该入参，依赖 CLAR 寄存器定位） * @param[out] state       tx_state 输出（本函数会写 in_flight_bytes） * @return 估算的剩余字节数 residue * * 计算方法： * - 通过读取通道 CLAR，定位“当前硬件正在处理的 hwdesc” * - 累加尚未处理的各 hwdesc 的 BNDT * - 加上当前 CBNDTR.BNDT 作为当前块的剩余 * - 如启用 mem_burst，则把 residue 向上取整到 burst_size 的整数倍 */static size_t stm32_mdma_desc_residue(struct stm32_mdma_chan *chan,				      struct stm32_mdma_desc *desc,				      u32 curr_hwdesc,				      struct dma_tx_state *state)&#123;	/* 由通道对象获取控制器实例，用于寄存器访问 */	struct stm32_mdma_device *dmadev = stm32_mdma_get_dev(chan);	/* hwdesc：循环中指向某个节点的硬件描述符 */	struct stm32_mdma_hwdesc *hwdesc;	/* cisr：通道中断/状态寄存器快照；clar：硬件当前链表地址寄存器；cbndtr：当前块剩余寄存器 */	u32 cisr, clar, cbndtr;	/* residue：累计的剩余字节数；modulo：用于突发对齐取模；burst_size：一次突发提交的字节粒度 */	u32 residue, modulo, burst_size;	/* i：用于从后向前扫描描述符节点 */	int i;	/* 读取通道状态寄存器：用于后续判断 CRQA 等状态位 */	cisr = stm32_mdma_read(dmadev, STM32_MDMA_CISR(chan-&gt;id));	/* 初始化 residue 为 0，后续逐步累加 */	residue = 0;	/*	 * 读取 CLAR：用于识别硬件当前正在处理（或将要处理）的链表节点标识。	 * 驱动用 “hwdesc-&gt;clar == clar” 来匹配当前节点。	 */	clar = stm32_mdma_read(dmadev, STM32_MDMA_CLAR(chan-&gt;id));	/*	 * 从最后一个节点向前扫描：	 * - 一旦遇到 hwdesc-&gt;clar 与硬件 CLAR 相等，认为找到了“当前传输节点”，停止累加	 * - 在此之前遇到的节点（位于当前节点之后的未处理节点）其 BNDT 被视为“尚未处理的剩余量”，加入 residue	 *	 * 这种“从尾到头累加直到匹配”实现的是：把当前节点之后所有未处理节点的长度求和。	 */	for (i = desc-&gt;count - 1; i &gt;= 0; i--) &#123;		/* 取得第 i 个节点的硬件描述符 */		hwdesc = desc-&gt;node[i].hwdesc;		/* 若该节点的 clar 与硬件寄存器 CLAR 相等，则认为当前节点已找到，停止累加 */		if (hwdesc-&gt;clar == clar)			break; /* 找到当前传输节点，停止累计未处理节点 */		/* 累加未处理节点的 BNDT（块内传输长度字段） */		residue += STM32_MDMA_CBNDTR_BNDT(hwdesc-&gt;cbndtr);	&#125;	/*	 * 读取当前 CBNDTR：其 BNDT 字段表示“当前块内尚未传输完成的字节数”	 * 将它加入 residue，得到“当前块剩余 + 后续未处理节点总和”的估计。	 */	cbndtr = stm32_mdma_read(dmadev, STM32_MDMA_CBNDTR(chan-&gt;id));	residue += cbndtr &amp; STM32_MDMA_CBNDTR_BNDT_MASK;	/* 默认 in_flight_bytes 为 0；后续在特定 MEM2MEM 硬件请求场景下会更新 */	state-&gt;in_flight_bytes = 0;	/*	 * 若启用了 m2m_hw（memcpy 使用硬件请求线）且 CRQA 置位：	 * 认为当前仍有“请求活跃”的 in-flight 字节，这里用当前块 BNDT 作为 in-flight_bytes 的估计值。	 */	if (chan-&gt;chan_config.m2m_hw &amp;&amp; (cisr &amp; STM32_MDMA_CISR_CRQA))		state-&gt;in_flight_bytes = cbndtr &amp; STM32_MDMA_CBNDTR_BNDT_MASK;	/*	 * 若未配置 mem_burst，则不做“突发粒度向上取整”，直接返回按 BNDT 计算的 residue。	 * 该返回值更接近“字节级剩余”，但可能不符合硬件 burst 提交的实际粒度。	 */	if (!chan-&gt;mem_burst)		return residue;	/* burst_size：一次突发提交的总字节数 = burst beats * 每 beat 字节宽度 */	burst_size = chan-&gt;mem_burst * chan-&gt;mem_width;	/* 计算 residue 对 burst_size 的取模 */	modulo = residue % burst_size;	/*	 * 若 residue 不是 burst_size 的整数倍，则向上取整到下一个 burst_size 边界：	 * 这样上层看到的 residue 不会低估“硬件按突发提交导致的最小剩余粒度”。	 */	if (modulo)		residue = residue - modulo + burst_size;	/* 返回按突发粒度对齐后的剩余字节数 */	return residue;&#125;/** * @brief 将计算得到的 residue 写入 dma_tx_state * @param[out] state   tx_state 指针（允许为 NULL） * @param[in]  residue 剩余字节数 * * 这是一个纯赋值函数：不做锁、不做计算，仅写 state-&gt;residue。 */static inline void dma_set_residue(struct dma_tx_state *state, u32 residue)&#123;	/* 若调用者提供了 state，则更新 residue 字段 */	if (state)		state-&gt;residue = residue;&#125;

stm32_mdma_terminate_all: 终止通道上所有事务，停止硬件并回收队列中的全部描述符这个函数实现 dma_device.device_terminate_all 回调：它的语义是强制清空该 DMA 通道上的事务状态——包括正在执行的事务（chan-&gt;desc）以及 virt-dma 队列里尚未执行&#x2F;已排队的事务。实现上分成两段：

锁内：把“正在执行的 vdesc”标记终止、必要时停硬件、把队列里的描述符全部摘到本地链表 head
锁外：统一释放 head 上的描述符对象，避免在自旋锁&#x2F;关中断的临界区内做潜在的慢操作或可能睡眠的释放路径

/** * @brief 强制终止该通道上的所有 DMA 事务：停止正在执行的传输并释放队列中全部描述符 * @param[in] c DMAengine 抽象通道指针 * @return 始终返回 0（DMAengine terminate_all 通常约定成功/失败由驱动自行定义，这里固定成功） * * 并发语义： * - 锁内完成“状态切断”：终止当前 vdesc、停止硬件、摘取所有队列描述符到本地链表 * - 锁外完成“资源释放”：避免在自旋锁/关中断临界区内做释放工作 */static int stm32_mdma_terminate_all(struct dma_chan *c)&#123;	/* 转换为驱动私有通道对象 */	struct stm32_mdma_chan *chan = to_stm32_mdma_chan(c);	/* 保存并恢复中断标志，确保临界区内不被同核 IRQ 打断 */	unsigned long flags;	/* 本地链表头：用于暂存从 vchan 队列摘下来的所有描述符，锁外统一释放 */	LIST_HEAD(head);	/* 进入临界区：保护 chan-&gt;desc/busy 与 vchan 队列结构 */	spin_lock_irqsave(&amp;chan-&gt;vchan.lock, flags);	/* 若存在当前正在执行的描述符，则先终止它并在需要时停止硬件 */	if (chan-&gt;desc) &#123;		/* 将当前 vdesc 标记为终止：virt-dma 会更新 cookie/状态并做必要的队列处理 */		vchan_terminate_vdesc(&amp;chan-&gt;desc-&gt;vdesc);		/* 若硬件正在忙，则主动停止 MDMA 通道，避免硬件继续写内存 */		if (chan-&gt;busy)			stm32_mdma_stop(chan);		/* 切断驱动对“当前描述符”的引用，避免后续路径误以为仍在执行 */		chan-&gt;desc = NULL;	&#125;	/*	 * 将 vchan 队列中所有剩余描述符全部摘取到本地 head 链表：	 * - 这些通常是已排队但尚未启动的事务	 * - 通过“摘取”把它们从 vchan 内部结构移出，后续可在锁外安全释放	 */	vchan_get_all_descriptors(&amp;chan-&gt;vchan, &amp;head);	/* 退出临界区：恢复中断并释放锁 */	spin_unlock_irqrestore(&amp;chan-&gt;vchan.lock, flags);	/*	 * 锁外释放：逐个释放 head 上的描述符	 * 释放过程中会调用你之前关注的 chan-&gt;vchan.desc_free（例如 stm32_mdma_desc_free）	 * 从而释放硬件描述符池对象/链表节点/子结构等。	 */	vchan_dma_desc_free_list(&amp;chan-&gt;vchan, &amp;head);	/* 固定返回 0：表示 terminate_all 执行完成 */	return 0;&#125;

