drivers&#x2F;gpio&#x2F;gpiolib.cgpiochip_setup_dev: 为单个GPIO控制器完成设备和接口的注册此函数的核心职责是接收一个代表GPIO控制器（如STM32的GPIOA）的内核对象gdev，并完成以下三件关键事情：

初始化设备对象: 确保gdev中的struct device成员被正确初始化。
创建字符设备: 在/dev目录下创建对应的gpiochipN字符设备节点，使用户空间程序可以通过文件I&#x2F;O操作来访问GPIO。
创建sysfs接口: 在/sys/class/gpio目录下创建对应的gpiochipN目录和属性文件，提供一种基于文件的、用于管理和调试GPIO的接口。

/* * gpiochip_setup_dev: 对一个gpio_device进行设置. * * @gdev: 指向要设置的 gpio_device 结构体的指针. * @return: 成功时返回0, 失败时返回负值的错误码. */static int gpiochip_setup_dev(struct gdevice *gdev)&#123;	/*	 * fwnode: 指向与此设备关联的固件节点(Firmware Node)的句柄.	 * 在基于设备树的系统(如STM32)上, 这通常指向设备树中对应的节点	 * (例如, &amp;gpioa 节点). dev_fwnode() 是获取这个句柄的标准函数.	 */	struct fwnode_handle *fwnode = dev_fwnode(&amp;gdev-&gt;dev);	/*	 * ret: 用于存储函数调用的返回值.	 */	int ret;	/*	 * 调用 device_initialize(), 对 gdev 中内嵌的 struct device 对象进行初始化.	 * 这一步会设置好设备的引用计数、锁等内部状态, 为后续的注册做准备.	 * 如果这个 gdev 之前已经注册过, 这一步可以确保其状态被重置.	 */	device_initialize(&amp;gdev-&gt;dev);	/*	 * 这是一个处理固件节点状态的特殊情况.	 * 如果固件节点存在, 并且它还没有被关联到任何一个&#x27;struct device&#x27;上,	 * 那么我们就安全地清除它的&quot;已初始化&quot;标志.	 * 这确保了设备可以被重新初始化和探测.	 */	if (fwnode &amp;&amp; !fwnode-&gt;dev)		fwnode_dev_initialized(fwnode, false);	/*	 * 第一步: 注册字符设备.	 * gcdev_register() 是一个辅助函数, 它的核心工作是:	 * 1. 从 gpio_devt (在gpiolib_dev_init中分配的设备号范围)中获取一个可用的次设备号.	 * 2. 使用这个主/次设备号, 调用 cdev_add() 将这个 gdev 注册为一个字符设备.	 * 3. 调用 device_add() 将 gdev-&gt;dev 这个设备对象正式添加到内核的设备模型中.	 *    device_add() 会触发用户空间的udev/mdev, 在/dev目录下创建对应的&#x27;gpiochipN&#x27;节点.	 */	ret = gcdev_register(gdev, gpio_devt);	if (ret) /* 检查注册是否成功. */		return ret;	/*	 * 第二步: 注册sysfs接口.	 * gpiochip_sysfs_register() 负责在 /sys/class/gpio/ 目录下创建对应的接口.	 * 它会创建一个名为 &#x27;gpiochipN&#x27; (N是GPIO的基准号, 如gpiochip0)的目录.	 * 在这个目录下, 它会创建几个属性文件, 例如:	 *  - &#x27;base&#x27;:  只读, 显示这个gpiochip的起始GPIO编号.	 *  - &#x27;label&#x27;: 只读, 显示这个gpiochip的标签 (通常来自设备树).	 *  - &#x27;ngpio&#x27;: 只读, 显示这个gpiochip管理的GPIO数量 (例如, 16个).	 */	ret = gpiochip_sysfs_register(gdev);	if (ret) /* 检查注册是否成功. */		goto err_remove_device; /* 如果失败, 跳转到错误处理. */	/*	 * 使用 dev_dbg() 打印一条调试级别的日志, 宣告注册成功.	 * 日志会包含GPIO的编号范围和标签, 这对于调试非常有帮助.	 */	dev_dbg(&amp;gdev-&gt;dev, &quot;registered GPIOs %u to %u on %s\n&quot;, gdev-&gt;base,		gdev-&gt;base + gdev-&gt;ngpio - 1, gdev-&gt;label);	/*	 * 所有操作成功, 返回0.	 */	return 0;/* * 错误处理标签. * 当sysfs注册失败时, 代码会跳转到这里. */err_remove_device:	/*	 * 必须执行清理操作, 注销之前成功注册的字符设备,	 * 以保持系统状态的一致性.	 */	gcdev_unregister(gdev);	/*	 * 返回sysfs注册失败时产生的错误码.	 */	return ret;&#125;

gpiochip_setup_devs: 为已注册的GPIO控制器设置设备节点此函数的核心作用是遍历当前系统中所有已经注册的GPIO控制器（gpio_device），并为每一个控制器调用gpiochip_setup_dev函数来完成其设备节点的最终设置。
/* * gpiochip_setup_devs: 为(一个或多个)gpio设备进行设置. */static void gpiochip_setup_devs(void)&#123;	/*	 * gdev: 一个指向 gpio_device 结构体的指针, 用作循环变量.	 *       gpio_device 是内核中代表一个完整GPIO控制器(如STM32的GPIOA)的核心对象.	 * ret:  用于存储函数调用的返回值.	 */	struct gpio_device *gdev;	int ret;	/*	 * guard(srcu)(&amp;gpio_devices_srcu):	 * 这是一个C++风格的RAII (Resource Acquisition Is Initialization) 宏,	 * 在内核中用于简化锁的管理. 它在这里的作用是:	 * 1. 在进入这个作用域时, 自动获取 gpio_devices_srcu 的 SRCU 读锁.	 *    SRCU (Sleepable Read-Copy-Update) 是一种特殊的读写锁, 它允许读端临界区睡眠.	 *    在这里加锁是为了安全地遍历全局的 gpio_devices 链表.	 * 2. 在退出这个作用域时 (无论函数是正常返回还是中途退出), 自动释放这个读锁.	 * 这就避免了忘记解锁导致死锁的问题.	 */	guard(srcu)(&amp;gpio_devices_srcu);	/*	 * list_for_each_entry_srcu: 这是一个专门用于在SRCU保护下安全遍历链表的宏.	 * @ gdev:           循环变量.	 * @ &amp;gpio_devices:  要遍历的全局链表的头部.	 * @ list:           链表节点在 gdev 结构体中的成员名.	 * @ srcu_read_lock_held(...): 一个条件, 用于静态检查或在调试时断言我们确实持有了锁.	 *	 * 这行代码会遍历 gpio_devices 链表中的每一个 gpio_device (即每一个已注册的GPIO控制器).	 */	list_for_each_entry_srcu(gdev, &amp;gpio_devices, list,				 srcu_read_lock_held(&amp;gpio_devices_srcu)) &#123;		/*		 * 对链表中的每一个 gdev, 调用 gpiochip_setup_dev 函数.		 * gpiochip_setup_dev (未在此处显示) 是真正干活的函数. 它的主要工作包括:		 * 1. 检查这个gdev是否已经被设置过, 如果是, 就直接返回.		 * 2. 使用之前分配的字符设备主设备号和动态分配的次设备号,		 *    调用 device_create() 函数.		 * 3. device_create() 会触发用户空间的 udev/mdev, 在 /dev 目录下		 *    创建一个对应的字符设备节点, 例如 /dev/gpiochip0.		 * 4. 它还会设置好 gdev-&gt;dev 这个设备对象, 将其与驱动模型完全集成.		 */		ret = gpiochip_setup_dev(gdev);		/*		 * 检查 gpiochip_setup_dev 是否成功.		 */		if (ret)			/*			 * 如果失败, 使用 dev_err() 打印一条错误日志.			 * &amp;gdev-&gt;dev 是与这个 gdev 关联的设备对象,			 * dev_err 会自动在日志中包含设备名, 方便调试.			 */			dev_err(&amp;gdev-&gt;dev,				&quot;Failed to initialize gpio device (%d)\n&quot;, ret);	&#125;&#125;

gpiolib_dev_init: 初始化GPIO设备库此函数在内核启动的早期阶段被调用，其核心职责是建立Linux内核GPIO子系统的设备驱动模型框架。它本身不注册任何具体的GPIO硬件，而是搭建一个“舞台”，让后续具体的GPIO控制器驱动（如STM32的GPIO驱动）能够在这个舞台上注册自己，并以一种标准化的方式向用户空间暴露接口。
/* * 定义一个静态的 &#x27;device_driver&#x27; 结构体实例, 名为 gpio_stub_drv. * 这是一个 &quot;存根驱动&quot; (stub driver). 它的作用是在没有真正的GPIO设备注册时, * 作为一个占位符存在于GPIO总线上. 这有助于简化总线管理逻辑. */static struct device_driver gpio_stub_drv = &#123;	/*	 * .name: 驱动的名称. 这个名字会出现在 sysfs 中.	 */	.name = &quot;gpio_stub_drv&quot;,	/*	 * .bus: 指定这个驱动属于哪个总线. 这里它被绑定到 gpio_bus_type.	 */	.bus = &amp;gpio_bus_type,	/*	 * .probe: 当一个设备与这个驱动匹配时, 内核会调用 .probe 函数.	 * (gpio_stub_drv_probe 的定义不在此处, 但它通常只做少量工作或什么都不做).	 */	.probe = gpio_stub_drv_probe,&#125;;/* * gpiolib_dev_init: GPIO设备库的初始化函数. * 标记为 __init, 表示它仅在内核启动期间执行. */static int __init gpiolib_dev_init(void)&#123;	/*	 * ret: 用于存储函数调用的返回值.	 */	int ret;	/*	 * 第一步: 注册GPIO总线类型.	 * bus_register() 会在 /sys/bus/ 目录下创建一个名为 &quot;gpio&quot; 的新目录.	 * 这就创建了一条虚拟的 &quot;GPIO总线&quot;. 所有后续的GPIO控制器设备和驱动,	 * 都会被 &quot;挂载&quot; 到这条总线上. 这是建立标准设备模型的第一步.	 */	ret = bus_register(&amp;gpio_bus_type);	if (ret &lt; 0) &#123; /* 检查注册是否成功. */		/* 如果失败, 打印错误日志. */		pr_err(&quot;gpiolib: could not register GPIO bus type\n&quot;);		return ret;	&#125;	/*	 * 第二步: 注册GPIO存根驱动.	 * driver_register() 会将我们上面定义的 gpio_stub_drv 注册到内核中,	 * 并将其与 gpio_bus_type 关联.	 */	ret = driver_register(&amp;gpio_stub_drv);	if (ret &lt; 0) &#123; /* 检查注册是否成功. */		pr_err(&quot;gpiolib: could not register GPIO stub driver\n&quot;);		/*		 * 如果失败, 必须执行清理操作: 注销之前成功注册的总线,		 * 以保持系统状态的一致性.		 */		bus_unregister(&amp;gpio_bus_type);		return ret;	&#125;	/*	 * 第三步: 为GPIO字符设备分配一个主次设备号范围.	 * 现代Linux内核推荐使用字符设备接口(/dev/gpiochipN)来访问GPIO.	 * alloc_chrdev_region() 会向内核申请一段连续的、未被使用的设备号.	 * @ &amp;gpio_devt: 用于存储分配到的起始设备号 (主设备号+次设备号).	 * @ 0:           起始的次设备号, 0表示由内核动态选择.	 * @ GPIO_DEV_MAX: 希望分配的设备号数量, 即最多支持多少个GPIO控制器.	 * @ GPIOCHIP_NAME: 与这个设备号范围关联的名称 (通常是 &quot;gpio&quot;).	 */	ret = alloc_chrdev_region(&amp;gpio_devt, 0, GPIO_DEV_MAX, GPIOCHIP_NAME);	if (ret &lt; 0) &#123; /* 检查分配是否成功. */		pr_err(&quot;gpiolib: failed to allocate char dev region\n&quot;);		/*		 * 如果失败, 必须按相反的顺序执行清理操作.		 */		driver_unregister(&amp;gpio_stub_drv);		bus_unregister(&amp;gpio_bus_type);		return ret;	&#125;	/*	 * 设置一个全局标志, 表示GPIO库的核心基础设施已经初始化完毕.	 * 其他部分的代码可能会检查这个标志.	 */	gpiolib_initialized = true;	/*	 * 调用 gpiochip_setup_devs(), 这个函数会进一步设置字符设备接口	 * 所需的类(class)等, 准备好动态创建/dev/gpiochipN节点的条件.	 */	gpiochip_setup_devs();/* * 这部分代码用于处理动态设备树(Dynamic Device Tree)的通知. * 它允许在系统运行时, 如果设备树中的GPIO相关节点发生变化(例如通过overlay), * GPIO子系统能够收到通知并做出相应的调整. * 这对于像树莓派这样支持DT overlay的系统很重要, 对于固件固定的STM32系统则不太常用. */#if IS_ENABLED(CONFIG_OF_DYNAMIC) &amp;&amp; IS_ENABLED(CONFIG_OF_GPIO)	/*	 * 注册一个通知回调函数(gpio_of_notifier),	 * 当设备树发生重新配置时, 内核会调用它.	 * WARN_ON 确保如果注册失败, 会打印一个警告, 因为这通常不应该发生.	 */	WARN_ON(of_reconfig_notifier_register(&amp;gpio_of_notifier));#endif /* CONFIG_OF_DYNAMIC &amp;&amp; CONFIG_OF_GPIO */	/*	 * 返回0或最后一次成功的操作的返回值, 表示初始化成功.	 */	return ret;&#125;/* * 使用 core_initcall() 将 gpiolib_dev_init 注册为一个核心初始化调用. * 这确保了GPIO的基础设施会在所有具体的GPIO控制器驱动(如STM32的GPIO驱动) * 尝试注册自己之前, 就已经准备就绪. */core_initcall(gpiolib_dev_init);

gpiolib 总线与设备类型定义此代码片段定义了Linux内核gpiolib子系统用于融入内核标准设备模型(Device Model)的两个核心数据结构。它的核心原理是创建一个名为 “gpio” 的逻辑总线(logical bus), 并为所有注册的GPIO控制器(gpio_chip)定义一个统一的设备类型(gpio_chip)。这使得内核可以将每一个GPIO控制器都视为一个标准化的”设备”, 并通过一个虚拟的”总线”来管理它们, 从而能够复用设备模型提供的所有成熟机制, 如驱动绑定、电源管理和sysfs接口。

gpio_dev_type: GPIO芯片的设备类型这是一个struct device_type实例, 它为所有由gpiolib创建的struct gpio_device对象提供了一组通用的属性。
原理与作用:device_type的主要作用是为一类设备提供共享的特性, 最重要的是统一的释放(release)回调函数。

.name = &quot;gpio_chip&quot;: 为这类设备指定了一个内部名称 “gpio_chip”。这个名字主要用于调试和内核内部识别。
.release = gpiodev_release: 这是此结构体最关键的部分。它指定了一个回调函数gpiodev_release。当一个gpio_device对象的最后一个引用被释放(其引用计数降为0)时, 内核的设备模型会自动调用这个函数。gpiodev_release函数内部会负责清理和释放与该gpio_device对象相关的所有内存和资源。这是一种健壮的、自动化的资源管理机制, 对于防止内存泄漏至关重要, 在像STM32H750这样内存资源宝贵的嵌入式系统中尤其重要。

/* * 定义一个静态的、常量类型的 struct device_type 实例. * &quot;static&quot;表示其作用域仅限于当前文件. &quot;const&quot;表示其内容在编译后是只读的. */static const struct device_type gpio_dev_type = &#123;	/*	 * .name: 指定此设备类型的名称为 &quot;gpio_chip&quot;.	 */	.name = &quot;gpio_chip&quot;,	/*	 * .release: 指定一个回调函数 gpiodev_release.	 * 当内核要销毁一个此类型的设备对象时, 这个函数会被自动调用以释放资源.	 */	.release = gpiodev_release,&#125;;


gpio_bus_match: GPIO总线的匹配规则这是一个自定义的match函数, 它定义了在”gpio”总线上, 一个设备和一个驱动程序应该如何被视为”兼容”的。
原理与作用:标准的总线(如I2C, SPI)通常根据设备和驱动的名称或ID来进行匹配。但”gpio”总线是一个逻辑上的虚拟总线, 其匹配规则也比较特殊。

struct fwnode_handle *fwnode = dev_fwnode(dev);: 获取与设备dev关联的固件节点(通常是设备树节点)。
if (fwnode &amp;&amp; fwnode-&gt;dev != dev): 这是匹配的核心逻辑。一个物理GPIO控制器在内核中可能对应多个struct device对象(例如, 一个platform_device和gpiolib创建的gpio_device)。fwnode-&gt;dev通常指向最主要的那个设备对象(即platform_device)。这个判断的意图是: 只有当这个gpio_device是其固件节点所代表的主要设备时, 才允许匹配。它防止了通用的”gpio总线驱动”错误地绑定到一个已经被更具体的平台驱动所拥有的硬件上, 是一种避免潜在逻辑冲突的保护机制。
return 1; 表示匹配成功。
return 0; 表示匹配失败。

/* * gpio_bus_match: &quot;gpio&quot;总线的自定义匹配函数. * @dev: 要进行匹配的设备. * @drv: 要进行匹配的驱动. * @return: 1 表示匹配成功, 0 表示失败. */static int gpio_bus_match(struct device *dev, const struct device_driver *drv)&#123;	/* 获取设备的固件节点句柄 (fwnode). */	struct fwnode_handle *fwnode = dev_fwnode(dev);	/*	 * 这是一个特殊的匹配逻辑, 用于处理一个硬件节点可能对应多个设备对象的情况.	 * 如果该固件节点存在, 并且它关联的主要设备不是当前正在匹配的这个设备,	 * 那么就认为不匹配.	 */	if (fwnode &amp;&amp; fwnode-&gt;dev != dev)		return 0;	/* 在其他情况下, 都认为匹配成功. */	return 1;&#125;


gpio_bus_type: “gpio” 逻辑总线这是一个struct bus_type实例, 它在内核中注册了一个全新的、名为”gpio”的总线。
原理与作用:注册这个结构体会在sysfs中创建/sys/bus/gpio/目录。所有被gpiolib注册的GPIO控制器都会作为设备出现在这个总线上。这提供了一个统一的场所来管理和查看系统中的所有GPIO控制器。

.name = &quot;gpio&quot;: 定义了总线的名称, 这也是sysfs中目录的名称。
.match = gpio_bus_match: 将上面定义的自定义匹配函数gpio_bus_match指定为本总线的官方匹配规则。当任何驱动或设备尝试在此总线上进行绑定时, 内核都会调用这个函数来做决定。

/* * 定义一个静态的、常量类型的 struct bus_type 实例, 用于描述 &quot;gpio&quot; 总线. */static const struct bus_type gpio_bus_type = &#123;	/*	 * .name: 总线的名称, 将会创建 /sys/bus/gpio 目录.	 */	.name = &quot;gpio&quot;,	/*	 * .match: 指定此总线的设备-驱动匹配函数.	 */	.match = gpio_bus_match,&#125;;

gpiochip_find_base_unlocked: 动态查找可用的GPIO编号基地址此函数是Linux内核gpiolib子系统中实现GPIO控制器编号动态分配的核心算法。当一个新的GPIO控制器驱动请求动态分配其GPIO编号基地址时(gpio_chip-&gt;base = -1), gpiochip_add_data函数会在持有锁的情况下调用此函数。它的核心原理是以一种”贪心算法”(Greedy Algorithm)的思路, 线性扫描一个全局的、已注册的GPIO设备链表, 以寻找第一个足够大的、未被占用的连续编号”空隙”。
工作流程详解:

初始化: 函数从一个预定义的动态分配起始点GPIO_DYNAMIC_BASE开始搜索。这个值通常足够大, 以避开为特殊硬件静态预留的低地址编号。
遍历已注册设备链表: 它使用list_for_each_entry_srcu宏来安全地遍历gpio_devices这个全局链表。这个链表按照GPIO基地址从小到大的顺序维护了所有已注册的GPIO控制器。_srcu版本的宏使用了”读-拷贝-更新”(Read-Copy-Update)的变体, 即使在遍历过程中有其他CPU在并发地修改链表(虽然此函数被调用时已持有锁, 但这个宏是通用的), 也能保证遍历的安全性。
寻找空隙 (核心算法): 在循环的每一步, 它会比较当前搜索的起始点base和正在检查的已注册设备gdev的范围:
找到空隙 (成功): 如果当前gdev的基地址 (gdev-&gt;base) 大于或等于 base + ngpio (当前搜索点 + 需要的引脚数量), 这意味着在base和gdev之间有一个足够大的空隙。循环立即break。
未找到空隙 (继续搜索): 如果没有找到空隙, 函数会将搜索的起始点base更新为当前gdev范围的末尾之后 (base = gdev-&gt;base + gdev-&gt;ngpio;)。然后继续下一次循环, 检查这个新的base与下一个已注册设备之间的关系。


边界检查: 在每次更新base后, 都会检查新的base是否超出了预定义的动态分配的最大范围GPIO_DYNAMIC_MAX。如果超出, 说明不可能再找到空隙了, 循环也会break。
返回结果:
如果循环结束后, base仍然在有效的动态分配范围内, 说明找到了一个可用的基地址, 函数将其返回。
如果超出了范围, 说明GPIO编号空间已满, 函数返回-ENOSPC(“设备上没有空间”)错误。



为什么这个机制很重要?在早期的Linux内核中, GPIO控制器的基地址通常由驱动程序或板级文件静态硬编码。这种方式非常容易导致冲突, 特别是在一个平台上集成了来自不同供应商的、可热插拔的模块化硬件时。动态分配机制彻底解决了这个问题。它使得内核可以像DHCP服务器分配IP地址一样, 自动地为新加入的GPIO控制器找到一个不与任何现有设备冲突的、唯一的编号范围。这对于构建可扩展、可维护的嵌入式Linux系统, 尤其是在STM32这样拥有众多GPIO端口的平台上, 是至关重要的。
/* * gpiochip_find_base_unlocked: 在未锁定的上下文中(但调用者必须持有锁), 动态地查找GPIO基地址. * @ngpio: 新的GPIO控制器需要的引脚数量. * @return: 成功时返回一个可用的基地址, 失败时返回 -ENOSPC. */static int gpiochip_find_base_unlocked(u16 ngpio)&#123;	/*	 * 从预定义的动态GPIO编号起始地址开始搜索.	 * 这个值通常是256或512, 以避开静态分配的低地址区域.	 */	unsigned int base = GPIO_DYNAMIC_BASE;	/* 定义一个gdev指针, 用于遍历已注册的GPIO设备. */	struct gpio_device *gdev;	/*	 * 安全地遍历全局的 gpio_devices 链表. 这个链表按照基地址排序.	 * lockdep_is_held() 是一个锁调试断言, 确保调用此函数时确实持有了 gpio_devices_lock.	 */	list_for_each_entry_srcu(gdev, &amp;gpio_devices, list,				 lockdep_is_held(&amp;gpio_devices_lock)) &#123;		/*		 * 核心的空隙查找逻辑:		 * 检查当前已注册设备 gdev 的基地址, 是否大于等于 (我们当前寻找的基地址 base + 我们需要的数量 ngpio).		 * 如果是, 说明在 base 和 gdev-&gt;base 之间有一个足够大的空隙.		 */		if (gdev-&gt;base &gt;= base + ngpio)			break; /* 找到了, 跳出循环. */				/*		 * 如果没有找到空隙, 更新我们的搜索起点:		 * 将 base 设置为当前设备 gdev 占用范围的末尾之后.		 */		base = gdev-&gt;base + gdev-&gt;ngpio;		/* 确保我们的搜索起点不会回退到动态范围的起始点之下. */		if (base &lt; GPIO_DYNAMIC_BASE)			base = GPIO_DYNAMIC_BASE;		/* 检查更新后的 base 是否还有可能容纳 ngpio 个引脚而不超出最大范围. */		if (base &gt; GPIO_DYNAMIC_MAX - ngpio)			break; /* 不可能了, 跳出循环. */	&#125;	/*	 * 循环结束后, 检查最终的 base 是否仍在合法范围内.	 */	if (base &lt;= GPIO_DYNAMIC_MAX - ngpio) &#123;		pr_debug(&quot;%s: found new base at %d\n&quot;, __func__, base);		return base; /* 成功, 返回找到的基地址. */	&#125; else &#123;		pr_err(&quot;%s: cannot find free range\n&quot;, __func__);		return -ENOSPC; /* 失败, 返回&quot;无可用空间&quot;错误. */	&#125;&#125;

gpiodev_add_to_list_unlocked: 将GPIO设备插入全局排序列表此函数是Linux内核gpiolib子系统内部一个至关重要的列表管理函数。它的核心原理是以一种原子性的、保证排序的方式, 将一个新初始化的GPIO设备(gdev)插入到一个全局的、按GPIO编号基地址排序的设备链表(gpio_devices)中。在插入的同时, 它还必须严格执行冲突检测, 确保新设备的GPIO编号范围不会与任何已存在的设备发生重叠。
这个函数是GPIO控制器能够被内核动态、安全地添加和管理的基础。它的命名后缀_unlocked是一个明确的约定, 意味着调用此函数的代码必须已经持有了保护该链表的gpio_devices_lock锁, lockdep_assert_held宏在函数开头就强制检查了这一前提条件。
工作流程与算法详解:
该函数的算法是一个为链表插入优化的”寻找间隙”过程:

空列表处理 (最快路径): 如果全局链表gpio_devices是空的, 说明这是第一个被注册的GPIO控制器。函数直接将其添加到链表尾部并成功返回。

头部插入优化 (次快路径): 函数检查新设备gdev是否可以被完整地插入到链表的最前端。它比较gdev的结束地址与链表中第一个设备next的起始地址。如果gdev的范围在next之前且无重叠, 就将其插入到链表头部。

尾部插入优化 (次快路径): 类似地, 函数检查gdev是否可以被完整地插入到链表的最后端。它比较gdev的起始地址与链表中最后一个设备prev的结束地址。如果gdev的范围在prev之后且无重叠, 就将其插入到链表尾部。这两种优化(头部和尾部)覆盖了系统启动时设备按顺序注册的绝大多数情况, 避免了昂贵的完整链表遍历。

中间插入 (通用路径): 如果以上优化都不适用, 函数就必须遍历整个链表来寻找一个可以容纳gdev的”间隙”。它使用list_for_each_entry_safe同时追踪前一个节点prev和下一个节点next, 并检查是否存在一个位置, 使得gdev的范围恰好在prev之后且在next之前。如果找到这样的间隙, 就执行插入并成功返回。

冲突检测与失败: 如果函数遍历完整个链表都没有找到任何可以插入的间隙(即不满足上述任何一个插入条件), 这就确定地意味着gdev的GPIO编号范围与一个或多个已存在的设备发生了重叠。在这种情况下, 函数不会执行任何插入操作, 而是直接返回-EBUSY错误码, 明确地告知上层调用者发生了冲突。


RCU (读-拷贝-更新) 的使用:此函数使用了list_add_rcu和list_add_tail_rcu。_rcu后缀表明这个链表是受RCU机制保护的。这是一种高级的同步技术, 它允许其他代码在不获取任何锁的情况下安全地并发读取gpio_devices链表, 极大地提高了系统的并发性能。只有在写入(添加或删除节点)时才需要获取锁。
在STM32H750上的应用:当STM32驱动程序一个接一个地注册其GPIO Bank (GPIOA, GPIOB, GPIOC…)时, gpiochip_add_data内部就会调用此函数。

注册GPIOA时, 会命中”空列表”路径。
注册GPIOB时, 会命中”尾部插入”路径。
注册GPIOC时, 同样会命中”尾部插入”路径。…以此类推。这使得STM32众多GPIO Bank的注册过程非常高效。

/* * gpiodev_add_to_list_unlocked: 将一个新的chip添加到全局chips列表中, 保持列表 * 按范围(即[base, base + ngpio - 1])排序. * * 返回: * -EBUSY 如果新的chip与某个其他chip的整数空间重叠. */static int gpiodev_add_to_list_unlocked(struct gpio_device *gdev)&#123;	struct gpio_device *prev, *next;	/* 这是一个锁调试断言, 确保调用者确实持有了 gpio_devices_lock 锁. */	lockdep_assert_held(&amp;gpio_devices_lock);	/* 情况1: 列表为空. 这是第一个被添加的设备. */	if (list_empty(&amp;gpio_devices)) &#123;		/* 直接添加到链表尾部. _rcu版本确保了对并发RCU读者的安全. */		list_add_tail_rcu(&amp;gdev-&gt;list, &amp;gpio_devices);		return 0;	&#125;	/* 情况2: 尝试在头部插入 (优化). */	next = list_first_entry(&amp;gpio_devices, struct gpio_device, list);	/* 检查新设备的范围是否完全在第一个设备之前. */	if (gdev-&gt;base + gdev-&gt;ngpio &lt;= next-&gt;base) &#123;		/* 使用_rcu版本添加到链表头部. */		list_add_rcu(&amp;gdev-&gt;list, &amp;gpio_devices);		return 0;	&#125;	/* 情况3: 尝试在尾部插入 (优化). */	prev = list_last_entry(&amp;gpio_devices, struct gpio_device, list);	/* 检查新设备的范围是否完全在最后一个设备之后. */	if (prev-&gt;base + prev-&gt;ngpio &lt;= gdev-&gt;base) &#123;		list_add_tail_rcu(&amp;gdev-&gt;list, &amp;gpio_devices);		return 0;	&#125;	/* 情况4: 在中间插入 (通用路径). */	/* _safe版本可以安全地处理循环中对链表的修改, 这里用于方便地获取prev和next. */	list_for_each_entry_safe(prev, next, &amp;gpio_devices, list) &#123;		/* &amp;next-&gt;list == &amp;gpio_devices 表示prev已经是最后一个元素了. */		if (&amp;next-&gt;list == &amp;gpio_devices)			break;		/*		 * 检查是否找到了一个间隙:		 * 新设备的起始地址在prev之后, 并且新设备的结束地址在next之前.		 */		if (prev-&gt;base + prev-&gt;ngpio &lt;= gdev-&gt;base				&amp;&amp; gdev-&gt;base + gdev-&gt;ngpio &lt;= next-&gt;base) &#123;			/* 在prev之后插入新设备. */			list_add_rcu(&amp;gdev-&gt;list, &amp;prev-&gt;list);			return 0;		&#125;	&#125;	/*	 * 如果执行到这里, 说明遍历了整个列表都没有找到可以插入的间隙.	 * 这意味着存在地址范围重叠.	 * 在返回错误前, 等待所有正在进行的RCU读取操作完成.	 */	synchronize_srcu(&amp;gpio_devices_srcu);	/* 返回 &quot;设备或资源繁忙&quot; 错误. */	return -EBUSY;&#125;

GPIO有效引脚掩码(Valid Mask)与引脚范围管理系列函数此代码片段展示了Linux内核gpiolib子系统中一组用于管理GPIO控制器引脚有效性和范围映射的函数。它们共同构成了一个强大而灵活的系统, 其核心原理是通过静态的设备树声明和&#x2F;或动态的驱动回调, 创建一个精确的”有效引脚掩码”(valid mask), 并将GPIO编号范围与pinctrl子系统关联起来。这使得gpiolib能够安全地处理具有非连续、复杂引脚布局的硬件, 并确保了不同子系统间的正确协作。

1. 有效引脚掩码的生命周期管理这组函数负责创建、填充和释放valid_mask位图。
gpiochip_allocate_mask &amp; gpiochip_free_mask &#x2F; gpiochip_free_valid_mask这是位图最基本的内存管理。allocate负责分配内存并设定一个”全部有效”的初始状态, free则负责释放。
/* gpiochip_allocate_mask: 分配一个有效掩码位图. */static unsigned long *gpiochip_allocate_mask(struct gpio_chip *gc)&#123;	unsigned long *p;	/* 使用内核位图API分配一块能容纳 ngpio 个比特的内存. */	p = bitmap_alloc(gc-&gt;ngpio, GFP_KERNEL);	if (!p)		return NULL;	/* 关键的初始状态: 默认假设所有GPIO引脚都是有效的, 将所有位都设置为1. */	bitmap_fill(p, gc-&gt;ngpio);	return p;&#125;/* gpiochip_free_mask: 释放一个掩码位图. */static void gpiochip_free_mask(unsigned long **p)&#123;	bitmap_free(*p); /* 释放位图内存. */	*p = NULL;       /* 将指针设为NULL, 防止悬挂指针. */&#125;/* gpiochip_free_valid_mask: devm框架使用的清理函数, 释放有效掩码. */static void gpiochip_free_valid_mask(struct gpio_chip *gc)&#123;	gpiochip_free_mask(&amp;gc-&gt;gpiodev-&gt;valid_mask);&#125;


2. 通过设备树声明无效引脚 (静态方式)这组函数实现了通过设备树中的gpio-reserved-ranges属性来声明无效引脚范围。
gpiochip_count_reserved_ranges &amp; gpiochip_apply_reserved_rangescount函数检查属性是否存在且格式正确, apply函数则读取属性内容并在valid_mask中”打孔”。
/* gpiochip_count_reserved_ranges: 计算 &quot;gpio-reserved-ranges&quot; 属性中的条目数量. */static unsigned int gpiochip_count_reserved_ranges(struct gpio_chip *gc)&#123;	struct device *dev = &amp;gc-&gt;gpiodev-&gt;dev;	int size;	/* 属性格式是成对的u32值: [起始偏移, 数量, ...], 所以总数必须是偶数. */	size = device_property_count_u32(dev, &quot;gpio-reserved-ranges&quot;);	if (size &gt; 0 &amp;&amp; size % 2 == 0)		return size;	return 0;&#125;/* gpiochip_apply_reserved_ranges: 读取保留范围属性并将其应用到有效掩码上. */static int gpiochip_apply_reserved_ranges(struct gpio_chip *gc)&#123;	// ... (代码逻辑: 1. 检查是否有保留范围. 2. 分配临时内存读取属性. 3. 读取属性.) ...    // ... (循环读取[start, count]对)	while (size) &#123;		u32 count = ranges[--size]; // 获取数量		u32 start = ranges[--size]; // 获取起始偏移		/* 安全检查, 确保范围不会超出芯片的能力. */		if (start &gt;= gc-&gt;ngpio || start + count &gt; gc-&gt;ngpio)			continue;		/* 核心操作: 在valid_mask位图中, 从start位开始, 清除count个位 (将它们设为0). */		bitmap_clear(gc-&gt;gpiodev-&gt;valid_mask, start, count);	&#125;    // ... (释放临时内存) ...	return 0;&#125;


3. 有效掩码的构建与查询这组函数是上层API, 用于协调掩码的构建过程并提供查询接口。
gpiochip_init_valid_mask这是gpiochip_add_data调用的主协调函数。
/* gpiochip_init_valid_mask: 为一个gpio_chip初始化其有效引脚掩码. */static int gpiochip_init_valid_mask(struct gpio_chip *gc)&#123;	int ret;	/* 只有在驱动定义了&quot;保留范围&quot;(静态方式)或提供了自定义初始化函数(动态方式)时, 才需要创建掩码. */	if (!(gpiochip_count_reserved_ranges(gc) || gc-&gt;init_valid_mask))		return 0;	/* 1. 分配一个全1的掩码. */	gc-&gt;gpiodev-&gt;valid_mask = gpiochip_allocate_mask(gc);	if (!gc-&gt;gpiodev-&gt;valid_mask)		return -ENOMEM;	/* 2. 应用设备树中定义的静态保留范围, 在掩码上&quot;打孔&quot;. */	ret = gpiochip_apply_reserved_ranges(gc);	if (ret)		return ret;	/* 3. 如果驱动提供了自定义的回调函数, 调用它, 给予驱动最后一次动态修改掩码的机会. */	if (gc-&gt;init_valid_mask)		return gc-&gt;init_valid_mask(gc,					   gc-&gt;gpiodev-&gt;valid_mask,					   gc-&gt;ngpio);	return 0;&#125;

gpiochip_query_valid_mask &amp; gpiochip_line_is_valid这两个函数提供了对已构建好的valid_mask的查询能力。
/* gpiochip_query_valid_mask: 返回整个有效掩码位图的指针. */const unsigned long *gpiochip_query_valid_mask(const struct gpio_chip *gc)&#123;	return gc-&gt;gpiodev-&gt;valid_mask;&#125;/* gpiochip_line_is_valid: 检查单个引脚是否有效. */bool gpiochip_line_is_valid(const struct gpio_chip *gc,				unsigned int offset)&#123;	/* 在芯片完全注册前(例如处理pin hog时), 默认所有引脚有效. */	if (!gc-&gt;gpiodev)		return true;	/* 快速路径优化: 如果没有掩码(NULL), 说明所有引脚都有效. */	if (likely(!gc-&gt;gpiodev-&gt;valid_mask))		return true;	/* 慢速路径: 检查掩码位图中对应的位是否为1. */	return test_bit(offset, gc-&gt;gpiodev-&gt;valid_mask);&#125;


4. GPIO范围与Pinctrl的关联gpiochip_add_pin_ranges此函数负责将GPIO控制器的编号范围与pinctrl子系统关联起来。
原理与作用:它的作用是调用驱动提供的add_pin_ranges回调函数, 在这个回调中驱动通常会手动调用pinctrl_add_gpio_range来注册映射关系。但是, 这个机制很大程度上是遗留(legacy)的。

现代方法: 现代内核强烈推荐使用设备树中的gpio-ranges属性来完成这个映射。内核的OF(Open Firmware)解析器会自动处理这个属性, 无需驱动操心。
函数行为: 因此, 此函数首先会检查设备树中是否存在gpio-ranges属性。如果存在, 它会立即返回成功, 有意地跳过调用驱动的add_pin_ranges回调, 以避免重复或冲突的映射。只有在gpio-ranges属性不存在时, 它才会调用那个遗留的回调函数, 以提供向后兼容性。

/* gpiochip_add_pin_ranges: 为gpio_chip添加引脚范围. */static int gpiochip_add_pin_ranges(struct gpio_chip *gc)&#123;	/*	 * 关键检查: 如果设备树平台已经使用了标准的&quot;gpio-ranges&quot;属性,	 * 那么就不应该再调用遗留的回调函数.	 */	if (device_property_present(&amp;gc-&gt;gpiodev-&gt;dev, &quot;gpio-ranges&quot;))		return 0;	/* 如果驱动提供了遗留的回调函数, 则调用它. */	if (gc-&gt;add_pin_ranges)		return gc-&gt;add_pin_ranges(gc);	return 0;&#125;

GPIO层次化中断域(Hierarchical IRQ Domain)实现此代码片段是Linux内核gpiolib中用于实现和管理层次化中断域的核心。其根本原理是为那些级联(cascaded)在另一个主中断控制器之下的GPIO控制器, 创建一个”子域”(child domain), 并提供一套完整的操作函数集来管理这个子域的生命周期, 包括它的创建、中断翻译、分配和释放。
这个模型对于像STM32这样具有分层中断结构的复杂SoC是必不可少的。在STM32中, GPIO引脚 -&gt; EXTI控制器 -&gt; NVIC(CPU)构成了一个清晰的中断层次。这组函数就是在软件层面精确地建模这种硬件上的父子级联关系, 使得内核能够正确地将一个来自特定GPIO引脚的中断请求, 逐级翻译并路由到CPU。

1. 域的创建与配置这组函数负责判断是否需要创建层次化域, 并执行创建和配置过程。
gpiochip_hierarchy_is_hierarchical一个简单的谓词函数, 用于判断是否应使用层次化模型。
/* gpiochip_hierarchy_is_hierarchical: 判断一个gpio_chip是否被配置为层次化中断. */static bool gpiochip_hierarchy_is_hierarchical(struct gpio_chip *gc)&#123;	/*	 * !! 是一个C语言技巧, 将任何非NULL指针转换为true(1), NULL指针转换为false(0).	 * 它的逻辑是: 如果驱动已经为 gc-&gt;irq.parent_domain 提供了有效的父域指针,	 * 那么就认为它工作在层次化模式下.	 */	return !!gc-&gt;irq.parent_domain;&#125;

gpiochip_hierarchy_setup_domain_ops为子域的irq_domain_ops结构体填充一组标准的、预设的回调函数。
/* gpiochip_hierarchy_setup_domain_ops: 为层次化域的操作函数集(ops)进行设置. */static void gpiochip_hierarchy_setup_domain_ops(struct irq_domain_ops *ops)&#123;	/* 当一个中断被请求时, 调用此函数来锁定GPIO引脚, 防止其被用作他途. */	ops-&gt;activate = gpiochip_irq_domain_activate;	/* 当中断被释放时, 调用此函数来解锁GPIO引脚. */	ops-&gt;deactivate = gpiochip_irq_domain_deactivate;	/* 当需要将硬件中断号映射到Linux IRQ号时, 调用此核心分配函数. */	ops-&gt;alloc = gpiochip_hierarchy_irq_domain_alloc;	/*	 * 对于层次化芯片, 我们只允许驱动有选择地覆盖 translate 和 free 函数.	 * 默认的 translate 函数能够处理标准的设备树绑定.	 * 默认的 free 函数能够处理通用的IRQ释放.	 */	if (!ops-&gt;translate)		ops-&gt;translate = gpiochip_hierarchy_irq_domain_translate;	if (!ops-&gt;free)		ops-&gt;free = irq_domain_free_irqs_common;&#125;

gpiochip_hierarchy_create_domain创建层次化中断域的主函数。
/* gpiochip_hierarchy_create_domain: 为一个gpio_chip创建一个层次化的中断域(子域). */static struct irq_domain *gpiochip_hierarchy_create_domain(struct gpio_chip *gc)&#123;	struct irq_domain *domain;	/* 健全性检查: 驱动必须提供核心的回调函数和固件节点. */	if (!gc-&gt;irq.child_to_parent_hwirq || !gc-&gt;irq.fwnode) &#123;		chip_err(gc, &quot;missing irqdomain vital data\n&quot;);		return ERR_PTR(-EINVAL);	&#125;	    /* 为驱动未提供的可选回调函数设置无操作的默认值, 简化驱动编写. */	if (!gc-&gt;irq.child_offset_to_irq)	/* 	static unsigned int gpiochip_child_offset_to_irq_noop(struct gpio_chip *gc,								unsigned int offset)	&#123;		return offset;	&#125;	*/		gc-&gt;irq.child_offset_to_irq = gpiochip_child_offset_to_irq_noop;	if (!gc-&gt;irq.populate_parent_alloc_arg)		gc-&gt;irq.populate_parent_alloc_arg =			gpiochip_populate_parent_fwspec_twocell;	/* 为子域配置标准的操作函数集. */	gpiochip_hierarchy_setup_domain_ops(&amp;gc-&gt;irq.child_irq_domain_ops);	/* 调用内核通用的层次化域创建函数, 实际创建域并建立父子链接. */	domain = irq_domain_create_hierarchy(		gc-&gt;irq.parent_domain, /* 父域 */		0,                     /* flags */		gc-&gt;ngpio,             /* 子域大小 */		gc-&gt;irq.fwnode,        /* 子域的固件节点 */		&amp;gc-&gt;irq.child_irq_domain_ops, /* 子域的操作函数集 */		gc);                   /* 私有数据 */	if (!domain)		return ERR_PTR(-ENOMEM);	/* 为irq_chip本身设置用于层次化操作的钩子 (主要是为了兼容非设备树的旧系统). */	gpiochip_set_hierarchical_irqchip(gc, gc-&gt;irq.chip);	return domain;&#125;


2. 中断域操作回调 (irq_domain_ops) 的实现这组函数是gpiochip_hierarchy_setup_domain_ops所设置的回调, 它们定义了子域的具体行为。
gpiochip_hierarchy_irq_domain_translate负责解析来自设备树的中断请求。
/* gpiochip_hierarchy_irq_domain_translate: 层次化域的translate回调. */static int gpiochip_hierarchy_irq_domain_translate(struct irq_domain *d,						   struct irq_fwspec *fwspec,						   unsigned long *hwirq,						   unsigned int *type)&#123;	/* 如果是标准的设备树节点, 使用内核提供的标准twocell/threecell翻译函数. */	if (is_of_node(fwspec-&gt;fwnode))		return irq_domain_translate_twothreecell(d, fwspec, hwirq, type);	/* 这是为了兼容旧的、非设备树的板级文件. */	if (is_fwnode_irqchip(fwspec-&gt;fwnode)) &#123;		// ... (处理旧格式) ...	&#125;	return -EINVAL;&#125;

gpiochip_hierarchy_irq_domain_alloc这是最核心的函数, 负责将一个子域的硬件中断(hwirq)映射到一个Linux IRQ, 并递归地向父域申请资源。
/* gpiochip_hierarchy_irq_domain_alloc: 层次化域的alloc回调. */static int gpiochip_hierarchy_irq_domain_alloc(struct irq_domain *d,					       unsigned int irq,					       unsigned int nr_irqs,					       void *data)&#123;	struct gpio_chip *gc = d-&gt;host_data; // 获取私有数据, 即gpio_chip	irq_hw_number_t hwirq; // 子域的硬件中断号 (即GPIO偏移)	unsigned int type = IRQ_TYPE_NONE;	struct irq_fwspec *fwspec = data; // 来自设备树的请求参数	union gpio_irq_fwspec gpio_parent_fwspec = &#123;&#125;; // 准备传递给父域的参数	unsigned int parent_hwirq; // 父域的硬件中断号 (即EXTI线号)	unsigned int parent_type;	struct gpio_irq_chip *girq = &amp;gc-&gt;irq;	int ret;	/* 步骤1: 将设备树请求翻译成本地域的hwirq和type. */	ret = gc-&gt;irq.child_irq_domain_ops.translate(d, fwspec, &amp;hwirq, &amp;type);	if (ret)		return ret;	/* 步骤2: 核心翻译. 调用驱动提供的回调, 将子域hwirq翻译成父域的parent_hwirq. */	ret = girq-&gt;child_to_parent_hwirq(gc, hwirq, type,					  &amp;parent_hwirq, &amp;parent_type);	if (ret) &#123;		chip_err(gc, &quot;can&#x27;t look up hwirq %lu\n&quot;, hwirq);		return ret;	&#125;	/* 步骤3: 设置本地域的映射关系. 将Linux IRQ(irq)与本地hwirq和irq_chip关联起来. */	irq_domain_set_info(d, irq, hwirq, gc-&gt;irq.chip, gc,			    girq-&gt;handler, NULL, NULL);	irq_set_probe(irq); // 标记此IRQ需要探测	/* 步骤4: 准备向父域申请资源的参数. */	ret = girq-&gt;populate_parent_alloc_arg(gc, &amp;gpio_parent_fwspec,					      parent_hwirq, parent_type);	if (ret)		return ret;	/* 步骤5: 递归向上, 向父域申请中断. 这会触发父域的alloc回调. */	ret = irq_domain_alloc_irqs_parent(d, irq, 1, &amp;gpio_parent_fwspec);	if (ret)		chip_err(gc, &quot;failed to allocate parent hwirq %d for hwirq %lu\n&quot;,			 parent_hwirq, hwirq);	return ret;&#125;

gpiochip_irq_domain_activate &#x2F; deactivate在请求&#x2F;释放中断时, 锁定&#x2F;解锁对应的GPIO引脚, 防止其被用作普通IO。
/* gpiochip_irq_domain_activate: activate回调, 锁定GPIO引脚作为IRQ. */static int gpiochip_irq_domain_activate(struct irq_domain *domain,					struct irq_data *data, bool reserve)&#123;	struct gpio_chip *gc = domain-&gt;host_data;	unsigned int hwirq = irqd_to_hwirq(data); // 从irq_data获取hwirq	/* 调用gpiolib内部函数, 将该引脚标记为&quot;已被IRQ使用&quot;. */	return gpiochip_lock_as_irq(gc, hwirq);&#125;/* gpiochip_irq_domain_deactivate: deactivate回调, 解锁作为IRQ的GPIO引脚. */static void gpiochip_irq_domain_deactivate(struct irq_domain *domain,					   struct irq_data *data)&#123;	struct gpio_chip *gc = domain-&gt;host_data;	unsigned int hwirq = irqd_to_hwirq(data);	/* 调用gpiolib内部函数, 解除引脚的&quot;已被IRQ使用&quot;标记. */	return gpiochip_unlock_as_irq(gc, hwirq);&#125;


3. 其他辅助与遗留(Legacy)支持函数/* gpiochip_set_hierarchical_irqchip: (主要用于遗留系统) 设置层次化irqchip. */static void gpiochip_set_hierarchical_irqchip(struct gpio_chip *gc,					      struct irq_chip *irqchip)&#123;	/* 如果使用设备树, 内核会动态处理映射, 无需此函数做任何事. */	if (is_of_node(gc-&gt;irq.fwnode))		return;	/*	 * 下面的代码是为了兼容旧的、不使用设备树的板级文件.	 * 它会尝试为所有可能的引脚预先分配中断.	 * 在现代内核和STM32开发中, 这部分代码通常不会被执行.	 */	// ... (legacy code) ...&#125;/* gpiochip_populate_parent_fwspec_*: 用于准备传递给父域中断分配函数的参数的默认实现. */int gpiochip_populate_parent_fwspec_twocell(struct gpio_chip *gc,					    union gpio_irq_fwspec *gfwspec,					    unsigned int parent_hwirq,					    unsigned int parent_type)&#123;	struct irq_fwspec *fwspec = &amp;gfwspec-&gt;fwspec;	fwspec-&gt;fwnode = gc-&gt;irq.parent_domain-&gt;fwnode; // 使用父域的节点	fwspec-&gt;param_count = 2; // 父域需要2个参数	fwspec-&gt;param[0] = parent_hwirq; // 第一个参数是父hwirq	fwspec-&gt;param[1] = parent_type;  // 第二个参数是触发类型	return 0;&#125;

GPIO简单中断域(Simple IRQ Domain)创建函数此代码片段展示了gpiolib中用于创建简单(或称”扁平”, flat)中断域的机制。其核心原理是为那些硬件结构较为简单、其GPIO中断线可以直接一对一映射到主中断控制器上的GPIO控制器, 提供一个简化的、非层次化的中断域创建流程。
这与我们之前讨论的gpiochip_hierarchy_create_domain形成了鲜明对比。层次化模型用于处理像STM32这样具有”GPIO -&gt; EXTI -&gt; NVIC”多级级联关系的复杂硬件, 而简单模型则适用于那些GPIO引脚中断可以直接被系统顶级中断控制器(如GIC on multi-core ARM, or NVIC on Cortex-M)识别的硬件。

gpiochip_irq_map: 映射一个Linux IRQ到GPIO引脚此函数是irq_domain_ops中最核心的回调函数。它的作用是建立一个从全局唯一的Linux IRQ号(irq)到特定GPIO控制器上一个本地硬件中断号(hwirq, 即引脚偏移量)的完整映射关系。它负责完成所有必要的软件配置, 为即将到来的中断做好准备。
原理与工作流程:

获取上下文: 从中断域的私有数据d-&gt;host_data中获取到对应的gpio_chip结构体, 这是所有操作的基础。
有效性检查: 调用gpiochip_irqchip_irq_valid检查hwirq(引脚偏移)是否在该gpio_chip的中断有效掩码内。如果一个引脚不支持中断, 则映射失败。
关联核心数据:
irq_set_chip_data(irq, gc): 将gpio_chip本身设置为该IRQ的”chip data”。这使得中断处理代码在处理这个IRQ时, 可以快速地回溯到管理它的GPIO控制器。
irq_set_chip_and_handler(irq, gc-&gt;irq.chip, gc-&gt;irq.handler): 这是关键的一步。它将驱动提供的irq_chip结构体(包含ack, mask, unmask等底层硬件操作函数)和中断流处理器(handler)与该IRQ关联起来。从此, 当这个IRQ触发时, 内核就知道应该调用哪个函数来处理它。


设置父IRQ (可选): 如果该GPIO控制器的中断是级联在一个父IRQ之下的(即使是在简单模型中也可能出现这种情况), 此函数会调用irq_set_parent来建立这种级联关系。
设置默认触发类型: 如果驱动程序在gpio_chip中指定了default_type (如边沿触发、电平触发), 此函数会调用irq_set_irq_type来将这个默认配置应用到硬件上。
配置特殊属性: 它还会设置一些额外的属性, 如lockdep锁分类(用于调试死锁)和nested_thread标志(用于支持嵌套的线程化中断处理器)。

/** * gpiochip_irq_map() - 将一个IRQ映射到一个GPIO irqchip中 * @d: 此irqchip使用的irqdomain * @irq: 此GPIO irqchip irq使用的全局irq号 * @hwirq: 此gpiochip上的本地IRQ/GPIO线偏移量 */static int gpiochip_irq_map(struct irq_domain *d, unsigned int irq,			    irq_hw_number_t hwirq)&#123;	struct gpio_chip *gc = d-&gt;host_data; // 获取gpio_chip上下文	int ret = 0;	/* 检查此hwirq(引脚)是否支持中断. */	if (!gpiochip_irqchip_irq_valid(gc, hwirq))		return -ENXIO; // 不支持则返回&quot;无此设备或地址&quot;错误	/* 将gpio_chip本身设置为此IRQ的私有数据. */	irq_set_chip_data(irq, gc);		/* 为锁调试器设置特殊的锁分类, 以避免误报. */	irq_set_lockdep_class(irq, gc-&gt;irq.lock_key, gc-&gt;irq.request_key);		/*	 * 核心关联: 将驱动提供的irq_chip和中断流处理器(handler)与此IRQ号绑定.	 * 当此IRQ触发时, 内核将调用 gc-&gt;irq.handler.	 * 在handler内部, 会再调用 gc-&gt;irq.chip 中的函数来操作硬件.	 */	irq_set_chip_and_handler(irq, gc-&gt;irq.chip, gc-&gt;irq.handler);		/* 如果驱动使用了嵌套线程化中断处理器, 则设置相应标志. */	if (gc-&gt;irq.threaded)		irq_set_nested_thread(irq, 1);		/* 标记此IRQ不需要在启动时被内核自动探测. */	irq_set_noprobe(irq);	/* 如果有父IRQ, 建立级联关系. */	if (gc-&gt;irq.num_parents == 1) // 简单级联, 只有一个父IRQ		ret = irq_set_parent(irq, gc-&gt;irq.parents[0]);	else if (gc-&gt;irq.map) // 复杂级联, 每个hwirq可能对应不同的父IRQ		ret = irq_set_parent(irq, gc-&gt;irq.map[hwirq]);	if (ret &lt; 0)		return ret;	/* 如果驱动指定了默认触发类型, 则应用它. */	if (gc-&gt;irq.default_type != IRQ_TYPE_NONE)		irq_set_irq_type(irq, gc-&gt;irq.default_type);	return 0;&#125;


gpiochip_irq_unmap: 解除一个Linux IRQ与GPIO引脚的映射此函数是gpiochip_irq_map的逆操作。当一个IRQ被释放时, 内核会调用此函数来清除所有在map阶段建立的软件关联。
/** * gpiochip_irq_unmap() - 解除一个IRQ与gpiochip的映射 * @d: irqdomain * @irq: 要解除映射的全局irq号 */static void gpiochip_irq_unmap(struct irq_domain *d, unsigned int irq)&#123;	struct gpio_chip *gc = d-&gt;host_data; // 获取gpio_chip上下文	/* 清除嵌套线程标志. */	if (gc-&gt;irq.threaded)		irq_set_nested_thread(irq, 0);		/*	 * 解除核心关联: 将irq_chip和handler都设为NULL.	 * 这样, 即使这个IRQ号意外触发, 内核也不会再调用旧的处理函数.	 */	irq_set_chip_and_handler(irq, NULL, NULL);		/* 清除私有数据. */	irq_set_chip_data(irq, NULL);&#125;


gpiochip_irq_select: 选择一个中断控制器此回调函数用于一个高级场景: 当一个设备在设备树中描述的中断可以由多个不同的中断控制器来提供服务时, 内核会调用.select回调来让驱动程序判断自己是否是那个”正确”的控制器。
原理与作用:它的主要作用是进行匹配。内核将从设备树中解析出的中断请求fwspec传递给它, 它需要将fwspec中的信息与自身irq_domain的信息进行比较。

对于使用设备树的现代系统, 它可能会调用of_gpiochip_instance_match来进行更复杂的匹配。
对于简单的、非层次化的域, 它主要比较fwspec中的固件节点(fwnode)是否与自身域的固件节点(d-&gt;fwnode)相同, 并可能比较总线令牌(bus_token)。如果匹配, 就返回true, 表示”这个中断请求是给我的”。

/** * gpiochip_irq_select() - 选择一个中断控制器来处理中断请求 * @d: irqdomain * @fwspec: 从设备树解析出的中断请求描述符 * @bus_token: 总线令牌 */static int gpiochip_irq_select(struct irq_domain *d, struct irq_fwspec *fwspec,			       enum irq_domain_bus_token bus_token)&#123;	struct fwnode_handle *fwnode = fwspec-&gt;fwnode;	struct gpio_chip *gc = d-&gt;host_data;	unsigned int index = fwspec-&gt;param[0];	/* 对于三单元格的设备树中断描述, 使用一个更复杂的匹配函数. */	if (fwspec-&gt;param_count == 3 &amp;&amp; is_of_node(fwnode))		return of_gpiochip_instance_match(gc, index);	/*	 * 对于两单元格的描述, 进行简单的匹配:	 * 请求的固件节点是否与本域的固件节点相同? 并且总线令牌是否匹配?	 */	return (fwnode &amp;&amp; (d-&gt;fwnode == fwnode) &amp;&amp; (d-&gt;bus_token == bus_token));&#125;

gpiochip_domain_ops: 简单域的操作函数集这是一个静态的irq_domain_ops结构体实例, 它为所有通过”简单模型”创建的GPIO中断域提供了一套标准的、通用的操作函数集。它就像是中断域的”行为手册”, 告诉内核在对该域进行各种操作时应该调用哪些函数。
/* * 定义一个静态的、常量类型的 struct irq_domain_ops 实例. * 这是为所有&quot;简单&quot;GPIO中断域提供的标准操作集. */static const struct irq_domain_ops gpiochip_domain_ops = &#123;	/*	 * .map: 指向 gpiochip_irq_map 函数.	 * 作用: 这是最重要的回调函数. 当内核需要将一个硬件中断号(hwirq, 在此上下文中就是GPIO的偏移量)	 *       映射到一个Linux IRQ号(virq)时, 此函数被调用. 它的职责是:	 *       1. 将virq与hwirq关联起来.	 *       2. 调用gpio_chip提供的irq_chip回调函数(如.irq_ack, .irq_mask)来配置硬件.	 *       3. 设置该IRQ的中断处理器(handler).	 */	.map	= gpiochip_irq_map,	/*	 * .unmap: 指向 gpiochip_irq_unmap 函数.	 * 作用: 这是 .map 的逆操作. 当一个映射被销毁时, 此函数被调用以释放硬件资源和软件关联.	 */	.unmap	= gpiochip_irq_unmap,	/*	 * .select: 指向 gpiochip_irq_select 函数.	 * 作用: (可选) 当一个IRQ可以由多个芯片或配置提供时, 此函数用于在它们之间进行选择.	 */	.select	= gpiochip_irq_select,	/*	 * .xlate: 指向 irq_domain_xlate_twothreecell 函数.	 * 作用: &quot;Translate&quot;, 即翻译. 此函数用于解析设备树(Device Tree)中的 &quot;interrupts&quot; 属性.	 *       内核提供了几个标准的xlate函数, irq_domain_xlate_twothreecell 用于处理最常见的两种格式:	 *       - 两单元格(twocell): interrupts = &lt;hwirq trigger_type&gt;; (例如 &lt;5 IRQ_TYPE_EDGE_RISING&gt;)	 *       - 三单元格(threecell): interrupts = &lt;hwirq trigger_type priority&gt;;	 *       它的职责是从设备树的这两个或三个单元格中提取出硬件中断号(hwirq)和触发类型等信息.	 */	.xlate	= irq_domain_xlate_twothreecell,&#125;;


gpiochip_simple_create_domain: 创建一个简单中断域这是一个内部函数, 它封装了内核通用的irq_domain_create_simple函数, 为GPIO控制器提供了一个便捷的创建接口。
/* * gpiochip_simple_create_domain: 为一个gpio_chip创建一个简单的中断域. * @gc: 目标gpio_chip. * @return: 成功时返回一个指向新创建的 irq_domain 的指针, 失败时返回一个错误指针. */static struct irq_domain *gpiochip_simple_create_domain(struct gpio_chip *gc)&#123;	/* 获取与该gpiolib设备关联的固件节点(设备树节点). */	struct fwnode_handle *fwnode = dev_fwnode(&amp;gc-&gt;gpiodev-&gt;dev);	struct irq_domain *domain;	/*	 * 调用内核通用的 irq_domain_create_simple 函数来完成实际的创建工作.	 * 这个函数适用于创建线性的、扁平的、一对一映射的中断域.	 * 参数解释:	 * - fwnode: 该中断控制器的固件节点.	 * - gc-&gt;ngpio: 域的大小, 即该控制器管理的GPIO(中断)数量.	 * - gc-&gt;irq.first: 硬件中断号(hwirq)的起始值. 对于简单模型, 这通常是0.	 * - &amp;gpiochip_domain_ops: 为这个新域指定上面定义好的标准操作函数集.	 * - gc: 将gpio_chip自身作为私有数据(host_data)传递给中断域, 以便在回调函数中可以访问到它.	 */	domain = irq_domain_create_simple(fwnode, gc-&gt;ngpio, gc-&gt;irq.first,					  &amp;gpiochip_domain_ops, gc);	/*	 * irq_domain_create_simple 在成功时返回域指针, 失败时返回NULL.	 * 这里将其转换为内核标准的错误指针格式.	 */	if (!domain)		return ERR_PTR(-EINVAL);	return domain;&#125;

gpiolib中断资源管理与使能&#x2F;禁用函数此代码片段展示了Linux内核gpiolib子系统中用于管理GPIO引脚作为中断资源的一组核心函数。这组函数与irqchip子系统紧密协作, 其根本原理是在一个GPIO引脚被用作中断源的整个生命周期中, 对其进行状态跟踪和访问控制。这包括:

锁定&#x2F;解锁: 当引脚被请求为中断时, 将其”锁定”, 防止它同时被用作普通的输入&#x2F;输出引脚, 从而避免了功能冲突。
模块引用计数: 确保提供GPIO控制器功能的内核模块在使用期间不会被意外卸载。
使能&#x2F;禁用状态跟踪: 在引脚的描述符中维护一个软件状态位, 记录该中断是处于使能还是禁用状态。

gpiochip_lock_as_irq: 将GPIO引脚锁定为中断模式当一个驱动程序请求一个GPIO引脚作为中断源时(通常在request_irq的调用链深处), irqchip子系统的request_resources回调函数(即gpiolib的gpiochip_reqres_irq)最终会调用此函数。
/** * gpiochip_lock_as_irq() - 锁定一个GPIO以用作IRQ * @gc: GPIO所属的chip * @offset: 要锁定为IRQ的GPIO的偏移量 * * 这个函数由那些希望锁定某条GPIO线用于IRQ的GPIO驱动直接使用. * * 返回: * 0 on success, or negative errno on failure. */int gpiochip_lock_as_irq(struct gpio_chip *gc, unsigned int offset)&#123;	struct gpio_desc *desc;	/* 步骤1: 获取该引脚的软件描述符. */	desc = gpiochip_get_desc(gc, offset);	if (IS_ERR(desc))		return PTR_ERR(desc); // 如果偏移无效, 返回错误.	/*	 * 步骤2 (可选的硬件同步):	 * 如果GPIO控制器的操作不能休眠(gc-&gt;can_sleep为false), 并且驱动提供了get_direction回调,	 * 这通常意味着寄存器访问非常快, 而且引脚方向可能被硬件或其他未知因素改变.	 * 在这种情况下, 函数会主动调用gpiod_get_direction()来从硬件回读当前的方向,	 * 以确保描述符中的软件状态与硬件的实际状态同步.	 */	if (!gc-&gt;can_sleep &amp;&amp; gc-&gt;get_direction) &#123;		int dir = gpiod_get_direction(desc);		if (dir &lt; 0) &#123;			chip_err(gc, &quot;%s: cannot get GPIO direction\n&quot;,				 __func__);			return dir;		&#125;	&#125;	/*	 * 步骤3: 关键的健全性检查.	 * 一个引脚要能作为中断输入, 它本身必须是输入模式, 或者是一种特殊的&quot;开漏&quot;(open drain)输出模式.	 * 开漏输出可以驱动低电平, 但在高电平状态下呈高阻态, 因此可以安全地感知外部信号的上拉或下拉.	 * 如果一个引脚被配置为标准的推挽(push-pull)输出模式, 那么它无法可靠地接收外部中断信号.	 * test_bit()用于原子地检查描述符中的标志位.	 */	if (test_bit(FLAG_IS_OUT, &amp;desc-&gt;flags) &amp;&amp;	    !test_bit(FLAG_OPEN_DRAIN, &amp;desc-&gt;flags)) &#123;		chip_err(gc,			 &quot;%s: tried to flag a GPIO set as output for IRQ\n&quot;,			 __func__);		return -EIO; // 返回&quot;IO错误&quot;	&#125;	/*	 * 步骤4: 核心操作.	 * 使用set_bit()原子地设置两个标志位:	 * FLAG_USED_AS_IRQ: 这是&quot;锁定&quot;标志, 表明该引脚现在被中断子系统独占.	 * FLAG_IRQ_IS_ENABLED: 将该中断的软件使能状态初始化为&quot;使能&quot;.	 */	set_bit(FLAG_USED_AS_IRQ, &amp;desc-&gt;flags);	set_bit(FLAG_IRQ_IS_ENABLED, &amp;desc-&gt;flags);	return 0; // 成功&#125;/* 将此函数导出, 使其对内核其他部分(主要是irqchip驱动)可用. */EXPORT_SYMBOL_GPL(gpiochip_lock_as_irq);


gpiochip_unlock_as_irq: 解锁一个用作中断的GPIO引脚当一个驱动程序释放一个中断时(在free_irq的调用链中), irqchip子系统的release_resources回调函数(即gpiolib的gpiochip_relres_irq)会调用此函数。
/** * gpiochip_unlock_as_irq() - 解锁一个用作IRQ的GPIO * @gc: GPIO所属的chip * @offset: 要解锁的GPIO的偏移量 * * 这个函数由那些希望表明某条GPIO不再被专门用于IRQ的GPIO驱动直接使用. */void gpiochip_unlock_as_irq(struct gpio_chip *gc, unsigned int offset)&#123;	struct gpio_desc *desc;	/* 步骤1: 获取该引脚的软件描述符. */	desc = gpiochip_get_desc(gc, offset);	if (IS_ERR(desc))		return; // 如果偏移无效, 静默返回.	/*	 * 步骤2: 核心操作.	 * 使用clear_bit()原子地清除两个标志位, 解除锁定并重置状态.	 * 此后, 该引脚就可以被重新配置为普通的输入或输出引脚了.	 */	clear_bit(FLAG_USED_AS_IRQ, &amp;desc-&gt;flags);	clear_bit(FLAG_IRQ_IS_ENABLED, &amp;desc-&gt;flags);&#125;/* 将此函数导出. */EXPORT_SYMBOL_GPL(gpiochip_unlock_as_irq);


gpiochip_reqres_irq &#x2F; gpiochip_relres_irq: 请求&#x2F;释放中断资源这两个函数是irqchip子系统的request_resources和release_resources回调函数的标准实现。它们负责一个GPIO引脚作为中断源的”获取”和”释放”操作。
/** * gpiochip_reqres_irq - 请求一个GPIO引脚作为中断资源 * @gc: 目标gpio_chip * @offset: 该chip上的引脚偏移量 */int gpiochip_reqres_irq(struct gpio_chip *gc, unsigned int offset)&#123;	int ret;	/*	 * 步骤1: 增加模块引用计数.	 * try_module_get()会尝试增加提供该GPIO控制器的内核模块(owner)的引用计数.	 * 这可以防止在中断正在使用时, 该模块被`rmmod`命令卸载, 从而避免了使用悬挂指针导致的系统崩溃.	 */	if (!try_module_get(gc-&gt;gpiodev-&gt;owner))		return -ENODEV;	/*	 * 步骤2: 将引脚锁定为中断模式.	 * gpiochip_lock_as_irq()会在该引脚的描述符中设置一个FLAG_USED_AS_IRQ标志.	 * 任何后续尝试通过gpiod_direction_*()等函数来改变该引脚方向的操作,	 * 都会因为检查到这个标志而失败.	 */	ret = gpiochip_lock_as_irq(gc, offset);	if (ret) &#123;		/*		 * 错误处理: 如果锁定失败, 必须撤销第一步的操作.		 * module_put()会减少模块的引用计数.		 */		chip_err(gc, &quot;unable to lock HW IRQ %u for IRQ\n&quot;, offset);		module_put(gc-&gt;gpiodev-&gt;owner);		return ret;	&#125;	return 0; // 成功&#125;EXPORT_SYMBOL_GPL(gpiochip_reqres_irq);/** * gpiochip_relres_irq - 释放一个作为中断资源的GPIO引脚 * @gc: 目标gpio_chip * @offset: 该chip上的引脚偏移量 */void gpiochip_relres_irq(struct gpio_chip *gc, unsigned int offset)&#123;	/*	 * 步骤1: 解锁引脚.	 * gpiochip_unlock_as_irq()会清除FLAG_USED_AS_IRQ标志,	 * 使得该引脚可以被重新用作普通的GPIO.	 */	gpiochip_unlock_as_irq(gc, offset);	/*	 * 步骤2: 减少模块引用计数.	 * 与try_module_get()配对, 表明我们已经不再需要这个模块提供的中断服务了.	 */	module_put(gc-&gt;gpiodev-&gt;owner);&#125;EXPORT_SYMBOL_GPL(gpiochip_relres_irq);

gpiochip_enable_irq &#x2F; gpiochip_disable_irq: 使能&#x2F;禁用中断(软件状态)这两个函数通常被irq_chip的mask&#x2F;unmask回调函数的包装器所调用。它们只负责在gpiolib的软件层面更新中断的使能状态, 而不直接操作硬件。硬件的屏蔽&#x2F;解屏蔽操作由irq_chip回调本身负责。
/** * gpiochip_disable_irq - (在gpiolib层面)禁用一个GPIO中断 * @gc: 目标gpio_chip * @offset: 该chip上的引脚偏移量 */void gpiochip_disable_irq(struct gpio_chip *gc, unsigned int offset)&#123;	/* 获取该引脚的描述符(gpio_desc). */	struct gpio_desc *desc = gpiochip_get_desc(gc, offset);	/*	 * 检查描述符是否有效, 并使用WARN_ON确保该引脚确实被配置为中断模式.	 * 如果一个引脚没有被配置为中断, 那么禁用它是一个逻辑错误, WARN_ON会打印警告.	 */	if (!IS_ERR(desc) &amp;&amp;	    !WARN_ON(!test_bit(FLAG_USED_AS_IRQ, &amp;desc-&gt;flags)))		/* 核心操作: 清除描述符中的FLAG_IRQ_IS_ENABLED标志位. */		clear_bit(FLAG_IRQ_IS_ENABLED, &amp;desc-&gt;flags);&#125;EXPORT_SYMBOL_GPL(gpiochip_disable_irq);/** * gpiochip_enable_irq - (在gpiolib层面)使能一个GPIO中断 * @gc: 目标gpio_chip * @offset: 该chip上的引脚偏移量 */void gpiochip_enable_irq(struct gpio_chip *gc, unsigned int offset)&#123;	/* 获取该引脚的描述符. */	struct gpio_desc *desc = gpiochip_get_desc(gc, offset);	if (!IS_ERR(desc) &amp;&amp;	    !WARN_ON(!test_bit(FLAG_USED_AS_IRQ, &amp;desc-&gt;flags))) &#123;		/*		 * 关键的健全性检查:		 * 一个引脚在用作中断时, 通常必须是输入模式.		 * 唯一的例外是它被配置为&quot;开漏&quot;(open drain)输出, 此时它可以同时驱动低电平并感知外部信号.		 * 如果一个推挽(push-pull)输出引脚被用作中断, 这是一个硬件配置错误, WARN_ON会打印警告.		 */		WARN_ON(test_bit(FLAG_IS_OUT, &amp;desc-&gt;flags) &amp;&amp;			!test_bit(FLAG_OPEN_DRAIN, &amp;desc-&gt;flags));		/* 核心操作: 设置描述符中的FLAG_IRQ_IS_ENABLED标志位. */		set_bit(FLAG_IRQ_IS_ENABLED, &amp;desc-&gt;flags);	&#125;&#125;EXPORT_SYMBOL_GPL(gpiochip_enable_irq);

gpiolib中断控制器(irqchip)的实现此代码片段是Linux内核gpiolib子系统与irqchip子系统集成的核心部分。它的根本原理是提供一套标准的适配器(Adapter)和包装器(Wrapper)函数, 将一个驱动程序提供的、特定于硬件的gpio_chip对象, 封装成一个内核可以统一识别和管理的标准irq_chip对象。这使得任何一个GPIO控制器, 无论其硬件实现如何, 都能作为中断源无缝地融入内核的中断处理框架, 从而实现了gpio_to_irq()这个关键功能。

1. gpio_to_irq的核心实现gpiochip_to_irq是驱动程序和内核其他部分将一个GPIO引脚坐标(控制器+偏移)翻译成一个全局Linux IRQ号所调用的核心API。
/** * gpiochip_to_irq - 将一个gpiochip上的偏移量翻译成Linux IRQ号 * @gc: 目标gpio_chip * @offset: 该chip上的引脚偏移量 * @return: 成功时返回Linux IRQ号, 失败时返回负的错误码 */static int gpiochip_to_irq(struct gpio_chip *gc, unsigned int offset)&#123;	struct irq_domain *domain = gc-&gt;irq.domain; // 获取与该chip关联的中断域	/*	 * 关键的竞态条件防护: 检查irq子系统是否已完全初始化.	 * 如果一个驱动尝试获取IRQ, 但gpiochip的irqchip部分尚未通过	 * gpiochip_irqchip_add_allocated_domain()注册完毕, gc-&gt;irq.initialized会是false.	 * 返回-EPROBE_DEFER是标准的处理方法, 请求内核稍后重试该驱动的探测.	 */	if (!gc-&gt;irq.initialized)		return -EPROBE_DEFER;	/* 检查该引脚是否在硬件上支持中断. */	if (!gpiochip_irqchip_irq_valid(gc, offset))		return -ENXIO; // 不支持则返回&quot;无此设备或地址&quot;#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY	/*	 * 如果这是一个层次化域 (例如STM32的GPIO域是EXTI域的子域).	 */	if (irq_domain_is_hierarchy(domain)) &#123;		struct irq_fwspec spec; // 创建一个通用的中断请求描述符		spec.fwnode = domain-&gt;fwnode; // 使用子域的固件节点		spec.param_count = 2; // 指定请求包含2个参数		/* 第一个参数: 本地硬件中断号(hwirq), 即引脚偏移 */		spec.param[0] = gc-&gt;irq.child_offset_to_irq(gc, offset);		/* 第二个参数: 触发类型, 此时未知, 设为NONE */		spec.param[1] = IRQ_TYPE_NONE;		/*		 * 调用irq_create_fwspec_mapping(), 这个函数会触发整个层次化域的		 * 分配(alloc)流程, 逐级向上申请和翻译, 最终创建一个完整的映射.		 */		return irq_create_fwspec_mapping(&amp;spec);	&#125;#endif	/*	 * 对于简单的(非层次化的)域, 直接调用irq_create_mapping.	 * 这个函数会使用domain-&gt;ops-&gt;map回调(即gpiochip_irq_map)来建立映射.	 */	return irq_create_mapping(domain, offset);&#125;


2. irq_chip回调函数的包装器gpiochip_set_irq_hooks函数通过巧妙的指针交换, 将gpiolib自己的通用逻辑”注入”到驱动提供的irq_chip回调中。下面是被注入的包装器函数, 它们在调用驱动原始的回调函数的同时, 执行了gpiolib的通用操作。
/* gpiochip_irq_reqres: &quot;request_resources&quot;回调的包装器. */int gpiochip_irq_reqres(struct irq_data *d)&#123;	/* 从irq_data中获取gpio_chip上下文 */	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	/* 从irq_data中获取硬件中断号(引脚偏移) */	unsigned int hwirq = irqd_to_hwirq(d);	/* 调用gpiolib内部函数, 将该引脚锁定为IRQ模式, 防止被用作普通GPIO. */	return gpiochip_reqres_irq(gc, hwirq);&#125;EXPORT_SYMBOL(gpiochip_irq_reqres);/* gpiochip_irq_relres: &quot;release_resources&quot;回调的包装器. */void gpiochip_irq_relres(struct irq_data *d)&#123;	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	unsigned int hwirq = irqd_to_hwirq(d);	/* 解锁引脚, 使其可以被重新用作普通GPIO. */	gpiochip_relres_irq(gc, hwirq);&#125;EXPORT_SYMBOL(gpiochip_irq_relres);/* gpiochip_irq_mask: &quot;irq_mask&quot;回调的包装器. */static void gpiochip_irq_mask(struct irq_data *d)&#123;	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	unsigned int hwirq = irqd_to_hwirq(d);	/* 如果驱动提供了自己的irq_mask实现, 先调用它. */	if (gc-&gt;irq.irq_mask)		gc-&gt;irq.irq_mask(d);	/* 然后, 调用gpiolib的通用disable函数. */	gpiochip_disable_irq(gc, hwirq);&#125;/* gpiochip_irq_unmask: &quot;irq_unmask&quot;回调的包装器. */static void gpiochip_irq_unmask(struct irq_data *d)&#123;	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	unsigned int hwirq = irqd_to_hwirq(d);	/* 先调用gpiolib的通用enable函数. */	gpiochip_enable_irq(gc, hwirq);	/* 如果驱动提供了自己的irq_unmask实现, 再调用它. */	if (gc-&gt;irq.irq_unmask)		gc-&gt;irq.irq_unmask(d);&#125;/* gpiochip_irq_enable: &quot;irq_enable&quot;回调的包装器 (用于旧式API). */static void gpiochip_irq_enable(struct irq_data *d)&#123;	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	unsigned int hwirq = irqd_to_hwirq(d);	gpiochip_enable_irq(gc, hwirq);	/* 调用驱动原始的irq_enable. */	gc-&gt;irq.irq_enable(d);&#125;/* gpiochip_irq_disable: &quot;irq_disable&quot;回调的包装器 (用于旧式API). */static void gpiochip_irq_disable(struct irq_data *d)&#123;	struct gpio_chip *gc = irq_data_get_irq_chip_data(d);	unsigned int hwirq = irqd_to_hwirq(d);	/* 调用驱动原始的irq_disable. */	gc-&gt;irq.irq_disable(d);	gpiochip_disable_irq(gc, hwirq);&#125;


3. irqchip的安装与初始化这组函数负责将上述所有部分组装起来, 完成irqchip在gpiolib中的注册。
/* gpiochip_set_irq_hooks: 为gpio_chip的irqchip安装包装器钩子. */static void gpiochip_set_irq_hooks(struct gpio_chip *gc)&#123;	struct irq_chip *irqchip = gc-&gt;irq.chip;	/*	 * 如果irq_chip被标记为&quot;不可变的&quot;(immutable), 说明其回调函数不应被修改,	 * 直接返回. 这是现代驱动推荐的做法.	 */	if (irqchip-&gt;flags &amp; IRQCHIP_IMMUTABLE)		return;	/* 否则, 打印一条警告, 建议驱动作者修复它. */	chip_warn(gc, &quot;not an immutable chip, please consider fixing it!\n&quot;);	/* 如果驱动没有提供资源管理回调, 则安装gpiolib的默认实现. */	if (!irqchip-&gt;irq_request_resources &amp;&amp;	    !irqchip-&gt;irq_release_resources) &#123;		irqchip-&gt;irq_request_resources = gpiochip_irq_reqres;		irqchip-&gt;irq_release_resources = gpiochip_irq_relres;	&#125;	if (WARN_ON(gc-&gt;irq.irq_enable))		return;	// ... (检查共享irqchip的警告) ...	/*	 * 核心的指针交换&quot;包装&quot;逻辑:	 * 1. 保存驱动原始的回调函数指针到gc-&gt;irq的私有字段中.	 * 2. 用gpiolib自己的包装器函数覆盖irqchip中的回调函数指针.	 */	if (irqchip-&gt;irq_disable) &#123;		gc-&gt;irq.irq_disable = irqchip-&gt;irq_disable;		irqchip-&gt;irq_disable = gpiochip_irq_disable;	&#125; else &#123;		gc-&gt;irq.irq_mask = irqchip-&gt;irq_mask;		irqchip-&gt;irq_mask = gpiochip_irq_mask;	&#125;	if (irqchip-&gt;irq_enable) &#123;		gc-&gt;irq.irq_enable = irqchip-&gt;irq_enable;		irqchip-&gt;irq_enable = gpiochip_irq_enable;	&#125; else &#123;		gc-&gt;irq.irq_unmask = irqchip-&gt;irq_unmask;		irqchip-&gt;irq_unmask = gpiochip_irq_unmask;	&#125;&#125;/* gpiochip_irqchip_add_allocated_domain: 将一个已分配的域与gpio_chip关联. */static int gpiochip_irqchip_add_allocated_domain(struct gpio_chip *gc,						 struct irq_domain *domain,						 bool allocated_externally)&#123;	if (!domain)		return -EINVAL;	/*	 * 警告并覆盖驱动中可能存在的旧的、已废弃的to_irq函数指针.	 * 现代驱动不应再使用它.	 */	if (gc-&gt;to_irq)		chip_warn(gc, &quot;to_irq is redefined in %s and you shouldn&#x27;t rely on it\n&quot;, __func__);	/*	 * 将gpiolib自己的to_irq实现和已创建的domain关联到gpio_chip.	 */	gc-&gt;to_irq = gpiochip_to_irq;	gc-&gt;irq.domain = domain;	gc-&gt;irq.domain_is_allocated_externally = allocated_externally;	/*	 * 使用内存屏障, 防止编译器将下面的initialized赋值操作重排到前面的指针赋值之前.	 * 这是确保竞态条件防护有效的关键.	 */	barrier();	/*	 * 最后, 设置initialized标志为true, 向外界宣告irqchip已准备就绪.	 */	gc-&gt;irq.initialized = true;	return 0;&#125;

gpiochip_add_irqchip: 为GPIO控制器添加中断控制器功能此函数是Linux内核gpiolib和irqchip两大子系统之间的核心桥梁。它的根本原理是将一个已经注册的GPIO控制器(gpio_chip)进一步封装和注册, 使其在内核中也扮演一个标准的中断控制器(irqchip)的角色。完成此函数的调用后, gpiolib就具备了将一个GPIO引脚号翻译成一个全局Linux IRQ号的能力(即gpio_to_irq()功能得以实现), 并且能够处理来自该引脚的中断请求。
这是一个复杂但设计精巧的注册过程, 其工作流程如下:

前提检查与配置: 函数首先进行一系列健全性检查。例如, 如果驱动使用了”链式中断处理器”(parent_handler), 那么该GPIO控制器的操作函数就绝不能休眠, 因为链式处理器通常在原子上下文中被调用。它还会警告并修正一个不推荐的做法: 在设备树系统中使用驱动硬编码的默认中断触发类型, 因为这应该由设备树来描述。

创建中断域 (irq_domain) - 核心逻辑: 这是函数最关键的一步。它会根据GPIO控制器的特性, 选择两种方式之一来创建其中断域:

层次化域 (Hierarchical Domain): 这是为像STM32这样复杂的SoC设计的。在这种模型中, GPIO控制器本身并不是顶级中断控制器, 而是作为一个次级(或三级)控制器, 级联(cascaded)在另一个主中断控制器之下(例如, STM32的EXTI)。函数会调用gpiochip_hierarchy_create_domain来创建一个子域(child domain), 并将其与驱动指定的**父域(parent domain)**关联起来。
简单域 (Simple Domain): 对于一些简单的硬件, GPIO控制器可能就是主中断源, 或者其级联关系非常简单。在这种情况下, 函数会创建一个独立的、非层次化的中断域。


设置链式中断处理器 (可选): 如果GPIO控制器是一个”中断解复用器”(即它自己有一条中断线连接到父中断控制器, 当其任何一个引脚中断时, 这条线都会触发), 此函数会调用irq_set_chained_handler_and_data。这个调用会将父中断控制器上的那个IRQ配置为: 当它触发时, 不去执行一个普通的中断服务程序, 而是直接调用本GPIO控制器驱动提供的parent_handler函数。这个parent_handler的职责就是去查询自己内部的寄存器, 找出到底是哪个GPIO引脚真正触发了中断。

最终注册与激活: 在创建好irq_domain并设置好所有链接后, 函数会调用gpiochip_irqchip_add_allocated_domain将这个域与gpio_chip正式绑定。从此, gpiolib和irqchip两大子系统就完全关联起来了。


在STM32H750上的应用:STM32的中断系统是典型的层次化结构:GPIO Pin -&gt; GPIO Bank -&gt; EXTI Controller -&gt; NVIC (CPU Interrupt Controller)
因此, 当STM32的GPIO驱动调用gpiochip_add_irqchip时, 总是会走”层次化域”的路径:

STM32的EXTI驱动会首先注册一个代表EXTI的父irq_domain。
当gpiolib为GPIOA这个Bank注册irqchip时, gpiochip_add_irqchip会创建一个新的irq_domain, 并将其parent指针指向EXTI的域。
当上层驱动调用gpio_to_irq()请求PA5的中断时, 这个两级域的层次结构就会被用来进行翻译, 最终返回一个由NVIC管理的、全局唯一的Linux IRQ号。

/* * gpiochip_add_irqchip: 为一个GPIO chip添加一个IRQ chip功能. * @gc: 要添加IRQ chip功能的GPIO chip. * @lock_key: 用于锁调试的锁分类键 (IRQ锁). * @request_key: 用于锁调试的锁分类键 (IRQ请求锁). * * 返回: 成功时返回0, 失败时返回负的错误码. */static int gpiochip_add_irqchip(struct gpio_chip *gc,				struct lock_class_key *lock_key,				struct lock_class_key *request_key)&#123;	struct fwnode_handle *fwnode = dev_fwnode(&amp;gc-&gt;gpiodev-&gt;dev);	struct irq_chip *irqchip = gc-&gt;irq.chip;	struct irq_domain *domain;	unsigned int type;	unsigned int i;	int ret;	/* 如果驱动没有提供 irqchip 结构体, 说明它不支持中断, 直接成功返回. */	if (!irqchip)		return 0;	/*	 * 健全性检查: 如果驱动使用了链式中断处理器, 那么它的操作函数绝不能休眠.	 * 因为链式处理器在原子上下文中被调用, 睡眠会导致系统死锁.	 */	if (gc-&gt;irq.parent_handler &amp;&amp; gc-&gt;can_sleep) &#123;		chip_err(gc, &quot;you cannot have chained interrupts on a chip that may sleep\n&quot;);		return -EINVAL;	&#125;	type = gc-&gt;irq.default_type;	/*	 * 健全性检查: 在使用设备树(fwnode存在)的系统中, 不应在驱动中硬编码默认触发类型.	 * 触发类型应该由设备树描述. 如果驱动这么做了, 打印警告并忽略该默认值.	 */	if (WARN(fwnode &amp;&amp; type != IRQ_TYPE_NONE,		 &quot;%pfw: Ignoring %u default trigger\n&quot;, fwnode, type))		type = IRQ_TYPE_NONE;	gc-&gt;irq.default_type = type;	gc-&gt;irq.lock_key = lock_key;	gc-&gt;irq.request_key = request_key;	/*	 * 核心逻辑: 根据驱动配置, 创建中断域.	 * 如果提供了父域, 则构建一个层次化域.	 */	if (gpiochip_hierarchy_is_hierarchical(gc)) &#123;		domain = gpiochip_hierarchy_create_domain(gc);	&#125; else &#123; /* 否则, 创建一个简单的、非层次化的域. */		domain = gpiochip_simple_create_domain(gc);	&#125;	if (IS_ERR(domain))		return PTR_ERR(domain);	/* 如果驱动配置了链式中断处理器. */	if (gc-&gt;irq.parent_handler) &#123;		/* 遍历所有父中断线. */		for (i = 0; i &lt; gc-&gt;irq.num_parents; i++) &#123;			void *data;			/* 获取传递给处理器的私有数据. */			if (gc-&gt;irq.per_parent_data)				data = gc-&gt;irq.parent_handler_data_array[i];			else				data = gc-&gt;irq.parent_handler_data ?: gc;			/*			 * 将父IRQ配置为链式中断模式.			 * 当父IRQ触发时, 会直接调用我们提供的 parent_handler 函数.			 */			irq_set_chained_handler_and_data(gc-&gt;irq.parents[i],							 gc-&gt;irq.parent_handler,							 data);		&#125;	&#125;	/* 设置gpiolib内部用于中断处理的钩子函数. */	gpiochip_set_irq_hooks(gc);	/* 将新创建的域与gpiochip正式关联起来. */	ret = gpiochip_irqchip_add_allocated_domain(gc, domain, false);	if (ret)		return ret;	/* 为ACPI平台请求中断(在非ACPI系统上此函数为空操作). */	acpi_gpiochip_request_interrupts(gc);	return 0;&#125;

gpiochip_setup_dev: 创建GPIO控制器的用户空间接口此函数是gpiolib注册流程的最后一步, 也是至关重要的一步。它的核心原理是将一个已经在内核内部完全初始化好的gpio_device对象”发布”(publish)给系统的更高层和用户空间, 主要通过两种机制来完成: 注册一个字符设备(character device) 和 创建其sysfs接口。
这个函数是连接内核内部的gpiolib世界和外部的用户空间世界的桥梁。在此函数成功执行之前, GPIO控制器只存在于内核的内存中; 在此函数执行之后, 它就成为了一个用户空间工具(如libgpiod的gpiodetect, gpioinfo命令)和udev&#x2F;mdev系统可以看见并与之交互的实体。
工作流程详解:

设备对象初始化: 它首先调用device_initialize, 对内核的gpio_device内部嵌入的struct device对象进行标准化的最后准备。此时, 设备对象已准备就绪, 但尚未对系统可见。
字符设备注册: 这是最关键的一步。它调用gcdev_register(GPIO Character Device Register), 将该GPIO控制器注册为一个字符设备。
内核会从gpiolib的动态主设备号gpio_devt中为这个新设备分配一个唯一的设备号(major:minor)。
这个注册操作会触发udev或mdev守护进程, 在/dev/目录下自动创建一个对应的设备节点, 例如/dev/gpiochip0。
现代的Linux GPIO用户空间工具(基于libgpiod)就是通过open()这个字符设备节点来与内核中的GPIO控制器进行交互的, 这种方式取代了旧的、已被废弃的通过sysfs的/sys/class/gpio/export接口来控制引脚的方法。


Sysfs接口注册: 它接着调用gpiochip_sysfs_register, 在/sys/class/gpio/目录下创建一个名为gpiochipN (N是该控制器的ID号)的符号链接, 指向其在/sys/devices/下的真实设备目录。同时, 它还会创建一些用于描述该控制器属性的只读文件, 例如:
label: 包含该控制器的名称(例如 “GPIOA”)。
base: 该控制器在全局GPIO编号空间中的起始编号。
ngpio: 该控制器管理的引脚数量。这些sysfs文件主要用于系统状态的查看、调试和诊断。


错误处理: 函数包含了健壮的错误处理逻辑。如果在注册sysfs接口时失败, 它会跳转到err_remove_device标签, 调用gcdev_unregister来撤销已经成功的字符设备注册, 从而保证了系统状态的一致性, 不会留下一个”半注册”的设备。

在STM32H750上的应用:当STM32驱动为每一个GPIO Bank(如GPIOA, GPIOB)调用gpiochip_add_data并成功完成所有内部初始化后, gpiochip_setup_dev就会被调用。

为GPIOA调用此函数后, 系统中就会出现/dev/gpiochip0设备节点和/sys/class/gpio/gpiochip0符号链接。
在Linux终端中运行gpioinfo命令, 你会看到一行输出, 显示”gpiochip0 [GPIOA] 16 lines”, 这些信息就是通过读写/dev/gpiochip0和解析其sysfs属性而获得的。
同样地, 为GPIOB调用后, 就会出现/dev/gpiochip1和/sys/class/gpio/gpiochip1。这个过程对所有使能的GPIO Bank依次重复。

/* * gpiochip_setup_dev: 为一个gpio_device设置其设备模型和用户空间接口. */static int gpiochip_setup_dev(struct gpio_device *gdev)&#123;	/* 获取与该gpiolib设备关联的固件节点(设备树节点)句柄. */	struct fwnode_handle *fwnode = dev_fwnode(&amp;gdev-&gt;dev);	int ret;	/*	 * 对gdev内部嵌入的struct device对象进行标准初始化.	 * 此时该设备对象已在内存中准备好, 但尚未注册到内核设备模型中.	 */	device_initialize(&amp;gdev-&gt;dev);	/*	 * 一个微妙的检查: 如果一个固件节点(fwnode)没有被一个主要设备所拥有	 * (fwnode-&gt;dev为NULL), 那么我们可以安全地清除它的&quot;已初始化&quot;标志.	 * 这允许我们将这个新的gpio_device作为该fwnode的主要用户接口.	 */	if (fwnode &amp;&amp; !fwnode-&gt;dev)		fwnode_dev_initialized(fwnode, false);	/*	 * 步骤1: 注册一个字符设备.	 * 这使得用户空间可以通过 /dev/gpiochipN 节点与此控制器交互.	 * gpio_devt 是gpiolib子系统的主设备号.	 */	ret = gcdev_register(gdev, gpio_devt);	if (ret)		return ret;	/*	 * 步骤2: 注册sysfs接口.	 * 这会创建 /sys/class/gpio/gpiochipN 等目录和属性文件.	 */	ret = gpiochip_sysfs_register(gdev);	if (ret)		goto err_remove_device; /* 如果失败, 跳转到错误处理路径. */	/*	 * 打印一条调试信息, 宣告该GPIO控制器已成功注册.	 */	dev_dbg(&amp;gdev-&gt;dev, &quot;registered GPIOs %u to %u on %s\n&quot;, gdev-&gt;base,		gdev-&gt;base + gdev-&gt;ngpio - 1, gdev-&gt;label);	return 0; /* 成功 *//* 错误处理路径 */err_remove_device:	/*	 * 撤销操作: 如果sysfs注册失败, 必须将已经成功注册的字符设备注销掉,	 * 以保持系统状态的一致性.	 */	gcdev_unregister(gdev);	return ret;&#125;

gpiochip_add_data: 将一个GPIO控制器注册到内核此函数是Linux内核gpiolib子系统的心脏。一个设备驱动程序(例如STM32的pinctrl驱动)在准备好一个描述其硬件能力的struct gpio_chip结构体之后, 会调用此函数, 将其正式注册并”激活”, 使其成为一个对整个内核可用的、功能完备的GPIO控制器。
它的核心原理是一个精心设计的、分阶段的”构造”过程, 它将一个驱动提供的、半成品的gpio_chip蓝图, 实例化为一个内核内部的、标准化的gpio_device对象, 并将其与内核的各大关键子系统(设备模型、中断系统、pinctrl系统、设备树)一一链接起来。
/* 这两个宏为调用者提供了更简洁的API, 它们会自动将用于高级锁分类的key参数设置为NULL. */#define gpiochip_add_data(gc, data) gpiochip_add_data_with_key(gc, data, NULL, NULL)#define devm_gpiochip_add_data(dev, gc, data) \	devm_gpiochip_add_data_with_key(dev, gc, data, NULL, NULL)

gpiochip_add_data_with_key: 核心注册函数工作流程概览:

内部对象创建: 函数首先为内核创建一个内部的gpio_device结构体, 这是gpiolib核心用来管理控制器的标准容器。它还会为此控制器分配一个全局唯一的ID号(例如, 0, 1, 2…), 并生成对应的设备名(如 “gpiochip0”)。
描述符分配: 它为该控制器的每一个引脚都分配一个struct gpio_desc描述符。这是现代内核中代表单个GPIO引脚的标准方式。
全局编号空间分配: 它会为该控制器在Linux全局GPIO编号空间中分配一段连续的编号。虽然这种全局编号机制已不被推荐(现代驱动应使用描述符), 但为了兼容旧的API和sysfs接口, 这一步仍然是必需的。此函数支持动态分配(推荐, gc-&gt;base = -1)和静态分配(已废弃)两种模式。
子系统集成: 这是最关键的部分, 它像接线员一样, 将这个新创建的gpio_device连接到各个相关子系统:
pinctrl: 调用gpiochip_add_pin_ranges来注册GPIO编号范围。
设备树(OF): 调用of_gpiochip_add来解析设备树中与GPIO相关的属性。
中断(IRQ): 调用gpiochip_add_irqchip将该GPIO控制器注册为一个irqchip(中断控制器), 这使得gpio_to_irq()功能得以实现。


sysfs设备创建: 最后, 它调用gpiochip_setup_dev在/sys/class/gpio/目录下创建对应的gpiochipN设备节点, 使得用户空间工具(如gpiodetect, udev)可以看到并与之交互。
错误处理: 此函数拥有一个非常健壮的错误处理机制。它使用了一系列的goto标签, 如果在上述任何一个阶段失败, 程序会跳转到对应的标签, 并以与注册相反的顺序, 精确地撤销所有已经成功完成的步骤, 确保不会有任何资源泄漏或状态不一致, 保证了系统的稳定性。

在STM32H750上的应用:当stm32_gpiolib_register_bank函数为STM32的某一个GPIO Bank(例如, GPIOA)准备好其gpio_chip结构体后, 它就会调用gpiochip_add_data (通过宏)。这个调用会触发上述所有流程, 最终结果是:

GPIOA被注册为gpiochipN。
它所管理的16个引脚(PA0-PA15)在内核中都有了对应的gpio_desc。
它会被分配一段GPIO编号(例如, 0-15)。
gpio_to_irq功能被激活, 可以将PA5的中断请求转换为一个全局的Linux IRQ号。
其他驱动程序从此可以通过gpio_request(5, ...)来申请并使用PA5。


