lookup 查找文件struct romfs_dirent *__dfs_romfs_lookup(struct romfs_dirent *root_dirent, constchar *path, rt_size_t *size)&#123;    rt_size_t index, found;    constchar *subpath, *subpath_end;    struct romfs_dirent *dirent;    rt_size_t dirent_size;    /* goto root directy entries */    dirent = (struct romfs_dirent *)root_dirent-&gt;data;    dirent_size = root_dirent-&gt;size;    /* get the end position of this subpath */    while (dirent != NULL)    &#123;        found = 0;        /* search in folder */        for (index = 0; index &lt; dirent_size; index ++)        &#123;            if (check_dirent(&amp;dirent[index]) != 0)                returnNULL;            if (rt_strlen(dirent[index].name) == (subpath_end - subpath) &amp;&amp;                    rt_strncmp(dirent[index].name, subpath, (subpath_end - subpath)) == 0)            &#123;                dirent_size = dirent[index].size;                if (dirent[index].type == ROMFS_DIRENT_DIR)                &#123;                    /* enter directory */                    dirent = (struct romfs_dirent *)dirent[index].data;                    found = 1;                    break;                &#125;                else                &#123;                    /* return file dirent */                    return &amp;dirent[index];                &#125;            &#125;        &#125;    &#125;    /* not found */    returnNULL;&#125;staticstruct dfs_vnode *dfs_romfs_lookup (struct dfs_dentry *dentry)&#123;    rt_size_t size;    struct dfs_vnode *vnode = RT_NULL;    struct romfs_dirent *root_dirent = RT_NULL, *dirent = RT_NULL;    //mount时挂载的数据    root_dirent = (struct romfs_dirent *)dentry-&gt;mnt-&gt;data;    if (check_dirent(root_dirent) == 0)    &#123;        /* create a vnode */        vnode = dfs_vnode_create();        if (vnode)        &#123;            dirent = __dfs_romfs_lookup(root_dirent, dentry-&gt;pathname, &amp;size);            if (dirent)            &#123;                vnode-&gt;nlink = 1;                vnode-&gt;size = dirent-&gt;size;                if (dirent-&gt;type == ROMFS_DIRENT_DIR)                &#123;                    vnode-&gt;mode = romfs_modemap[ROMFS_DIRENT_DIR] | (S_IRUSR | S_IXUSR | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);                    vnode-&gt;type = FT_DIRECTORY;                &#125;                elseif (dirent-&gt;type == ROMFS_DIRENT_FILE)                &#123;                    vnode-&gt;mode = romfs_modemap[ROMFS_DIRENT_FILE] | (S_IRUSR | S_IXUSR | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);                    vnode-&gt;type = FT_REGULAR;                &#125;                //挂载vnode数据                vnode-&gt;data = dirent;                vnode-&gt;mnt = dentry-&gt;mnt;            &#125;            else            &#123;                dfs_vnode_destroy(vnode);                vnode = RT_NULL;            &#125;        &#125;    &#125;    return vnode;&#125;

