getdents 获取目录条目staticintdfs_tmpfs_getdents(struct dfs_file *file,                       struct dirent *dirp,                       uint32_t    count)&#123;    //create_vnode中创建的文件    d_file = (struct tmpfs_file *)file-&gt;vnode-&gt;data;    rt_mutex_take(&amp;file-&gt;vnode-&gt;lock, RT_WAITING_FOREVER);    end = file-&gt;fpos + count;    index = 0;    count = 0;    //获取文件的子目录    rt_list_for_each(list, &amp;d_file-&gt;subdirs)    &#123;           //获取子目录中的兄弟节点进行拷贝        n_file = rt_list_entry(list, struct tmpfs_file, sibling);        if (index &gt;= (rt_size_t)file-&gt;fpos)        &#123;            d = dirp + count;            if (d_file-&gt;type == TMPFS_TYPE_FILE)            &#123;                d-&gt;d_type = DT_REG;            &#125;            if (d_file-&gt;type == TMPFS_TYPE_DIR)            &#123;                d-&gt;d_type = DT_DIR;            &#125;            d-&gt;d_namlen = RT_NAME_MAX;            d-&gt;d_reclen = (rt_uint16_t)sizeof(struct dirent);            rt_strncpy(d-&gt;d_name, n_file-&gt;name, TMPFS_NAME_MAX);            count += 1;            file-&gt;fpos += 1;        &#125;        index += 1;        if (index &gt;= end)        &#123;            break;        &#125;    &#125;    rt_mutex_release(&amp;file-&gt;vnode-&gt;lock);    return count * sizeof(struct dirent);&#125;

truncate 截断文件staticintdfs_tmpfs_truncate(struct dfs_file *file, off_toffset)&#123;    d_file = (struct tmpfs_file *)file-&gt;vnode-&gt;data;    superblock = d_file-&gt;sb;    ptr = rt_realloc(d_file-&gt;data, offset);    rt_spin_lock(&amp;superblock-&gt;lock);    superblock-&gt;df_size = offset;    rt_spin_unlock(&amp;superblock-&gt;lock);    /* update d_file and file size */    d_file-&gt;data = ptr;    d_file-&gt;size = offset;    file-&gt;vnode-&gt;size = d_file-&gt;size;    return0;&#125;

DFS 虚拟文件系统https://www.rt-thread.org/document/site/#/rt-thread-version/rt-thread-standard/programming-manual/filesystem/filesystem
FatFS 是专为小型嵌入式设备开发的一个兼容微软 FAT 格式的文件系统，采用 ANSI C 编写，具有良好的硬件无关性以及可移植性，是 RT-Thread 中最常用的文件系统类型。传统型的 RomFS 文件系统是一种简单的、紧凑的、只读的文件系统，不支持动态擦写保存，按顺序存放数据，因而支持应用程序以 XIP(execute In Place，片内运行) 方式运行，在系统运行时, 节省 RAM 空间。Jffs2 文件系统是一种日志闪存文件系统。主要用于 NOR 型闪存，基于 MTD 驱动层，特点是：可读写的、支持数据压缩的、基于哈希表的日志型文件系统，并提供了崩溃 / 掉电安全保护，提供写平衡支持等。DevFS 即设备文件系统，在 RT-Thread 操作系统中开启该功能后，可以将系统中的设备在 /dev 文件夹下虚拟成文件，使得设备可以按照文件的操作方式使用 read、write 等接口进行操作。NFS 网络文件系统（Network File System）是一项在不同机器、不同操作系统之间通过网络共享文件的技术。在操作系统的开发调试阶段，可以利用该技术在主机上建立基于 NFS 的根文件系统，挂载到嵌入式设备上，可以很方便地修改根文件系统的内容。UFFS 是 Ultra-low-cost Flash File System（超低功耗的闪存文件系统）的简称。它是国人开发的、专为嵌入式设备等小内存环境中使用 Nand Flash 的开源文件系统。与嵌入式中常使用的 Yaffs 文件系统相比具有资源占用少、启动速度快、免费等优势。

