挂载(挂载指定设备到指定目录)挂载是指将一个存储设备挂接到一个已存在的路径上。我们要访问存储设备中的文件，必须将文件所在的分区挂载到一个已存在的路径上，然后通过这个路径来访问存储设备
/* *    parent(mount path) *    mnt_parent &lt;- - - - - - -  + *         |                     | *         |- mnt_child &lt;- - - - - -+ (1 refcount) *                 |             | *                 |- parent - - + (1 refcount) */intdfs_mount(constchar *device_name,              constchar *path,              constchar *filesystemtype,              unsignedlongrwflag,              constvoid *data)&#123;    struct dfs_filesystem_type *type = *_find_filesystem(filesystemtype);    if (type)    &#123;        //对于路径进行规范化,内部使用malloc,需要注意释放        fullpath = dfs_normalize_path(RT_NULL, path);        if (fullpath)        &#123;            /* open specific device */            if (device_name) dev_id = rt_device_find(device_name);            //不需要设备支持的文件系统 或者 设备存在            if (!(type-&gt;fs_ops-&gt;flags &amp; FS_NEED_DEVICE) ||                ((type-&gt;fs_ops-&gt;flags &amp; FS_NEED_DEVICE) &amp;&amp; dev_id))            &#123;                mnt_parent = dfs_mnt_lookup(fullpath);                if ((!mnt_parent &amp;&amp; (strcmp(fullpath, &quot;/&quot;) == 0 || strcmp(fullpath, &quot;/dev&quot;) == 0))                    || (mnt_parent &amp;&amp; strcmp(fullpath, &quot;/&quot;) == 0 &amp;&amp; strcmp(mnt_parent-&gt;fullpath, fullpath) != 0))                &#123;                    /* it&#x27;s the root file system */                    /* the mount point dentry is the same as root dentry. */                    mnt_parent = dfs_mnt_create(fullpath); /* mnt-&gt;ref_count should be 1. */                    if (mnt_parent)                    &#123;                        mnt_parent-&gt;fs_ops = type-&gt;fs_ops;                        mnt_parent-&gt;dev_id = dev_id;                        if (mnt_parent-&gt;fs_ops-&gt;mount)                        &#123;                            ret = mnt_parent-&gt;fs_ops-&gt;mount(mnt_parent, rwflag, data);                            if (ret == RT_EOK)                            &#123;                                mnt_child = mnt_parent;                                mnt_child-&gt;flags |= MNT_IS_MOUNTED;                                dfs_mnt_insert(RT_NULL, mnt_child);                                dfs_mnt_unref(mnt_parent);                                /*                                * About root mnt:                                * There are two ref_count:                                * 1. the gobal root reference.                                * 1. the mnt-&gt;parent reference.                                */                            &#125;                            else                            &#123;                                dfs_mnt_destroy(mnt_parent);                                mnt_parent = RT_NULL;                                rt_set_errno(EPERM);                            &#125;                        &#125;                        else                        &#123;                            dfs_mnt_destroy(mnt_parent);                            mnt_parent = RT_NULL;                            rt_set_errno(EIO);                        &#125;                    &#125;                &#125;            &#125;        &#125;    &#125;&#125;

mnt挂载点/* * mnt tree structure * * mnt_root &lt;----------------------------------------+ *   | (child)                +----------+           | *   v          (sibling)     v          |           | *   mnt_child0     -&gt;    mnt_child1     |           | *                            | (child)  |           | *                            v         / (parent)   | (root) *                            mnt_child10         ---/ * */

mnt创建struct dfs_mnt *dfs_mnt_create(constchar *path)&#123;    struct dfs_mnt *mnt = rt_calloc(1, sizeof(struct dfs_mnt));    mnt-&gt;fullpath = rt_strdup(path);        //alloc路径    rt_list_init(&amp;mnt-&gt;sibling);            //初始化兄弟节点    rt_list_init(&amp;mnt-&gt;child);              //初始化子节点    mnt-&gt;flags |= MNT_IS_ALLOCED;           //设置标志,已分配    rt_atomic_store(&amp;(mnt-&gt;ref_count), 1);  //引用计数    return mnt;&#125;

mnt销毁intdfs_mnt_destroy(struct dfs_mnt* mnt)&#123;    if (mnt-&gt;flags &amp; MNT_IS_MOUNTED)    &#123;        if (mnt-&gt;flags &amp; MNT_IS_ADDLIST)        &#123;            dfs_mnt_remove(mnt);        &#125;    &#125;    dfs_mnt_unref(mnt);&#125;/* remove mnt from mnt_tree */intdfs_mnt_remove(struct dfs_mnt* mnt)&#123;    //没有子节点,执行删除兄弟节点    if (rt_list_isempty(&amp;mnt-&gt;child))    &#123;        rt_list_remove(&amp;mnt-&gt;sibling);        if (mnt-&gt;parent)        &#123;            /* parent unref parent */            rt_atomic_sub(&amp;(mnt-&gt;parent-&gt;ref_count), 1);        &#125;        ret = RT_EOK;    &#125;    else    &#123;        //有子节点,返回错误        LOG_W(&quot;remove a mnt point:%s with child.&quot;, mnt-&gt;fullpath);    &#125;    return ret;&#125;intdfs_mnt_unref(struct dfs_mnt* mnt)&#123;    if (mnt)    &#123;        rt_atomic_sub(&amp;(mnt-&gt;ref_count), 1);        if (rt_atomic_load(&amp;(mnt-&gt;ref_count)) == 0)        &#123;            dfs_lock();            if (mnt-&gt;flags &amp; MNT_IS_UMOUNT)            &#123;                mnt-&gt;fs_ops-&gt;umount(mnt);            &#125;            /* free full path */            rt_free(mnt-&gt;fullpath);            mnt-&gt;fullpath = RT_NULL;            rt_free(mnt);            dfs_unlock();        &#125;        else        &#123;            DLOG(note, &quot;mnt&quot;, &quot;mnt(%s),ref_count=%d&quot;, mnt-&gt;fs_ops-&gt;name, rt_atomic_load(&amp;(mnt-&gt;ref_count)));        &#125;    &#125;&#125;

mnt查找/** * this function will return the file system mounted on specified path. * * @parampath the specified path string. * * @return the found file system or NULL if no file system mounted on * specified path */struct dfs_mnt *dfs_mnt_lookup(constchar *fullpath)&#123;    struct dfs_mnt *mnt = _root_mnt;    struct dfs_mnt *iter = RT_NULL;    if (mnt)    &#123;        int mnt_len = rt_strlen(mnt-&gt;fullpath);        dfs_lock();        if ((strncmp(mnt-&gt;fullpath, fullpath, mnt_len) == 0) &amp;&amp; //路径匹配            (mnt_len == 1 || (fullpath[mnt_len] == &#x27;\0&#x27;) || (fullpath[mnt_len] == &#x27;/&#x27;))) //根路径或者具有子目录或者路径结束        &#123;            //挂载点存在子节点            while (!rt_list_isempty(&amp;mnt-&gt;child))            &#123;                //遍历寻找匹配的子节点                rt_list_for_each_entry(iter, &amp;mnt-&gt;child, sibling)                &#123;                    mnt_len = rt_strlen(iter-&gt;fullpath);                    if ((strncmp(iter-&gt;fullpath, fullpath, mnt_len) == 0) &amp;&amp;                        ((fullpath[mnt_len] == &#x27;\0&#x27;) || (fullpath[mnt_len] == &#x27;/&#x27;)))                    &#123;                        mnt = iter;                        break;                    &#125;                &#125;                if (mnt != iter) break;            &#125;        &#125;        else        &#123;            mnt = RT_NULL;        &#125;        dfs_unlock();        if (mnt)        &#123;            LOG_D(&quot;mnt_lookup: %s path @ mount point %p&quot;, fullpath, mnt);            DLOG(note, &quot;mnt&quot;, &quot;found mnt(%s)&quot;, mnt-&gt;fs_ops-&gt;name);        &#125;    &#125;    return mnt;&#125;

mnt插入intdfs_mnt_insert(struct dfs_mnt* mnt, struct dfs_mnt* child)&#123;    if (child)    &#123;        if (mnt == RT_NULL)        &#123;            /* insert into root */            mnt = dfs_mnt_lookup(child-&gt;fullpath);            if (mnt == RT_NULL //找不到该路径            || (strcmp(child-&gt;fullpath, &quot;/&quot;) == 0)) //插入为根路径            &#123;                /* it&#x27;s root mnt */                mnt = child;                mnt-&gt;flags |= MNT_IS_LOCKED;                /* ref to gobal root */                if (_root_mnt)                &#123;                    child = _root_mnt;                    rt_atomic_sub(&amp;(_root_mnt-&gt;parent-&gt;ref_count), 1);                    rt_atomic_sub(&amp;(_root_mnt-&gt;ref_count), 1);                    _root_mnt = dfs_mnt_ref(mnt);                    mnt-&gt;parent = dfs_mnt_ref(mnt);                    mnt-&gt;flags |= MNT_IS_ADDLIST;                    mkdir(&quot;/dev&quot;, 0777);                &#125;                else                &#123;                    //根路径不存在,直接赋值当前mnt挂载点为根路径                    _root_mnt = dfs_mnt_ref(mnt);//引用次数+1                &#125;            &#125;        &#125;        if (mnt)        &#123;            child-&gt;flags |= MNT_IS_ADDLIST;            if (child != mnt)            &#123;                /* not the root, insert into the child list */                rt_list_insert_before(&amp;mnt-&gt;child, &amp;child-&gt;sibling);                /* child ref self */                dfs_mnt_ref(child);            &#125;            /* parent ref parent */            child-&gt;parent = dfs_mnt_ref(mnt);        &#125;    &#125;    return0;&#125;

mnt搜索staticstruct dfs_mnt* _dfs_mnt_foreach(struct dfs_mnt *mnt, struct dfs_mnt* (*func)(struct dfs_mnt *mnt, void *parameter), void *parameter)&#123;    struct dfs_mnt *iter, *ret = NULL;    if (mnt)    &#123;        //执行注册的函数        ret = func(mnt, parameter);        if (ret == RT_NULL)        &#123;            //具有子节点            if (!rt_list_isempty(&amp;mnt-&gt;child))            &#123;                //遍历子节点的兄弟节点,都执行一次注册的函数                rt_list_for_each_entry(iter, &amp;mnt-&gt;child, sibling)                &#123;                    ret = _dfs_mnt_foreach(iter, func, parameter);                    if (ret != RT_NULL)                    &#123;                        break;                    &#125;                &#125;            &#125;        &#125;    &#125;    else    &#123;        ret = RT_NULL;    &#125;    return ret;&#125;

