mkdir 创建目录/** * this function is a POSIX compliant version, which will make a directory * * @parampath the directory path to be made. * @parammode * * @return 0 on successful, others on failed. */intmkdir(constchar *path, mode_tmode)&#123;    int result;    struct stat stat;    struct dfs_file file;    if (path == NULL)    &#123;        rt_set_errno(-EBADF);        return -1;    &#125;    //dfs_file_lstat == 0,证明该目录已经存在    if (path &amp;&amp; dfs_file_lstat(path, &amp;stat) == 0)    &#123;        rt_set_errno(-EEXIST);        return -1;    &#125;    dfs_file_init(&amp;file);    result = dfs_file_open(&amp;file, path, O_DIRECTORY | O_CREAT, mode);    if (result &gt;= 0)    &#123;        dfs_file_close(&amp;file);        result = 0;    &#125;    else    &#123;        rt_set_errno(result);        result = -1;    &#125;    dfs_file_deinit(&amp;file);    return result;&#125;

