/** * this function is a POSIX compliant version, which will open a file and * return a file descriptor according specified flags. * * @paramfile the path name of file. * @paramflags the file open flags. * * @return the non-negative integer on successful open, others for failed. */intopen(constchar *file, intflags, ...)&#123;    fd = fd_new();    if (fd &gt;= 0)    &#123;        df = fd_get(fd);    &#125;    else    &#123;        rt_set_errno(-RT_ERROR);        return RT_NULL;    &#125;    result = dfs_file_open(df, file, flags, mode);    if (result &lt; 0)    &#123;        fd_release(fd);        rt_set_errno(result);        return -1;    &#125;    return fd;&#125;

utimensat 修改文件时间intutimensat(int__fd, constchar *__path, conststruct timespec __times[2], int__flags)&#123;    int ret;    struct stat buffer;    struct dfs_file *d;    char *fullpath;    struct dfs_attr attr;    time_t current_time;    char *link_fn = (char *)rt_malloc(DFS_PATH_MAX);    int err;    if (__path == NULL)    &#123;        return -EFAULT;    &#125;    //1. 获取文件路径    if (__path[0] == &#x27;/&#x27; || __fd == AT_FDCWD)    &#123;        if (stat(__path, &amp;buffer) &lt; 0)        &#123;            return -ENOENT;        &#125;        else        &#123;            fullpath = (char*)__path;        &#125;    &#125;    else    &#123;        if (__fd != AT_FDCWD)        &#123;            d = fd_get(__fd);            if (!d || !d-&gt;vnode)            &#123;                return -EBADF;            &#125;            fullpath = dfs_dentry_full_path(d-&gt;dentry);            if (!fullpath)            &#123;                rt_set_errno(-ENOMEM);                return -1;            &#125;        &#125;    &#125;    //2. update time    attr.ia_valid = ATTR_ATIME_SET | ATTR_MTIME_SET;    time(&amp;current_time);    if (UTIME_NOW == __times[0].tv_nsec)    &#123;        attr.ia_atime.tv_sec = current_time;    &#125;    elseif (UTIME_OMIT != __times[0].tv_nsec)    &#123;        attr.ia_atime.tv_sec = __times[0].tv_sec;    &#125;    else    &#123;        attr.ia_valid &amp;= ~ATTR_ATIME_SET;    &#125;    if (UTIME_NOW == __times[1].tv_nsec)    &#123;        attr.ia_mtime.tv_sec = current_time;    &#125;    elseif (UTIME_OMIT == __times[1].tv_nsec)    &#123;        attr.ia_mtime.tv_sec = __times[1].tv_sec;    &#125;    else    &#123;        attr.ia_valid &amp;= ~ATTR_MTIME_SET;    &#125;    // 3. 获取文件属性    if (dfs_file_lstat(fullpath, &amp;buffer) == 0)    &#123;        if (S_ISLNK(buffer.st_mode) &amp;&amp; (__flags != AT_SYMLINK_NOFOLLOW))        &#123;            if (link_fn)            &#123;                err = dfs_file_readlink(fullpath, link_fn, DFS_PATH_MAX);                if (err &lt; 0)                &#123;                    rt_free(link_fn);                    return -ENOENT;                &#125;                else                &#123;                    fullpath = link_fn;                    if (dfs_file_stat(fullpath, &amp;buffer) != 0)                    &#123;                        rt_free(link_fn);                        return -ENOENT;                    &#125;                &#125;            &#125;        &#125;    &#125;    // 4. 设置文件属性    attr.st_mode = buffer.st_mode;    ret = dfs_file_setattr(fullpath, &amp;attr);    rt_free(link_fn);    return ret;&#125;

