init &amp;&amp; deinitvoiddfs_file_init(struct dfs_file *file)&#123;    if (file)    &#123;        rt_memset(file, 0x00, sizeof(struct dfs_file));        file-&gt;magic = DFS_FD_MAGIC;        rt_mutex_init(&amp;file-&gt;pos_lock, &quot;fpos&quot;, RT_IPC_FLAG_PRIO);        rt_atomic_store(&amp;(file-&gt;ref_count), 1);    &#125;&#125;voiddfs_file_deinit(struct dfs_file *file)&#123;    if (file)    &#123;        rt_mutex_detach(&amp;file-&gt;pos_lock);    &#125;&#125;

open &amp;&amp; close/** * this function will open a file which specified by path with specified oflags. * * @paramfd the file descriptor pointer to return the corresponding result. * @parampath the specified file path. * @paramoflags the oflags for open operator. * * @return 0 on successful, -1 on failed. */intdfs_file_open(struct dfs_file *file, constchar *path, intoflags, mode_tmode)&#123;    //1. 找到路径的挂载点,并获取文件目录    dentry = dfs_dentry_lookup(mnt, fullpath, oflags);    if (dentry &amp;&amp; dentry-&gt;vnode-&gt;type == FT_SYMLINK)    //链接文件,类似与快捷方式    &#123;        /* it&#x27;s a symbol link but not follow */        if (oflags &amp; O_NOFOLLOW)        &#123;            /* no follow symbol link */            dfs_dentry_unref(dentry);            dentry = RT_NULL;        &#125;        else        &#123;            struct dfs_dentry *target_dentry = RT_NULL;            char *path = dfs_file_realpath(&amp;mnt, fullpath, DFS_REALPATH_ONLY_LAST);            if (path)            &#123;                target_dentry = dfs_dentry_lookup(mnt, path, oflags);                rt_free(path);            &#125;            dfs_dentry_unref(dentry);            dentry = target_dentry;        &#125;    &#125;    //2. 创建文件/目录    if (oflags &amp; O_CREAT)    &#123;        dfs_file_lock();        dentry = dfs_dentry_create(mnt, fullpath);        if (dentry)        &#123;            vnode = mnt-&gt;fs_ops-&gt;create_vnode(dentry, oflags &amp; O_DIRECTORY ? FT_DIRECTORY:FT_REGULAR, mode);            if (vnode)            &#123;                /* set vnode */                dentry-&gt;vnode = vnode;  /* the refcount of created vnode is 1. no need to reference */                dfs_dentry_insert(dentry);            &#125;            else            &#123;                DLOG(msg, mnt-&gt;fs_ops-&gt;name, &quot;dfs_file&quot;, DLOG_MSG_RET, &quot;create failed.&quot;);                dfs_dentry_unref(dentry);                dentry = RT_NULL;            &#125;        &#125;        dfs_file_unlock();    &#125;    //3. 将文件放在目录下    if (dentry)    &#123;        rt_bool_t permission = RT_TRUE;        //文件的目录        file-&gt;dentry = dentry;        file-&gt;vnode = dentry-&gt;vnode;        file-&gt;fops  = dentry-&gt;mnt-&gt;fs_ops-&gt;default_fops;        file-&gt;flags = oflags;        dfs_file_lock();        ret = file-&gt;fops-&gt;open(file);        dfs_file_unlock();    &#125;&#125;

intdfs_file_close(struct dfs_file *file)&#123;    int ret = -RT_ERROR;    if (file)    &#123;        if (dfs_file_lock() == RT_EOK)        &#123;            rt_atomic_t ref_count = rt_atomic_load(&amp;(file-&gt;ref_count));            //引用计数为1进入关闭流程            if (ref_count == 1 &amp;&amp; file-&gt;fops &amp;&amp; file-&gt;fops-&gt;close)            &#123;                ret = file-&gt;fops-&gt;close(file);                if (ret == 0) /* close file sucessfully */                &#123;                    dfs_file_unref(file);                &#125;            &#125;            else            &#123;                //还有引用, 减少引用                dfs_file_unref(file);                ret = 0;            &#125;            dfs_file_unlock();        &#125;    &#125;    return ret;&#125;

read &amp;&amp; write
write不允许指定位置写入,只能顺序写入;pwrite允许指定位置写入
write和read都会对文件的位置进行加锁,防止多线程操作文件时出现问题
实际使用过程中,如果具有多线程操作文件的需求,可以使用 pwrite和 pread进行操作

ssize_tdfs_file_read(struct dfs_file *file, void *buf, size_tlen)&#123;    /* fpos lock */    off_t pos = dfs_file_get_fpos(file);    ret = file-&gt;fops-&gt;read(file, buf, len, &amp;pos);    /* fpos unlock */    dfs_file_set_fpos(file, pos);&#125;ssize_tdfs_file_write(struct dfs_file *file, constvoid *buf, size_tlen)&#123;    /* fpos lock */    pos = dfs_file_get_fpos(file);    &#123;        ret = file-&gt;fops-&gt;write(file, buf, len, &amp;pos);    &#125;    if (file-&gt;flags &amp; O_SYNC)    &#123;        file-&gt;fops-&gt;flush(file);    &#125;    dfs_file_set_fpos(file, pos);&#125;

