-vnode节点对 File types进行统一抽象
/* File types */#define FT_REGULAR      0   /* regular file */#define FT_SOCKET       1   /* socket file  */#define FT_DIRECTORY    2   /* directory    */#define FT_USER         3   /* user defined */#define FT_DEVICE       4   /* device */#define FT_SYMLINK      5   /* symbol link */#define FT_NONLOCK      6   /* non lock */struct dfs_vnode&#123;    uint16_t type;               /* Type (regular or socket) */    char *path;                  /* Name (below mount point) */    char *fullpath;              /* Full path is hash key */    int ref_count;               /* Descriptor reference count */    rt_list_t list;              /* The node of vnode hash table */    struct dfs_filesystem *fs;    conststruct dfs_file_ops *fops;    uint32_t flags;              /* self flags, is dir etc.. */    size_t   size;               /* Size in bytes */    void *data;                  /* Specific file system data */&#125;;struct dfs_dentry&#123;    rt_list_t hashlist;    uint32_t flags;#define DENTRY_IS_MOUNTED   0x1 /* dentry is mounted */#define DENTRY_IS_ALLOCED   0x2 /* dentry is allocated */#define DENTRY_IS_ADDHASH   0x4 /* dentry was added into hash table */#define DENTRY_IS_OPENED    0x8 /* dentry was opened. */    char *pathname;             /* the pathname under mounted file sytem */    struct dfs_vnode *vnode;    /* the vnode of this dentry */    struct dfs_mnt *mnt;        /* which mounted file system does this dentry belong to */    rt_atomic_t ref_count;    /* the reference count */&#125;;

哈希表
对路径进行hash,并根据挂载点进行hash并取模 DFS_DENTRY_HASH_NR以分配到不同的哈希链表

staticuint32_t_dentry_hash(struct dfs_mnt *mnt, constchar *path)&#123;    uint32_t val = 0;    if (path)    &#123;        while (*path)        &#123;            val = ((val &lt;&lt; 5) + val) + *path++;        &#125;    &#125;    return (val ^ (unsignedlong) mnt) &amp; (DFS_DENTRY_HASH_NR - 1);&#125;

