staticvoidrt_link_frame_check(void)&#123;    staticstruct rt_link_frame receive_frame = &#123;0&#125;;    staticrt_link_frame_parse_t analysis_status = FIND_FRAME_HEAD;    staticrt_uint8_t *data = RT_NULL;    staticrt_uint16_t buff_len = RT_LINK_HEAD_LENGTH;    struct rt_link_frame *send_frame = RT_NULL;    rt_tick_t timeout = 0;    rt_uint32_t temporary_crc = 0;    rt_uint8_t offset = 0;    rt_size_t recv_len = rt_link_hw_recv_len(rt_link_scb-&gt;rx_buffer);    while (recv_len &gt; 0)    &#123;        switch (analysis_status)        &#123;        //查找帧头,不断查找直到找到帧头        case FIND_FRAME_HEAD:        &#123;            break;        &#125;        //解析帧头        case PARSE_FRAME_HEAD:        &#123;            if (receive_frame.head.extend)            &#123;                buff_len += RT_LINK_EXTEND_LENGTH;                analysis_status = PARSE_FRAME_EXTEND;            &#125;            else            &#123;                receive_frame.attribute = RT_LINK_SHORT_DATA_FRAME;                analysis_status = PARSE_FRAME_SEQ;            &#125;        &#125;        //解析帧扩展        case PARSE_FRAME_EXTEND:        &#123;            if (receive_frame.head.extend)            &#123;                //没有接收完整,继续接收                if (recv_len &lt; buff_len)                &#123;                    LOG_D(&quot;EXTEND: actual: %d, need: %d.&quot;, recv_len, buff_len);                    /* should set timer, control receive frame timeout, one shot */                    timeout = 50;                    rt_timer_control(&amp;rt_link_scb-&gt;recvtimer, RT_TIMER_CTRL_SET_TIME, &amp;timeout);                    rt_timer_start(&amp;rt_link_scb-&gt;recvtimer);                    return;                &#125;                rt_timer_stop(&amp;rt_link_scb-&gt;recvtimer);            &#125;            analysis_status = PARSE_FRAME_SEQ;        &#125;        //解析帧序列        case PARSE_FRAME_SEQ:        &#123;            switch (receive_frame.attribute)            &#123;            case RT_LINK_CONFIRM_FRAME:            case RT_LINK_RESEND_FRAME:            &#123;                //检查发送和接收次数,不一致忽略                break;            &#125;            case RT_LINK_LONG_DATA_FRAME:            case RT_LINK_SHORT_DATA_FRAME:            case RT_LINK_SESSION_END:            &#123;                //检查发送和接收次数,不一致忽略            &#125;            case RT_LINK_HANDSHAKE_FRAME:            case RT_LINK_DETACH_FRAME:                analysis_status = HEADLE_FRAME_DATA;                break;            default:                LOG_D(&quot;quick filter error frame.&quot;);                goto __find_head;            &#125;            buff_len += receive_frame.data_len;            if (receive_frame.head.crc)            &#123;                buff_len += RT_LINK_CRC_LENGTH;                analysis_status = CHECK_FRAME_CRC;            &#125;            else            &#123;                analysis_status = HEADLE_FRAME_DATA;            &#125;            /* fill real data point */            receive_frame.real_data = data;        &#125;        //检查CRC        case CHECK_FRAME_CRC:        &#123;            if (receive_frame.head.crc)            &#123;            analysis_status = HEADLE_FRAME_DATA;        &#125;        //处理数据        case HEADLE_FRAME_DATA:        &#123;            rt_timer_stop(&amp;rt_link_scb-&gt;recvtimer);            rt_link_hw_buffer_point_shift(&amp;rt_link_scb-&gt;rx_buffer-&gt;read_point, buff_len);            rt_link_parse_frame(&amp;receive_frame);            data = RT_NULL;            buff_len = RT_LINK_HEAD_LENGTH;            analysis_status = FIND_FRAME_HEAD;            break;        &#125;        default:__find_head:            LOG_D(&quot;to find head (%d)&quot;, analysis_status);            rt_link_frame_stop_receive(&amp;receive_frame);            buff_len = RT_LINK_HEAD_LENGTH;            analysis_status = FIND_FRAME_HEAD;            break;        &#125;        recv_len = rt_link_hw_recv_len(rt_link_scb-&gt;rx_buffer);    &#125;&#125;

