staticvoidulog_file_backend_flush_with_buf(struct ulog_backend *backend)&#123;    struct ulog_file_be *be = (struct ulog_file_be *) backend;    rt_size_t file_size = 0, write_size = 0;    if (be-&gt;enable == RT_FALSE || be-&gt;buf_ptr_now == be-&gt;file_buf)    &#123;        return;    &#125;    if (be-&gt;cur_log_file_fd &lt; 0)    &#123;        /* check log file directory  */        if (access(be-&gt;cur_log_dir_path, F_OK) &lt; 0)        &#123;            mkdir(be-&gt;cur_log_dir_path, 0);        &#125;        /* open file */        rt_snprintf(be-&gt;cur_log_file_path, ULOG_FILE_PATH_LEN, &quot;%s/%s.log&quot;, be-&gt;cur_log_dir_path, be-&gt;parent.name);        be-&gt;cur_log_file_fd = open(be-&gt;cur_log_file_path, O_CREAT | O_RDWR | O_APPEND);        if (be-&gt;cur_log_file_fd &lt; 0)        &#123;            rt_kprintf(&quot;ulog file(%s) open failed.&quot;, be-&gt;cur_log_file_path);            return;        &#125;    &#125;    file_size = lseek(be-&gt;cur_log_file_fd, 0, SEEK_END);    //文件大小大于最大值,则执行文件切换    if (file_size &gt;= (be-&gt;file_max_size - be-&gt;buf_size * 2))    &#123;        if (!ulog_file_rotate(be))        &#123;            return;        &#125;    &#125;    write_size = (rt_size_t)(be-&gt;buf_ptr_now - be-&gt;file_buf);    /* write to the file */    if (write(be-&gt;cur_log_file_fd, be-&gt;file_buf, write_size) != write_size)    &#123;        return;    &#125;    /* flush file cache */    fsync(be-&gt;cur_log_file_fd);    /* point be-&gt;buf_ptr_now at the head of be-&gt;file_buf[be-&gt;buf_size] */    be-&gt;buf_ptr_now = be-&gt;file_buf;&#125;


