bootm_run_statesint bootm_run_states(struct bootm_info *bmi, int states)&#123;	struct bootm_headers *images = bmi-&gt;images;	boot_os_fn *boot_fn;	ulong iflag = 0;	int ret = 0, need_boot_fn;	images-&gt;state |= states;	if (states &amp; BOOTM_STATE_START)		ret = bootm_start();	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_PRE_LOAD))		ret = bootm_pre_load(bmi-&gt;addr_img);	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_FINDOS))		ret = bootm_find_os(bmi-&gt;cmd_name, bmi-&gt;addr_img);//字符串&quot;90080000&quot;	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_FINDOTHER)) &#123;		ulong img_addr;		img_addr = bmi-&gt;addr_img ? hextoul(bmi-&gt;addr_img, NULL)			: image_load_addr;		//可以通过设置环境变量bootargs来设置ramdisk和fdt,也可以在fit中获取		ret = bootm_find_other(img_addr, bmi-&gt;conf_ramdisk,	//do_bootm bmi.conf_ramdisk = argv[1];				       bmi-&gt;conf_fdt);	//do_bootm bmi.conf_fdt = argv[2];	&#125;	/* Load the OS */	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_LOADOS)) &#123;		iflag = bootm_disable_interrupts();		ret = bootm_load_os(images, 0);		if (ret &amp;&amp; ret != BOOTM_ERR_OVERLAP)			goto err;		else if (ret == BOOTM_ERR_OVERLAP)			ret = 0;	&#125;	/* Relocate the ramdisk */	//将ramdisk移动到高地址,避免与内核重叠#ifdef CONFIG_SYS_BOOT_RAMDISK_HIGH	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_RAMDISK)) &#123;		ulong rd_len = images-&gt;rd_end - images-&gt;rd_start;		ret = boot_ramdisk_high(images-&gt;rd_start, rd_len,					&amp;images-&gt;initrd_start,					&amp;images-&gt;initrd_end);		if (!ret) &#123;			env_set_hex(&quot;initrd_start&quot;, images-&gt;initrd_start);			env_set_hex(&quot;initrd_end&quot;, images-&gt;initrd_end);		&#125;	&#125;#endif	/* 从现在开始，我们需要操作系统启动功能 */	if (ret)		return ret;	boot_fn = bootm_os_get_boot_func(images-&gt;os.os);	need_boot_fn = states &amp; (BOOTM_STATE_OS_CMDLINE |			BOOTM_STATE_OS_BD_T | BOOTM_STATE_OS_PREP |			BOOTM_STATE_OS_FAKE_GO | BOOTM_STATE_OS_GO);	if (boot_fn == NULL &amp;&amp; need_boot_fn) &#123;		if (iflag)			enable_interrupts();		printf(&quot;ERROR: booting os &#x27;%s&#x27; (%d) is not supported\n&quot;,		       genimg_get_os_name(images-&gt;os.os), images-&gt;os.os);		bootstage_error(BOOTSTAGE_ID_CHECK_BOOT_OS);		return 1;	&#125;	/* Call various other states that are not generally used */	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_OS_CMDLINE))		ret = boot_fn(BOOTM_STATE_OS_CMDLINE, bmi);	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_OS_BD_T))		ret = boot_fn(BOOTM_STATE_OS_BD_T, bmi);	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_OS_PREP)) &#123;	//准备启动操作系统		int flags = 0;		/* 对于 Linux 操作系统，请在控制台处理时执行所有替换 */		if (images-&gt;os.os == IH_OS_LINUX)			flags = BOOTM_CL_ALL;		//将bootarg进行替换为静默模式		ret = bootm_process_cmdline_env(flags);		if (ret) &#123;			printf(&quot;Cmdline setup failed (err=%d)\n&quot;, ret);			ret = CMD_RET_FAILURE;			goto err;		&#125;		ret = boot_fn(BOOTM_STATE_OS_PREP, bmi);	&#125;	/* Check for unsupported subcommand. */	if (ret) &#123;		printf(&quot;subcommand failed (err=%d)\n&quot;, ret);		return ret;	&#125;	/* 现在运行操作系统！我们希望这种情况不会再次出现 */	if (!ret &amp;&amp; (states &amp; BOOTM_STATE_OS_GO))		ret = boot_selected_os(BOOTM_STATE_OS_GO, bmi, boot_fn);	/* 处理任何后果 */err:	if (iflag)		enable_interrupts();	if (ret == BOOTM_ERR_UNIMPLEMENTED) &#123;		bootstage_error(BOOTSTAGE_ID_DECOMP_UNIMPL);	&#125; else if (ret == BOOTM_ERR_RESET) &#123;		printf(&quot;Resetting the board...\n&quot;);		reset_cpu();	&#125;	return ret;&#125;

bootm_find_os/** * bootm_find_os（）：找到要启动的操作系统 * * @cmd_name：启动此启动的命令名称，例如 “bootm” * @addr_fit：地址和/或 FIT 说明符（bootm 命令的第一个参数） * 返回：成功时为 0，错误时为 -ve */static int bootm_find_os(const char *cmd_name, const char *addr_fit)&#123;	/* 获取内核镜像头、起始地址和长度 */	ret = boot_get_kernel(addr_fit, 		//字符串&quot;90080000&quot;					&amp;images, &amp;images.os.image_start,			      	&amp;images.os.image_len, &amp;os_hdr);	if (ret) &#123;		if (ret == -EPROTOTYPE)			printf(&quot;Wrong Image Type for %s command\n&quot;, cmd_name);		printf(&quot;ERROR %dE: can&#x27;t get kernel image!\n&quot;, ret);		return 1;	&#125;	//进行镜像检查	/* 获取内核入口点 */	if (images.os.arch == IH_ARCH_I386 ||	    images.os.arch == IH_ARCH_X86_64) &#123;	&#125; else if (images.legacy_hdr_valid) &#123;#if CONFIG_IS_ENABLED(FIT)	&#125; else if (images.fit_uname_os) &#123;		int ret;		//获取内核入口点的地址		ret = fit_image_get_entry(images.fit_hdr_os,					  images.fit_noffset_os, &amp;images.ep);		if (ret) &#123;			puts(&quot;Can&#x27;t get entry point property!\n&quot;);			return 1;		&#125;#endif	&#125; else if (!ep_found) &#123;		puts(&quot;Could not find kernel entry point!\n&quot;);		return 1;	&#125;	images.os.start = map_to_sysmem(os_hdr);	return 0;&#125;

boot_get_kernelstatic int boot_get_kernel(const char *addr_fit, struct bootm_headers *images,			   ulong *os_data, ulong *os_len, const void **kernp)&#123;	//解析 FIT 说明符,获取内核地址	img_addr = genimg_get_kernel_addr_fit(addr_fit, //字符串&quot;90080000&quot;							&amp;fit_uname_config,	//返回配置单元名称					      	&amp;fit_uname_kernel);	//返回子镜像名称	bootstage_mark(BOOTSTAGE_ID_CHECK_MAGIC);	/* 检查图像类型，对于 FIT 图像，获取 FIT 内核节点 */	*os_data = *os_len = 0;	buf = map_sysmem(img_addr, 0);	switch (genimg_get_format(buf)) &#123;	//获取镜像格式#if CONFIG_IS_ENABLED(LEGACY_IMAGE_FORMAT)	case IMAGE_FORMAT_LEGACY:		break;#endif#if CONFIG_IS_ENABLED(FIT)	case IMAGE_FORMAT_FIT:		os_noffset = fit_image_load(images, img_addr,				&amp;fit_uname_kernel, &amp;fit_uname_config,				IH_ARCH_DEFAULT, IH_TYPE_KERNEL,				BOOTSTAGE_ID_FIT_KERNEL_START,				FIT_LOAD_IGNORED, os_data, os_len);		if (os_noffset &lt; 0)			return -ENOENT;		images-&gt;fit_hdr_os = map_sysmem(img_addr, 0);		images-&gt;fit_uname_os = fit_uname_kernel;		images-&gt;fit_uname_cfg = fit_uname_config;		images-&gt;fit_noffset_os = os_noffset;		break;#endif	default:		bootstage_error(BOOTSTAGE_ID_CHECK_IMAGETYPE);		return -EPROTOTYPE;	&#125;	debug(&quot;   kernel data at 0x%08lx, len = 0x%08lx (%ld)\n&quot;,	      *os_data, *os_len, *os_len);	*kernp = buf;	return 0;&#125;

bootm_find_other
ramdisk（RAM Disk）是一种将文件系统加载到内存中的技术。它通常用于在系统启动时提供一个临时的根文件系统，以便操作系统内核能够访问必要的文件和驱动程序，直到真正的根文件系统被挂载。
临时根文件系统: 在系统启动的早期阶段，内核可能还没有访问永久存储设备（如硬盘、闪存等）的能力。RAM Disk 提供了一个临时的根文件系统，使内核能够加载必要的驱动程序和启动脚本。
快速访问: 由于 RAM Disk 存储在内存中，访问速度非常快。这对于启动过程中的性能提升非常有帮助。

//满足os类型和os的操作系统类型寻找ramdisk和fdtstatic int bootm_find_other(ulong img_addr, const char *conf_ramdisk,			    const char *conf_fdt)&#123;	if ((images.os.type == IH_TYPE_KERNEL ||	     images.os.type == IH_TYPE_KERNEL_NOLOAD ||	     images.os.type == IH_TYPE_MULTI) &amp;&amp;	    (images.os.os == IH_OS_LINUX || images.os.os == IH_OS_VXWORKS ||	     images.os.os == IH_OS_EFI || images.os.os == IH_OS_TEE)) &#123;		return bootm_find_images(img_addr, conf_ramdisk, conf_fdt, 0,					 0);	&#125;	return 0;&#125;

