int bootm_find_images(ulong img_addr, const char *conf_ramdisk,		      const char *conf_fdt, ulong start, ulong size)&#123;	const char *select = conf_ramdisk;	char addr_str[17];	void *buf;	int ret;	/* find ramdisk */	ret = boot_get_ramdisk(select, &amp;images, IH_INITRD_ARCH,			       &amp;images.rd_start, &amp;images.rd_end);	if (ret) &#123;		puts(&quot;Ramdisk image is corrupt or invalid\n&quot;);		return 1;	&#125;	/* 检查 ramdisk 是否与操作系统映像重叠 */	if (check_overlap(&quot;RD&quot;, images.rd_start, images.rd_end, start, size))		return 1;	if (CONFIG_IS_ENABLED(OF_LIBFDT)) &#123;		buf = map_sysmem(img_addr, 0);		/* find flattened device tree */		//一样的逻辑,获取fdt地址与长度		ret = boot_get_fdt(buf, conf_fdt, IH_ARCH_DEFAULT, 	//arm					&amp;images,				   &amp;images.ft_addr, &amp;images.ft_len);		if (ret) &#123;			puts(&quot;Could not find a valid device tree\n&quot;);			return 1;		&#125;		/* 检查 FDT 是否与 OS 映像重叠 */		if (check_overlap(&quot;FDT&quot;, map_to_sysmem(images.ft_addr),				  images.ft_len, start, size))			return 1;		if (IS_ENABLED(CONFIG_CMD_FDT))			//fdtaddr: 镜像中fdt的地址			set_working_fdt_addr(map_to_sysmem(images.ft_addr));	//在环境变量中设置fdt地址	&#125;&#125;

bootm_disable_interrupts/** * bootm_disable_interrupts（） - 禁用中断以准备加载/启动 * * 返回：中断标志（如果中断被禁用，则为 0，如果中断被禁用，则为非零 * 已启用） */ulong bootm_disable_interrupts(void)&#123;	ulong iflag;	/*	 * 我们已经到了不归路：我们要	 * 覆盖所有异常向量代码，所以我们不能轻易	 * 不再从任何故障中恢复...	 */	iflag = disable_interrupts();#ifdef CONFIG_NETCONSOLE	/* 如果 NetConsole 可以保留以太网堆栈，请停止它 */	eth_halt();#endif	return iflag;&#125;

bootm_load_osstatic int bootm_load_os(struct bootm_headers *images, int boot_progress)&#123;	load_buf = map_sysmem(load, 0);	image_buf = map_sysmem(os.image_start, image_len);	//image_decomp解压缩镜像,没压缩且是XIP,直接返回	err = image_decomp(os.comp, load, os.image_start, os.type,			   load_buf, image_buf, image_len,			   CONFIG_SYS_BOOTM_LEN, &amp;load_end);	if (err) &#123;		err = handle_decomp_error(os.comp, load_end - load,					  CONFIG_SYS_BOOTM_LEN, err);		bootstage_error(BOOTSTAGE_ID_DECOMP_IMAGE);		return err;	&#125;	/* We need the decompressed image size in the next steps */	images-&gt;os.image_len = load_end - load;	flush_cache(flush_start, ALIGN(load_end, ARCH_DMA_MINALIGN) - flush_start);	debug(&quot;   kernel loaded at 0x%08lx, end = 0x%08lx\n&quot;, load, load_end);	bootstage_mark(BOOTSTAGE_ID_KERNEL_LOADED);	//检查内存是否重叠	no_overlap = (os.comp == IH_COMP_NONE &amp;&amp; load == image_start);	if (!no_overlap &amp;&amp; load &lt; blob_end &amp;&amp; load_end &gt; blob_start) &#123;		debug(&quot;images.os.start = 0x%lX, images.os.end = 0x%lx\n&quot;,		      blob_start, blob_end);		debug(&quot;images.os.load = 0x%lx, load_end = 0x%lx\n&quot;, load,		      load_end);		/* Check what type of image this is. */		if (images-&gt;legacy_hdr_valid) &#123;			if (image_get_type(&amp;images-&gt;legacy_hdr_os_copy)					== IH_TYPE_MULTI)				puts(&quot;WARNING: legacy format multi component image overwritten\n&quot;);			return BOOTM_ERR_OVERLAP;		&#125; else &#123;			puts(&quot;ERROR: new format image overwritten - must RESET the board to recover\n&quot;);			bootstage_error(BOOTSTAGE_ID_OVERWRITTEN);			return BOOTM_ERR_RESET;		&#125;	&#125;	//设置lmbd(内存块描述符)的保留区域,保护内核区域	if (CONFIG_IS_ENABLED(LMB))		lmb_reserve(images-&gt;os.load, (load_end - images-&gt;os.load),			    LMB_NONE);&#125;	return 0;&#125;

