complete_cmdvcomplete_subcmdv 自动补全子命令int complete_subcmdv(struct cmd_tbl *cmdtp, int count, int argc,		     char *const argv[], char last_char,		     int maxv, char *cmdv[])&#123;#ifdef CONFIG_CMDLINE	const struct cmd_tbl *cmdend = cmdtp + count;	const char *p;	int len, clen;	int n_found = 0;	const char *cmd;	/* sanity? */	if (maxv &lt; 2)		return -2;	cmdv[0] = NULL;	if (argc == 0) &#123;    //tab键补全命令 没有任何字符,进行列表打印		/* output full list of commands */		for (; cmdtp != cmdend; cmdtp++) &#123;			if (n_found &gt;= maxv - 2) &#123;  //超过最大数量				cmdv[n_found++] = &quot;...&quot;;    //显示省略号				break;			&#125;			cmdv[n_found++] = cmdtp-&gt;name;		&#125;		cmdv[n_found] = NULL;		return n_found;	&#125;	/*        输入了多个参数。          `ls -l`        输入了一个参数并按下空格。 `ls `        输入了一个参数并按下回车。 `ls`    */	if (argc &gt; 1 || last_char == &#x27;\0&#x27; || isblank(last_char)) &#123;		cmdtp = find_cmd_tbl(argv[0], cmdtp, count);		if (cmdtp == NULL || cmdtp-&gt;complete == NULL) &#123;			cmdv[0] = NULL;			return 0;		&#125;        //调用子命令的自动补全函数,补全子命令的参数		return (*cmdtp-&gt;complete)(argc, argv, last_char, maxv, cmdv);	&#125;	cmd = argv[0];	/*	 * Some commands allow length modifiers (like &quot;cp.b&quot;);	 * compare command name only until first dot.	 */	p = strchr(cmd, &#x27;.&#x27;);	if (p == NULL)		len = strlen(cmd);	else		len = p - cmd;	// 遍历命令表,查找匹配的命令	for (; cmdtp != cmdend; cmdtp++) &#123;		clen = strlen(cmdtp-&gt;name);		if (clen &lt; len)			continue;		if (memcmp(cmd, cmdtp-&gt;name, len) != 0)			continue;		/* too many! */		if (n_found &gt;= maxv - 2) &#123;			cmdv[n_found++] = &quot;...&quot;;			break;		&#125;		cmdv[n_found++] = cmdtp-&gt;name;	&#125;	cmdv[n_found] = NULL;	return n_found;#else	return 0;#endif&#125;

find_common_prefix 查找匹配的命令的公共前缀static int find_common_prefix(char *const argv[])&#123;	int i, len;	char *anchor, *s, *t;	if (*argv == NULL)		return 0;	/* begin with max */	anchor = *argv++;	len = strlen(anchor);    //s:当前命令,t:下一个命令,在while中不断指向下一个命令	while ((t = *argv++) != NULL) &#123;		s = anchor;		for (i = 0; i &lt; len; i++, t++, s++) &#123;            //比较命令的字符不相同,退出循环			if (*t != *s)				break;		&#125;		len = s - anchor;   //记录公共前缀的长度,最后返回最小的公共前缀长度	&#125;	return len;&#125;

print_argv 打印命令列表/** * @banner: 在参数之前打印的字符串。 * @leader: 在每个参数之前打印的字符串。 * @sep: 在每个参数之间打印的字符串。 * @linemax: 每行的最大字符数。 * * 此函数以格式化的方式打印命令行参数。 * 首先打印 @banner，然后每个参数前缀 @leader 并用 @sep 分隔。 举例： print_argv(&quot;Command List&quot;, &quot;&gt; &quot;, &quot;, &quot;, 20, (char *const [])&#123;&quot;git&quot;, &quot;status&quot;, &quot;commit&quot;, &quot;push&quot;, &quot;pull&quot;, NULL&#125;);    输出： Command List          &gt; git, status, commit, push, pull */

