image-board.cgenimg_get_kernel_addr_fit/** * genimg_get_kernel_addr_fit（） - 解析 FIT 说明符 * * 从通常为第一个的字符串中获取真正的内核起始地址 bootm/bootz 的 argv * 这些情况根据 @img_addr 的值进行处理： * NULL：返回 image_load_addr，不设置最后两个参数 * “&lt;addr&gt;”：返回地址 * 对于 FIT： * “[&lt;addr&gt;]#&lt;conf&gt;”：返回地址（或image_load_addr）、 * 将 fit_uname_config 设置为 Config Name * “[&lt;addr&gt;]：&lt;subimage&gt;”：返回地址（或 image_load_addr）并设置 * fit_uname_kernel子图像名称 * * @img_addr：字符串可能包含真实图像地址（或 NULL） * @fit_uname_config：返回配置单元名称 * @fit_uname_kernel：返回子图像名称 * * 返回： kernel start address */ulong genimg_get_kernel_addr_fit(const char *const img_addr,				 const char **fit_uname_config,				 const char **fit_uname_kernel)&#123;	ulong kernel_addr;	//没有指定地址,则使用默认地址	if (!img_addr) &#123;		kernel_addr = image_load_addr;		debug(&quot;*  kernel: default image load address = 0x%08lx\n&quot;,		      image_load_addr);	&#125; else if (CONFIG_IS_ENABLED(FIT) &amp;&amp;	//使用了FIT		//从img_addr传入的字符串中根据分隔符&quot;#解析出配置,则返回1,否则返回0		   fit_parse_conf(img_addr, image_load_addr, &amp;kernel_addr,				  fit_uname_config)) &#123;		debug(&quot;*  kernel: config &#x27;%s&#x27; from image at 0x%08lx\n&quot;,		      *fit_uname_config, kernel_addr);	&#125; else if (CONFIG_IS_ENABLED(FIT) &amp;&amp;		//从img_addr传入的字符串中根据分隔符&quot;:&quot;解析出子图像,则返回1,否则返回0		   fit_parse_subimage(img_addr, image_load_addr, &amp;kernel_addr,				      fit_uname_kernel)) &#123;		debug(&quot;*  kernel: subimage &#x27;%s&#x27; from image at 0x%08lx\n&quot;,		      *fit_uname_kernel, kernel_addr);	&#125; else &#123;		//将img_addr字符串转换为地址		kernel_addr = hextoul(img_addr, NULL);		debug(&quot;*  kernel: cmdline image address = 0x%08lx\n&quot;,		      kernel_addr);	&#125;	return kernel_addr;&#125;

genimg_get_format/** * genimg_get_format - 获取图像格式类型 * @img_addr：镜像起始地址 * * genimg_get_format（） 检查提供的地址是否指向有效的旧版或 FIT 图像。 * * 新的 uImage 格式和 FDT blob 基于 libfdt。FDT blob可以直接传递或嵌入到 FIT 图像中。 * 在这两种情况下genimg_get_format（） 必须能够识别 libfdt 头文件。 * *返回：图像格式类型或IMAGE_FORMAT_INVALID如果不存在图像 */#define IMAGE_FORMAT_INVALID	0x00#define IMAGE_FORMAT_LEGACY	0x01	/* legacy image_header based format */#define IMAGE_FORMAT_FIT	0x02	/* new, libfdt based format */#define IMAGE_FORMAT_ANDROID	0x03	/* Android boot image */int genimg_get_format(const void *img_addr)&#123;	//检查传统的 uImage 头	if (CONFIG_IS_ENABLED(LEGACY_IMAGE_FORMAT)) &#123;		const struct legacy_img_hdr *hdr;		hdr = (const struct legacy_img_hdr *)img_addr;		if (image_check_magic(hdr))			return IMAGE_FORMAT_LEGACY;	&#125;	//检查 FIT 头	if (CONFIG_IS_ENABLED(FIT) || CONFIG_IS_ENABLED(OF_LIBFDT)) &#123;		if (!fdt_check_header(img_addr))			return IMAGE_FORMAT_FIT;	&#125;	if (IS_ENABLED(CONFIG_ANDROID_BOOT_IMAGE) &amp;&amp;	    is_android_boot_image_header(img_addr))		return IMAGE_FORMAT_ANDROID;	return IMAGE_FORMAT_INVALID;&#125;

boot_get_ramdiskint boot_get_ramdisk(char const *select, struct bootm_headers *images,		     uint arch, ulong *rd_start, ulong *rd_end)&#123;		//从命令中解析出ramdisk的地址	if (select &amp;&amp; strcmp(select, &quot;-&quot;) ==  0) &#123;		debug(&quot;## Skipping init Ramdisk\n&quot;);		rd_len = 0;		rd_data = 0;	&#125; else if (select || genimg_has_config(images)) &#123;	//从fit中解析出ramdisk的地址		int ret;		//从fit中解析出ramdisk的地址与长度		ret = select_ramdisk(images, select, arch, &amp;rd_data, &amp;rd_len);		if (ret == -ENOPKG)			return 0;		else if (ret)			return ret;	&#125; else &#123;		/*		 * no initrd image		 */		bootstage_mark(BOOTSTAGE_ID_NO_RAMDISK);		rd_len = 0;		rd_data = 0;	&#125;	if (!rd_data) &#123;		debug(&quot;## No init Ramdisk\n&quot;);	&#125; else &#123;		*rd_start = rd_data;		*rd_end = rd_data + rd_len;	&#125;	debug(&quot;   ramdisk start = 0x%08lx, ramdisk end = 0x%08lx\n&quot;,	      *rd_start, *rd_end);	return 0;&#125;

select_ramdisk
