static int select_ramdisk(struct bootm_headers *images, const char *select, u8 arch,			  ulong *rd_datap, ulong *rd_lenp)&#123;	const char *fit_uname_config;	const char *fit_uname_ramdisk;	bool done_select = !select;	bool done = false;	int rd_noffset;	ulong rd_addr = 0;	char *buf;	if (CONFIG_IS_ENABLED(FIT)) &#123;	//从镜像的fit中解析出ramdisk的地址		fit_uname_config = images-&gt;fit_uname_cfg;		fit_uname_ramdisk = NULL;		if (select) &#123;		&#125;	&#125;	//从镜像的fit中获取ramdisk的地址	if (CONFIG_IS_ENABLED(FIT) &amp;&amp; !select) &#123;		rd_addr = map_to_sysmem(images-&gt;fit_hdr_os);		rd_noffset = fit_get_node_from_config(images, FIT_RAMDISK_PROP,						      rd_addr);		if (rd_noffset == -ENOENT)			return -ENOPKG;		else if (rd_noffset &lt; 0)			return rd_noffset;	&#125;	buf = map_sysmem(rd_addr, 0);	switch (genimg_get_format(buf)) &#123;	case IMAGE_FORMAT_LEGACY:		break;	case IMAGE_FORMAT_FIT:		if (CONFIG_IS_ENABLED(FIT)) &#123;			//从fit中解析出ramdisk的地址与长度,名称			rd_noffset = fit_image_load(images, rd_addr,						    &amp;fit_uname_ramdisk,						    &amp;fit_uname_config,						    arch, IH_TYPE_RAMDISK,						    BOOTSTAGE_ID_FIT_RD_START,						    FIT_LOAD_OPTIONAL_NON_ZERO,						    rd_datap, rd_lenp);			if (rd_noffset &lt; 0)				return rd_noffset;			images-&gt;fit_hdr_rd = map_sysmem(rd_addr, 0);			images-&gt;fit_uname_rd = fit_uname_ramdisk;			images-&gt;fit_noffset_rd = rd_noffset;			done = true;		&#125;		break;	case IMAGE_FORMAT_ANDROID:		break;	&#125;	return 0;&#125;

boot_ramdisk_highint boot_ramdisk_high(ulong rd_data, ulong rd_len, ulong *initrd_start,		      ulong *initrd_end)&#123;	char	*s;	phys_addr_t initrd_high;	int	initrd_copy_to_ram = 1;	s = env_get(&quot;initrd_high&quot;);	if (s) &#123;	//从环境变量中获取initrd_high的地址		/* a value of &quot;no&quot; or a similar string will act like 0,		 * turning the &quot;load high&quot; feature off. This is intentional.		 */		initrd_high = hextoul(s, NULL);		if (initrd_high == ~0)	//-1(未定义或无效值),则不拷贝到高地址			initrd_copy_to_ram = 0;	&#125; else &#123;		//计算initrd_high的地址 = 内核内存映射大小 + RAM的基础地址		initrd_high = env_get_bootm_mapsize() + env_get_bootm_low();	&#125;	if (rd_data) &#123;		//0拷贝到高地址		if (!initrd_copy_to_ram) &#123;	/* zero-copy ramdisk support */			debug(&quot;   in-place initrd\n&quot;);			*initrd_start = rd_data;			*initrd_end = rd_data + rd_len;			lmb_reserve(rd_data, rd_len, LMB_NONE);		&#125; else &#123;			//拷贝到高地址			if (initrd_high)				*initrd_start =					//分配一个高于initrd_high的地址,按0x1000对齐					(ulong)lmb_alloc_base(rd_len,								    0x1000,								    initrd_high,								    LMB_NONE);			else				//在当前地址分配内存				*initrd_start = (ulong)lmb_alloc(rd_len,								 0x1000);			if (*initrd_start == 0) &#123;				puts(&quot;ramdisk - allocation error\n&quot;);				goto error;			&#125;			bootstage_mark(BOOTSTAGE_ID_COPY_RAMDISK);			*initrd_end = *initrd_start + rd_len;			printf(&quot;   Loading Ramdisk to %08lx, end %08lx ... &quot;,			       *initrd_start, *initrd_end);			memmove_wd((void *)*initrd_start,				   (void *)rd_data, rd_len, CHUNKSZ);			/*			 * Ensure the image is flushed to memory to handle			 * AMP boot scenarios in which we might not be			 * HW cache coherent			 */			if (IS_ENABLED(CONFIG_MP)) &#123;				flush_cache((unsigned long)*initrd_start,					    ALIGN(rd_len, ARCH_DMA_MINALIGN));			&#125;			puts(&quot;OK\n&quot;);		&#125;	&#125; else &#123;		*initrd_start = 0;		*initrd_end = 0;	&#125;	debug(&quot;   ramdisk load start = 0x%08lx, ramdisk load end = 0x%08lx\n&quot;,	      *initrd_start, *initrd_end);	return 0;error:	return -1;&#125;

memmove_wd 内存拷贝 并喂狗env_get_bootm_mapsize 获取RAM的映射大小phys_size_t env_get_bootm_mapsize(void)&#123;	char *s = env_get(&quot;bootm_mapsize&quot;);	if (s)		return simple_strtoull(s, NULL, 16);#if defined(CFG_SYS_BOOTMAPSZ)	return CFG_SYS_BOOTMAPSZ;#else	return env_get_bootm_size();#endif&#125;

env_get_bootm_low 获取RAM的基础地址phys_addr_t env_get_bootm_low(void)&#123;	char *s = env_get(&quot;bootm_low&quot;);	if (s)		return simple_strtoull(s, NULL, 16);#if defined(CFG_SYS_SDRAM_BASE)	return CFG_SYS_SDRAM_BASE;#elif defined(CONFIG_ARM) || defined(CONFIG_MICROBLAZE) || defined(CONFIG_RISCV)	/*		common/board_f.c dram_init_banksize中定义为		gd-&gt;bd-&gt;bi_dram[0].start = gd-&gt;ram_base;		gd-&gt;bd-&gt;bi_dram[0].size = get_effective_memsize();		dram_init -&gt; fdtdec_setup_mem_size_base()中定义为		gd-&gt;ram_size = (phys_size_t)(res.end - res.start + 1);		gd-&gt;ram_base = (unsigned long)res.start;		debug(&quot;%s: Initial DRAM size %llx\n&quot;, __func__,			(unsigned long long)gd-&gt;ram_size);		memory@c0000000 &#123;			device_type = &quot;memory&quot;;			reg = &lt;0xc0000000 0x2000000&gt;;	&#125;;	*/	return gd-&gt;bd-&gt;bi_dram[0].start;#else	return 0;#endif&#125;

image_setup_linuxint image_setup_linux(struct bootm_headers *images)&#123;	ulong of_size = images-&gt;ft_len;	char **of_flat_tree = &amp;images-&gt;ft_addr;	int ret;	/* This function cannot be called without lmb support */	if (!CONFIG_IS_ENABLED(LMB))		return -EFAULT;	if (CONFIG_IS_ENABLED(OF_LIBFDT))		boot_fdt_add_mem_rsv_regions(*of_flat_tree);	//设置fdt保留的内存区域和fdt中指定的保留内存区域	if (IS_ENABLED(CONFIG_SYS_BOOT_GET_CMDLINE)) &#123;		ret = boot_get_cmdline(&amp;images-&gt;cmdline_start,				       &amp;images-&gt;cmdline_end);		if (ret) &#123;			puts(&quot;ERROR with allocation of cmdline\n&quot;);			return ret;		&#125;	&#125;	if (CONFIG_IS_ENABLED(OF_LIBFDT)) &#123;		ret = boot_relocate_fdt(of_flat_tree, &amp;of_size);	//将fdt数据移动到RAM中		if (ret)			return ret;	&#125;	if (CONFIG_IS_ENABLED(OF_LIBFDT) &amp;&amp; of_size) &#123;		ret = image_setup_libfdt(images, *of_flat_tree, true);	//将fdt转换为动态设备树		if (ret)			return ret;	&#125;	return 0;&#125;

image-fit.c
FIT（Flattened Image Tree）是一种用于嵌入式系统的镜像格式，主要用于 U-Boot 引导加载程序中。FIT 镜像可以包含多个不同类型的镜像文件（如内核、设备树、RAM 磁盘等），并且可以通过配置节点来定义这些镜像文件的加载和启动方式。

功能

多镜像支持:FIT 镜像可以包含多个不同类型的镜像文件，如内核、设备树、RAM 磁盘、固件等。
配置管理:通过配置节点，可以定义不同的启动配置，选择不同的镜像文件进行加载和启动。
镜像验证:支持镜像的完整性验证，通过哈希算法（如 SHA1）验证镜像文件的完整性，确保镜像文件未被篡改。
灵活性:可以动态选择和加载不同的镜像文件，适应不同的启动需求。



fit_parse_conffit_parse_spec/** * fit_parse_conf - 解析 FIT 配置规范 * @spec：输入字符串，包含配置规范 * @add_curr：当前镜像地址（没有找到则使用这个地址） * @addr：指向 ulong 变量的指针，将保存给定的 FIT 图像地址配置 * @conf_name指向 char 的双指针，将保存指向配置的指针单位名称 * fit_parse_conf（） 期望 []# 形式的配置规范&lt;addr&gt;&lt;conf&gt;， * 其中 &lt;addr&gt; 是包含配置的 FIT 镜像地址 * 替换为&lt;conf&gt;单位名称。 * * 地址部分是可选的，如果省略默认add_curr替换为 * 。 * 返回值:成功解析到分隔符的位置返回1,否则返回0 */ int fit_parse_conf(const char *spec, ulong addr_curr,		ulong *addr, const char **conf_name)&#123;	return fit_parse_spec(spec,	//字符串&quot;90080000&quot;							&#x27;#&#x27;, addr_curr, addr, conf_name);&#125;

fit_parse_spec 将字符串根据分隔符解析为地址和名称/* spec:需要解析的字符串 * sepc:分隔符 * addr_curr:当前地址 * addr:返回的地址 * name:返回的名称 * 返回值:成功解析到分隔符的位置返回1,否则返回0 */static int fit_parse_spec(const char *spec, char sepc, ulong addr_curr,		ulong *addr, const char **name)

fit_image_load 从 FIT 加载镜像// ph_type = IH_TYPE_KERNELint fit_image_load(struct bootm_headers *images, ulong addr,		   const char **fit_unamep, const char **fit_uname_configp,		   int arch, int ph_type, int bootstage_id,		   enum fit_load_op load_op, ulong *datap, ulong *lenp)&#123;	fit = map_sysmem(addr, 0);	fit_uname = fit_unamep ? *fit_unamep : NULL;	//请求的映像名称	fit_uname_config = fit_uname_configp ? *fit_uname_configp : NULL;	//请求的配置名称	fit_base_uname_config = NULL;	//基本配置名称	//例如&quot;kernel&quot;	prop_name = fit_get_image_type_property(image_type);	//获取镜像类型的属性名称	bootstage_mark(bootstage_id + BOOTSTAGE_SUB_FORMAT);	ret = fit_check_format(fit, IMAGE_SIZE_INVAL);			//检查 FIT 格式	if (fit_uname) &#123;	//如果请求的映像名称不为空		bootstage_mark(bootstage_id + BOOTSTAGE_SUB_UNIT_NAME);		noffset = fit_image_get_node(fit, fit_uname);	&#125; else &#123;		/*		 * 没有镜像节点单元名称，尝试获取配置		 * node 优先。如果配置单元节点名称为 NULL		 * fit_conf_get_node（） 将尝试查找默认配置节点		 */		bootstage_mark(bootstage_id + BOOTSTAGE_SUB_NO_UNIT_NAME);		if (ret &lt; 0 &amp;&amp; ret != -EINVAL)			ret = fit_conf_get_node(fit, fit_uname_config);	//查找/configurations节点中的配置节点,默认为default的配置		if (ret &lt; 0) &#123;			puts(&quot;Could not find configuration node\n&quot;);			bootstage_error(bootstage_id +					BOOTSTAGE_SUB_NO_UNIT_NAME);			return -ENOENT;		&#125;		cfg_noffset = ret;		fit_base_uname_config = fdt_get_name(fit, cfg_noffset, NULL);		printf(&quot;   Using &#x27;%s&#x27; configuration\n&quot;, fit_base_uname_config);		/* Remember this config */		if (image_type == IH_TYPE_KERNEL)			images-&gt;fit_uname_cfg = fit_base_uname_config;		if (FIT_IMAGE_ENABLE_VERIFY &amp;&amp; images-&gt;verify) &#123;			puts(&quot;   Verifying Hash Integrity ... &quot;);			if (fit_config_verify(fit, cfg_noffset)) &#123;				puts(&quot;Bad Data Hash\n&quot;);				bootstage_error(bootstage_id +					BOOTSTAGE_SUB_HASH);				return -EACCES;			&#125;			puts(&quot;OK\n&quot;);		&#125;		bootstage_mark(BOOTSTAGE_ID_FIT_CONFIG);		//获取镜像类型节点的偏移量	kernel:&quot;kernel&quot;		noffset = fit_conf_get_prop_node(fit, cfg_noffset, prop_name,						 image_ph_phase(ph_type));		//获取镜像类型节点的名称		fit_uname = fit_get_name(fit, noffset, NULL);	&#125;	if (noffset &lt; 0) &#123;		printf(&quot;Could not find subimage node type &#x27;%s&#x27;\n&quot;, prop_name);		bootstage_error(bootstage_id + BOOTSTAGE_SUB_SUBNODE);		return -ENOENT;	&#125;	printf(&quot;   Trying &#x27;%s&#x27; %s subimage\n&quot;, fit_uname, prop_name);	//bootm_start中 images.verify = env_get_yesno(&quot;verify&quot;);	ret = fit_image_select(fit, noffset, images-&gt;verify);	//打印镜像信息,并进行完整性检查#ifndef USE_HOSTCC	&#123;	uint8_t os_arch;	fit_image_get_arch(fit, noffset, &amp;os_arch);	images-&gt;os.arch = os_arch;	&#125;#endif	//检查镜像是否具有获取到的类型	bootstage_mark(bootstage_id + BOOTSTAGE_SUB_CHECK_ALL);	type_ok = fit_image_check_type(fit, noffset, image_type) ||		  fit_image_check_type(fit, noffset, IH_TYPE_FIRMWARE) ||		  fit_image_check_type(fit, noffset, IH_TYPE_TEE) ||		  (image_type == IH_TYPE_KERNEL &amp;&amp;		   fit_image_check_type(fit, noffset, IH_TYPE_KERNEL_NOLOAD));	//os类型为linux,uboot,tee,openrtos,efi,vxworks,elf	os_ok = image_type == IH_TYPE_FLATDT ||		image_type == IH_TYPE_FPGA ||		fit_image_check_os(fit, noffset, IH_OS_LINUX) ||		fit_image_check_os(fit, noffset, IH_OS_U_BOOT) ||		fit_image_check_os(fit, noffset, IH_OS_TEE) ||		fit_image_check_os(fit, noffset, IH_OS_OPENRTOS) ||		fit_image_check_os(fit, noffset, IH_OS_EFI) ||		fit_image_check_os(fit, noffset, IH_OS_VXWORKS) ||		fit_image_check_os(fit, noffset, IH_OS_ELF);	bootstage_mark(bootstage_id + BOOTSTAGE_SUB_LOAD);	*datap = load;	*lenp = len;	if (fit_unamep)		*fit_unamep = (char *)fit_uname;	if (fit_uname_configp)		*fit_uname_configp = (char *)(fit_uname_config ? :					      fit_base_uname_config);	return noffset;&#125;

