fit_conf_get_node	查找配置节点/*    configurations &#123;        default = &quot;conf0&quot;;        conf0 &#123;            description = &quot;Boot Linux kernel with FDT blob&quot;;            kernel = &quot;kernel&quot;;            fdt = &quot;fdt&quot;;            ramdisk = &quot;ramdisk&quot;;        &#125;;    &#125;;*/int fit_conf_get_node(const void *fit, const char *conf_uname)&#123;	int noffset, confs_noffset;	int len;	const char *s;	char *conf_uname_copy = NULL;	//查找/configurations节点的偏移量	confs_noffset = fdt_path_offset(fit, FIT_CONFS_PATH);	if (confs_noffset &lt; 0) &#123;		debug(&quot;Can&#x27;t find configurations parent node &#x27;%s&#x27; (%s)\n&quot;,		      FIT_CONFS_PATH, fdt_strerror(confs_noffset));		return confs_noffset;	&#125;	if (conf_uname == NULL) &#123;		/* 从 default 属性获取配置单元名称 */		debug(&quot;No configuration specified, trying default...\n&quot;);		if (!tools_build() &amp;&amp; IS_ENABLED(CONFIG_MULTI_DTB_FIT)) &#123;	//多个设备树查找配置节点			noffset = fit_find_config_node(fit);			if (noffset &lt; 0)				return noffset;			conf_uname = fdt_get_name(fit, noffset, NULL);		&#125; else &#123;	//单个设备树查找配置节点			//查找&quot;default&quot;属性的值			conf_uname = (char *)fdt_getprop(fit, confs_noffset,							 FIT_DEFAULT_PROP, &amp;len);			if (conf_uname == NULL) &#123;				fit_get_debug(fit, confs_noffset, FIT_DEFAULT_PROP,					      len);				return len;			&#125;		&#125;		debug(&quot;Found default configuration: &#x27;%s&#x27;\n&quot;, conf_uname);	&#125;	//处理&quot;#&quot;后的注释部分	s = strchr(conf_uname, &#x27;#&#x27;);	if (s) &#123;		len = s - conf_uname;		conf_uname_copy = malloc(len + 1);		if (!conf_uname_copy) &#123;			debug(&quot;Can&#x27;t allocate uname copy: &#x27;%s&#x27;\n&quot;,					conf_uname);			return -ENOMEM;		&#125;		memcpy(conf_uname_copy, conf_uname, len);		conf_uname_copy[len] = &#x27;\0&#x27;;		conf_uname = conf_uname_copy;	&#125;	//查找配置单元名称的节点偏移量	noffset = fdt_subnode_offset(fit, confs_noffset, conf_uname);	if (noffset &lt; 0) &#123;		debug(&quot;Can&#x27;t get node offset for configuration unit name: &#x27;%s&#x27; (%s)\n&quot;,		      conf_uname, fdt_strerror(noffset));	&#125;	free(conf_uname_copy);	return noffset;&#125;

