//fit:FIT头指针,rd_noffset:镜像节点偏移量,verify:是否进行完整性检查static int fit_image_select(const void *fit, int rd_noffset, int verify)&#123;	fit_image_print(fit, rd_noffset, &quot;   &quot;);	if (verify) &#123;		puts(&quot;   Verifying Hash Integrity ... &quot;);		if (!fit_image_verify(fit, rd_noffset)) &#123;			puts(&quot;Bad Data Hash\n&quot;);			return -EACCES;		&#125;		puts(&quot;OK\n&quot;);	&#125;	return 0;&#125;

