fit_image_get_entry 获取镜像入口地址fit_image_get_address 获取镜像地址static int fit_image_get_address(const void *fit, int noffset, char *name,			  ulong *load)&#123;	int len, cell_len;	const fdt32_t *cell;	uint64_t load64 = 0;	//获取长度和返回属性的指针	cell = fdt_getprop(fit, noffset, name, &amp;len);	if (cell == NULL) &#123;		fit_get_debug(fit, noffset, name, len);		return -1;	&#125;	cell_len = len &gt;&gt; 2;	//将属性值转换为地址	while (cell_len--) &#123;		load64 = (load64 &lt;&lt; 32) | uimage_to_cpu(*cell);		cell++;	&#125;	if (len &gt; sizeof(ulong) &amp;&amp; (uint32_t)(load64 &gt;&gt; 32)) &#123;		printf(&quot;Unsupported %s address size\n&quot;, name);		return -1;	&#125;	*load = (ulong)load64;	return 0;&#125;

image.cimage_decomp 解压缩int image_decomp(int comp, ulong load, ulong image_start, int type,		 void *load_buf, void *image_buf, ulong image_len,		 uint unc_len, ulong *load_end)&#123;	int ret = -ENOSYS;	*load_end = load;	//bootm_find_os images.os.load = images.os.image_start;	//所以打印XIP	print_decomp_msg(comp, type, load == image_start, load);	/*	 * 将图像加载到正确的位置，如果需要，请解压缩。后	 * this，image_len 将设置为未压缩字节数	 * loaded，则 ret 在出错时将为非零。	 */	switch (comp) &#123;	case IH_COMP_NONE:		ret = 0;		if (load == image_start)			break;		if (image_len &lt;= unc_len)			memmove_wd(load_buf, image_buf, image_len, CHUNKSZ);		else			ret = -ENOSPC;		break;	&#125;&#125;

print_decomp_msg/** * print_decomp_msg() - Print a suitable decompression/loading message * * @type:	OS type (IH_OS_...) * @comp_type:	Compression type being used (IH_COMP_...) * @is_xip:	true if the load address matches the image start * @load:	Load address for printing */static void print_decomp_msg(int comp_type, int type, bool is_xip,			     ulong load)&#123;	const char *name = genimg_get_type_name(type);	/* Shows &quot;Loading Kernel Image&quot; for example */	if (comp_type == IH_COMP_NONE)		printf(&quot;   %s %s&quot;, is_xip ? &quot;XIP&quot; : &quot;Loading&quot;, name);	else		printf(&quot;   Uncompressing %s&quot;, name);	printf(&quot; to %lx\n&quot;, load);&#125;

image-fdt.c
设备树是一种描述硬件的数据结构，它描述了硬件的组织结构、属性和连接关系。设备树通常用于嵌入式系统中，用于描述系统中的各种硬件设备，如 CPU、内存、外设等。设备树通常以 .dts（Device Tree Source）文件的形式存在，通过编译器编译成 .dtb（Device Tree Blob）文件，然后由引导加载程序加载到内存中。

boot_fdt_add_mem_rsv_regions 设置fdt保留的内存区域和fdt中指定的保留内存区域void boot_fdt_add_mem_rsv_regions(void *fdt_blob)&#123;	uint64_t addr, size;	int i, total, ret;	int nodeoffset, subnode;	struct fdt_resource res;	u32 flags;	if (fdt_check_header(fdt_blob) != 0)		return;	//获取保留的内存数量	total = fdt_num_mem_rsv(fdt_blob);	for (i = 0; i &lt; total; i++) &#123;		//获取保留的内存地址和大小		if (fdt_get_mem_rsv(fdt_blob, i, &amp;addr, &amp;size) != 0)			continue;		//添加保留的内存区域		boot_fdt_reserve_region(addr, size, LMB_NOOVERWRITE);	&#125;	/* process reserved-memory */	/*		reserved-memory &#123;		#address-cells = &lt;1&gt;;		#size-cells = &lt;1&gt;;		ranges;		linux,cma &#123;			compatible = &quot;shared-dma-pool&quot;;			no-map;			size = &lt;0x100000&gt;;			linux,dma-default;		&#125;;	&#125;;	*/	nodeoffset = fdt_subnode_offset(fdt_blob, 0, &quot;reserved-memory&quot;);	if (nodeoffset &gt;= 0) &#123;		subnode = fdt_first_subnode(fdt_blob, nodeoffset);		while (subnode &gt;= 0) &#123;			/* check if this subnode has a reg property */			ret = fdt_get_resource(fdt_blob, subnode, &quot;reg&quot;, 0,					       &amp;res);			if (!ret &amp;&amp; fdtdec_get_is_enabled(fdt_blob, subnode)) &#123;				flags = LMB_NOOVERWRITE;				if (fdtdec_get_bool(fdt_blob, subnode,						    &quot;no-map&quot;))					flags = LMB_NOMAP;				addr = res.start;				size = res.end - res.start + 1;				boot_fdt_reserve_region(addr, size, flags);			&#125;			subnode = fdt_next_subnode(fdt_blob, subnode);		&#125;	&#125;&#125;

boot_relocate_fdt	将fdt数据移动到RAM中int boot_relocate_fdt(char **of_flat_tree, ulong *of_size)&#123;	u64	start, size, usable, addr, low, mapsize;	void	*fdt_blob = *of_flat_tree;	void	*of_start = NULL;	char	*fdt_high;	ulong	of_len = 0;	int	bank;	int	err;	int	disable_relocation = 0;	/* nothing to do */	if (*of_size == 0)		return 0;	if (fdt_check_header(fdt_blob) != 0) &#123;		fdt_error(&quot;image is not a fdt&quot;);		goto error;	&#125;	/* position on a 4K boundary before the alloc_current */	/* Pad the FDT by a specified amount */	/* 		CONFIG_SYS_FDT_PAD 可能用于指定设备树在内存中预留的填充空间（padding）。		填充空间的作用是为设备树的动态修改预留额外的内存，		以便在运行时可以添加或修改设备树节点和属性，		而不需要重新分配内存或移动设备树的位置。	*/	of_len = *of_size + CONFIG_SYS_FDT_PAD;	/* If fdt_high is set use it to select the relocation address */	fdt_high = env_get(&quot;fdt_high&quot;);	if (fdt_high) &#123;	//尝试使用env的fdt_high	&#125; else &#123;	//通过fdt的内存映射大小和基础地址计算fdt的地址		mapsize = env_get_bootm_mapsize();		low = env_get_bootm_low();		of_start = NULL;		for (bank = 0; bank &lt; CONFIG_NR_DRAM_BANKS; bank++) &#123;			start = gd-&gt;bd-&gt;bi_dram[bank].start;			size = gd-&gt;bd-&gt;bi_dram[bank].size;			/* DRAM bank addresses are too low, skip it. */			if (start + size &lt; low)				continue;			//计算已用空间;是当前分配掉的空间更小,使用当前分配掉的空间继续分配			//否则使用当前DRAM的空间			//如果当前 DRAM 银行的结束地址大于或等于 low，则至少有一部分地址范围在 low 以上。在这种情况下，代码计算可用的地址范围 usable，并尝试从这个范围中分配内存块。			usable = min(start + size, low + mapsize);			addr = lmb_alloc_base(of_len, 0x1000, usable, LMB_NONE);			of_start = map_sysmem(addr, of_len);			/* Allocation succeeded, use this block. */			if (of_start != NULL)				break;			//如果当前DRAM的空间不够,则继续分配下一个DRAM的空间			mapsize -= usable - max(start, low);			if (!mapsize)				break;		&#125;	&#125;	if (disable_relocation) &#123;	&#125; else &#123;		debug(&quot;## device tree at %p ... %p (len=%ld [0x%lX])\n&quot;,		      fdt_blob, fdt_blob + *of_size - 1, of_len, of_len);		printf(&quot;   Loading Device Tree to %p, end %p ... &quot;,		       of_start, of_start + of_len - 1);		err = fdt_open_into(fdt_blob, of_start, of_len);	//将fdt_blob移动到of_start		if (err != 0) &#123;			fdt_error(&quot;fdt move failed&quot;);			goto error;		&#125;		puts(&quot;OK\n&quot;);	&#125;	*of_flat_tree = of_start;	*of_size = of_len;	if (IS_ENABLED(CONFIG_CMD_FDT))		//设置fdt的地址		set_working_fdt_addr(map_to_sysmem(*of_flat_tree));	return 0;error:	return 1;&#125;

fdt_root 检测fdt头部,将环境变量中serial#设置到fdt中int fdt_root(void *fdt)&#123;	char *serial;	int err;	err = fdt_check_header(fdt);	if (err &lt; 0) &#123;		printf(&quot;fdt_root: %s\n&quot;, fdt_strerror(err));		return err;	&#125;	serial = env_get(&quot;serial#&quot;);	//获取环境变量serial#的值	if (serial) &#123;		//获取serial成功后设置设备树属性		err = fdt_setprop(fdt, 0, &quot;serial-number&quot;, serial,				  strlen(serial) + 1);		if (err &lt; 0) &#123;			printf(&quot;WARNING: could not set serial-number %s.\n&quot;,			       fdt_strerror(err));			return err;		&#125;	&#125;	return 0;&#125;

fdt_chosen 创建&#x2F;chosen节点,添加bootargs属性和rng-seed属性,u-boot版本号,bootargs属性/** * board_fdt_chosen_bootargs - 板子可以覆盖此函数以使用替代内核命令行参数 * 默认将env的bootargs设置到fdt中 */__weak const char *board_fdt_chosen_bootargs(const struct fdt_property *fdt_ba)&#123;	return env_get(&quot;bootargs&quot;);&#125;int fdt_chosen(void *fdt)&#123;	struct abuf buf = &#123;&#125;;	int   nodeoffset;	int   err;	const char *str;		/* used to set string properties */	err = fdt_check_header(fdt);	if (err &lt; 0) &#123;		printf(&quot;fdt_chosen: %s\n&quot;, fdt_strerror(err));		return err;	&#125;	/* 查找或创建 “/Chosen” 节点。 */	nodeoffset = fdt_find_or_add_subnode(fdt, 0, &quot;chosen&quot;);	if (nodeoffset &lt; 0)		return nodeoffset;	//设置rng-seed属性	if (IS_ENABLED(CONFIG_BOARD_RNG_SEED) &amp;&amp; !board_rng_seed(&amp;buf)) &#123;		err = fdt_setprop(fdt, nodeoffset, &quot;rng-seed&quot;,				  abuf_data(&amp;buf), abuf_size(&amp;buf));		abuf_uninit(&amp;buf);		if (err &lt; 0) &#123;			printf(&quot;WARNING: could not set rng-seed %s.\n&quot;,			       fdt_strerror(err));			return err;		&#125;	&#125;	//设置bootargs属性 将env的bootargs设置到fdt中	str = board_fdt_chosen_bootargs(fdt_get_property(fdt, nodeoffset,							 &quot;bootargs&quot;, NULL));	if (str) &#123;		err = fdt_setprop(fdt, nodeoffset, &quot;bootargs&quot;, str,				  strlen(str) + 1);		if (err &lt; 0) &#123;			printf(&quot;WARNING: could not set bootargs %s.\n&quot;,			       fdt_strerror(err));			return err;		&#125;	&#125;	/* 添加 u-boot 版本 */	err = fdt_setprop(fdt, nodeoffset, &quot;u-boot,version&quot;, PLAIN_VERSION,			  strlen(PLAIN_VERSION) + 1);	if (err &lt; 0) &#123;		printf(&quot;WARNING: could not set u-boot,version %s.\n&quot;,		       fdt_strerror(err));		return err;	&#125;	return fdt_fixup_stdout(fdt, nodeoffset);&#125;

image_setup_libfdt 将fdt转换为动态设备树,并设置相关属性到fdt中int image_setup_libfdt(struct bootm_headers *images, void *blob, bool lmb)&#123;	ret = -EPERM;	//检测fdt头部,设置serial#属性	if (fdt_root(blob) &lt; 0) &#123;			printf(&quot;ERROR: root node setup failed\n&quot;);		goto err;	&#125;	// 创建/chosen节点,添加bootargs属性和rng-seed属性,u-boot版本号,bootargs属性	if (fdt_chosen(blob) &lt; 0) &#123;		printf(&quot;ERROR: /chosen node create failed\n&quot;);		goto err;	&#125;	if (arch_fixup_fdt(blob) &lt; 0) &#123;		printf(&quot;ERROR: arch-specific fdt fixup failed\n&quot;);		goto err;	&#125;	fdt_ret = optee_copy_fdt_nodes(blob);	if (fdt_ret) &#123;		printf(&quot;ERROR: transfer of optee nodes to new fdt failed: %s\n&quot;,		       fdt_strerror(fdt_ret));		goto err;	&#125;	/* 将配置节点的名称存储为 u-boot，bootconf 在 /chosen 节点中 */	if (images-&gt;fit_uname_cfg)		fdt_find_and_setprop(blob, &quot;/chosen&quot;, &quot;u-boot,bootconf&quot;,					images-&gt;fit_uname_cfg,					strlen(images-&gt;fit_uname_cfg) + 1, 1);	//在 /chosen 节点中设置ramdisk的开始和结束地址	if (fdt_initrd(blob, *initrd_start, *initrd_end))		goto err;	// 转换FDT为动台设备树	if (!of_live_active() &amp;&amp; CONFIG_IS_ENABLED(EVENT)) &#123;		struct event_ft_fixup fixup;		fixup.tree = oftree_from_fdt(blob);		fixup.images = images;		if (oftree_valid(fixup.tree)) &#123;			ret = event_notify(EVT_FT_FIXUP, &amp;fixup, sizeof(fixup));			if (ret) &#123;				printf(&quot;ERROR: fdt fixup event failed: %d\n&quot;,				       ret);				goto err;			&#125;		&#125;	&#125;	/* Delete the old LMB reservation */	if (CONFIG_IS_ENABLED(LMB) &amp;&amp; lmb)		lmb_free(map_to_sysmem(blob), fdt_totalsize(blob));	ret = fdt_shrink_to_minimum(blob, 0);	//fdt转换为空的fdt	if (ret &lt; 0)		goto err;	of_size = ret;	/* Create a new LMB reservation */	if (CONFIG_IS_ENABLED(LMB) &amp;&amp; lmb)	//将新的fdt空间设置为保留		lmb_reserve(map_to_sysmem(blob), of_size, LMB_NONE);	return 0;err:	printf(&quot; - must RESET the board to recover.\n\n&quot;);	return ret;&#125;

autoboot.cautoboot_command 自动启动命令void autoboot_command(const char *s)&#123;    debug(&quot;### main_loop: bootcmd=\&quot;%s\&quot;\n&quot;, s ? s : &quot;&lt;UNDEFINED&gt;&quot;);    if (s //有bootcmd    &amp;&amp; (stored_bootdelay == -2 ||        //有延迟时间,且没有按键中断         (stored_bootdelay != -1 &amp;&amp; !abortboot(stored_bootdelay)))) &#123;        bool lock;        int prev;        lock = autoboot_keyed() &amp;&amp;            !IS_ENABLED(CONFIG_AUTOBOOT_KEYED_CTRLC);        if (lock)            prev = disable_ctrlc(1); /* disable Ctrl-C checking */        run_command_list(s, -1, 0);        if (lock)            disable_ctrlc(prev);    /* restore Ctrl-C checking */    &#125;    if (IS_ENABLED(CONFIG_AUTOBOOT_USE_MENUKEY) &amp;&amp;        menukey == AUTOBOOT_MENUKEY) &#123;        s = env_get(&quot;menucmd&quot;);        if (s)            run_command_list(s, -1, 0);    &#125;&#125;

abortboot 检查是否有按键中断static int abortboot(int bootdelay)&#123;    int abort = 0;    if (bootdelay &gt;= 0) &#123;        if (autoboot_keyed())            abort = abortboot_key_sequence(bootdelay);        else            abort = abortboot_single_key(bootdelay);    &#125;    if (IS_ENABLED(CONFIG_SILENT_CONSOLE) &amp;&amp; abort)        gd-&gt;flags &amp;= ~GD_FLG_SILENT;    return abort;&#125;

passwd_abort_key
输入bootdelaykey或者bootstopkey中的任意一个按键,则返回1;终止自动启动
bootdelaykey的匹配字符串为env中的bootdelaykey的值,如果没有配置,则使用CONFIG_AUTOBOOT_DELAY_STR的值
bootstopkey的匹配字符串为env中的bootstopkey的值,如果没有配置,则使用CONFIG_AUTOBOOT_STOP_STR的值

static int passwd_abort_key(uint64_t etime)&#123;    int abort = 0;    struct &#123;        char *str;        u_int len;        int retry;    &#125;    delaykey[] = &#123;        &#123; .str = env_get(&quot;bootdelaykey&quot;),  .retry = 1 &#125;,        &#123; .str = env_get(&quot;bootstopkey&quot;),   .retry = 0 &#125;,    &#125;;    char presskey[DELAY_STOP_STR_MAX_LENGTH];    //需要匹配的输入字符串,env中没有配置则宏定义的字符串#  ifdef CONFIG_AUTOBOOT_DELAY_STR  //默认为&quot;&quot;,即任意都不匹配    if (delaykey[0].str == NULL)        delaykey[0].str = CONFIG_AUTOBOOT_DELAY_STR;#  endif#  ifdef CONFIG_AUTOBOOT_STOP_STR   //默认为&quot; &quot;,即输入空格终止    if (delaykey[1].str == NULL)        delaykey[1].str = CONFIG_AUTOBOOT_STOP_STR;#  endif    do &#123;        //检查是否有按键输入        if (tstc()) &#123;        &#125;        //获取按键输入并进行匹配        for (i = 0; i &lt; sizeof(delaykey) / sizeof(delaykey[0]); i++) &#123;            if (delaykey[i].len &gt; 0 &amp;&amp;                presskey_len &gt;= delaykey[i].len &amp;&amp;                memcmp(presskey + presskey_len -                    delaykey[i].len, delaykey[i].str,                    delaykey[i].len) == 0) &#123;                    debug_bootkeys(&quot;got %skey\n&quot;,                        delaykey[i].retry ? &quot;delay&quot; :                        &quot;stop&quot;);                /* don&#x27;t retry auto boot */                //如果是STOP按键,则不再重试                if (!delaykey[i].retry)                    bootretry_dont_retry(); //重试时间设置为-1,不在重试                abort = 1;            &#125;        &#125;        udelay(10000);    &#125; while (!abort &amp;&amp; get_ticks() &lt;= etime);    return abort;&#125;

