bootdelay_process
获取bootdelay的值,如果没有配置,则使用CONFIG_BOOTDELAY的值

const char *bootdelay_process(void)&#123;	char *s;	int bootdelay;	bootcount_inc();	s = env_get(&quot;bootdelay&quot;);	bootdelay = s ? (int)simple_strtol(s, NULL, 10) : CONFIG_BOOTDELAY;	/*	 * Does it really make sense that the devicetree overrides the user	 * setting? It is possibly helpful for security since the device tree	 * may be signed whereas the environment is often loaded from storage.	 */	if (IS_ENABLED(CONFIG_OF_CONTROL))		bootdelay = ofnode_conf_read_int(&quot;bootdelay&quot;, bootdelay);	debug(&quot;### main_loop entered: bootdelay=%d\n\n&quot;, bootdelay);	if (IS_ENABLED(CONFIG_AUTOBOOT_MENU_SHOW))		bootdelay = menu_show(bootdelay);	bootretry_init_cmd_timeout();#ifdef CONFIG_POST	if (gd-&gt;flags &amp; GD_FLG_POSTFAIL) &#123;		s = env_get(&quot;failbootcmd&quot;);	&#125; else#endif /* CONFIG_POST */	if (bootcount_error())		s = env_get(&quot;altbootcmd&quot;);	else		s = env_get(&quot;bootcmd&quot;);	if (IS_ENABLED(CONFIG_OF_CONTROL))		process_fdt_options();	stored_bootdelay = bootdelay;	return s;&#125;

