static int stm32_adc_core_probe(struct udevice *dev)&#123;	struct stm32_adc_common *common = dev_get_priv(dev);	int ret;	common-&gt;base = dev_read_addr_ptr(dev);	if (!common-&gt;base) &#123;		dev_err(dev, &quot;can&#x27;t get address\n&quot;);		return -ENOENT;	&#125;	ret = device_get_supply_regulator(dev, &quot;vref-supply&quot;, &amp;common-&gt;vref);	if (ret) &#123;		dev_err(dev, &quot;can&#x27;t get vref-supply: %d\n&quot;, ret);		return ret;	&#125;	ret = regulator_get_value(common-&gt;vref);	if (ret &lt; 0) &#123;		dev_err(dev, &quot;can&#x27;t get vref-supply value: %d\n&quot;, ret);		return ret;	&#125;	common-&gt;vref_uv = ret;	ret = clk_get_by_name(dev, &quot;adc&quot;, &amp;common-&gt;aclk);	if (!ret) &#123;		ret = clk_enable(&amp;common-&gt;aclk);		if (ret) &#123;			dev_err(dev, &quot;Can&#x27;t enable aclk: %d\n&quot;, ret);			return ret;		&#125;	&#125;	ret = clk_get_by_name(dev, &quot;bus&quot;, &amp;common-&gt;bclk);	if (!ret) &#123;		ret = clk_enable(&amp;common-&gt;bclk);		if (ret) &#123;			dev_err(dev, &quot;Can&#x27;t enable bclk: %d\n&quot;, ret);			goto err_aclk_disable;		&#125;	&#125;	ret = stm32h7_adc_clk_sel(dev, common);	if (ret)		goto err_bclk_disable;	return ret;err_bclk_disable:	if (clk_valid(&amp;common-&gt;bclk))		clk_disable(&amp;common-&gt;bclk);err_aclk_disable:	if (clk_valid(&amp;common-&gt;aclk))		clk_disable(&amp;common-&gt;aclk);	return ret;&#125;

