static int stm32_adc_probe(struct udevice *dev)&#123;	struct adc_uclass_plat *uc_pdata = dev_get_uclass_plat(dev);	struct stm32_adc_common *common = dev_get_priv(dev_get_parent(dev));	struct stm32_adc *adc = dev_get_priv(dev);	int offset, ret;	offset = dev_read_u32_default(dev, &quot;reg&quot;, -ENODATA);	if (offset &lt; 0) &#123;		dev_err(dev, &quot;Can&#x27;t read reg property\n&quot;);		return offset;	&#125;	adc-&gt;regs = common-&gt;base + offset;	adc-&gt;cfg = (const struct stm32_adc_cfg *)dev_get_driver_data(dev);	/* VDD supplied by common vref pin */	uc_pdata-&gt;vdd_supply = common-&gt;vref;	uc_pdata-&gt;vdd_microvolts = common-&gt;vref_uv;	uc_pdata-&gt;vss_microvolts = 0;	ret = stm32_adc_chan_of_init(dev);	if (ret &lt; 0)		return ret;	ret = stm32_adc_exit_pwr_down(dev);	if (ret &lt; 0)		return ret;	ret = stm32_adc_selfcalib(dev);	if (ret)		stm32_adc_enter_pwr_down(dev);	return ret;&#125;

