adc_pre_probe 设置 VDD VSSstatic int adc_pre_probe(struct udevice *dev)&#123;	int ret;	/* 设置 ADC VDD 平台：极性、uV、稳压器 （phandle）. */	ret = adc_vdd_plat_set(dev);	if (ret)		pr_err(&quot;%s: Can&#x27;t update Vdd. Error: %d&quot;, dev-&gt;name, ret);	/* /* 设置 ADC VSS 平台：极性、uV、稳压器 （phandle）。 */ */	ret = adc_vss_plat_set(dev);	if (ret)		pr_err(&quot;%s: Can&#x27;t update Vss. Error: %d&quot;, dev-&gt;name, ret);	return 0;&#125;

