clk_get_by_index_tail 转换客户端的设备树 （OF） 时钟说明符。static int clk_get_by_index_tail(int ret, ofnode node,				 struct ofnode_phandle_args *args,				 const char *list_name, int index,				 struct clk *clk)&#123;	struct udevice *dev_clk;	const struct clk_ops *ops;	assert(clk);	clk-&gt;dev = NULL;	if (ret)		goto err;	//通过uclass id 查找与节点匹配的设备	//这个时候已经绑定完所有可以操作的设备	ret = uclass_get_device_by_ofnode(UCLASS_CLK, args-&gt;node, &amp;dev_clk);	clk-&gt;dev = dev_clk;	ops = clk_dev_ops(dev_clk);	if (ops-&gt;of_xlate)		ret = ops-&gt;of_xlate(clk, args);	//转换客户端的设备树 （OF） 时钟说明符。	else		ret = clk_of_xlate_default(clk, args);	if (ret) &#123;		debug(&quot;of_xlate() failed: %d\n&quot;, ret);		return log_msg_ret(&quot;xlate&quot;, ret);	&#125;	return clk_request(dev_clk, clk);&#125;

