clk_set_defaults
CLK_DEFAULTS_PRE probe之前调用
CLK_DEFAULTS_POST probe之后调用
CLK_DEFAULTS_POST_FORCE 重定向后的probe之后调用

enum clk_defaults_stage &#123;	CLK_DEFAULTS_PRE = 0,	CLK_DEFAULTS_POST = 1,	CLK_DEFAULTS_POST_FORCE,&#125;;

device_probe函数中调用

/* Only handle devices that have a valid ofnode */if (dev_has_ofnode(dev)) &#123;	/*	 * Process &#x27;assigned-&#123;clocks/clock-parents/clock-rates&#125;&#x27;	 * properties	 */	ret = clk_set_defaults(dev, CLK_DEFAULTS_PRE);	if (ret)		goto fail;&#125;

int clk_set_defaults(struct udevice *dev, enum clk_defaults_stage stage)&#123;	int ret;	//如果不是reloc阶段,则不处理	if (!(IS_ENABLED(CONFIG_XPL_BUILD) || (gd-&gt;flags &amp; GD_FLG_RELOC)))		if (stage != CLK_DEFAULTS_POST_FORCE)			return 0;	ret = clk_set_default_parents(dev, stage);	ret = clk_set_default_rates(dev, stage);	return 0;&#125;

clk_set_default_parents 具备assigned-clock-parents属性才可以设置clk_set_default_rates 具备assigned-clock-rates属性才可以设置clk_request 一般不在使用ops-&gt;request,但是这里将clk绑定了devint clk_request(struct udevice *dev, struct clk *clk)&#123;	const struct clk_ops *ops;	debug(&quot;%s(dev=%p, clk=%p)\n&quot;, __func__, dev, clk);	if (!clk)		return 0;	ops = clk_dev_ops(dev);	//注意这里将clk绑定了dev	clk-&gt;dev = dev;	if (!ops-&gt;request)		return 0;	return ops-&gt;request(clk);&#125;

