stm32_clk_probereset-clock-controller@58024400 &#123;	compatible = &quot;st,stm32h743-rcc\0st,stm32-rcc&quot;;	reg = &lt;0x58024400 0x400&gt;;	#clock-cells = &lt;0x01&gt;;	#reset-cells = &lt;0x01&gt;;	clocks = &lt;0x18 0x19 0x1a&gt;;	st,syscfg = &lt;0x17&gt;;	bootph-all;	phandle = &lt;0x02&gt;;&#125;;static int stm32_clk_probe(struct udevice *dev)&#123;	struct stm32_clk *priv = dev_get_priv(dev);	struct udevice *syscon;	fdt_addr_t addr;	int err;	addr = dev_read_addr(dev);	//由rcc设备传入的node节点,获取的是rcc的地址	if (addr == FDT_ADDR_T_NONE)		return -EINVAL;	priv-&gt;rcc_base = (struct stm32_rcc_regs *)addr;	//获取rcc设备下的&quot;st,syscfg&quot;属性的phandle,通过phandle索引到syscon设备,并执行设备的probe函数	err = uclass_get_device_by_phandle(UCLASS_SYSCON, dev,					   &quot;st,syscfg&quot;, &amp;syscon);	//获取syscon设备的regmap	priv-&gt;pwr_regmap = syscon_get_regmap(syscon);	configure_clocks(dev);	return 0;&#125;

configure_clocks
使能HSI
设置电压为1.15-1.26V
锁定电源配置更新
配置HSE:25 MHz
配置PLL:pll1_p &#x3D; 250MHz &#x2F; pll1_q &#x3D; 250MHz pll1_r &#x3D; 250Mhz
配置AHB: 125MHz
配置APB: 125MHz
配置SDRAM时钟: 125MHz

/* * OSC_HSE = 25 MHz * VCO = 500MHz * pll1_p = 250MHz / pll1_q = 250MHz pll1_r = 250Mhz */struct pll_psc sys_pll_psc = &#123;	.divm = 4,	.divn = 80,	.divp = 2,	.divq = 2,	.divr = 2,&#125;;int configure_clocks(struct udevice *dev)&#123;	struct stm32_clk *priv = dev_get_priv(dev);	struct stm32_rcc_regs *regs = priv-&gt;rcc_base;	uint8_t *pwr_base = (uint8_t *)regmap_get_range(priv-&gt;pwr_regmap, 0);	uint32_t pllckselr = 0;	uint32_t pll1divr = 0;	uint32_t pllcfgr = 0;	/* Switch on HSI */	setbits_le32(&amp;regs-&gt;cr, RCC_CR_HSION);	while (!(readl(&amp;regs-&gt;cr) &amp; RCC_CR_HSIRDY))		;	/* Reset CFGR, now HSI is the default system clock */	writel(0, &amp;regs-&gt;cfgr);	/* Set all kernel domain clock registers to reset value*/	writel(x0, &amp;regs-&gt;d1ccipr);	writel(0x0, &amp;regs-&gt;d2ccip1r);	writel(0x0, &amp;regs-&gt;d2ccip2r);	/* Set voltage scaling at scale 1 (1,15 - 1,26 Volts) */	clrsetbits_le32(pwr_base + PWR_D3CR, PWR_D3CR_VOS_MASK,			VOS_SCALE_1 &lt;&lt; PWR_D3CR_VOS_SHIFT);	/* Lock supply configuration update */	clrbits_le32(pwr_base + PWR_CR3, PWR_CR3_SCUEN);	while (!(readl(pwr_base + PWR_D3CR) &amp; PWR_D3CR_VOSREADY))		;	/* disable HSE to configure it  */	clrbits_le32(&amp;regs-&gt;cr, RCC_CR_HSEON);	while ((readl(&amp;regs-&gt;cr) &amp; RCC_CR_HSERDY))		;	/* clear HSE bypass and set it ON */	clrbits_le32(&amp;regs-&gt;cr, RCC_CR_HSEBYP);	/* Switch on HSE */	setbits_le32(&amp;regs-&gt;cr, RCC_CR_HSEON);	while (!(readl(&amp;regs-&gt;cr) &amp; RCC_CR_HSERDY))		;	/* pll setup, disable it */	clrbits_le32(&amp;regs-&gt;cr, RCC_CR_PLL1ON);	while ((readl(&amp;regs-&gt;cr) &amp; RCC_CR_PLL1RDY))		;	/* Select HSE as PLL clock source */	pllckselr |= RCC_PLLCKSELR_PLLSRC_HSE;	pllckselr |= sys_pll_psc.divm &lt;&lt; RCC_PLLCKSELR_DIVM1_SHIFT;	writel(pllckselr, &amp;regs-&gt;pllckselr);	pll1divr |= (sys_pll_psc.divr - 1) &lt;&lt; RCC_PLL1DIVR_DIVR1_SHIFT;	pll1divr |= (sys_pll_psc.divq - 1) &lt;&lt; RCC_PLL1DIVR_DIVQ1_SHIFT;	pll1divr |= (sys_pll_psc.divp - 1) &lt;&lt; RCC_PLL1DIVR_DIVP1_SHIFT;	pll1divr |= (sys_pll_psc.divn - 1);	writel(pll1divr, &amp;regs-&gt;pll1divr);	pllcfgr |= PLL1RGE_4_8_MHZ &lt;&lt; RCC_PLLCFGR_PLL1RGE_SHIFT;	pllcfgr |= RCC_PLLCFGR_DIVP1EN;	pllcfgr |= RCC_PLLCFGR_DIVQ1EN;	pllcfgr |= RCC_PLLCFGR_DIVR1EN;	writel(pllcfgr, &amp;regs-&gt;pllcfgr);	/* pll setup, enable it */	setbits_le32(&amp;regs-&gt;cr, RCC_CR_PLL1ON);	/* set HPRE (/2) DI clk --&gt; 125MHz */	clrsetbits_le32(&amp;regs-&gt;d1cfgr, RCC_D1CFGR_HPRE_MASK,			RCC_D1CFGR_HPRE_DIV2);	/*  select PLL1 as system clock source (sys_ck)*/	clrsetbits_le32(&amp;regs-&gt;cfgr, RCC_CFGR_SW_MASK, RCC_CFGR_SW_PLL1);	while ((readl(&amp;regs-&gt;cfgr) &amp; RCC_CFGR_SW_MASK) != RCC_CFGR_SW_PLL1)		;	/* sdram: use pll1_q as fmc_k clk */	clrsetbits_le32(&amp;regs-&gt;d1ccipr, RCC_D1CCIPR_FMCSRC_MASK,			FMCSRC_PLL1_Q_CK);	return 0;&#125;

stm32_clk_of_xlate 转换客户端的设备树 （OF） 时钟说明符。static int stm32_clk_of_xlate(struct clk *clk,			struct ofnode_phandle_args *args)&#123;	//设备节点下的clocks属性内容只能有一个	/*		timer5: timer@40000c00 &#123;			compatible = &quot;st,stm32-timer&quot;;			reg = &lt;0x40000c00 0x400&gt;;			interrupts = &lt;50&gt;;			clocks = &lt;&amp;rcc TIM5_CK&gt;;		&#125;;	*/	if (args-&gt;args_count != 1) &#123;		dev_dbg(clk-&gt;dev, &quot;Invalid args_count: %d\n&quot;, args-&gt;args_count);		return -EINVAL;	&#125;	if (args-&gt;args_count) &#123;		clk-&gt;id = args-&gt;args[0];		if (clk-&gt;id &gt;= KERN_BANK) &#123;			clk-&gt;id -= KERN_BANK;			clk-&gt;id += LAST_PERIF_BANK - PERIF_BANK + 1;		&#125; else &#123;			clk-&gt;id -= PERIF_BANK;		&#125;	&#125; else &#123;		clk-&gt;id = 0;	&#125;	dev_dbg(clk-&gt;dev, &quot;clk-&gt;id %ld\n&quot;, clk-&gt;id);	return 0;&#125;

stm32_clk_get_rate 获取时钟频率static const struct clk_cfg clk_map[] = &#123;&#125;;	//时钟配置表static ulong stm32_clk_get_rate(struct clk *clk)&#123;	struct stm32_clk *priv = dev_get_priv(clk-&gt;dev);	struct stm32_rcc_regs *regs = priv-&gt;rcc_base;	ulong sysclk = 0;	u32 gate_offset;	u32 d1cfgr, d3cfgr;	/* prescaler table lookups for clock computation */	u16 prescaler_table[8] = &#123;2, 4, 8, 16, 64, 128, 256, 512&#125;;	u8 source, idx;	/*	 * get system clock (sys_ck) source	 * can be HSI_CK, CSI_CK, HSE_CK or pll1_p_ck	 */	source = readl(&amp;regs-&gt;cfgr) &amp; RCC_CFGR_SW_MASK;	switch (source) &#123;	case RCC_CFGR_SW_PLL1:		sysclk = stm32_get_PLL1_rate(regs, PLL1_P_CK);		break;	case RCC_CFGR_SW_HSE:		sysclk = stm32_get_rate(regs, HSE);		break;	case RCC_CFGR_SW_CSI:		sysclk = stm32_get_rate(regs, CSI);		break;	case RCC_CFGR_SW_HSI:		sysclk = stm32_get_rate(regs, HSI);		break;	&#125;	/* sysclk = 0 ? no need to go ahead */	if (!sysclk)		return sysclk;	dev_dbg(clk-&gt;dev, &quot;system clock: source = %d freq = %ld\n&quot;,		source, sysclk);	d1cfgr = readl(&amp;regs-&gt;d1cfgr);	if (d1cfgr &amp; RCC_D1CFGR_D1CPRE_DIVIDED) &#123;		/* get D1 domain Core prescaler */		idx = (d1cfgr &amp; RCC_D1CFGR_D1CPRE_DIVIDER) &gt;&gt;		      RCC_D1CFGR_D1CPRE_SHIFT;		sysclk = sysclk / prescaler_table[idx];	&#125;	if (d1cfgr &amp; RCC_D1CFGR_HPRE_DIVIDED) &#123;		/* get D1 domain AHB prescaler */		idx = d1cfgr &amp; RCC_D1CFGR_HPRE_DIVIDER;		sysclk = sysclk / prescaler_table[idx];	&#125;	gate_offset = clk_map[clk-&gt;id].gate_offset;	dev_dbg(clk-&gt;dev, &quot;clk-&gt;id=%ld gate_offset=0x%x sysclk=%ld\n&quot;,		clk-&gt;id, gate_offset, sysclk);	switch (gate_offset) &#123;	case RCC_AHB3ENR:	case RCC_AHB1ENR:	case RCC_AHB2ENR:	case RCC_AHB4ENR:		return sysclk;		break;	case RCC_APB3ENR:		if (d1cfgr &amp; RCC_D1CFGR_D1PPRE_DIVIDED) &#123;			/* get D1 domain APB3 prescaler */			idx = (d1cfgr &amp; RCC_D1CFGR_D1PPRE_DIVIDER) &gt;&gt;			      RCC_D1CFGR_D1PPRE_SHIFT;			sysclk = sysclk / prescaler_table[idx];		&#125;		dev_dbg(clk-&gt;dev, &quot;system clock: freq after APB3 prescaler = %ld\n&quot;,			sysclk);		return sysclk;		break;	case RCC_APB4ENR:		d3cfgr = readl(&amp;regs-&gt;d3cfgr);		if (d3cfgr &amp; RCC_D3CFGR_D3PPRE_DIVIDED) &#123;			/* get D3 domain APB4 prescaler */			idx = (d3cfgr &amp; RCC_D3CFGR_D3PPRE_DIVIDER) &gt;&gt;			      RCC_D3CFGR_D3PPRE_SHIFT;			sysclk = sysclk / prescaler_table[idx];		&#125;		dev_dbg(clk-&gt;dev,			&quot;system clock: freq after APB4 prescaler = %ld\n&quot;,			sysclk);		return sysclk;		break;	case RCC_APB1LENR:	case RCC_APB1HENR:		/* special case for GPT timers */		switch (clk-&gt;id) &#123;		case TIM14_CK:		case TIM13_CK:		case TIM12_CK:		case TIM7_CK:		case TIM6_CK:		case TIM5_CK:		case TIM4_CK:		case TIM3_CK:		case TIM2_CK:			return stm32_get_timer_rate(priv, sysclk, APB1);		&#125;		dev_dbg(clk-&gt;dev,			&quot;system clock: freq after APB1 prescaler = %ld\n&quot;,			sysclk);		return (sysclk / stm32_get_apb_psc(regs, APB1));		break;	case RCC_APB2ENR:		/* special case for timers */		switch (clk-&gt;id) &#123;		case TIM17_CK:		case TIM16_CK:		case TIM15_CK:		case TIM8_CK:		case TIM1_CK:			return stm32_get_timer_rate(priv, sysclk, APB2);		&#125;		dev_dbg(clk-&gt;dev,			&quot;system clock: freq after APB2 prescaler = %ld\n&quot;,			sysclk);		return (sysclk / stm32_get_apb_psc(regs, APB2));		break;	default:		dev_err(clk-&gt;dev, &quot;unexpected gate_offset value (0x%x)\n&quot;,			gate_offset);		return -EINVAL;		break;	&#125;&#125;

stm32_get_rate 获取时钟源频率static const char * const pllsrc_name[PLLSRC_NB] = &#123;	[HSE] = &quot;clk-hse&quot;,	[LSE] = &quot;clk-lse&quot;,	[HSI] = &quot;clk-hsi&quot;,	[CSI] = &quot;clk-csi&quot;,	[I2S] = &quot;clk-i2s&quot;,	[TIMER] = &quot;timer-clk&quot;&#125;;static ulong stm32_get_rate(struct stm32_rcc_regs *regs, enum pllsrc pllsrc)&#123;	struct clk clk;	struct udevice *fixed_clock_dev = NULL;	u32 divider;	int ret;	const char *name = pllsrc_name[pllsrc];	log_debug(&quot;pllsrc name %s\n&quot;, name);	clk.id = 0;	//通过名字匹配fixed-clock设备,并进行probe	ret = uclass_get_device_by_name(UCLASS_CLK, name, &amp;fixed_clock_dev);	if (ret) &#123;		log_err(&quot;Can&#x27;t find clk %s (%d)&quot;, name, ret);		return 0;	&#125;	ret = clk_request(fixed_clock_dev, &amp;clk);	if (ret) &#123;		log_err(&quot;Can&#x27;t request %s clk (%d)&quot;, name, ret);		return 0;	&#125;	divider = 0;	if (pllsrc == HSI)		divider = stm32_get_HSI_divider(regs);	//获取compatible = &quot;fixed-clock&quot;的节点下的clock-frequency属性值	log_debug(&quot;divider %d rate %ld\n&quot;, divider, clk_get_rate(&amp;clk));	return clk_get_rate(&amp;clk) &gt;&gt; divider;&#125;;

stm32_clk_enable 使能时钟
