dm_scan_fdt_ofnode_path 扫描chosen、clocks、firmware、reserved-memory节点并绑定设备到根节点dm_scan_other boot&#x2F;bootstd-uclass.c ,用于bootmethoddm_autoprobe 绑定后探测根节点下的子设备和子设备的子设备device flag 说明// probe 后设置,表示设备已经激活#define DM_FLAG_ACTIVATED		(1 &lt;&lt; 0)// 表示是 malloc 分配的设备私有数据,需要在设备移除时释放#define DM_FLAG_ALLOC_PDATA		(1 &lt;&lt; 1)// 表示设备在重定位之前绑定,没有这个标志的设备在重定位之后绑定#define DM_FLAG_PRE_RELOC		(1 &lt;&lt; 2)// DM 负责分配和释放父设备的平台数据#define DM_FLAG_ALLOC_PARENT_PDATA	(1 &lt;&lt; 3)// DM 负责分配和释放 uclass 的平台数据#define DM_FLAG_ALLOC_UCLASS_PDATA	(1 &lt;&lt; 4)// 分配私有 DMA 数据#define DM_FLAG_ALLOC_PRIV_DMA		(1 &lt;&lt; 5)// 设备已经绑定#define DM_FLAG_BOUND			(1 &lt;&lt; 6)// 设备名字是通过 malloc 分配的#define DM_FLAG_NAME_ALLOCED		(1 &lt;&lt; 7)/* 设备具有由 of-platdata 提供的平台数据*/#define DM_FLAG_OF_PLATDATA		(1 &lt;&lt; 8)// 设备具有活动 DMA#define DM_FLAG_ACTIVE_DMA		(1 &lt;&lt; 9)/** 调用驱动 remove 函数做一些最后的配置，之前 * U-Boot 退出并启动作系统 */#define DM_FLAG_OS_PREPARE		(1 &lt;&lt; 10)/* DM 不会启用/禁用与此设备对应的电源域 */#define DM_FLAG_DEFAULT_PD_CTRL_OFF	(1 &lt;&lt; 11)/* Driver plat 有效。移除设备时清除 */#define DM_FLAG_PLATDATA_VALID		(1 &lt;&lt; 12)/* * 设备被移除，但未关闭其电源域。这可能会 * 是必需的，即用于引导作系统时的串行控制台 （debug） 输出。 */#define DM_FLAG_LEAVE_PD_ON		(1 &lt;&lt; 13)/* * 设备对其他设备的运行至关重要。可以删除 * 在移除所有常规设备后删除此设备。这很有用 * 例如，对于 clock，它需要在设备删除阶段处于活动状态。 */#define DM_FLAG_VITAL			(1 &lt;&lt; 14)/* 设备绑定后必须探测 */#define DM_FLAG_PROBE_AFTER_BIND	(1 &lt;&lt; 15)/* * 这些标志中的一个或多个被传递给 device_remove（），以便 * 由 remove-stage 指定的选择性设备删除，并且 * 可以进行驱动程序标记。 * * 不要在驱动程序的 @flags 值中使用这些标志... * 使用上述DM_FLAG_...值 */enum &#123;	/* 正常删除、删除所有设备*/	DM_REMOVE_NORMAL	= 1 &lt;&lt; 0,	/* 删除具有活动 DMA 的设备*/	DM_REMOVE_ACTIVE_DMA	= DM_FLAG_ACTIVE_DMA,	/* 删除需要一些最终 OS 准备步骤的设备*/	DM_REMOVE_OS_PREPARE	= DM_FLAG_OS_PREPARE,	/* 仅删除未标记为 Vital 的设备 */	DM_REMOVE_NON_VITAL	= DM_FLAG_VITAL,	/* Remove devices with any active flag */	DM_REMOVE_ACTIVE_ALL	= DM_REMOVE_ACTIVE_DMA | DM_REMOVE_OS_PREPARE,	/*不要关闭任何连接的电源域*/	DM_REMOVE_NO_PD		= 1 &lt;&lt; 1,&#125;;

