dm_init_and_scan/** * dm_init_and_scan（） - 初始化驱动程序模型结构并扫描设备 * * 此函数初始化驱动程序树和 uclass 树的根， * 然后扫描并绑定来自平台数据和 FDT 的可用设备。 * 这将调用 dm_init（） 来设置驱动程序模型结构。 * * @pre_reloc_only： 如果为 true，则仅绑定具有特殊 devicetree 属性的节点， * 或带有 DM_FLAG_PRE_RELOC 标志的驱动程序。如果为 false，则绑定所有驱动程序。 * 返回：OK 时为 0，出错时为 -ve */int dm_init_and_scan(bool pre_reloc_only)&#123;	int ret;	ret = dm_init(CONFIG_IS_ENABLED(OF_LIVE));	//初始化驱动模型结构,初始化根节点	if (!CONFIG_IS_ENABLED(OF_PLATDATA_INST)) &#123;		ret = dm_scan(pre_reloc_only);			//扫描设备并绑定到根节点	&#125;	if (CONFIG_IS_ENABLED(DM_EVENT)) &#123;		ret = event_notify_null(gd-&gt;flags &amp; GD_FLG_RELOC ?					EVT_DM_POST_INIT_R :					EVT_DM_POST_INIT_F);		if (ret)			return log_msg_ret(&quot;ev&quot;, ret);	&#125;	return 0;&#125;

dm_init 初始化驱动模型结构/** * dm_init（） - 初始化驱动模型结构 * * 此函数将初始化驱动程序树和类树的根。 * 这需要在使用 DM 之前调用 * * @of_live：启用 Live 设备树 * 返回：OK 时为 0，出错时为 -ve */int dm_init(bool of_live)&#123;	int ret;	if (CONFIG_IS_ENABLED(OF_PLATDATA_INST)) &#123;		gd-&gt;uclass_root = &amp;uclass_head;	&#125; else &#123;		//初始化uclass根		gd-&gt;uclass_root = &amp;DM_UCLASS_ROOT_S_NON_CONST;		INIT_LIST_HEAD(DM_UCLASS_ROOT_NON_CONST);	&#125;	if (CONFIG_IS_ENABLED(OF_PLATDATA_INST)) &#123;		ret = dm_setup_inst();		if (ret) &#123;			log_debug(&quot;dm_setup_inst() failed: %d\n&quot;, ret);			return ret;		&#125;	&#125; else &#123;		//绑定root_info,并将指向绑定设备的指针返回到DM_ROOT_NON_CONST		ret = device_bind_by_name(NULL, false, &amp;root_info,					  &amp;DM_ROOT_NON_CONST);		if (ret)			return ret;		if (CONFIG_IS_ENABLED(OF_CONTROL))			dev_set_ofnode(DM_ROOT_NON_CONST, ofnode_root());	//设置根节点		ret = device_probe(DM_ROOT_NON_CONST);	//探测设备		if (ret)			return ret;	&#125;&#125;

dm_scan 设备扫描static int dm_scan(bool pre_reloc_only)&#123;	int ret;	ret = dm_scan_plat(pre_reloc_only);	//绑定段中的driver_info	if (CONFIG_IS_ENABLED(OF_REAL)) &#123;		ret = dm_extended_scan(pre_reloc_only);	//从FDT中扫描设备并绑定到根节点	&#125;	//boot/bootstd-uclass.c ,用于bootmethod	ret = dm_scan_other(pre_reloc_only); //弱定义函数，扫描其他设备	return 0;&#125;

