dm_autoprobe	绑定后探测根节点下的子设备和子设备的子设备dm_probe_devices 绑定后探测节点下的子设备和子设备的子设备static int dm_probe_devices(struct udevice *dev)&#123;	struct udevice *child;	if (dev_get_flags(dev) &amp; DM_FLAG_PROBE_AFTER_BIND) &#123;	//设备具有DM_FLAG_PROBE_AFTER_BIND标志，将在绑定后探测设备		int ret;		ret = device_probe(dev);		if (ret)			return ret;	&#125;	//扫描所有设备进行探测	list_for_each_entry(child, &amp;dev-&gt;child_head, sibling_node)		dm_probe_devices(child);	//再次调用探测设备,递归探测执行所有子节点	return 0;&#125;

dm_extended_scan 从FDT中扫描设备并绑定到根节点int dm_extended_scan(bool pre_reloc_only)&#123;	int ret, i;	const char * const nodes[] = &#123;		&quot;/chosen&quot;,		&quot;/clocks&quot;,		&quot;/firmware&quot;,		&quot;/reserved-memory&quot;,	&#125;;	//扫描FDT中的节点并根据节点属性compatible信息匹配,绑定设备; 注意节点若具有`satus`属性,则值为`ok`,则才会绑定设备	ret = dm_scan_fdt(pre_reloc_only);	//扫描FDT中的设备并绑定到根节点	/* 有些节点本身不是设备，但可能包含一些驱动*/	for (i = 0; i &lt; ARRAY_SIZE(nodes); i++) &#123;		ret = dm_scan_fdt_ofnode_path(nodes[i], pre_reloc_only);	&#125;	return ret;&#125;

dm_scan_fdt 扫描FDT中的设备并绑定到根节点dm_scan_fdt_node 扫描FDT中的节点并根据节点compatible信息匹配,绑定设备
注意节点若具有satus属性,则值为ok,则才会绑定设备

static int dm_scan_fdt_node(struct udevice *parent, ofnode parent_node,			    bool pre_reloc_only)&#123;	int ret = 0, err = 0;	ofnode node;	for (node = ofnode_first_subnode(parent_node);	//获取第一个子节点	     ofnode_valid(node);						//判断节点是否有效	     node = ofnode_next_subnode(node)) &#123;		//获取下一个子节点		const char *node_name = ofnode_get_name(node);		if (!ofnode_is_enabled(node)) &#123;				//设备树中节点属性status=ok			pr_debug(&quot;   - ignoring disabled device\n&quot;);			continue;		&#125;		//从FDT的每个节点获取compatible信息并与段中的driver结构体的of_match信息匹配,进而绑定设备		err = lists_bind_fdt(parent, node, NULL, NULL, pre_reloc_only);	&#125;	return ret;&#125;

## dm_remove_devices_active 移除所有激活的设备void dm_remove_devices_active(void)&#123;	/* Remove non-vital devices first */	device_remove(dm_root(), DM_REMOVE_ACTIVE_ALL | DM_REMOVE_NON_VITAL);	device_remove(dm_root(), DM_REMOVE_ACTIVE_ALL);&#125;

device.cudevice 驱动程序实例
函数包含有关设备的信息，该设备是绑定到特定端口或外围设备（本质上是一个驱动程序实例）
包含节点,序列号

driver 功能或外围设备的驱动程序
此字段包含设置新设备和删除新设备的方法。设备需要信息来设置自身 
驱动程序都属于一个 uclass，代表相同类型。

device_bind_by_name 通过名字绑定设备int device_bind_by_name(struct udevice *parent, bool pre_reloc_only,			const struct driver_info *info, struct udevice **devp)&#123;	struct driver *drv;	uint plat_size = 0;	int ret;	//根据名字在段里面查找驱动	drv = lists_driver_lookup_name(info-&gt;name);	if (!drv)		return -ENOENT;	if (pre_reloc_only &amp;&amp; !(drv-&gt;flags &amp; DM_FLAG_PRE_RELOC))		return -EPERM;#if CONFIG_IS_ENABLED(OF_PLATDATA)	plat_size = info-&gt;plat_size;#endif	ret = device_bind_common(parent, drv, info-&gt;name, (void *)info-&gt;plat, 0,				 ofnode_null(), plat_size, devp);	if (ret)		return ret;	return ret;&#125;

device_bind_common 绑定设备static int device_bind_common(struct udevice *parent, const struct driver *drv,			      const char *name, void *plat,			      ulong driver_data, ofnode node,			      uint of_plat_size, struct udevice **devp)&#123;	struct udevice *dev;	struct uclass *uc;	int size, ret = 0;	bool auto_seq = true;	void *ptr;	//根据drv-&gt;id在段中找到对应的uclass	ret = uclass_get(drv-&gt;id, &amp;uc);	dev = calloc(1, sizeof(struct udevice));	INIT_LIST_HEAD(&amp;dev-&gt;sibling_node);	INIT_LIST_HEAD(&amp;dev-&gt;child_head);	INIT_LIST_HEAD(&amp;dev-&gt;uclass_node);#if CONFIG_IS_ENABLED(DEVRES)	INIT_LIST_HEAD(&amp;dev-&gt;devres_head);#endif	//绑定driver_info到plat中,一般不要使用,而是使用下方的这个函数调用	dev_set_plat(dev, plat);	dev-&gt;driver_data = driver_data;	dev-&gt;name = name;		//注意这里将初始化定义的驱动名称替换为FDT中的名称	dev_set_ofnode(dev, node);	dev-&gt;parent = parent;	dev-&gt;driver = drv;	dev-&gt;uclass = uc;	dev-&gt;seq_ = -1;	//根据配置文件中的配置，设置seq_	if (CONFIG_IS_ENABLED(DM_SEQ_ALIAS) &amp;&amp;	    (uc-&gt;uc_drv-&gt;flags &amp; DM_UC_FLAG_SEQ_ALIAS)) &#123;		/*某些设备，例如 SPI 总线、I2C 总线和串行端口使用别名进行编号。*/		if (CONFIG_IS_ENABLED(OF_CONTROL) &amp;&amp;	//如果开启了设备树控制		    !CONFIG_IS_ENABLED(OF_PLATDATA)) &#123;	//并且没有开启设备树平台数据			if (uc-&gt;uc_drv-&gt;name &amp;&amp; ofnode_valid(node)) &#123;				if (!dev_read_alias_seq(dev, &amp;dev-&gt;seq_)) &#123;					//如果读取别名后缀数字成功，设置auto_seq为false,seq_为读取到的数字					auto_seq = false;					log_debug(&quot;   - seq=%d\n&quot;, dev-&gt;seq_);					&#125;			&#125;		&#125;	&#125;	//没有在FDT中读取到别名后缀数字	if (auto_seq &amp;&amp; !(uc-&gt;uc_drv-&gt;flags &amp; DM_UC_FLAG_NO_AUTO_SEQ))		dev-&gt;seq_ = uclass_find_next_free_seq(uc);	//由程序自动设置seq_	//有父节点设备	if (parent) &#123;		/*将 dev 放入父级的 successor list */		list_add_tail(&amp;dev-&gt;sibling_node, &amp;parent-&gt;child_head);	&#125;	ret = uclass_bind_device(dev);	//将设备绑定到uclass	if (drv-&gt;bind) &#123;		ret = drv-&gt;bind(dev);	&#125;	if (parent &amp;&amp; parent-&gt;driver-&gt;child_post_bind) &#123;		ret = parent-&gt;driver-&gt;child_post_bind(dev);	&#125;	if (uc-&gt;uc_drv-&gt;post_bind) &#123;		ret = uc-&gt;uc_drv-&gt;post_bind(dev);	&#125;	if (parent)		pr_debug(&quot;Bound device %s to %s\n&quot;, dev-&gt;name, parent-&gt;name);	if (devp)		*devp = dev;	dev_or_flags(dev, DM_FLAG_BOUND);	return 0;&#125;

device_probe 探测设备int device_probe(struct udevice *dev)&#123;	const struct driver *drv;	int ret;	if (!dev)		return -EINVAL;	if (dev_get_flags(dev) &amp; DM_FLAG_ACTIVATED)		return 0;	ret = device_notify(dev, EVT_DM_PRE_PROBE);	drv = dev-&gt;driver;	ret = device_of_to_plat(dev);						//识别设备并分配与设置平台内部的数据	//在父设备上调用 probe	if (dev-&gt;parent) &#123;		ret = device_probe(dev-&gt;parent);		if (dev_get_flags(dev) &amp; DM_FLAG_ACTIVATED)			return 0;	&#125;	dev_or_flags(dev, DM_FLAG_ACTIVATED);				//设置设备激活标志	ret = dev_power_domain_on(dev);						//打开电源域	ret = pinctrl_select_state(dev, &quot;default&quot;);			//选择默认状态	ret = dev_iommu_enable(dev);						//启用IOMMU	ret = device_get_dma_constraints(dev);				//获取DMA约束	ret = uclass_pre_probe_device(dev);					//uclass预探测设备	ret = dev-&gt;parent-&gt;driver-&gt;child_pre_probe(dev);	//父设备的child_pre_probe	ret = clk_set_defaults(dev, CLK_DEFAULTS_PRE);		//设置默认时钟	ret = drv-&gt;probe(dev);								//调用驱动的probe函数	ret = uclass_post_probe_device(dev);				//uclass后探测设备	ret = pinctrl_select_state(dev, &quot;default&quot;);			//选择默认状态	return ret;&#125;


device_of_to_plat 识别设备并分配与设置平台内部的数据int device_of_to_plat(struct udevice *dev)&#123;	const struct driver *drv;	int ret;	/* Ensure all parents have ofdata */	if (dev-&gt;parent) &#123;		ret = device_of_to_plat(dev-&gt;parent);	&#125;	ret = device_alloc_priv(dev);	//分配设备私有数据	drv = dev-&gt;driver;	ret = drv-&gt;of_to_plat(dev);		//驱动平台内部的数据进行识别设置	dev_or_flags(dev, DM_FLAG_PLATDATA_VALID);	return 0;&#125;

device_alloc_priv 分配设备私有数据static int device_alloc_priv(struct udevice *dev)&#123;	/* Allocate private data if requested and not reentered */	size = dev-&gt;uclass-&gt;uc_drv-&gt;per_device_auto;	if (size &amp;&amp; !dev_get_uclass_priv(dev)) &#123;		ptr = alloc_priv(size, dev-&gt;uclass-&gt;uc_drv-&gt;flags);	//分配私有数据		if (!ptr)			return -ENOMEM;		dev_set_uclass_priv(dev, ptr);	//设置设备私有数据	&#125;&#125;

device_bind_with_driver_data 绑定设备到父节点并传入驱动数据,与fdt的node信息int device_bind_with_driver_data(struct udevice *parent,				 const struct driver *drv, const char *name,				 ulong driver_data, ofnode node,				 struct udevice **devp)&#123;	return device_bind_common(parent, drv, name, NULL, driver_data, node,				  0, devp);&#125;

uclass.cuclass_getuclass_find 根据key查找uclassstruct uclass *uclass_find(enum uclass_id key)&#123;	struct uclass *uc;	if (!gd-&gt;dm_root)		return NULL;	//遍历uclass链表，根据key找到对应的uclass	list_for_each_entry(uc, gd-&gt;uclass_root, sibling_node) &#123;		if (uc-&gt;uc_drv-&gt;id == key)			return uc;	&#125;	return NULL;&#125;

uclass_find_device_by_ofnode 根据ofnode查找设备int uclass_find_device_by_ofnode(enum uclass_id id, ofnode node,				 struct udevice **devp)&#123;	struct uclass *uc;	struct udevice *dev;	int ret;	log(LOGC_DM, LOGL_DEBUG, &quot;Looking for %s\n&quot;, ofnode_get_name(node));	*devp = NULL;	ret = uclass_get(id, &amp;uc);	//根据id获取uclass	if (ret)		return ret;	//遍历uclass链表，根据ofnode找到对应的设备	uclass_foreach_dev(dev, uc) &#123;		log(LOGC_DM, LOGL_DEBUG_CONTENT, &quot;      - checking %s\n&quot;,		    dev-&gt;name);		//比较ofnode的偏移量是否一致		//dev是扫描FDT所有节点时获取的偏移量，node是直接从fdt中读取的偏移量		if (ofnode_equal(dev_ofnode(dev), node)) &#123;			*devp = dev;			goto done;		&#125;	&#125;	ret = -ENODEV;done:	log(LOGC_DM, LOGL_DEBUG, &quot;   - result for %s: %s (ret=%d)\n&quot;,	    ofnode_get_name(node), *devp ? (*devp)-&gt;name : &quot;(none)&quot;, ret);	return ret;&#125;

