int uclass_find_device_by_phandle(enum uclass_id id, struct udevice *parent,				  const char *name, struct udevice **devp)&#123;	int find_phandle;	*devp = NULL;	find_phandle = dev_read_u32_default(parent, name, -1);	if (find_phandle &lt;= 0)		return -ENOENT;	return uclass_find_device_by_phandle_id(id, find_phandle, devp);&#125;

