lists.clists_bind_drivers 绑定段中的driver_info
由于设备之间可能存在依赖关系，因此可能需要多次绑定设备
必须先绑定父设备，然后再绑定子设备
所以尝试绑定设备10次，如果绑定失败，返回-EAGAIN

int lists_bind_drivers(struct udevice *parent, bool pre_reloc_only)&#123;	int result = 0;	int pass;	/*	 * 10 次传递是 DeviceTree 中的 10 个级别，这已经足够了。如果	 * OF_PLATDATA_PARENT未启用，则 bind_drivers_pass（） 将	 * 总是在第一次传递时成功。	 */	for (pass = 0; pass &lt; 10; pass++) &#123;		int ret;		ret = bind_drivers_pass(parent, pre_reloc_only);		if (!result || result == -EAGAIN)			result = ret;		if (ret != -EAGAIN)			break;	&#125;	return result;&#125;

bind_drivers_pass 遍历段中的driver_infostatic int bind_drivers_pass(struct udevice *parent, bool pre_reloc_only)&#123;	//遍历段中的driver_info	struct driver_info *info =		ll_entry_start(struct driver_info, driver_info);	const int n_ents = ll_entry_count(struct driver_info, driver_info);	bool missing_parent = false;	int result = 0;	int idx;	/*	 * 对 driver_info 记录执行一次迭代。对于 of-platdata，	 * 仅绑定父设备已绑定的设备。如果我们发现任何	 * device 无法绑定，将 missing_parent 设置为 true，这会导致	 * 此函数将再次调用。	 */	for (idx = 0; idx &lt; n_ents; idx++) &#123;		struct udevice *par = parent;		const struct driver_info *entry = info + idx;		struct driver_rt *drt = gd_dm_driver_rt() + idx;		struct udevice *dev;		int ret;		ret = device_bind_by_name(par, pre_reloc_only, entry, &amp;dev);		if (!ret) &#123;			if (CONFIG_IS_ENABLED(OF_PLATDATA))				drt-&gt;dev = dev;		&#125; else if (ret != -EPERM) &#123;			dm_warn(&quot;No match for driver &#x27;%s&#x27;\n&quot;, entry-&gt;name);			if (!result || ret != -ENOENT)				result = ret;		&#125;	&#125;	return result ? result : missing_parent ? -EAGAIN : 0;&#125;

lists_bind_fdt 从FDT的每个节点获取compatible信息并与段中的driver结构体的of_match信息匹配,进而绑定设备int lists_bind_fdt(struct udevice *parent, ofnode node, struct udevice **devp,		   struct driver *drv, bool pre_reloc_only)&#123;	struct driver *driver = ll_entry_start(struct driver, driver);	const int n_ents = ll_entry_count(struct driver, driver);	const struct udevice_id *id;	struct driver *entry;	struct udevice *dev;	bool found = false;	const char *name, *compat_list, *compat;	int compat_length, i;	int result = 0;	int ret = 0;	if (devp)		*devp = NULL;	name = ofnode_get_name(node);	log_debug(&quot;bind node %s\n&quot;, name);	compat_list = ofnode_get_property(node, &quot;compatible&quot;, &amp;compat_length);	if (!compat_list) &#123;		if (compat_length == -FDT_ERR_NOTFOUND) &#123;			log_debug(&quot;Device &#x27;%s&#x27; has no compatible string\n&quot;,				  name);			return 0;		&#125;		dm_warn(&quot;Device tree error at node &#x27;%s&#x27;\n&quot;, name);		return compat_length;	&#125;	/*	 * 遍历兼容的字符串列表，尝试匹配每个字符串	 * compatible 字符串，以便我们按优先级顺序匹配	 * 从第一个字符串到最后一个字符串。	 */	for (i = 0; i &lt; compat_length; i += strlen(compat) + 1) &#123;		compat = compat_list + i;		log_debug(&quot;   - attempt to match compatible string &#x27;%s&#x27;\n&quot;,			  compat);		id = NULL;		//遍历段中的driver		for (entry = driver; entry != driver + n_ents; entry++) &#123;			if (drv) &#123;	//如果drv不为空，只绑定drv				if (drv != entry)					continue;				if (!entry-&gt;of_match)					break;			&#125;			//设备的of_match与FDT的compatible字符串匹配,返回匹配的驱动id和驱动数据			ret = driver_check_compatible(entry-&gt;of_match, &amp;id,						      compat);			if (!ret)	//匹配成功				break;		&#125;		if (entry == driver + n_ents)	//没有匹配成功,继续下一个兼容字符串			continue;		if (pre_reloc_only) &#123;//重定向之前必需满足的条件			if (!ofnode_pre_reloc(node) &amp;&amp;					//判断节点是否需要在重定位之前绑定			    !(entry-&gt;flags &amp; DM_FLAG_PRE_RELOC)) &#123;		//如果设备没有DM_FLAG_PRE_RELOC标志，跳过设备				log_debug(&quot;Skipping device pre-relocation\n&quot;);				return 0;			&#125;		&#125;		if (entry-&gt;of_match)			log_debug(&quot;   - found match at driver &#x27;%s&#x27; for &#x27;%s&#x27;\n&quot;,				  entry-&gt;name, id-&gt;compatible);		//绑定设备到父节点,将匹配的兼容设备id的data传递给设备,node是FDT中的节点进行传入绑定		ret = device_bind_with_driver_data(parent, entry, name,						   id ? id-&gt;data : 0, node,						   &amp;dev);		found = true;		if (devp)			*devp = dev;		break;	&#125;	return result;&#125;

driver_check_compatible 检查设备是否与驱动程序兼容,每个字符串需要完全匹配
驱动有一个of_match数组，用于检查设备是否与驱动兼容
通过比较设备的compatible字符串，判断设备是否与驱动兼容
可以多个compatible字符串，只要有一个匹配即可
of_idp返回匹配的驱动id和驱动数据
返回0表示匹配

static int driver_check_compatible(const struct udevice_id *of_match,				   const struct udevice_id **of_idp,				   const char *compat)&#123;	if (!of_match)		return -ENOENT;	while (of_match-&gt;compatible) &#123;		if (!strcmp(of_match-&gt;compatible, compat)) &#123;			*of_idp = of_match;			return 0;		&#125;		of_match++;	&#125;	return -ENOENT;&#125;

