bool ofnode_pre_reloc(ofnode node)&#123;#if defined(CONFIG_XPL_BUILD) || defined(CONFIG_TPL_BUILD)	/* for SPL and TPL the remaining nodes after the fdtgrep 1st pass	 * had property bootph-all or bootph-pre-sram/bootph-pre-ram.	 * They are removed in final dtb (fdtgrep 2nd pass)	 */	return true;#else	if (ofnode_read_bool(node, &quot;bootph-all&quot;))		return true;	if (ofnode_read_bool(node, &quot;bootph-some-ram&quot;))		return true;	/*	 * In regular builds individual spl and tpl handling both	 * count as handled pre-relocation for later second init.	 */	if (ofnode_read_bool(node, &quot;bootph-pre-ram&quot;) ||	    ofnode_read_bool(node, &quot;bootph-pre-sram&quot;))		return gd-&gt;flags &amp; GD_FLG_RELOC;	if (IS_ENABLED(CONFIG_OF_TAG_MIGRATE)) &#123;		/* detect and handle old tags */		if (ofnode_read_bool(node, &quot;u-boot,dm-pre-reloc&quot;) ||		    ofnode_read_bool(node, &quot;u-boot,dm-pre-proper&quot;) ||		    ofnode_read_bool(node, &quot;u-boot,dm-spl&quot;) ||		    ofnode_read_bool(node, &quot;u-boot,dm-tpl&quot;) ||		    ofnode_read_bool(node, &quot;u-boot,dm-vpl&quot;)) &#123;			gd-&gt;flags |= GD_FLG_OF_TAG_MIGRATE;			return true;		&#125;	&#125;	return false;#endif&#125;

