device-remove.cdevice_remove 移除设备int device_remove(struct udevice *dev, uint flags)&#123;	const struct driver *drv;	int ret;	if (!dev)		return -EINVAL;	if (!(dev_get_flags(dev) &amp; DM_FLAG_ACTIVATED))	//没激活的设备不需要移除		return 0;	ret = device_notify(dev, EVT_DM_PRE_REMOVE);	if (ret)		return ret;	/*	 * 如果子项返回 EKEYREJECTED，请继续。它只是意味着它	 * 不匹配标志。	 */	ret = device_chld_remove(dev, NULL, flags);	if (ret &amp;&amp; ret != -EKEYREJECTED)		return ret;	/*	 * 如果在设置了 “normal” remove 标志的情况下调用设备，则删除设备，	 * 或者如果 remove 标志与任何驱动程序 remove 标志匹配	 */	drv = dev-&gt;driver;	assert(drv);	ret = flags_remove(flags, drv-&gt;flags);	//判断设备属性是否允许移除	if (ret) &#123;		log_debug(&quot;%s: When removing: flags=%x, drv-&gt;flags=%x, err=%d\n&quot;,			  dev-&gt;name, flags, drv-&gt;flags, ret);		return ret;	&#125;	ret = uclass_pre_remove_device(dev);	if (ret)		return ret;	if (drv-&gt;remove) &#123;		ret = drv-&gt;remove(dev);		if (ret)			goto err_remove;	&#125;	if (dev-&gt;parent &amp;&amp; dev-&gt;parent-&gt;driver-&gt;child_post_remove) &#123;		ret = dev-&gt;parent-&gt;driver-&gt;child_post_remove(dev);		if (ret) &#123;			dm_warn(&quot;%s: Device &#x27;%s&#x27; failed child_post_remove()&quot;,				__func__, dev-&gt;name);		&#125;	&#125;	if (!(flags &amp; DM_REMOVE_NO_PD) &amp;&amp;	    !(drv-&gt;flags &amp;	      (DM_FLAG_DEFAULT_PD_CTRL_OFF | DM_FLAG_LEAVE_PD_ON)) &amp;&amp;	    dev != gd-&gt;cur_serial_dev)		dev_power_domain_off(dev);	device_free(dev);	dev_bic_flags(dev, DM_FLAG_ACTIVATED);	ret = device_notify(dev, EVT_DM_POST_REMOVE);	if (ret)		goto err_remove;	return 0;err_remove:	/* We can&#x27;t put the children back */	dm_warn(&quot;%s: Device &#x27;%s&#x27; failed to remove, but children are gone\n&quot;,		__func__, dev-&gt;name);	return ret;&#125;

device_chld_remove 移除设备下的子设备int device_chld_remove(struct udevice *dev, struct driver *drv,		       uint flags)&#123;	struct udevice *pos, *n;	int result = 0;	assert(dev);	device_foreach_child_safe(pos, n, dev) &#123;		int ret;		if (drv &amp;&amp; (pos-&gt;driver != drv))			continue;		ret = device_remove(pos, flags);		if (ret == -EPROBE_DEFER)			result = ret;		else if (ret &amp;&amp; ret != -EKEYREJECTED)			return ret;	&#125;	return result;&#125;

flags_remove 判断设备属性是否允许移除
具有DM_REMOVE_NORMAL标志的正常设备,允许进行卸载
具有活动 DMA 的设备(DM_REMOVE_ACTIVE_DMA	= DM_FLAG_ACTIVE_DMA) 和跳转APP所需要的活动设备(DM_REMOVE_OS_PREPARE	= DM_FLAG_OS_PREPARE)，不允许卸载;返回-EKEYREJECTED
具有标记为 Vital 的设备(DM_REMOVE_NON_VITAL	= DM_FLAG_VITAL,),不允许卸载;返回-EPROBE_DEFER

static int flags_remove(uint flags, uint drv_flags)&#123;	if (!(flags &amp; DM_REMOVE_NORMAL)) &#123;		bool vital_match;		bool active_match;		active_match = !(flags &amp; DM_REMOVE_ACTIVE_ALL) ||			(drv_flags &amp; flags);		vital_match = !(flags &amp; DM_REMOVE_NON_VITAL) ||			!(drv_flags &amp; DM_FLAG_VITAL);		if (!vital_match)			return -EPROBE_DEFER;		if (!active_match)			return -EKEYREJECTED;	&#125;	return 0;&#125;

