static int stm32_pinctrl_config(ofnode node)&#123;	u32 pin_mux[MAX_PINS_ONE_IP];	int rv, len;	ofnode subnode;	/*	 * check for &quot;pinmux&quot; property in each subnode (e.g. pins1 and pins2 for	 * usart1) of pin controller phandle &quot;pinctrl-0&quot;	 * */	ofnode_for_each_subnode(subnode, node) &#123;		struct stm32_gpio_dsc gpio_dsc;		struct stm32_gpio_ctl gpio_ctl;		int i;		rv = ofnode_read_size(subnode, &quot;pinmux&quot;);		if (rv &lt; 0)			return rv;		len = rv / sizeof(pin_mux[0]);		log_debug(&quot;No of pinmux entries= %d\n&quot;, len);		if (len &gt; MAX_PINS_ONE_IP)			return -EINVAL;		rv = ofnode_read_u32_array(subnode, &quot;pinmux&quot;, pin_mux, len);		if (rv &lt; 0)			return rv;		for (i = 0; i &lt; len; i++) &#123;			struct gpio_desc desc;			log_debug(&quot;pinmux = %x\n&quot;, *(pin_mux + i));			prep_gpio_dsc(&amp;gpio_dsc, *(pin_mux + i));			//解析GPIO描述引脚			prep_gpio_ctl(&amp;gpio_ctl, *(pin_mux + i), subnode);	//解析GPIO控制模式			rv = uclass_get_device_by_seq(UCLASS_GPIO,			//获取GPIO设备						      gpio_dsc.port,						      &amp;desc.dev);			if (rv)				return rv;			desc.offset = gpio_dsc.pin;			rv = stm32_gpio_config(node, &amp;desc, &amp;gpio_ctl);		//配置GPIO			log_debug(&quot;rv = %d\n\n&quot;, rv);			if (rv)				return rv;		&#125;	&#125;	return 0;&#125;

prep_gpio_dsc 解析GPIO描述引脚static int prep_gpio_dsc(struct stm32_gpio_dsc *gpio_dsc, u32 port_pin)&#123;	gpio_dsc-&gt;port = (port_pin &amp; 0x1F000) &gt;&gt; 12;	gpio_dsc-&gt;pin = (port_pin &amp; 0x0F00) &gt;&gt; 8;	log_debug(&quot;GPIO:port= %d, pin= %d\n&quot;, gpio_dsc-&gt;port, gpio_dsc-&gt;pin);	return 0;&#125;

prep_gpio_ctl 解析GPIO控制模式static int prep_gpio_ctl(struct stm32_gpio_ctl *gpio_ctl, u32 gpio_fn,			 ofnode node)&#123;	gpio_fn &amp;= 0x00FF;	gpio_ctl-&gt;af = 0;	switch (gpio_fn) &#123;	case 0:		gpio_ctl-&gt;mode = STM32_GPIO_MODE_IN;		break;	case 1 ... 16:		gpio_ctl-&gt;mode = STM32_GPIO_MODE_AF;		gpio_ctl-&gt;af = gpio_fn - 1;		break;	case 17:		gpio_ctl-&gt;mode = STM32_GPIO_MODE_AN;		break;	default:		gpio_ctl-&gt;mode = STM32_GPIO_MODE_OUT;		break;	&#125;	gpio_ctl-&gt;speed = ofnode_read_u32_default(node, &quot;slew-rate&quot;, 0);	if (ofnode_read_bool(node, &quot;drive-open-drain&quot;))		gpio_ctl-&gt;otype = STM32_GPIO_OTYPE_OD;	else		gpio_ctl-&gt;otype = STM32_GPIO_OTYPE_PP;	if (ofnode_read_bool(node, &quot;bias-pull-up&quot;))		gpio_ctl-&gt;pupd = STM32_GPIO_PUPD_UP;	else if (ofnode_read_bool(node, &quot;bias-pull-down&quot;))		gpio_ctl-&gt;pupd = STM32_GPIO_PUPD_DOWN;	else		gpio_ctl-&gt;pupd = STM32_GPIO_PUPD_NO;	log_debug(&quot;gpio fn= %d, slew-rate= %x, op type= %x, pull-upd is = %x\n&quot;,		  gpio_fn, gpio_ctl-&gt;speed, gpio_ctl-&gt;otype,		  gpio_ctl-&gt;pupd);	return 0;&#125;

gpiogpio-uclass.cgpio_post_bind 配置了GPIO_HOG属性的节点绑定gpio_hog驱动
GPIO hogging是一种机制，允许在GPIO控制器的驱动程序探测（probe）函数中自动请求和配置GPIO。这种机制的主要目的是简化GPIO的初始化过程，确保在驱动程序加载时，GPIO能够自动配置为所需的状态。

gpio_post_probe 为每个GPIO控制器分配name和claimed数组static int gpio_post_probe(struct udevice *dev)&#123;	struct gpio_dev_priv *uc_priv = dev_get_uclass_priv(dev);	uc_priv-&gt;name = calloc(uc_priv-&gt;gpio_count, sizeof(char *));	if (!uc_priv-&gt;name)		return -ENOMEM;	uc_priv-&gt;claimed = calloc(DIV_ROUND_UP(uc_priv-&gt;gpio_count,					       GPIO_ALLOC_BITS),				  GPIO_ALLOC_BITS / 8);	if (!uc_priv-&gt;claimed) &#123;		free(uc_priv-&gt;name);		return -ENOMEM;	&#125;	return gpio_renumber(NULL);&#125;

gpio_renumber 为每个GPIO控制器分配gpio_basestatic int gpio_renumber(struct udevice *removed_dev)&#123;	struct gpio_dev_priv *uc_priv;	struct udevice *dev;	struct uclass *uc;	unsigned base;	int ret;	ret = uclass_get(UCLASS_GPIO, &amp;uc);	if (ret)		return ret;	/* Ensure that we have a base for each bank */	base = 0;	uclass_foreach_dev(dev, uc) &#123;		if (device_active(dev) &amp;&amp; dev != removed_dev) &#123;			uc_priv = dev_get_uclass_priv(dev);			uc_priv-&gt;gpio_base = base;			base += uc_priv-&gt;gpio_count;		&#125;	&#125;	return 0;&#125;

gpio_request_list_by_namegpio_request_list_by_name_nodev_gpio_request_by_name_nodevgpio_request_tail 通过node获取gpio_dev,并设置GPIO已经被占用,设置GPIO名字,设置GPIO方向static int gpio_request_tail(int ret, const char *nodename,			     struct ofnode_phandle_args *args,			     const char *list_name, int index,			     struct gpio_desc *desc, int flags,			     bool add_index, struct udevice *gpio_dev)&#123;	/*	desc-&gt;dev = dev;	desc-&gt;offset = offset;	desc-&gt;flags = 0;	*/	gpio_desc_init(desc, gpio_dev, 0);	if (ret)		goto err;	if (!desc-&gt;dev) &#123;	//如果没有找到gpio_dev,则根据node获取		//从GPIO类中获取args-&gt;node节点的设备,并赋值给desc-&gt;dev		ret = uclass_get_device_by_ofnode(UCLASS_GPIO, args-&gt;node,						  &amp;desc-&gt;dev);		if (ret) &#123;			debug(&quot;%s: uclass_get_device_by_ofnode failed\n&quot;,			      __func__);			goto err;		&#125;	&#125;	ret = gpio_find_and_xlate(desc, args);	//将phandle_args转换为gpio_desc	if (ret) &#123;		debug(&quot;%s: gpio_find_and_xlate failed\n&quot;, __func__);		goto err;	&#125;	//设置GPIO已经被占用,设置GPIO名字	ret = dm_gpio_requestf(desc, add_index ? &quot;%s.%s%d&quot; : &quot;%s.%s&quot;,			       nodename, list_name, index);	if (ret) &#123;		debug(&quot;%s: dm_gpio_requestf failed\n&quot;, __func__);		goto err;	&#125;	/* 保留 devicetree 提供的任何方向标志 */	ret = dm_gpio_set_dir_flags(desc,				    flags | (desc-&gt;flags &amp; GPIOD_MASK_DIR));	if (ret) &#123;		debug(&quot;%s: dm_gpio_set_dir failed\n&quot;, __func__);		goto err;	&#125;	return 0;err:	debug(&quot;%s: Node &#x27;%s&#x27;, property &#x27;%s&#x27;, failed to request GPIO index %d: %d\n&quot;,	      __func__, nodename, list_name, index, ret);	return ret;&#125;

gpio_find_and_xlate 将phandle_args转换为gpio_descstatic int gpio_find_and_xlate(struct gpio_desc *desc,			       struct ofnode_phandle_args *args)&#123;	const struct dm_gpio_ops *ops = gpio_get_ops(desc-&gt;dev);	if (ops-&gt;xlate)	//驱动自定义说明符识别		return ops-&gt;xlate(desc-&gt;dev, desc, args);	else	//默认说明符识别		return gpio_xlate_offs_flags(desc-&gt;dev, desc, args);&#125;

gpio_xlate_offs_flags 将phandle的arg[0]作为offset, arg[1]作为flagsint gpio_xlate_offs_flags(struct udevice *dev, struct gpio_desc *desc,			  struct ofnode_phandle_args *args)&#123;	struct gpio_dev_priv *uc_priv = dev_get_uclass_priv(dev);	if (args-&gt;args_count &lt; 1)		return -EINVAL;	desc-&gt;offset = args-&gt;args[0];	if (desc-&gt;offset &gt;= uc_priv-&gt;gpio_count)		return -EINVAL;	if (args-&gt;args_count &lt; 2)		return 0;	desc-&gt;flags = gpio_flags_xlate(args-&gt;args[1]);	return 0;&#125;

gpio_flags_xlate 转换FDT说明符为GPIO flagsunsigned long gpio_flags_xlate(uint32_t arg)&#123;	unsigned long flags = 0;	if (arg &amp; GPIO_ACTIVE_LOW)		flags |= GPIOD_ACTIVE_LOW;	/*	 * need to test 2 bits for gpio output binding:	 * OPEN_DRAIN (0x6) = SINGLE_ENDED (0x2) | LINE_OPEN_DRAIN (0x4)	 * OPEN_SOURCE (0x2) = SINGLE_ENDED (0x2) | LINE_OPEN_SOURCE (0x0)	 */	if (arg &amp; GPIO_SINGLE_ENDED) &#123;		if (arg &amp; GPIO_LINE_OPEN_DRAIN)			flags |= GPIOD_OPEN_DRAIN;		else			flags |= GPIOD_OPEN_SOURCE;	&#125;	if (arg &amp; GPIO_PULL_UP)		flags |= GPIOD_PULL_UP;	if (arg &amp; GPIO_PULL_DOWN)		flags |= GPIOD_PULL_DOWN;	return flags;&#125;

dts&#x2F;upstream&#x2F;include&#x2F;dt-bindings&#x2F;gpio&#x2F;gpio.h GPIO flag 说明* Bit 0 express polarity */#define GPIO_ACTIVE_HIGH 0#define GPIO_ACTIVE_LOW 1/* Bit 1 express single-endedness */#define GPIO_PUSH_PULL 0#define GPIO_SINGLE_ENDED 2/* Bit 2 express Open drain or open source */#define GPIO_LINE_OPEN_SOURCE 0#define GPIO_LINE_OPEN_DRAIN 4/* * Open Drain/Collector is the combination of single-ended open drain interface. * Open Source/Emitter is the combination of single-ended open source interface. */#define GPIO_OPEN_DRAIN (GPIO_SINGLE_ENDED | GPIO_LINE_OPEN_DRAIN)#define GPIO_OPEN_SOURCE (GPIO_SINGLE_ENDED | GPIO_LINE_OPEN_SOURCE)/* Bit 3 express GPIO suspend/resume and reset persistence */#define GPIO_PERSISTENT 0#define GPIO_TRANSITORY 8/* Bit 4 express pull up */#define GPIO_PULL_UP 16/* Bit 5 express pull down */#define GPIO_PULL_DOWN 32/* Bit 6 express pull disable */#define GPIO_PULL_DISABLE 64

include&#x2F;asm-generic&#x2F;gpio.h GPIO说明
GPIOD_MASK_DIR: 设置GPIO方向,注意其中不包括GPIOD_ACTIVE_LOW
所以设置GPIOD_ACTIVE_LOW和没有GPIOD_ACTIVE_LOW,其实是设置激活电平,并不设置方向与模式

#define GPIOD_IS_OUT		BIT(1)	/* GPIO is an output */#define GPIOD_IS_IN		BIT(2)	/* GPIO is an input */#define GPIOD_ACTIVE_LOW	BIT(3)	/* GPIO is active when value is low */#define GPIOD_IS_OUT_ACTIVE	BIT(4)	/* set output active */#define GPIOD_OPEN_DRAIN	BIT(5)	/* GPIO is open drain type */#define GPIOD_OPEN_SOURCE	BIT(6)	/* GPIO is open source type */#define GPIOD_PULL_UP		BIT(7)	/* GPIO has pull-up enabled */#define GPIOD_PULL_DOWN		BIT(8)	/* GPIO has pull-down enabled */#define GPIOD_IS_AF		BIT(9)	/* GPIO is an alternate function *//* Flags for updating the above */#define GPIOD_MASK_DIR		(GPIOD_IS_OUT | GPIOD_IS_IN | \					GPIOD_IS_OUT_ACTIVE)#define GPIOD_MASK_DSTYPE	(GPIOD_OPEN_DRAIN | GPIOD_OPEN_SOURCE)#define GPIOD_MASK_PULL		(GPIOD_PULL_UP | GPIOD_PULL_DOWN)

dm_gpio_requestf 通过字符串请求GPIO,并设置GPIO已经被占用,设置GPIO名字// ret = dm_gpio_requestf(desc, add_index ? &quot;%s.%s%d&quot; : &quot;%s.%s&quot;, nodename, list_name, index); 传入spi2.cs0static int dm_gpio_requestf(struct gpio_desc *desc, const char *fmt, ...)&#123;#if !defined(CONFIG_XPL_BUILD) || !CONFIG_IS_ENABLED(USE_TINY_PRINTF)	va_list args;	char buf[40];	va_start(args, fmt);	vscnprintf(buf, sizeof(buf), fmt, args);	va_end(args);	return dm_gpio_request(desc, buf);#else	return dm_gpio_request(desc, fmt);#endif&#125;

dm_gpio_request 通过字符串请求GPIO,并设置GPIO已经被占用,设置GPIO名字int dm_gpio_request(struct gpio_desc *desc, const char *label)&#123;	const struct dm_gpio_ops *ops = gpio_get_ops(desc-&gt;dev);	struct udevice *dev = desc-&gt;dev;	struct gpio_dev_priv *uc_priv;	char *str;	int ret;	uc_priv = dev_get_uclass_priv(dev);	if (gpio_is_claimed(uc_priv, desc-&gt;offset))	//GPIO是否已经被占用		return -EBUSY;	str = strdup(label);	if (!str)		return -ENOMEM;	if (ops-&gt;request) &#123;		ret = ops-&gt;request(dev, desc-&gt;offset, label);		if (ret) &#123;			free(str);			return ret;		&#125;	&#125;	gpio_set_claim(uc_priv, desc-&gt;offset);	//设置GPIO已经被占用	uc_priv-&gt;name[desc-&gt;offset] = str;		//设置GPIO名字	return 0;&#125;

dm_gpio_set_dir_flags 设置GPIO方向int dm_gpio_set_dir_flags(struct gpio_desc *desc, ulong flags)&#123;	/* combine the requested flags (for IN/OUT) and the descriptor flags */	return dm_gpio_clrset_flags(desc, GPIOD_MASK_DIR, flags);&#125;

dm_gpio_clrset_flags 清除并设置GPIO flagsint dm_gpio_clrset_flags(struct gpio_desc *desc, ulong clr, ulong set)&#123;	ulong flags;	int ret;	ret = check_reserved(desc, &quot;set_dir_flags&quot;);	//检查GPIO是否被占用,字符串用于debug输出是什么函数调用的	if (ret)		return ret;	flags = (desc-&gt;flags &amp; ~clr) | set;	ret = _dm_gpio_set_flags(desc, flags);	if (ret)		return ret;	/* save the flags also in descriptor */	desc-&gt;flags = flags;	return 0;&#125;

_dm_gpio_set_flags 设置GPIO flagsstatic int _dm_gpio_set_flags(struct gpio_desc *desc, ulong flags)&#123;	struct udevice *dev = desc-&gt;dev;	const struct dm_gpio_ops *ops = gpio_get_ops(dev);	struct gpio_dev_priv *uc_priv = dev_get_uclass_priv(dev);	int ret = 0;	ret = check_dir_flags(flags);	//检查flag是否设置合法	/* 如果低电平有效，则反转输出状态 */	if ((flags &amp; (GPIOD_IS_OUT | GPIOD_ACTIVE_LOW)) ==		(GPIOD_IS_OUT | GPIOD_ACTIVE_LOW))		flags ^= GPIOD_IS_OUT_ACTIVE;	/* GPIOD_由驱动直接管理 set_flags */	if (ops-&gt;set_flags) &#123;		ret = ops-&gt;set_flags(dev, desc-&gt;offset, flags);	&#125; else &#123;		if (flags &amp; GPIOD_MASK_PULL)			return -EINVAL;		if (flags &amp; GPIOD_IS_OUT) &#123;			bool value = flags &amp; GPIOD_IS_OUT_ACTIVE;			ret = ops-&gt;direction_output(dev, desc-&gt;offset, value);		&#125; else if (flags &amp; GPIOD_IS_IN) &#123;			ret = ops-&gt;direction_input(dev, desc-&gt;offset);		&#125;	&#125;	return ret;&#125;

