gpio_stm32_probe 识别节点具有st,bank-name属性,设置gpio_count和gpio_range,并使能时钟static int gpio_stm32_probe(struct udevice *dev)&#123;	struct stm32_gpio_priv *priv = dev_get_priv(dev);	struct gpio_dev_priv *uc_priv = dev_get_uclass_priv(dev);	struct ofnode_phandle_args args;	const char *name;	struct clk clk;	fdt_addr_t addr;	int ret, i;	addr = dev_read_addr(dev);	if (addr == FDT_ADDR_T_NONE)		return -EINVAL;	priv-&gt;regs = (struct stm32_gpio_regs *)addr;	name = dev_read_string(dev, &quot;st,bank-name&quot;);	if (!name)		return -EINVAL;	uc_priv-&gt;bank_name = name;	i = 0;	ret = dev_read_phandle_with_args(dev, &quot;gpio-ranges&quot;,					 NULL, 3, i, &amp;args);	if (!ret &amp;&amp; args.args_count &lt; 3)		return -EINVAL;	uc_priv-&gt;gpio_count = STM32_GPIOS_PER_BANK; //16.GPIO一般一个段有16个引脚,但是有些会更少	if (ret == -ENOENT) //没找到gpio-ranges属性,则默认16个引脚		priv-&gt;gpio_range = GENMASK(STM32_GPIOS_PER_BANK - 1, 0);    /*    该属性可以有多个值,每个值代表一个引脚范围    gpio-ranges =			&lt;&amp;pinctrl1 0 20 10&gt;,                            &lt;&amp;pinctrl2 10 0 0&gt;,                            &lt;&amp;pinctrl1 15 0 10&gt;,                            &lt;&amp;pinctrl2 25 0 0&gt;;    */	while (ret != -ENOENT) &#123;        //设置gpio_range引脚范围		priv-&gt;gpio_range |= GENMASK(args.args[2] + args.args[0] - 1,				    args.args[0]);		ret = dev_read_phandle_with_args(dev, &quot;gpio-ranges&quot;, NULL, 3,						 ++i, &amp;args);		if (!ret &amp;&amp; args.args_count &lt; 3)			return -EINVAL;	&#125;	dev_dbg(dev, &quot;addr = 0x%p bank_name = %s gpio_count = %d gpio_range = 0x%x\n&quot;,		(u32 *)priv-&gt;regs, uc_priv-&gt;bank_name, uc_priv-&gt;gpio_count,		priv-&gt;gpio_range);    //获取引脚时钟GPIOX_CK	ret = clk_get_by_index(dev, 0, &amp;clk);	if (ret &lt; 0)		return ret;	ret = clk_enable(&amp;clk);	if (ret) &#123;		dev_err(dev, &quot;failed to enable clock\n&quot;);		return ret;	&#125;	dev_dbg(dev, &quot;clock enabled\n&quot;);	return 0;&#125;

stm32_gpio_set_flags 设置GPIO flagsstatic int stm32_gpio_set_flags(struct udevice *dev, unsigned int offset,				ulong flags)&#123;	struct stm32_gpio_priv *priv = dev_get_priv(dev);	struct stm32_gpio_regs *regs = priv-&gt;regs;	if (!stm32_gpio_is_mapped(dev, offset))		return -ENXIO;	if (flags &amp; GPIOD_IS_OUT) &#123;		bool value = flags &amp; GPIOD_IS_OUT_ACTIVE;		if (flags &amp; GPIOD_OPEN_DRAIN)			stm32_gpio_set_otype(regs, offset, STM32_GPIO_OTYPE_OD);		else			stm32_gpio_set_otype(regs, offset, STM32_GPIO_OTYPE_PP);		stm32_gpio_set_moder(regs, offset, STM32_GPIO_MODE_OUT);		writel(BSRR_BIT(offset, value), &amp;regs-&gt;bsrr);	&#125; else if (flags &amp; GPIOD_IS_IN) &#123;		stm32_gpio_set_moder(regs, offset, STM32_GPIO_MODE_IN);	&#125;	if (flags &amp; GPIOD_PULL_UP)		stm32_gpio_set_pupd(regs, offset, STM32_GPIO_PUPD_UP);	else if (flags &amp; GPIOD_PULL_DOWN)		stm32_gpio_set_pupd(regs, offset, STM32_GPIO_PUPD_DOWN);	return 0;&#125;

