_stm32_serial_init 初始化串口 启用fifo与tx rxstatic void _stm32_serial_init(void __iomem *base,			       struct stm32_uart_info *uart_info)&#123;	bool stm32f4 = uart_info-&gt;stm32f4;	u8 uart_enable_bit = uart_info-&gt;uart_enable_bit;	/* Disable uart-&gt; enable fifo -&gt; enable uart */	clrbits_le32(base + CR1_OFFSET(stm32f4), USART_CR1_RE | USART_CR1_TE |		     BIT(uart_enable_bit));	if (uart_info-&gt;has_fifo)		setbits_le32(base + CR1_OFFSET(stm32f4), USART_CR1_FIFOEN);	setbits_le32(base + CR1_OFFSET(stm32f4), USART_CR1_RE | USART_CR1_TE |		     BIT(uart_enable_bit));&#125;

