regmap.c 寄存器映射regmap_init_memint regmap_init_mem(ofnode node, struct regmap **mapp)&#123;	ofnode parent;	struct regmap_range *range;	struct regmap *map;	int count;	int addr_len, size_len, both_len;	int len;	int index;	int ret;	parent = ofnode_get_parent(node);    //读取syscon节点的父节点的#address-cells属性值,根据示例dts,这里是soc的#address-cells属性值为1	addr_len = ofnode_read_simple_addr_cells(parent);    //读取syscon节点的父节点的#size-cells属性值,根据示例dts,这里是soc的#size-cells属性值为1	size_len = ofnode_read_simple_size_cells(parent);	both_len = addr_len + size_len;         //both_len = 2	len = ofnode_read_size(node, &quot;reg&quot;);    //LEN = 0x400	len /= sizeof(fdt32_t);                 //len = 0x100	count = len / both_len;                 //计算地址和大小对的数量 = 0x80	map = regmap_alloc(count);              //分配地址对空间+头部信息空间    //遍历地址对,初始化地址对信息	for (range = map-&gt;ranges, //range指向map的地址对信息        index = 0; count &gt; 0;	     count--, range++, index++) &#123;		ret = init_range(node, range, addr_len, size_len, index);		if (ret)			goto err;	&#125;	if (ofnode_read_bool(node, &quot;little-endian&quot;))		map-&gt;endianness = REGMAP_LITTLE_ENDIAN;	else if (ofnode_read_bool(node, &quot;big-endian&quot;))		map-&gt;endianness = REGMAP_BIG_ENDIAN;	else if (ofnode_read_bool(node, &quot;native-endian&quot;))		map-&gt;endianness = REGMAP_NATIVE_ENDIAN;	else /* Default: native endianness */		map-&gt;endianness = REGMAP_NATIVE_ENDIAN;	*mapp = map;	return 0;&#125;

regmap_alloc 分配头部存储空间+地址大小对存储空间static struct regmap *regmap_alloc(int count)&#123;	struct regmap *map;    //计算头部信息大小与分配的空间大小	size_t size = sizeof(*map) + sizeof(map-&gt;ranges[0]) * count;	map = calloc(1, size);	if (!map)		return NULL;	map-&gt;range_count = count;	map-&gt;width = REGMAP_SIZE_32;	return map;&#125;

init_range 初始化地址对信息,设置地址和大小static int init_range(ofnode node, struct regmap_range *range, int addr_len,		      int size_len, int index)&#123;	fdt_size_t sz;	struct resource r;    int offset = ofnode_to_offset(node);    //根据当前节点的reg的属性值,通过index确定第几个地址对,获取地址和大小    range-&gt;start = fdtdec_get_addr_size_fixed(gd-&gt;fdt_blob,                             offset,                            &quot;reg&quot;,                             index,              //第几个地址对                            addr_len, size_len, //确定是32位还是64位                            &amp;sz, true);    range-&gt;size = sz;	return 0;&#125;

