// 声明一个链接生成的条目,以__u_boot_list_2_XXX_2_YYY命名#define ll_entry_declare(_type, _name, _list)				\	_type _u_boot_list_2_##_list##_2_##_name __aligned(4)		\			__attribute__((unused))				\			__section(&quot;__u_boot_list_2_&quot;#_list&quot;_2_&quot;#_name)// 声明一个链接生成的列表,以__u_boot_list_2_XXX_2_YYY命名,但是是一个数组#define ll_entry_declare_list(_type, _name, _list)			\	_type _u_boot_list_2_##_list##_2_##_name[] __aligned(4)		\			__attribute__((unused))				\			__section(&quot;__u_boot_list_2_&quot;#_list&quot;_2_&quot;#_name) // 声明一个段的开头,以__u_boot_list_2_XXX_1命名#define ll_entry_start(_type, _list)					\(&#123;									\	static char start[0] __aligned(CONFIG_LINKER_LIST_ALIGN)	\		__attribute__((unused))					\		__section(&quot;__u_boot_list_2_&quot;#_list&quot;_1&quot;);			\	_type * tmp = (_type *)&amp;start;					\	asm(&quot;&quot;:&quot;+r&quot;(tmp));						\	tmp;								\&#125;)// 声明一个段的结尾,以__u_boot_list_2_XXX_3命名#define ll_entry_end(_type, _list)					\(&#123;									\	static char end[0] __aligned(4) __attribute__((unused))		\		__section(&quot;__u_boot_list_2_&quot;#_list&quot;_3&quot;);			\	_type * tmp = (_type *)&amp;end;					\	asm(&quot;&quot;:&quot;+r&quot;(tmp));						\	tmp;								\&#125;)// 计算段的数量#define ll_entry_count(_type, _list)					\	(&#123;								\		_type *start = ll_entry_start(_type, _list);		\		_type *end = ll_entry_end(_type, _list);		\		unsigned int _ll_result = end - start;			\		_ll_result;						\	&#125;)

