/* * 这是一个静态的内部函数，用于在一个指定的CPU上，根据一个热插拔线程模板来创建线程。 * @ht:  指向smp_hotplug_thread线程模板的指针。 * @cpu: 目标CPU的编号。 * * 返回值: 0表示成功，负的错误码表示失败。 */static int__smpboot_create_thread(struct smp_hotplug_thread *ht, unsigned int cpu)&#123;	/* tsk: 指向新创建任务的task_struct的指针。*/	struct task_struct *tsk = *per_cpu_ptr(ht-&gt;store, cpu);	/* td: 指向一个临时的数据结构，用于向新线程传递参数。*/	struct smpboot_thread_data *td;	/*	 * 检查ht-&gt;store这个per-cpu数组中，对应于当前cpu的槽位是否已经有值。	 * per_cpu_ptr(ht-&gt;store, cpu)获取该槽位的地址，&#x27;*&#x27;解引用获取其内容。	 */	if (tsk)		/* 如果已经存在，说明线程已创建，直接返回成功。*/		return 0;	/*	 * 为smpboot_thread_data动态分配内存。	 * GFP_KERNEL表示这是一个常规的、可能引起睡眠的内核内存分配。	 * cpu_to_node(cpu)确保内存在与目标CPU亲和的NUMA节点上分配。	 */	td = kzalloc_node(sizeof(*td), GFP_KERNEL, cpu_to_node(cpu));	/* 如果内存分配失败，返回-ENOMEM错误。*/	if (!td)		return -ENOMEM;	/* 将目标CPU编号和线程模板指针存入td中，以便传递。*/	td-&gt;cpu = cpu;	td-&gt;ht = ht;	/*	 * 调用kthread_create_on_cpu()来创建并绑定线程。	 * - smpboot_thread_fn: 是所有通过此框架创建的线程的通用入口函数。	 * - td:                是传递给smpboot_thread_fn的参数。	 * - cpu:                 指定线程必须在这个CPU上创建和运行。	 * - ht-&gt;thread_comm:     是线程名的格式化字符串，如&quot;ksoftirqd/%u&quot;。	 */	tsk = kthread_create_on_cpu(smpboot_thread_fn, td, cpu,				    ht-&gt;thread_comm);	/* 检查kthread_create_on_cpu是否返回了一个错误。IS_ERR会判断指针是否编码了错误。*/	if (IS_ERR(tsk)) &#123;		/* 如果创建失败，释放之前分配的td内存。*/		kfree(td);		/* 使用PTR_ERR从指针中提取出负的错误码并返回。*/		return PTR_ERR(tsk);	&#125;	/* 调用kthread_set_per_cpu，在task_struct中设置这是一个per-cpu线程的标志。*/	kthread_set_per_cpu(tsk, cpu);	/*	 * 注释：停泊该线程，以便当CPU可用时，它能立刻在该CPU上启动。	 */	/* 调用kthread_park，向新线程发出一个“请停泊”的请求。*/	kthread_park(tsk);	/*	 * 增加新线程tsk的引用计数。因为我们将要把它的指针存入一个全局的	 * per-cpu变量中，必须增加引用计数以防止它意外消失。	 */	get_task_struct(tsk);	/* 将新创建的task_struct指针，存入ht-&gt;store的对应CPU槽位中。*/	*per_cpu_ptr(ht-&gt;store, cpu) = tsk;		/* 检查线程模板中是否提供了一个create回调函数。*/	if (ht-&gt;create) &#123;		/*		 * 注释：在调用create回调之前，确保该任务实际上已经调度出去并		 *       进入了停泊位置。至少，迁移线程的回调要求任务已不在运行队列上。		 */		/*		 * 调用wait_task_inactive，同步等待，直到tsk的状态变为TASK_PARKED。		 * 如果等待失败，则触发一个内核警告。		 */		if (!wait_task_inactive(tsk, TASK_PARKED))			WARN_ON(1);		else			/* 在确认线程已停泊后，安全地调用用户提供的create回调函数。*/			ht-&gt;create(cpu);	&#125;	/* 返回0表示成功。*/	return 0;&#125;

