smpboot_register_percpu_thread 注册一个与热插拔相关的per_cpu线程static LIST_HEAD(hotplug_threads);static DEFINE_MUTEX(smpboot_threads_lock);/** * smpboot_register_percpu_thread - 注册一个与热插拔相关的per_cpu线程 * @plug_thread:	热插拔线程的描述符结构体指针。 * * 在所有在线的CPU上创建并启动这些线程。 */int smpboot_register_percpu_thread(struct smp_hotplug_thread *plug_thread)&#123;	/* cpu: 用于在循环中迭代CPU编号。*/	unsigned int cpu;	/* ret: 用于存储函数返回值，默认为0(成功)。*/	int ret = 0;	/*	 * 获取cpus_read_lock读锁，以创建一个稳定的CPU视图，防止在遍历期间	 * CPU的在线状态发生改变。	 */	cpus_read_lock();	/*	 * 获取smpboot_threads_lock互斥锁，以保护对全局hotplug_threads链表的	 * 并发访问。	 */	mutex_lock(&amp;smpboot_threads_lock);		/* 使用for_each_online_cpu宏，遍历系统中所有当前处于“在线”状态的CPU。*/	for_each_online_cpu(cpu) &#123;		/*		 * 调用内部辅助函数__smpboot_create_thread，根据plug_thread模板，		 * 为指定的cpu创建一个内核线程。		 */		ret = __smpboot_create_thread(plug_thread, cpu);		/* 如果线程创建失败（ret不为0）。*/		if (ret) &#123;			/* 调用smpboot_destroy_threads，清理掉所有已经为这个			 * plug_thread模板创建成功的线程，以回滚操作。*/			smpboot_destroy_threads(plug_thread);			/* 跳转到out标签，准备解锁并返回错误。*/			goto out;		&#125;		/* 如果创建成功，则调用smpboot_unpark_thread唤醒这个新创建的、		 * 处于停泊状态的线程，让它开始运行。*/		smpboot_unpark_thread(plug_thread, cpu);	&#125;	/*	 * 在为所有当前在线的CPU都创建了线程之后，将这个plug_thread模板	 * 添加到全局的hotplug_threads链表中。	 * 这确保了未来有新CPU上线时，也会为它创建这个线程。	 */	list_add(&amp;plug_thread-&gt;list, &amp;hotplug_threads);out:	/* 释放互斥锁。*/	mutex_unlock(&amp;smpboot_threads_lock);	/* 释放读锁。*/	cpus_read_unlock();	/* 返回操作结果（0表示成功，否则为错误码）。*/	return ret;&#125;/* * 将smpboot_register_percpu_thread函数符号以GPL兼容的方式导出， * 使得遵循GPL许可的可加载内核模块也能调用它。 */EXPORT_SYMBOL_GPL(smpboot_register_percpu_thread);

smpboot_thread_fn - per-cpu热插拔线程的循环函数/** * smpboot_thread_fn - per-cpu热插拔线程的循环函数 * @data:	线程的数据指针 * * 检查线程的停止和停泊条件。为已注册的线程调用必要的 * setup, cleanup, park和unpark函数。 * * 返回值: 当线程应该退出时返回1，否则返回0。 * (注：根据实现，它最终返回0来退出) */static int smpboot_thread_fn(void *data)&#123;	/* td: 指向本次线程实例的私有数据，包含了cpu编号和ht模板指针。*/	struct smpboot_thread_data *td = data;	/* ht: 指向定义了这类per-cpu线程通用行为的模板结构体。*/	struct smp_hotplug_thread *ht = td-&gt;ht;	/* 进入无限循环，构成线程的主体。*/	while (1) &#123;		/* 将自己的状态置为可中断睡眠，准备在无事可做时睡眠。*/		set_current_state(TASK_INTERRUPTIBLE);		/* 在检查状态前禁用抢占，以防止在检查和睡眠之间产生竞争。*/		preempt_disable();		/* 检查是否有外部请求要求本线程停止并退出。*/		if (kthread_should_stop()) &#123;			/* 如果需要停止，则恢复为运行状态以执行清理。*/			__set_current_state(TASK_RUNNING);			/* 重新使能抢占。*/			preempt_enable();			/* 清理必须与设置镜像对应。*/			/* 如果模板中定义了cleanup回调，并且本线程已初始化过，则调用它。*/			if (ht-&gt;cleanup &amp;&amp; td-&gt;status != HP_THREAD_NONE)				ht-&gt;cleanup(td-&gt;cpu, cpu_online(td-&gt;cpu));			/* 释放为本次实例分配的私有数据td。*/			kfree(td);			/* 从线程主函数返回0，这将最终导致kthread_exit被调用。*/			return 0;		&#125;		/* 检查是否有外部请求要求本线程暂停工作并进入停泊状态。*/		if (kthread_should_park()) &#123;			/* 恢复运行状态以执行停泊前的回调。*/			__set_current_state(TASK_RUNNING);			preempt_enable();			/* 如果模板中定义了park回调，并且线程当前是活跃的。*/			if (ht-&gt;park &amp;&amp; td-&gt;status == HP_THREAD_ACTIVE) &#123;				/* 健壮性检查：确保我们在预期的CPU上运行。*/				BUG_ON(td-&gt;cpu != smp_processor_id());				/* 调用park回调。*/				ht-&gt;park(td-&gt;cpu);				/* 更新内部状态为已停泊。*/				td-&gt;status = HP_THREAD_PARKED;			&#125;			/* 调用kthread框架的标准停泊函数，它会让自己睡眠。*/			kthread_parkme();			/* 我们可能因为stop而被唤醒。*/			/* 当从kthread_parkme()唤醒后，继续下一次主循环，重新评估所有状态。*/			continue;		&#125;		/* 健壮性检查：再次确认我们运行在正确的CPU上。*/		BUG_ON(td-&gt;cpu != smp_processor_id());		/* 检查状态机，以执行一次性的setup或unpark操作。*/		switch (td-&gt;status) &#123;		case HP_THREAD_NONE: /* 初始状态，线程首次运行。*/			__set_current_state(TASK_RUNNING);			preempt_enable();			/* 如果模板中定义了setup回调，则调用它。*/			if (ht-&gt;setup)				ht-&gt;setup(td-&gt;cpu);			/* 将状态迁移到活跃状态。*/			td-&gt;status = HP_THREAD_ACTIVE;			/* 继续下一次主循环。*/			continue;		case HP_THREAD_PARKED: /* 从停泊状态被唤醒。*/			__set_current_state(TASK_RUNNING);			preempt_enable();			/* 如果模板中定义了unpark回调，则调用它。*/			if (ht-&gt;unpark)				ht-&gt;unpark(td-&gt;cpu);			/* 将状态迁移到活跃状态。*/			td-&gt;status = HP_THREAD_ACTIVE;			/* 继续下一次主循环。*/			continue;		&#125;		/* 如果模板中定义了thread_should_run回调，则调用它判断当前是否真的有工作要做。*/		if (!ht-&gt;thread_should_run(td-&gt;cpu)) &#123;			/* 如果没有工作，则使能抢占（但不检查重新调度），然后调用schedule()主动让出CPU。*/			preempt_enable_no_resched();			schedule();		&#125; else &#123;			/* 如果有工作要做，则恢复运行状态并使能抢占。*/			__set_current_state(TASK_RUNNING);			preempt_enable();			/* 调用模板中定义的核心工作函数。*/			ht-&gt;thread_fn(td-&gt;cpu);		&#125;	&#125;&#125;

