/* * 核算一整个tick的CPU时间。 * @p:         CPU时间被记到其头上的那个进程。 * @user_tick: 指示这个tick是用户时间还是系统时间。 */void account_process_tick(struct task_struct *p, int user_tick)&#123;	/* cputime: 存储一个tick代表的总纳秒数。*/	u64 cputime;	/* steal: 存储从虚拟机宿主机那里被“窃取”的CPU时间。*/	u64 steal;	/* 如果当前CPU开启了虚拟时间记账(vtime)，则不使用基于tick的记账，直接返回。*/	// if (vtime_accounting_enabled_this_cpu())		// return;	/* 如果开启了精确中断时间记账(irqtime)... */	// if (irqtime_enabled()) &#123;		/* ...则将记账工作委托给专门的irqtime处理函数并返回。*/	// 	irqtime_account_process_tick(p, user_tick, 1);	// 	return;	// &#125;	/* 获取一个tick周期的标准纳秒数。*/	cputime = TICK_NSEC;	/*	 * 计算并核算从上次记账以来，被hypervisor窃走的CPU时间。	 * ULONG_MAX表示我们不关心具体的cycle数，只关心时间。	 */	// steal = steal_account_process_time(ULONG_MAX);	/* 如果被窃取的时间大于等于整个tick周期，说明本tick内没有有效时间，直接返回。*/	// if (steal &gt;= cputime)	// 	return;	/* 从总时间中减去被窃取的时间，得到任务实际可用的CPU时间。*/	// cputime -= steal;	/* 如果这个tick是在用户态发生的...*/	if (user_tick)		/* ...则调用account_user_time，将cputime记为任务p的用户态时间。*/		account_user_time(p, cputime);	/* 否则，如果是在内核态发生的，并且当前任务p不是空闲线程(idle)...	 * (irq_count() != HARDIRQ_OFFSET这个检查用于排除从idle循环中	 * 发生的、但不在硬中断上下文中的tick)*/	else if ((p != this_rq()-&gt;idle) || (irq_count() != HARDIRQ_OFFSET))		/* ...则调用account_system_time，将cputime记为任务p的内核态时间。		 * HARDIRQ_OFFSET用于区分是纯内核态还是硬中断上下文。*/		account_system_time(p, HARDIRQ_OFFSET, cputime);	else		/* 否则，如果是在内核态，并且任务是idle线程，则调用account_idle_time，		 * 将cputime记为该CPU的空闲时间。*/		account_idle_time(cputime);&#125;


