kernel&#x2F;time&#x2F;time.cset_normalized_timespec64 设置并规范化 timespec64 结构体/** * set_normalized_timespec64 - 设置 TimeSpec 秒和 NSec 部分并归一化 * * @ts：指向要设置的 timespec 变量的指针 * @sec：秒设置 * @nsec：纳秒设置 * * 设置 timespec 变量的 seconds 和 náns 字段，并规范化为 timespec 存储格式 * * 注意：tv_nsec部分始终在 0 &lt;= tv_nsec &lt; NSEC_PER_SEC 的范围内。对于负值，只有 tv_sec 字段为负数！ */void set_normalized_timespec64(struct timespec64 *ts, time64_t sec, s64 nsec)&#123;	/* 如果 nsec 的值大于或等于 NSEC_PER_SEC（每秒的纳秒数，通常为 10^9），则通过循环将多余的纳秒转换为秒 */    while (nsec &gt;= NSEC_PER_SEC) &#123;        /*         *以下 asm（） 可防止编译器将此循环优化为模运算。		 * 另请参见 include/linux/time.h 中的 __iter_div_u64_rem（）         */		/* 每次循环减少 NSEC_PER_SEC 纳秒，同时将对应的秒数加到 sec 中 */        asm(&quot;&quot; : &quot;+rm&quot;(nsec));        nsec -= NSEC_PER_SEC;        ++sec;    &#125;	/* 如果 nsec 的值小于 0，则通过循环将负的纳秒值转换为秒 */    while (nsec &lt; 0) &#123;        asm(&quot;&quot; : &quot;+rm&quot;(nsec));        nsec += NSEC_PER_SEC;        --sec;    &#125;    ts-&gt;tv_sec = sec;    ts-&gt;tv_nsec = nsec;&#125;EXPORT_SYMBOL(set_normalized_timespec64);

ns_to_timespec64 - 将纳秒转换为 timespec64/** * ns_to_timespec64 - 将纳秒转换为 timespec64 * @nsec：要转换的纳秒值 * * 返回：nsec 参数的 timespec64 表示形式。 */struct timespec64 ns_to_timespec64(s64 nsec)&#123;	struct timespec64 ts = &#123; 0, 0 &#125;;	s32 rem;	if (likely(nsec &gt; 0)) &#123;		ts.tv_sec = div_u64_rem(nsec, NSEC_PER_SEC, &amp;rem);		ts.tv_nsec = rem;	&#125; else if (nsec &lt; 0) &#123;		/*		 * With negative times, tv_sec points to the earlier		 * second, and tv_nsec counts the nanoseconds since		 * then, so tv_nsec is always a positive number.		 */		ts.tv_sec = -div_u64_rem(-nsec - 1, NSEC_PER_SEC, &amp;rem) - 1;		ts.tv_nsec = NSEC_PER_SEC - rem - 1;	&#125;	return ts;&#125;EXPORT_SYMBOL(ns_to_timespec64);

