kernel&#x2F;time&#x2F;sleep_timeout.cmsleep &amp; schedule_timeout: 任务睡眠与延时调度本代码片段展示了Linux内核中任务（线程）进行延时操作的核心实现。其主要功能由schedule_timeout函数族提供，它允许当前任务进入不同类型的睡眠状态（可中断、不可中断等），并设置一个定时器在指定时间后将其唤醒。msleep则是在此基础上封装的一个更易于使用的、以毫秒为单位的不可中断睡眠函数。
实现原理分析该机制是内核调度器与内核定时器子系统协同工作的经典范例。它通过组合任务状态变更、定时器设置和调度器调用，实现了精确的、可配置的延时功能。

核心引擎 (schedule_timeout):

这是所有延时功能的基础。其核心思想是在当前任务的栈上创建一个临时的内核定时器（struct timer_list）。
定时器设置: 该函数计算出未来的超时时刻（expire = timeout + jiffies），并设置一个定时器。当定时器到期时，内核会调用其回调函数process_timeout。
唤醒机制: process_timeout回调函数的唯一作用就是调用wake_up_process，将创建该定时器的任务（timer.task）的状态从睡眠态（如 TASK_UNINTERRUPTIBLE）变更为就绪态（TASK_RUNNING），使其能够被调度器再次选中执行。
放弃CPU: 设置好定时器后，函数会调用schedule()。这个调用会主动触发调度器，让出CPU给其他处于就緒态的任务。此时，由于当前任务处于睡眠状态，它不会被调度器选中，从而实现了“睡眠”。
同步与清理: 当任务被唤醒并重新获得CPU后，它会从schedule()调用处继续执行。timer_delete_sync()是一个关键的同步函数，它确保在函数返回、栈上的定时器变量被销毁之前，该定时器已经被完全停用，并且其回调函数（process_timeout）没有也绝不会在任何CPU上运行。


睡眠状态的控制 (schedule_timeout_* 变体):

内核中的睡眠分为多种状态，主要区别在于能否被信号唤醒。
schedule_timeout_uninterruptible: 将任务状态设置为TASK_UNINTERRUPTIBLE。在这种状态下，任务只能被显式的wake_up_process调用唤醒，完全忽略信号。这是最“深”的睡眠，用于等待必要资源且不能被用户干预的场景。
schedule_timeout_interruptible: 将任务状态设置为TASK_INTERRUPTIBLE。任务既可以被定时器到期唤醒，也可以被未屏蔽的信号提前唤醒。
schedule_timeout_killable: 任务状态为TASK_KILLABLE，是前两者的折中。它会忽略普通信号，但可以被致命信号（如SIGKILL）中断。
这些函数本质上都是在调用核心的schedule_timeout之前，先通过__set_current_state()设置好任务状态的简单封装。


高层封装 (msleep):

这是一个对驱动开发者更友好的API，它接受毫秒作为参数。
它首先将毫秒转换为内核内部的时间单位jiffies。
它在一个while循环中调用schedule_timeout_uninterruptible。这种循环结构非常健壮，即使schedule_timeout因为某些罕见原因（虽然在uninterruptible模式下几乎不可能）提前返回，它也会重新计算剩余的超时时间，并继续睡眠，直到总的睡眠时间达到要求。



代码分析/** * @brief 以毫秒为单位进行不可中断的睡眠。 * @param msecs 要睡眠的毫秒数。 * * @details 该函数使用基于jiffies的超时机制。由于内核定时器轮的设计， *          实际的睡眠时间可能会有一定的正向偏差（slack）。 *          它会安全地处理睡眠过程，即使被（理论上不可能的）唤醒信号中断， *          也会继续睡完剩余的时间。 */void msleep(unsigned int msecs)&#123;	/* 将毫秒转换为内核时间单位 jiffies。 */	unsigned long timeout = msecs_to_jiffies(msecs);	/* 循环调用 schedule_timeout_uninterruptible 直到超时用尽。*/	/* 这确保了即使被意外唤醒，也能睡足指定的总时长。*/	while (timeout)		timeout = schedule_timeout_uninterruptible(timeout);&#125;EXPORT_SYMBOL(msleep);/** * @struct process_timer * @brief 一个在栈上创建的辅助结构，用于将定时器与特定任务关联。 */struct process_timer &#123;	struct timer_list timer; /*!&lt; 内核定时器对象。 */	struct task_struct *task; /*!&lt; 定时器到期时需要唤醒的任务。 */&#125;;/** * @brief schedule_timeout 所使用的定时器回调函数。 * @param t 指向触发此回调的 timer_list 结构的指针。 */static void process_timeout(struct timer_list *t)&#123;	/* 从 timer_list 指针找到其容器 process_timer 结构的指针。 */	struct process_timer *timeout = timer_container_of(timeout, t, timer);	/* 唤醒与此定时器关联的任务。 */	wake_up_process(timeout-&gt;task);&#125;/** * @brief 使当前任务睡眠，直到指定的jiffies超时。 * @param timeout 以jiffies为单位的超时值。 * @return signed long 0表示定时器已到期，否则返回剩余的jiffies。 * * @details 函数的行为取决于当前任务的状态： *          - TASK_RUNNING: 只调用调度器，任务不睡眠。 *          - TASK_UNINTERRUPTIBLE: 任务会睡眠，直到超时或被显式唤醒。 *          - TASK_INTERRUPTIBLE: 任务可能会因信号或显式唤醒而提前返回。 *          函数返回时，任务状态保证是 TASK_RUNNING。 *          若timeout为MAX_SCHEDULE_TIMEOUT，则任务会无限期睡眠。 */signed long __sched schedule_timeout(signed long timeout)&#123;	struct process_timer timer;	unsigned long expire;	switch (timeout) &#123;	case MAX_SCHEDULE_TIMEOUT:		/* 对于无限期超时，直接调用调度器让出CPU。 */		schedule();		goto out;	default:		/* 检查并处理无效的负数超时值。 */		if (timeout &lt; 0) &#123;			pr_err(&quot;%s: 错误的超时值 %lx\n&quot;, __func__, timeout);			dump_stack();			__set_current_state(TASK_RUNNING);			goto out;		&#125;	&#125;	/* 计算定时器的绝对到期时间（jiffies）。 */	expire = timeout + jiffies;	/* 将定时器与当前任务关联。 */	timer.task = current;	/* 在栈上初始化定时器，并设置回调函数。 */	timer_setup_on_stack(&amp;timer.timer, process_timeout, 0);	timer.timer.expires = expire;	/* 将定时器添加到内核的定时器列表中。 */	add_timer(&amp;timer.timer);	/* 调用调度器，让出CPU，进入睡眠。 */	schedule();	/* 当任务被唤醒后，从这里继续执行。同步并删除定时器。*/	/* 这确保定时器回调不会在函数返回后被执行。*/	timer_delete_sync(&amp;timer.timer);	/* 从对象跟踪器中移除定时器。 */	timer_destroy_on_stack(&amp;timer.timer);	/* 计算剩余的超时时间。 */	timeout = expire - jiffies; out:	/* 返回值确保为非负数。 */	return timeout &lt; 0 ? 0 : timeout;&#125;EXPORT_SYMBOL(schedule_timeout);/** * @brief 进行可被信号中断的睡眠，直到超时。 * @param timeout 以jiffies为单位的超时值。 * @return signed long 剩余的jiffies或0。 */signed long __sched schedule_timeout_interruptible(signed long timeout)&#123;	/* 将当前任务状态设置为可中断。 */	__set_current_state(TASK_INTERRUPTIBLE);	/* 调用核心的超时函数。 */	return schedule_timeout(timeout);&#125;EXPORT_SYMBOL(schedule_timeout_interruptible);/** * @brief 进行可被致命信号中断的睡眠，直到超时。 * @param timeout 以jiffies为单位的超时值。 * @return signed long 剩余的jiffies或0。 */signed long __sched schedule_timeout_killable(signed long timeout)&#123;	/* 将当前任务状态设置为可被致命信号中断。 */	__set_current_state(TASK_KILLABLE);	/* 调用核心的超时函数。 */	return schedule_timeout(timeout);&#125;EXPORT_SYMBOL(schedule_timeout_killable);/** * @brief 进行不可中断的睡眠，直到超时。 * @param timeout 以jiffies为单位的超时值。 * @return signed long 剩余的jiffies或0。 */signed long __sched schedule_timeout_uninterruptible(signed long timeout)&#123;	/* 将当前任务状态设置为不可中断。 */	__set_current_state(TASK_UNINTERRUPTIBLE);	/* 调用核心的超时函数。 */	return schedule_timeout(timeout);&#125;EXPORT_SYMBOL(schedule_timeout_uninterruptible);

